insert into books (volume_id, book_no, title_ml, title_ar, start_page) values (3, 17, 'ഗ്രന്ഥകർത്താവിനെക്കുറിച്ച്', null, 1029) on conflict (volume_id, book_no) do update set title_ml=excluded.title_ml, title_ar=coalesce(excluded.title_ar, books.title_ar), start_page=excluded.start_page;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 1, 'عَنِ الْمُسْتَوْرِدِ بْنِ شَدَّادٍ الْفِهْرِيِّ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "بُعِثْتُ فِي نَفَسِ السَّاعَةِ، فَسَبَقْتُهَا كَمَا سَبَقَتْ هَذِهِ هَذِهِ". لِأُصْبُعَيْهِ السَّبَّابَةِ وَالْوُسْطَى. حَسَنٌ صَحِيحٌ. (ت)', 'മുസ്തൗരിദുബ്നു ശദ്ദാദിൽ ഫിഹ്രി(റ): നബി(സ) പറയുന്നു: "അന്ത്യനാളിന്റെ ശ്വാസത്തിലാണ് ഞാൻ നിയോഗിക്കപ്പെട്ടത്. പക്ഷേ, ഞാൻ അതിനെ മുൻകടന്നു, ഇത് ഇതിനെ മുൻകടന്നതുപോല." തന്റെ ചൂണ്ടുവിരലിനെക്കുറിച്ചും നടുവിരലിനെക്കുറിച്ചുമാണവിടന്ന് പറഞ്ഞത്. (തു)', 'الْمُسْتَوْرِدِ بْنِ شَدَّادٍ الْفِهْرِيِّ', 'മുസ്തൗരിദുബ്നു ശദ്ദാദിൽ ഫിഹ്രി(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 711, 711, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 2, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "بُعِثْتُ أَنَا وَالسَّاعَةُ كَهَاتَيْنِ". وَأَشَارَ أَبُو دَاوُدَ بِالسَّبَّابَةِ وَالْوُسْطَى، فَمَا فَضَّلَ إِحْدَاهُمَا عَلَى الْأُخْرَى. حَسَنٌ صَحِيحٌ. (ق,ت)', 'അനസ്(റ): റസൂൽ(സ) പറയുന്നു: "ഇവ രണ്ടിനെയും പോലെ ഞാനും അന്ത്യനാളും നിയോഗിക്കപ്പെട്ടു." ശേഷം അബൂദാവൂദ്(റ) നടുവിരലും ചൂണ്ടുവിരലും കാണിച്ചു. അതിൽ ഒന്നിനെയും ശ്രേഷ്ഠമാക്കി പറഞ്ഞില്ല. (ബു,മു,തു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ق','ت']::text[], array['ബു','മു','തു']::text[], null, null, 711, 711, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 3, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَجُلًا سَأَلَ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَتَى [تَقُومُ] السَّاعَةُ؟ قَالَ: فَسَكَتَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ هُنَيْهَةً، ثُمَّ نَظَرَ إِلَى غُلَامٍ بَيْنَ يَدَيْهِ مِنْ أَزْدِ شَنُوءَةَ، فَقَالَ: "إِنْ عُمِّرَ هَذَا لَمْ يُدْرِكْهُ الْهَرَمُ حَتَّى تَقُومَ السَّاعَةُ". قَالَ: قَالَ أَنَسُ بْنُ مَالِكٍ رَضِيَ اللهُ عَنْهُ: ذَاكَ الْغُلَامُ مِنْ أَتْرَابِي يَوْمَئِذٍ. (م)', 'അനസുബ്നു മാലിക്(റ): ഒരാൾ നബി(സ)യോട് ചോദിച്ചു: അന്ത്യനാൾ എപ്പോഴാണുണ്ടാവുക? നിവേദകൻ പറയുന്നു: റസൂൽ(സ) കുറച്ചുനേരം മൗനം പാലിച്ചു. പിന്നെ അടുത്തുള്ള അസദ് ശനൂഅയിലെ ഒരു കുട്ടിയെ നോക്കി പറഞ്ഞു: "ഇവൻ വലുതായി വാർധക്യം വരുന്നതിനു മുമ്പ് അന്ത്യനാൾ സംഭവിക്കും." അനസുബ്നു മാലിക്(റ) പറഞ്ഞു: ആ കുട്ടി അന്ന് എന്റെ സമപ്രായക്കാരനായിരുന്നു. (മു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['م']::text[], array['മു']::text[], 'تَقُومُ', null, 711, 711, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 4, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ الْأَعْرَابُ إِذَا قَدِمُوا عَلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ سَأَلُوهُ عَنِ السَّاعَةِ: مَتَى السَّاعَةُ؟ فَنَظَرَ إِلَى أَحْدَثِ إِنْسَانٍ مِنْهُمْ، فَقَالَ: "إِنْ يَعِشْ هَذَا لَمْ يُدْرِكْهُ الْهَرَمُ قَامَتْ عَلَيْكُمْ سَاعَتُكُمْ". (م)', 'ആഇശ(റ): അനറബികൾ റസൂൽ(സ)യുടെ അടുത്തുവന്നാൽ അന്ത്യനാളിനെ കുറിച്ച് എപ്പോൾ സംഭവിക്കുമെന്ന് ചോദിക്കാറുണ്ടായിരുന്നു. അപ്പോൾ അവരിൽ ചെറിയ ആളിലേക്ക് നോക്കിയിട്ട് റസൂൽ(സ) പറഞ്ഞു: "ഇവൻ ജീവിച്ചിരിക്കുകയാണെങ്കിൽ ഇവന് വാർധക്യം വരികയില്ല, നിങ്ങൾക്കുമേൽ നിങ്ങളുടെ അന്ത്യനാൾ സംഭവിച്ചിട്ടല്ലാതെ." (മു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 711, 711, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 5, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ - يَبْلُغُ بِهِ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ - قَالَ: "تَقُومُ السَّاعَةُ وَالرَّجُلُ يَحْلُبُ اللِّقْحَةَ، فَمَا يَصِلُ الْإِنَاءُ إِلَى فِيهِ حَتَّى تَقُومَ. وَالرَّجُلَانِ يَتَبَايَعَانِ الثَّوْبَ، فَمَا يَتَبَايَعَانِهِ حَتَّى تَقُومَ. وَالرَّجُلُ يَلُوطُ [فِي] حَوْضِهِ، فَمَا يَصْدُرُ حَتَّى تَقُومَ". (م)', 'അബൂഹുറൈറ(റ): നബി(സ) പറയുന്നതായിട്ട് അദ്ദേഹം പറയുന്നു: "ഒരാൾ ഒട്ടകത്തെ പാൽ കറന്ന് പാത്രം തന്റെ വായിൽ എത്തുന്നതിനു മുമ്പ് അന്ത്യനാൾ സംഭവിക്കും. രണ്ടാളുകൾ വസ്ത്രം കച്ചവടം ചെയ്യുന്നു. പക്ഷേ, അത് കൈമാറുന്നതിനു മുമ്പ് അന്ത്യനാൾ സംഭവിക്കും. ഒരാൾ തന്റെ ഹൗള് വൃത്തിയാക്കുന്നു. പക്ഷേ, അദ്ദേഹം തിരിച്ചുവരുന്നതിനു മുമ്പ് അന്ത്യനാൾ സംഭവിക്കും." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], 'فِي', null, 712, 712, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 6, 'عَنْ مُوسَى بْنِ عَلِيٍّ عَنْ أَبِيهِ قَالَ: قَالَ الْمُسْتَوْرِدُ الْقُرَشِيُّ عِنْدَ عَمْرِو بْنِ الْعَاصِ رَضِيَ اللهُ عَنْهُ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "تَقُومُ السَّاعَةُ وَالرُّومُ أَكْثَرُ النَّاسِ". فَقَالَ لَهُ عَمْرٌو: أَبْصِرْ مَا تَقُولُ. قَالَ: أَقُولُ مَا سَمِعْتُ مِنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. قَالَ: لَئِنْ قُلْتَ ذَلِكَ إِنَّ فِيهِمْ لَخِصَالًا أَرْبَعًا: إِنَّهُمْ لَأَحْلَمُ النَّاسِ عِنْدَ فِتْنَةٍ، وَأَسْرَعُهُمْ إِفَاقَةً بَعْدَ مُصِيبَةٍ، وَأَوْشَكُهُمْ كَرَّةً بَعْدَ فَرَّةٍ، وَخَيْرُهُمْ لِمِسْكِينٍ وَيَتِيمٍ وَضَعِيفٍ، وَخَامِسَةٌ حَسَنَةٌ جَمِيلَةٌ: وَأَمْنَعُهُمْ مِنْ ظُلْمِ الْمُلُوكِ. (م)', 'തന്റെ പിതാവിൽ നിന്ന് മൂസബിനു ഉലയ്യ്(റ): അംറുബ്നുൽ ആസ്(റ)വിന്റെ സന്നിധിയിൽ മുസ്തൗരിദുൽ ഖുറശി(റ) പറഞ്ഞു: റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "റോമുകാർ ജനങ്ങളിൽ ഭൂരിപക്ഷമാകുന്ന കാലത്താണ് അന്ത്യനാൾ സംഭവിക്കുക." അപ്പോൾ അംറ്(റ) പറഞ്ഞു: താങ്കൾ പറയുന്നതെന്താണെന്ന് മനസ്സിലാക്കുക. അദ്ദേഹം പറഞ്ഞു: റസൂൽ(സ)യിൽ നിന്ന് ഞാൻ കേട്ടതാണ് ഞാൻ പറയുന്നത്. അംറ്(റ) പറഞ്ഞു: താങ്കൾ അത് പറയുകയാണെങ്കിൽ അവരിൽ നാല് കാര്യങ്ങളുണ്ട്: ഫിതനകളുടെ സമയത്ത് ജനങ്ങളിൽ വെച്ചേറ്റവും ക്ഷമിക്കുന്നവരാകുന്നു അവർ. ആപത്തിന് ശേഷം പെട്ടെന്ന് ബോധം വരുന്നവരും പെട്ടെന്ന് കാര്യങ്ങൾ തിരിച്ചെടുക്കുന്നവരുമാണ് അവർ. അനാഥനും ദുർബലനും പാവപ്പെട്ടവനും ഏറ്റവും ഗുണം ചെയ്യുന്നവരും അവരാണ്. അഞ്ചാമതായി നല്ലൊരു ഗുണം കൂടിയുണ്ട്: രാജാക്കന്മാരുടെ അക്രമത്തെ ഏറ്റവും കൂടുതൽ തടയുന്നവരും അവരാകുന്നു. (മു)', 'مُوسَى بْنِ عَلِيٍّ عَنْ أَبِيهِ قَالَ', 'തന്റെ പിതാവിൽ നിന്ന് മൂസബിനു ഉലയ്യ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 712, 712, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 7, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "وَالَّذِي نَفْسِي بِيَدِهِ، لَا تَذْهَبُ الدُّنْيَا حَتَّى يَأْتِيَ عَلَى النَّاسِ يَوْمٌ لَا يَدْرِي الْقَاتِلُ فِيمَ قَتَلَ، وَلَا الْمَقْتُولُ فِيمَ قُتِلَ". فَقِيلَ: كَيْفَ يَكُونُ ذَلِكَ؟ قَالَ: "الْهَرْجُ، الْقَاتِلُ وَالْمَقْتُولُ فِي النَّارِ". (م)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറയുന്നു: "എന്റെ ശരീരം ആരുടെ കയ്യിലാണോ അവൻ തന്നെ സത്യം, കൊല്ലുന്നവൻ താൻ എന്തിനത് ചെയ്തുവെന്നോ, കൊല്ലപ്പെട്ടവൻ താൻ എന്തിന് കൊല്ലപ്പെട്ടുവെന്നോ അറിയാത്ത ഒരു കാലം വരുന്നതു വരെ ഈ ദുൻയാവ് നശിക്കുകയില്ല." അപ്പോൾ ചോദിക്കപ്പെട്ടു: അതെങ്ങനെയാണുണ്ടാവുക? അവിടുന്ന് പറഞ്ഞു: "കലഹങ്ങൾ തന്നെ, കൊന്നവനും കൊല്ലപ്പെട്ടവനും നരകത്തിലാണ്." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 712, 712, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 8, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا تَقُومُ السَّاعَةُ حَتَّى تَضْطَرِبَ أَلَيَاتُ نِسَاءِ دَوْسٍ حَوْلَ ذِي الْخَلَصَةِ". وَكَانَتْ صَنَمًا تَعْبُدُهَا دَوْسٌ فِي الْجَاهِلِيَّةِ بِتَبَالَةَ. (م)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറയുന്നു: "ദുൽഖലസ വിഗ്രഹത്തിന് ചുറ്റും ദൗസ് ഗോത്രത്തിലെ സ്ത്രീകൾ ചന്തി കുലുക്കി നടക്കുന്നതു വരെ (വിഗ്രഹാരാധന കഴിഞ്ഞ് മടങ്ങിവരുന്നത് വരെ) അന്ത്യനാൾ സംഭവിക്കുകയില്ല." (യമനിലെ) തബാല എന്ന സ്ഥലത്ത് ജാഹിലിയ്യാ കാലഘട്ടത്തിൽ ദൗസ് ഗോത്രക്കാർ ആരാധിച്ചിരുന്ന ഒരു ബിംബമായിരുന്നു അത്. (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 712, 713, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 9, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَا يَذْهَبُ اللَّيْلُ وَالنَّهَارُ حَتَّى تُعْبَدَ اللَّاتُ وَالْعُزَّى". فَقُلْتُ: يَا رَسُولَ اللهِ، إِنْ كُنْتُ لَأَظُنُّ حِينَ أَنْزَلَ اللهُ عَزَّ وَجَلَّ: {هُوَ الَّذِي أَرْسَلَ رَسُولَهُ بِالْهُدَى وَدِينِ الْحَقِّ لِيُظْهِرَهُ عَلَى الدِّينِ كُلِّهِ وَلَوْ كَرِهَ الْمُشْرِكُونَ} أَنَّ ذَلِكَ تَامًّا. قَالَ: "إِنَّهُ سَيَكُونُ مِنْ ذَلِكَ مَا شَاءَ اللهُ، ثُمَّ يَبْعَثُ اللهُ رِيحًا طَيِّبَةً فَتَوَفَّى كُلُّ مَنْ فِي قَلْبِهِ مِثْقَالُ حَبَّةِ خَرْدَلٍ مِنْ إِيمَانٍ، فَيَبْقَى مَنْ لَا خَيْرَ فِيهِ، فَيَرْجِعُونَ إِلَى دِينِ آبَائِهِمْ". (م)', 'ആഇശ(റ): റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "ലാത്തയും ഉസ്സയും ആരാധിക്കപ്പെടുന്നത് വരെ പകലും രാത്രിയും ഇല്ലാതാവുകയില്ല. (അന്ത്യനാൾ സംഭവിക്കുകയില്ല)." അപ്പോൾ ഞാൻ പറഞ്ഞു: ''എല്ലാ മതങ്ങളേക്കാളും സത്യമതത്തെയും സന്മാർഗത്തെയും അതിജയിപ്പിക്കാൻ വേണ്ടി തന്റെ ദൂതനെ അയച്ചവനാണവൻ, മുശ്രിക്കുകൾ വെറുത്താലും'' എന്ന സൂക്തം അല്ലാഹു ഇറക്കിയപ്പോൾ , തിരുദൂതരേ, ഞാൻ വിചാരിച്ചിരുന്നു അത് പൂർണമായെന്ന്. തിരുമേനി(സ) പറഞ്ഞു: "അതിൽ നിന്ന് അല്ലാഹു വിചാരിച്ചതെല്ലാം നടക്കും. പിന്നെ അല്ലാഹു നല്ലൊരു കാറ്റിനെ അയക്കുകയും ഒരു കടുക് മണിയോളം ഈമാനുള്ളവരെയെല്ലാം മരിക്കുകയും ചെയ്യും. ശേഷം നന്മ അൽപം പോലുമില്ലാത്തവർ അവശേഷിക്കും. അവർ അവരുടെ പിതാക്കളുടെ മതത്തിലേക്ക് മടങ്ങുകയും ചെയ്യും." (മു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 713, 713, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 10, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "سَمِعْتُمْ بِمَدِينَةٍ جَانِبٌ مِنْهَا فِي الْبَرِّ وَجَانِبٌ مِنْهَا فِي الْبَحْرِ". قَالُوا: نَعَمْ، يَا رَسُولَ اللهِ. قَالَ: "لَا تَقُومُ السَّاعَةُ حَتَّى يَغْزُوَهَا سَبْعُونَ أَلْفًا مِنْ بَنِي إِسْحَقَ، فَإِذَا جَاءُوهَا نَزَلُوا فَلَمْ يُقَاتِلُوا بِسِلَاحٍ وَلَمْ يَرْمُوا بِسَهْمٍ، قَالُوا: لَا إِلَهَ إِلَّا اللهُ وَاللهُ أَكْبَرُ، فَيَسْقُطُ أَحَدُ جَانِبَيْهَا - قَالَ ثَوْرٌ: لَا أَعْلَمُهُ إِلَّا قَالَ - الَّذِي فِي الْبَحْرِ، ثُمَّ تَقُولُ الثَّانِيَةَ: لَا إِلَهَ إِلَّا اللهُ وَاللهُ أَكْبَرُ، فَيَسْقُطُ جَانِبُهَا الْآخَرُ، ثُمَّ تَقُولُ الثَّالِثَةَ: لَا إِلَهَ إِلَّا اللهُ وَاللهُ أَكْبَرُ، فَتَفَرَّجُ لَهُمْ، فَيَدْخُلُونَهَا فَيَغْنَمُونَ، فَبَيْنَمَا هُمْ يَقْسِمُونَ الْمَغَانِمَ، إِذْ جَاءَهُمُ الصَّرِيخُ فَقَالَ: إِنَّ الدَّجَّالَ قَدْ خَرَجَ، فَيَتْرُكُونَ كُلَّ شَيْءٍ وَيَرْجِعُونَ". (م)', 'അബൂഹുറൈറ(റ): നബി(സ) ചോദിച്ചു: "ഒരു ഭാഗം കരയിലും ഒരു ഭാഗം കടലിലും വെച്ചിട്ടുള്ള ഒരു പട്ടണത്തെക്കുറിച്ച് നിങ്ങൾ കേട്ടിട്ടുണ്ടോ?" അവർ പറഞ്ഞു: അതെ, തിരുദൂതരേ. അവിടുന്ന് പറഞ്ഞു: "ഇസ്ഹാഖ്(അ)മിന്റെ സന്താനങ്ങളിലെ എഴുപതിനായിരം പേർ അതിനോട് യുദ്ധം ചെയ്യുന്നതുവരെ അന്ത്യനാൾ സംഭവിക്കുകയില്ല. അങ്ങനെ അവർ അവിടെ ഇറങ്ങുകയും - അപ്പോൾ അവർ ആയുധം കൊണ്ട് യുദ്ധം ചെയ്യുകയോ അമ്പ് എറിയുകയോ ചെയ്തിട്ടില്ലായിരിക്കും - ഇപ്രകാരം പറയുകയും ചെയ്യും: അല്ലാഹു മാത്രമാണ് ആരാധ്യൻ, അവൻ വലിയവനാകുന്നു. അപ്പോൾ അതിന്റെ ഒരു ഭാഗം വീഴും - സൗർ(റ) പറയുന്നു: കടലിലുള്ള ഭാഗമെന്ന് അവിടുന്ന് പറഞ്ഞുവെന്ന് ഞാൻ വിചാരിക്കുന്നു - ശേഷം രണ്ടാമതും പറയും: ആരാധ്യൻ അല്ലാഹു മാത്രമാണ്, അവൻ വലിയവനാകുന്നു. അപ്പോൾ മറ്റേ ഭാഗവും വീഴും. പിന്നെ മൂന്നാമതും പറയും: ആരാധ്യൻ അല്ലാഹു മാത്രമാകുന്നു, അവൻ വലിയവനുമാകുന്നു. അപ്പോൾ അവർക്കത് തുറന്നുകിട്ടുകയും അങ്ങനെ അതിൽ പ്രവേശിക്കുകയും യുദ്ധമുതൽ ശേഖരിക്കുകയും ചെയ്യും. ശേഷം അവർ മുതൽ വീതിക്കുമ്പോൾ ഒരാൾ അട്ടഹസിച്ചുകൊണ്ട് വന്ന് പറയും: നിശ്ചയം ദജ്ജാൽ പുറപ്പെട്ടിട്ടുണ്ട്. അപ്പോൾ അവർ എല്ലാം ഉപേക്ഷിച്ച് മടങ്ങും." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 713, 713, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 11, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا تَقُومُ السَّاعَةُ حَتَّى لَا يُقَالَ فِي الْأَرْضِ اللهُ اللهُ". (م,ت)', 'അനസ്(റ): റസൂൽ(സ) പറയുന്നു: "ഭൂമിയിൽ ''അല്ലാഹു, അല്ലാഹു'' എന്ന് പറയപ്പെടാതിരിക്കുംവരെ അന്ത്യനാൾ സംഭവിക്കുകയില്ല." (മു,തു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['م','ت']::text[], array['മു','തു']::text[], null, null, 714, 714, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 12, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ اللهَ يَبْعَثُ رِيحًا مِنَ الْيَمَنِ أَلْيَنَ مِنَ الْحَرِيرِ، فَلَا تَدَعُ أَحَدًا فِي قَلْبِهِ - قَالَ أَبُو عَلْقَمَةَ: مِثْقَالُ حَبَّةٍ، وَقَالَ عَبْدُ الْعَزِيزِ - مِثْقَالُ ذَرَّةٍ مِنْ إِيمَانٍ إِلَّا قَبَضَتْهُ". (م)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറയുന്നു: "യമനിൽ നിന്ന് പട്ടിനേക്കാൾ മൃദുലമായ ഒരു കാറ്റ് അല്ലാഹു അയക്കും. ഹൃദയത്തിൽ - അബൂഅൽഖമ(റ) പറയുന്നു: ഒരു ധാന്യത്തിന്റെ അളവ്, അബ്ദുൽ അസീസ്(റ) പറയുന്നു: - ഒരു അണുവിന്റെ അളവ് ഈമാനുള്ളവരെയെല്ലാം ആ കാറ്റ് മരിപ്പിക്കും." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 714, 714, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 13, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا تَقُومُ السَّاعَةُ إِلَّا عَلَى شِرَارِ النَّاسِ". (م)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): നബി(സ) പറഞ്ഞു: "ജനങ്ങളിലെ മോശപ്പെട്ടവരുടെ മേലല്ലാതെ അന്ത്യനാൾ സംഭവിക്കുകയില്ല." (മു)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 714, 714, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 14, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا تَقُومُ السَّاعَةُ حَتَّى يَخْرُجَ رَجُلٌ مِنْ قَحْطَانَ يَسُوقُ النَّاسَ بِعَصَاهُ". (م)', 'അബുഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "തന്റെ വടികൊണ്ട് ജനങ്ങളെ തെളിക്കുന്ന ഒരാൾ ഖഹ്ത്വാനിൽ നിന്ന് വരുന്നതുവരെ അന്ത്യനാൾ സംഭവിക്കുകയില്ല." (മു)', 'أَبِي هُرَيْرَةَ', 'അബുഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 714, 714, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 15, 'عَنْ حُذَيْفَةَ بْنِ الْيَمَانِ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا تَقُومُ السَّاعَةُ حَتَّى يَكُونَ أَسْعَدَ النَّاسِ بِالدُّنْيَا لُكَعُ بْنُ لُكَعٍ". (ت)', 'ഹുദൈഫതുബ്നുൽ യമാൻ(റ): റസൂൽ(സ) പറയുന്നു: "ജനങ്ങൾക്കിടയിൽ ദുൻയാവിന്റെ കാര്യത്തിൽ ഏറ്റവും വലിയ വിജയി ഒരു നീചനാകുന്നതുവരെ അന്ത്യനാൾ സംഭവിക്കുകയില്ല." (തു)', 'حُذَيْفَةَ بْنِ الْيَمَانِ', 'ഹുദൈഫതുബ്നുൽ യമാൻ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 714, 714, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 16, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا تَقُومُ السَّاعَةُ حَتَّى تَقْتَتِلَ فِئَتَانِ عَظِيمَتَانِ يَكُونُ بَيْنَهُمَا مَقْتَلَةٌ عَظِيمَةٌ دَعْوَتُهُمَا وَاحِدَةٌ، وَحَتَّى يُبْعَثَ دَجَّالُونَ كَذَّابُونَ قَرِيبٌ مِنْ ثَلَاثِينَ، كُلُّهُمْ يَزْعُمُ أَنَّهُ رَسُولُ اللهِ، وَحَتَّى يُقْبَضَ الْعِلْمُ، وَتَكْثُرَ الزَّلَازِلُ، وَيَتَقَارَبَ الزَّمَانُ، وَتَظْهَرَ الْفِتَنُ، وَيَكْثُرَ الْهَرْجُ وَهُوَ الْقَتْلُ، وَحَتَّى يَكْثُرَ فِيكُمُ الْمَالُ فَيَفِيضَ حَتَّى يُهِمَّ رَبَّ الْمَالِ مَنْ يَقْبَلُ صَدَقَتَهُ، وَحَتَّى يَعْرِضَهُ فَيَقُولَ الَّذِي يَعْرِضُهُ عَلَيْهِ لَا أَرَبَ لِي بِهِ، وَحَتَّى يَتَطَاوَلَ النَّاسُ فِي الْبُنْيَانِ، وَحَتَّى يَمُرَّ الرَّجُلُ بِقَبْرِ الرَّجُلِ فَيَقُولُ يَا لَيْتَنِي مَكَانَهُ، وَحَتَّى تَطْلُعَ الشَّمْسُ مِنْ مَغْرِبِهَا فَإِذَا طَلَعَتْ وَرَآهَا النَّاسُ آمَنُوا أَجْمَعُونَ، فَذَلِكَ حِينَ {لَا يَنْفَعُ نَفْسًا إِيمَانُهَا لَمْ تَكُنْ آمَنَتْ مِنْ قَبْلُ أَوْ كَسَبَتْ فِي إِيمَانِهَا خَيْرًا}. وَلَتَقُومَنَّ السَّاعَةُ وَقَدْ نَشَرَ الرَّجُلَانِ ثَوْبَهُمَا بَيْنَهُمَا، فَلَا يَتَبَايَعَانِهِ، وَلَا يَطْوِيَانِهِ، وَلَتَقُومَنَّ السَّاعَةُ وَقَدِ انْصَرَفَ الرَّجُلُ بِلَبَنِ لِقْحَتِهِ فَلَا يَطْعَمُهُ، وَلَتَقُومَنَّ السَّاعَةُ وَهُوَ يُلِيطُ حَوْضَهُ فَلَا يَسْقِي فِيهِ، وَلَتَقُومَنَّ السَّاعَةُ وَقَدْ رَفَعَ أُكْلَتَهُ إِلَى فِيهِ فَلَا يَطْعَمُهَا". (خ)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "രണ്ട് വലിയ സൈന്യം യുദ്ധം ചെയ്യുന്നതുവരെ അന്ത്യനാൾ സംഭവിക്കുകയില്ല. യുദ്ധം ഘോരമായിരിക്കും. രണ്ട് വിഭാഗത്തിന്റെയും വാദം ഒന്നായിരിക്കും. താൻ അല്ലാഹുവിന്റെ ദൂതനാണെന്ന് വാദിക്കുന്ന മുപ്പതോളം കള്ളന്മാരായ ദജ്ജാലുകൾ വരുന്നത് വരെയും, അറിവ് പിടക്കപ്പെടുന്നത് വരെയും, പ്രകമ്പനങ്ങൾ അധികരിക്കുന്നത് വരെയും, കാലങ്ങൾ അടുക്കുന്നത് വരെയും, ഫിത്ന പുറപ്പെടുന്നത് വരെയും, കൊല അധികരിക്കുന്നത് വരെയും, നിങ്ങളിൽ ധനം വർധിക്കുകയും അങ്ങനെ തന്റെ ദാനം സ്വീകരിക്കാൻ ആരാണുള്ളതെന്ന് മുതലിന്റെ ഉടമ ചിന്തിക്കുകയും അവനത് ഒരാൾക്ക് നൽകുമ്പോൾ എനിക്കത് ആവശ്യമില്ലെന്ന് പറയുകയും ചെയ്യുന്നത് വരെയും, കെട്ടിടം പണിയുന്നതിൽ ജനങ്ങൾ അഹന്ത നടിക്കുന്നത് വരെയും, ഖബറിന്റെയരികിലൂടെ ഒരാൾ നടക്കുമ്പോൾ ആ സ്ഥാനത്ത് ഞാനായിരുന്നെങ്കിലെന്ന് അവൻ പറയുന്നത് വരെയും, സൂര്യൻ പടിഞ്ഞാറിൽ നിന്ന് ഉദിക്കുന്നത് വരെയും (അന്ത്യനാൾ സംഭവിക്കുകയില്ല). അങ്ങനെ സൂര്യനുദിച്ച് ജനങ്ങൾ അത് കണ്ടാൽ അവർ മുഴുവനും വിശ്വസിക്കും. പക്ഷേ, മുമ്പ് വിശ്വസിക്കുകയോ തന്റെ വിശ്വാസത്തിനായി നന്മ പ്രവർത്തിക്കുകയോ ചെയ്തിട്ടില്ലാത്ത ഒരാൾക്കും തന്റെ വിശ്വാസം ഉപകരിക്കാത്ത സമയമാണത്. രണ്ടാളുകൾ വസ്ത്രം നിവർത്തി കച്ചവടം ചെയ്തുകൊണ്ടിരിക്കെ അന്ത്യനാൾ സംഭവിക്കും. അവർക്കത് കൈമാറാനോ മടക്കിവെക്കാനോ സാധിക്കില്ല. ഒരാൾ തന്റെ ഒട്ടകത്തിനെ കറന്ന് പാൽ കുടിക്കുന്നതിന് മുമ്പായിട്ട് അന്ത്യനാൾ സംഭവിക്കും. ഒരാൾ ഹൗള് നന്നാക്കുന്നു. പക്ഷേ, അതിൽ വെള്ളം നിറക്കുന്നതിന് മുമ്പ് അന്ത്യനാൾ സംഭവിക്കും. ഒരാൾ ഭക്ഷണത്തിന്റെ ഉരുള തന്റെ വായിലേക്കുയർത്തി അത് ഭക്ഷിക്കുന്നതിന് മുമ്പ് അന്ത്യനാൾ സംഭവിക്കും." (ബു,മു,ദ,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു','മു','ദ','ജ']::text[], null, null, 714, 715, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 17, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا تَقُومُ السَّاعَةُ حَتَّى يَحْسِرَ الْفُرَاتُ عَنْ جَبَلٍ مِنْ ذَهَبٍ، يَقْتَتِلُ النَّاسُ عَلَيْهِ، فَيُقْتَلُ مِنْ كُلِّ مِائَةٍ تِسْعَةٌ وَتِسْعُونَ، وَيَقُولُ كُلُّ رَجُلٍ مِنْهُمْ: لَعَلِّي أَكُونُ أَنَا الَّذِي أَنْجُو". (م)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "യൂഫ്രട്ടീസ് നദി വറ്റി സ്വർണ്ണത്തിന്റെ മല വെളിവാകുന്നത് വരെ അന്ത്യനാൾ സംഭവിക്കുകയില്ല. അതിന് വേണ്ടി ജനങ്ങൾ യുദ്ധം ചെയ്യും. അങ്ങനെ ഓരോ നൂറ് പേരിലും തൊണ്ണൂറ്റി ഒമ്പത് പേരും കൊല്ലപ്പെടും. അവരിൽ ഓരോരുത്തരും പറയും: രക്ഷപ്പെടുന്ന ആ വ്യക്തി ഞാനായിരുന്നെങ്കിൽ." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 715, 715, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 18, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا تَقُومُ السَّاعَةُ حَتَّى تَخْرُجَ نَارٌ مِنْ أَرْضِ الْحِجَازِ، تُضِيءُ أَعْنَاقَ الْإِبِلِ بِبُصْرَى". (ق)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ബുസ്റാ എന്ന സ്ഥലത്തെ ഒട്ടകങ്ങളുടെ കഴുത്തുകളെ പ്രകാശിപ്പിക്കുന്ന വിധത്തിൽ ഹിജാസിൽ നിന്ന് ഒരു തീ പുറപ്പെടുന്നതുവരെ അന്ത്യനാൾ സംഭവിക്കുകയില്ല." (ബു,മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], null, null, 715, 715, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 19, 'عَنْ عَبْدِ اللهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "سَتَخْرُجُ نَارٌ مِنْ حَضْرَمَوْتَ - أَوْ: مِنْ نَحْوِ بَحْرِ حَضْرَمَوْتَ - قَبْلَ يَوْمِ الْقِيَامَةِ، تَحْشُرُ النَّاسَ". قَالُوا: يَا رَسُولَ اللهِ، فَمَا تَأْمُرُنَا؟ قَالَ: "عَلَيْكُمْ بِالشَّامِ". حَسَنٌ صَحِيحٌ. (ت)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): റസൂൽ(സ) പറഞ്ഞു: "അന്ത്യനാളിന്റെ മുമ്പ് ഹളർമൗതിൽ നിന്ന് - അല്ലെങ്കിൽ ഹളർമൗതിലെ കടലിന്റെ ഭാഗത്ത് നിന്ന് - ഒരു തീ പുറപ്പെടും. അത് ജനങ്ങളെ ഒരുമിച്ചുകൂട്ടും." അവർ ചോദിച്ചു: തിരുദൂതരേ, അപ്പോൾ ഞങ്ങളോടെന്താണ് അവിടുന്ന് കൽപിക്കുന്നത്? തിരുമേനി(സ) പറഞ്ഞു: "നിങ്ങൾ ശാമിൽ പോകുക." (തു)', 'عَبْدِ اللهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 715, 715, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 20, 'عَنْ جَابِرِ بْنِ سَمُرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "إِنَّ بَيْنَ يَدَيِ السَّاعَةِ كَذَّابِينَ". وَفِي رِوَايَةٍ: قَالَ جَابِرٌ: "فَاحْذَرُوهُمْ". (م)', 'ജാബിറുബ്നു സമുറ(റ): റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "നിശ്ചയം അന്ത്യനാളിന്റെ മുമ്പ് കുറച്ച് കള്ളന്മാർ വരാനുണ്ട്." മറ്റൊരു റിപ്പോർട്ടിൽ: ജാബിർ(റ) പറയുന്നു: "അതുകൊണ്ട് അവരെ നിങ്ങൾ സൂക്ഷിക്കുക." (മു)', 'جَابِرِ بْنِ سَمُرَةَ', 'ജാബിറുബ്നു സമുറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 715, 716, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=13 and h.hadith_no=20), 1, 'وَفِي رِوَايَةٍ: قَالَ جَابِرٌ: "فَاحْذَرُوهُمْ". (م)', 'മറ്റൊരു നിവേദനിൽ: ജാബിർ(റ) പറയുന്നു: "അതുകൊണ്ട് അവരെ നിങ്ങൾ സൂക്ഷിക്കുക." (മു)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 21, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "وَالَّذِي نَفْسِي بِيَدِهِ، لَا تَذْهَبُ الدُّنْيَا حَتَّى يَمُرَّ الرَّجُلُ عَلَى الْقَبْرِ فَيَتَمَرَّغُ عَلَيْهِ، وَيَقُولُ: يَا لَيْتَنِي كُنْتُ مَكَانَ صَاحِبِ هَذَا الْقَبْرِ، وَلَيْسَ بِهِ الدِّينُ، إِلَّا الْبَلَاءُ". (م)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറയുന്നു: "എന്റെ ശരീരം ആരുടെ കയ്യിലാണോ അവൻ തന്നെ സത്യം, മനുഷ്യൻ ഖബറിന്റെ അരികിലൂടെ നടക്കുകയും അതിന്റെ മണ്ണിൽ കിടന്നുരുളുകയും ചെയ്യുന്നതുവരെ ദുൻയാവ് ഇല്ലാതാവുകയില്ല. അവൻ പറയുന്നുണ്ടാകും: ഈ ഖബറിലെ ആളുടെ സ്ഥാനത്ത് ഞാനായിരുന്നെങ്കിൽ. അവനിൽ ദീനില്ല, ബുദ്ധിമുട്ട് മാത്രമാണുള്ളത്." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 716, 716, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 22, 'عَنْ ثَوْبَانَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا تَقُومُ السَّاعَةُ حَتَّى تَلْحَقَ قَبَائِلُ مِنْ أُمَّتِي بِالْمُشْرِكِينَ، وَحَتَّى يَعْبُدُوا الْأَوْثَانَ. وَإِنَّهُ سَيَكُونُ فِي أُمَّتِي ثَلَاثُونَ كَذَّابُونَ، كُلُّهُمْ يَزْعُمُ أَنَّهُ نَبِيٌّ، وَأَنَا خَاتَمُ النَّبِيِّينَ لَا نَبِيَّ بَعْدِي". حَسَنٌ صَحِيحٌ. (ت)', 'സൗബാൻ(റ): റസൂൽ(സ) പറഞ്ഞു: "എന്റെ സമുദായത്തിലെ ചില കൂട്ടങ്ങൾ ബഹുദൈവാരാധകരോട് കൂടുകയും എന്നിട്ടവർ ബിംബങ്ങളെ ആരാധിക്കുകയും ചെയ്യുന്നതുവരെ അന്ത്യനാൾ സംഭവിക്കുകയില്ല. നിശ്ചയം എന്റെ സമുദായത്തിൽ മുപ്പത് കള്ളവാദികൾ വരും. അവരിലോരോരുത്തനും താൻ നബിയാണെന്ന് വാദിക്കും. ഞാൻ അന്ത്യപ്രവാചകനാകുന്നു, എന്റെ ശേഷം ഒരു പ്രവാചകനുമില്ല." (തു)', 'ثَوْبَانَ', 'സൗബാൻ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 716, 716, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 23, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا تَقُومُ السَّاعَةُ حَتَّى يُقَاتِلَ الْمُسْلِمُونَ التُّرْكَ، قَوْمًا وُجُوهُهُمْ كَالْمَجَانِّ الْمُطْرَقَةِ يَلْبَسُونَ الشَّعْرَ". (م,د,ن)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "മുസ്ലിംകൾ തുർക്കികളോട് യുദ്ധം ചെയ്യുന്നതുവരെ അന്ത്യനാൾ സംഭവിക്കുകയില്ല. രോമം കൊണ്ടുണ്ടാക്കിയ (വസ്ത്രങ്ങളും ചെരുപ്പുകളും) ധരിക്കുന്ന, തോൽ വെക്കപ്പെട്ട പരിചകൾ പോലെയുള്ള മുഖങ്ങളുള്ള വിഭാഗമാണവർ." (മു,ദ,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','د','ن']::text[], array['മു','ദ','ന']::text[], null, null, 716, 716, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 24, 'عَنْ بُرَيْدَةَ رَضِيَ اللهُ عَنْهُ: عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فِي حَدِيثِ يُقَاتِلُكُمْ قَوْمٌ صِغَارُ الْأَعْيُنِ يَعْنِي التُّرْكَ قَالَ: "تَسُوقُونَهُمْ ثَلَاثَ مِرَارٍ حَتَّى تُلْحِقُوهُمْ بِجَزِيرَةِ الْعَرَبِ، فَأَمَّا فِي السِّيَاقَةِ الْأُولَى فَيَنْجُو مَنْ هَرَبَ مِنْهُمْ، وَأَمَّا فِي الثَّانِيَةِ فَيَنْجُو بَعْضٌ وَيَهْلَكُ بَعْضٌ، وَأَمَّا فِي الثَّالِثَةِ فَيُصْطَلَمُونَ". أَوْ كَمَا قَالَ. (د)', 'ബുറൈദ(റ): നബി(സ) പറഞ്ഞു: "കുറിയ കണ്ണുകളുള്ള ഒരു വിഭാഗം നിങ്ങളോട് യുദ്ധം ചെയ്യും." അഥവാ തുർക്കികൾ എന്ന് തുടങ്ങുന്ന ഹദീസിൽ നബി(സ) പറയുന്നു: "അവരെ അറേബ്യൻ ദ്വീപിലെത്തിക്കും വരെ നിങ്ങൾ മൂന്ന് പ്രാവശ്യം തെളിച്ച് കൊണ്ടുപോകും, അപ്പോൾ ആദ്യ പ്രാവശ്യം അവരിൽ നിന്നും ഓടിപ്പോയവൻ രക്ഷപ്പെടും. രണ്ടാം പ്രാവശ്യം ചിലർ മരിക്കുകയും ചിലർ രക്ഷപ്പെടുകയും ചെയ്യും. മൂന്നാം പ്രാവശ്യം അവർ വേരോടെ പിഴുതെടുക്കപ്പെടും." അല്ലെങ്കിൽ നബി(സ) പറഞ്ഞതുപോലെ. (ദ)', 'بُرَيْدَةَ', 'ബുറൈദ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 716, 716, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 25, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: صَلَّى بِنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَوْمًا صَلَاةَ الْعَصْرِ بِنَهَارٍ، ثُمَّ قَامَ خَطِيبًا، فَلَمْ يَدَعْ شَيْئًا يَكُونُ إِلَى قِيَامِ السَّاعَةِ إِلَّا أَخْبَرَنَا بِهِ، حَفِظَهُ مَنْ حَفِظَهُ وَنَسِيَهُ مَنْ نَسِيَهُ، وَكَانَ فِيمَا قَالَ: "إِنَّ الدُّنْيَا حُلْوَةٌ خَضِرَةٌ، وَإِنَّ اللهَ مُسْتَخْلِفُكُمْ فِيهَا فَنَاظِرٌ كَيْفَ تَعْمَلُونَ. أَلَا، فَاتَّقُوا الدُّنْيَا وَاتَّقُوا النِّسَاءَ". وَكَانَ فِيمَا قَالَ: "أَلَا، لَا يَمْنَعَنَّ رَجُلًا هَيْبَةُ النَّاسِ أَنْ يَقُولَ بِحَقٍّ إِذَا عَلِمَهُ". قَالَ: فَبَكَى أَبُو سَعِيدٍ فَقَالَ: قَدْ وَاللهِ رَأَيْنَا أَشْيَاءَ فَهِبْنَا، فَكَانَ فِيمَا قَالَ: "أَلَا، إِنَّهُ يُنْصَبُ لِكُلِّ غَادِرٍ لِوَاءٌ يَوْمَ الْقِيَامَةِ بِقَدْرِ غَدْرَتِهِ، وَلَا غَدْرَةَ أَعْظَمُ مِنْ غَدْرَةِ إِمَامِ عَامَّةٍ، يُرْكَزُ لِوَاؤُهُ عِنْدَ اسْتِهِ". فَكَانَ فِيمَا حَفِظْنَا يَوْمَئِذٍ: "أَلَا، إِنَّ بَنِي آدَمَ خُلِقُوا عَلَى طَبَقَاتٍ شَتَّى: فَمِنْهُمْ مَنْ يُولَدُ مُؤْمِنًا وَيَحْيَا مُؤْمِنًا وَيَمُوتُ مُؤْمِنًا، وَمِنْهُمْ مَنْ يُولَدُ كَافِرًا وَيَحْيَا كَافِرًا وَيَمُوتُ كَافِرًا، وَمِنْهُمْ مَنْ يُولَدُ مُؤْمِنًا وَيَحْيَا مُؤْمِنًا وَيَمُوتُ كَافِرًا، وَمِنْهُمْ مَنْ يُولَدُ كَافِرًا وَيَحْيَا كَافِرًا وَيَمُوتُ مُؤْمِنًا، أَلَا، وَإِنَّ مِنْهُمُ الْبَطِيءَ الْغَضَبِ سَرِيعَ الْفَيْءِ، وَمِنْهُمْ سَرِيعُ الْغَضَبِ سَرِيعُ الْفَيْءِ، فَتِلْكَ بِتِلْكَ. أَلَا، وَإِنَّ مِنْهُمْ سَرِيعَ الْغَضَبِ بَطِيءَ الْفَيْءِ، أَلَا وَخَيْرُهُمْ بَطِيءُ الْغَضَبِ سَرِيعُ الْفَيْءِ، أَلَا وَشَرُّهُمْ سَرِيعُ الْغَضَبِ بَطِيءُ الْفَيْءِ، أَلَا وَإِنَّ مِنْهُمْ حَسَنَ الْقَضَاءِ حَسَنَ الطَّلَبِ، وَمِنْهُمْ سَيِّئُ الْقَضَاءِ حَسَنُ الطَّلَبِ، وَمِنْهُمْ حَسَنُ الْقَضَاءِ سَيِّئُ الطَّلَبِ، فَتِلْكَ بِتِلْكَ. أَلَا وَإِنَّ مِنْهُمُ السَّيِّئَ الْقَضَاءِ السَّيِّئَ الطَّلَبِ، أَلَا وَخَيْرُهُمُ الْحَسَنُ الْقَضَاءِ الْحَسَنُ الطَّلَبِ، أَلَا وَشَرُّهُمْ سَيِّئُ الْقَضَاءِ سَيِّئُ الطَّلَبِ. أَلَا وَإِنَّ الْغَضَبَ جَمْرَةٌ فِي قَلْبِ ابْنِ آدَمَ، أَمَا رَأَيْتُمْ إِلَى حُمْرَةِ عَيْنَيْهِ وَانْتِفَاخِ أَوْدَاجِهِ؟ فَمَنْ أَحَسَّ بِشَيْءٍ مِنْ ذَلِكَ فَلْيَلْصَقْ بِالْأَرْضِ". قَالَ: وَجَعَلْنَا نَلْتَفِتُ إِلَى الشَّمْسِ هَلْ بَقِيَ مِنْهَا شَيْءٌ؟ فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَلَا، إِنَّهُ لَمْ يَبْقَ مِنَ الدُّنْيَا فِيمَا مَضَى مِنْهَا إِلَّا كَمَا بَقِيَ مِنْ يَوْمِكُمْ هَذَا فِيمَا مَضَى مِنْهُ". حَسَنٌ صَحِيحٌ. (م,ت,جه)', 'അബൂസഈദിൽ ഖുദ്‌രി(റ): ഒരു ദിവസം ഞങ്ങളുമായി റസൂൽ(സ) അസർ നിസ്കരിച്ചു. ശേഷം പ്രസംഗിക്കാൻ എഴുന്നേറ്റു. അന്ത്യനാൾ വരെ ഉണ്ടാകുന്നതെല്ലാം ഞങ്ങളോട് പറഞ്ഞു. അത് മനഃപാഠമാക്കിയവർ മനഃപാഠമാക്കി. മറന്നവരെല്ലാം മറക്കുകയും ചെയ്തു. കൂട്ടത്തിൽ ഇങ്ങനെ പറഞ്ഞു: "ദുൻയാവ് സമ്പുഷ്ടമായതും മധുരവുമാകുന്നു. അതിൽ നിങ്ങളെ അല്ലാഹു പ്രതിനിധിയായി നിയോഗിക്കും. നിങ്ങളെന്താണ് ചെയ്യുന്നതെന്ന് അവൻ നോക്കും. അറിയുക, അതുകൊണ്ട് ദുൻയാവിനെയും സ്ത്രീകളെയും നിങ്ങൾ സൂക്ഷിക്കുക." റസൂൽ(സ) പറഞ്ഞതിൽ ഇങ്ങനെയുമുണ്ടായിരുന്നു: "അറിയുക, ജനങ്ങളോടുള്ള പേടി താൻ അറിഞ്ഞ സത്യം പറയുന്നതിൽ നിന്ന് ആരെയും തടയരുത്." നിവേദകൻ പറയുന്നു: അപ്പോൾ അബുസഈദ്(റ) കരഞ്ഞുകൊണ്ട് പറഞ്ഞു: അല്ലാഹുവാണ് സത്യം, ഞങ്ങൾ ഇന്ന് കുറേ കാര്യങ്ങൾ കണ്ട് ഭയപ്പെട്ടിരിക്കുന്നു. റസൂൽ(സ) ഇങ്ങനെയും പറഞ്ഞു: "വഞ്ചന ചെയ്തവന് അന്ത്യനാളിൽ തന്റെ വഞ്ചനയുടെ തോതനുസരിച്ചുള്ള പതാക ലഭിക്കും. ഒരു പൊതുനേതാവിന്റെ വഞ്ചനയേക്കാൾ വലുതായിട്ട് ഒരു വഞ്ചനയുമില്ല. അവന്റെ കൊടി തന്റെ ആസനത്തോടടുത്തായിരിക്കും നാട്ടപ്പെടുക." ഞങ്ങൾ അന്ന് മനഃപാഠമാക്കിയതിൽ ഇങ്ങനെയുമുണ്ട്: "അറിയുക, നിശ്ചയം ആദം സന്തതികൾ പല പദവികളിലാണ് സൃഷ്ടിക്കപ്പെട്ടിട്ടുള്ളത്. അവരിൽ മുഅ്മിനായി ജനിക്കുകയും മുഅ്മിനായി ജീവിക്കുകയും മുഅ്മിനായി തന്നെ മരിക്കുന്നവരുണ്ട്. കാഫിറായി ജനിക്കുകയും കാഫിറായി ജീവിക്കുകയും കാഫിറായി മരിക്കുകയും ചെയ്യുന്നവരുമുണ്ട്. മുഅ്മിനായി ജനിക്കുകയും മുഅ്മിനായി ജീവിക്കുകയും ചെയ്ത് കാഫിറായി മരിക്കുന്നവരുമുണ്ട്. കാഫിറായി ജനിക്കുകയും കാഫിറായി ജീവിക്കുകയും ചെയ്ത് മുഅ്മിനായി മരിക്കുന്നവരുമുണ്ട്. അറിയുക, നിശ്ചയം അവരിൽ പതുക്കെ ദേഷ്യപ്പെടുന്നവരും കാര്യങ്ങളിലേക്ക് പെട്ടെന്ന് മടങ്ങുന്നവരുമുണ്ട്. പെട്ടെന്ന് ദേഷ്യപ്പെടുന്നവരും പെട്ടെന്ന് കാര്യത്തിലേക്ക് മടങ്ങിവരുന്നവരുമുണ്ട്. പക്ഷേ, പെട്ടെന്നുള്ള ദേഷ്യം പെട്ടെന്നുള്ള മടങ്ങിവരവുമായി യോജിക്കും. അറിയുക, അവരിൽ പെട്ടെന്ന് ദേഷ്യപ്പെടുന്നവരും പതുക്കെ കാര്യത്തിലേക്ക് മടങ്ങിവരുന്നവരുമുണ്ട്. അറിയുക, അവരിൽ ഉത്തമർ പതുക്കെ ദേഷ്യപ്പെടുന്നവരും കാര്യത്തിലേക്ക് പെട്ടെന്ന് മടങ്ങിവരുന്നവരുണ്ട്. അവരിൽ ഏറ്റവും ദുഷിച്ചവൻ പെട്ടെന്ന് ദേഷ്യപ്പെടുന്നവരും കാര്യത്തിലേക്ക് പതുക്കെ മടങ്ങിവരുന്നവരുമാണ്. അറിയുക, അവരിൽ നല്ല നിലയിൽ വീട്ടുന്നവരും(കടം) നല്ലനിലയിൽ ആവശ്യപ്പെടുന്നവരും(കടം) ഉണ്ട്, അവരിൽ നല്ലനിലയിൽ ആവശ്യപ്പെടുന്നവരും മോശമായി വീട്ടുന്നവരുമുണ്ട്. അവരിൽ നല്ല രീതിയിൽ വീട്ടുകയും തെറ്റായ രീതിയിൽ ആവശ്യപ്പെടുകയും ചെയ്യുന്നവരുമുണ്ട്. അതിലൊന്ന്(നന്മ) മറ്റേതിന്(തിന്മക്ക്) പകരമാകും (അതുകൊണ്ട് പ്രശ്നമില്ല). അറിയുക, അവരിൽ തെറ്റായ രീതിയിൽ ആവശ്യപ്പെടുകയും തെറ്റായ രീതിയിൽ വീട്ടുന്നവരുമുണ്ട്. അറിയുക, അവരിൽ ഉത്തമർ ശരിയായി ആവശ്യപ്പെട്ട് ശരിയായി വീട്ടുന്നവരാകുന്നു. അവരിൽ ദുഷിച്ചവർ, തെറ്റായി ആവശ്യപ്പെട്ട് തെറ്റായി വീട്ടുന്നവരാകുന്നു. അറിയുക, ദേഷ്യം ആദം സന്തതിയുടെ ഹൃദയത്തിലെ തീക്കനലാകുന്നു. അവന്റെ കണ്ണിലെ ചുവപ്പും ഞരമ്പ് വീർത്തതും നിങ്ങൾ കണ്ടിട്ടില്ലേ? അങ്ങനെ ആർക്കെങ്കിലും സംഭവിച്ചാൽ അവൻ ഭൂമിയിൽ ഇരിക്കട്ടെ." നിവേദകൻ പറയുന്നു: വെയിൽ വല്ലതുമുണ്ടോ എന്ന് മനസ്സലാക്കാൻ വേണ്ടി ഞങ്ങൾ സൂര്യനെ നോക്കി. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "ഐഹിക ലോകത്തെ കഴിഞ്ഞ കാലങ്ങളോട് തട്ടിച്ചുനോക്കുമ്പോൾ അതിൽ ഇനി ശേഷിച്ചിരിക്കുന്നത്, ഈ ദിവസത്തെ കഴിഞ്ഞ ഭാഗത്തോട് തട്ടിച്ചുനോക്കുമ്പോൾ ശേഷിച്ച ഭാഗം എത്രയുണ്ടോ അത്രമാത്രമാണ്." (മു,തു,ജ)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്‌രി(റ)', null, null, array['م','ت','جه']::text[], array['മു','തു','ജ']::text[], null, null, 717, 718, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 26, 'عَنْ عَبْدِ اللهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: قِيلَ لِعُمَرَ بْنِ الْخَطَّابِ رَضِيَ اللهُ عَنْهُ: لَوِ اسْتَخْلَفْتَ؟ قَالَ: إِنْ أَسْتَخْلِفْ فَقَدِ اسْتَخْلَفَ أَبُو بَكْرٍ رَضِيَ اللهُ عَنْهُ، وَإِنْ لَمْ أَسْتَخْلِفْ لَمْ يَسْتَخْلِفْ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. صَحِيحٌ. (م,د,ت)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): ഉമറുബ്നുൽ ഖത്താബ്(റ)വിനോട് പറയപ്പെട്ടു: താങ്കൾ പ്രതിനിധിയെ വെച്ചിരുന്നെങ്കിൽ(നന്നായിരുന്നു). അദ്ദേഹം പറഞ്ഞു: ഞാൻ പ്രതിനിധിയെ നിശ്ചയിക്കുന്ന പക്ഷം, അബൂബക്കർ(റ) പ്രതിനിധിയെ വെച്ചിട്ടുണ്ട്. ഞാൻ പ്രതിനിധിയെ നിശ്ചയിക്കുന്നില്ലെങ്കിൽ റസൂൽ(സ) പ്രതിനിധിയെ വെച്ചിട്ടില്ല. (മു,ദ,തു)', 'عَبْدِ اللهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['م','د','ت']::text[], array['മു','ദ','തു']::text[], null, null, 718, 718, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 27, 'عَنْ سَعِيدِ بْنِ جُمْهَانَ رَضِيَ اللهُ عَنْهُ قَالَ: حَدَّثَنِي سَفِينَةُ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "الْخِلَافَةُ فِي أُمَّتِي ثَلَاثُونَ سَنَةً، ثُمَّ مُلْكٌ بَعْدَ ذَلِكَ". ثُمَّ قَالَ لِي سَفِينَةُ: أَمْسِكْ خِلَافَةَ أَبِي بَكْرٍ ثُمَّ قَالَ: وَخِلَافَةَ عُمَرَ وَخِلَافَةَ عُثْمَانَ، رَضِيَ اللهُ عَنْهُمْ. ثُمَّ قَالَ لِي: أَمْسِكْ خِلَافَةَ عَلِيٍّ رَضِيَ اللهُ عَنْهُ. قَالَ: فَوَجَدْنَاهَا ثَلَاثِينَ سَنَةً. حَسَنٌ. (د,ت)', 'സഈദുബ്നു ജുംഹാൻ(റ): സഫീനത്ത്(റ) എനിക്ക് ഹദീസ് പറഞ്ഞ് തന്നു. അദ്ദേഹം പറഞ്ഞു: റസൂലുല്ലാഹി(സ) പറഞ്ഞു: "ഖിലാഫത്ത് (പ്രാതിനിധ്യം) എനിക്ക് ശേഷം മുപ്പത് വർഷമാണ്. അതിനുശേഷം രാജഭരണമാണുണ്ടാകുക." പിന്നീട് എന്നോട് സഫീനത്ത്(റ) പറഞ്ഞു: അബൂബക്കർ(റ)വിന്റെയും ഉമർ(റ)വിന്റെയും ഉസ്മാൻ(റ)വിന്റെയും ഖിലാഫത്ത് (പ്രാതിനിധ്യം) നീ എണ്ണുക. പിന്നെ അദ്ദേഹം പറഞ്ഞു: അലി(റ)വിന്റെയും ഖിലാഫത്ത് നീ എണ്ണുക. നിവേദകൻ പറയുന്നു: അങ്ങനെ ഞങ്ങൾ അവ മൊത്തം മുപ്പത് വർഷമാണെന്ന് കണ്ടെത്തി. (ദ,തു)', 'سَعِيدِ بْنِ جُمْهَانَ', 'സഈദുബ്നു ജുംഹാൻ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 718, 718, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 28, 'عَنْ جَابِرِ بْنِ سَمُرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "يَكُونُ مِنْ بَعْدِي اثْنَا عَشَرَ أَمِيرًا". قَالَ: ثُمَّ تَكَلَّمَ بِشَيْءٍ لَمْ أَفْهَمْهُ، فَسَأَلْتُ الَّذِي يَلِينِي، فَقَالَ: "كُلُّهُمْ مِنْ قُرَيْشٍ". حَسَنٌ صَحِيحٌ. (ق,د,ت)', 'ജാബിറുബ്നു സമുറ(റ): റസൂൽ(സ) പറഞ്ഞു: "എനിക്ക് ശേഷം പന്ത്രണ്ട് അമീറുമാർ (നേതാക്കൾ) വരുന്നതാണ്." നിവേദകൻ പറയുന്നു: പിന്നീടവിടന്ന് എന്തോ പറഞ്ഞു. എനിക്ക് അത് മനസ്സിലായില്ല. അപ്പോൾ ഞാൻ എന്റെ അടുത്തുള്ളയാളോട് ചോദിച്ചു. അദ്ദേഹം പറഞ്ഞു: അവിടന്ന് പറഞ്ഞത്: "അവരെല്ലാം ഖുറൈശിൽ നിന്നാണ്." എന്നാണ്. (ബു,മു,ദ,തു)', 'جَابِرِ بْنِ سَمُرَةَ', 'ജാബിറുബ്നു സമുറ(റ)', null, null, array['ق','د','ت']::text[], array['ബു','മു','ദ','തു']::text[], null, null, 719, 719, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 29, 'عَنْ عَبْدِ اللهِ بْنِ أَبِي الْهُذَيْلِ قَالَ: كَانَ نَاسٌ مِنْ رَبِيعَةَ عِنْدَ عَمْرِو بْنِ الْعَاصِ رَضِيَ اللهُ عَنْهُ، فَقَالَ رَجُلٌ مِنْ بَكْرِ بْنِ وَائِلٍ: لَتَنْتَهِيَنَّ قُرَيْشٌ، أَوْ لَيَجْعَلَنَّ اللهُ هَذَا الْأَمْرَ فِي جُمْهُورٍ مِنَ الْعَرَبِ غَيْرِهِمْ. فَقَالَ عَمْرُو بْنُ الْعَاصِ: كَذَبْتَ، سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "قُرَيْشٌ وُلَاةُ النَّاسِ فِي الْخَيْرِ وَالشَّرِّ إِلَى يَوْمِ الْقِيَامَةِ". حَسَنٌ صَحِيحٌ. (ت)', 'അബ്ദുല്ലാഹിബ്നു അബിൽഹുദൈൽ(റ): റബീഅത്ത് ഗോത്രത്തിൽ പെട്ട ചിലയാളുകൾ അംറുബ്നുൽആസ്(റ)വിന്റെയടുത്തുണ്ടായിരുന്നു. അപ്പോൾ ബക്റുബ്നു വാഇലിൽ പെട്ട ഒരാൾ പറഞ്ഞു: ഖുറൈശികൾ ഇത് (അക്രമങ്ങൾ) അവസാനിപ്പിക്കുക തന്നെ ചെയ്യണം. അല്ലെങ്കിൽ, നിശ്ചയം അല്ലാഹു ഈ അധികാരം അറബികളിലെ, ഇവരല്ലാത്ത വലിയ വിഭാഗത്തിന് നൽകുക തന്നെ ചെയ്യും. അപ്പോൾ അംറുബ്നുൽആസ്(റ) പറഞ്ഞു: താങ്കൾ കള്ളം പറഞ്ഞിരിക്കുന്നു. റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "അന്ത്യനാൾ വരെ നന്മയിലും തിന്മയിലും ഖുറൈശികളാണ് ജനങ്ങളുടെ നേതാക്കൾ." (തു)', 'عَبْدِ اللهِ بْنِ أَبِي الْهُذَيْلِ قَالَ', 'അബ്ദുല്ലാഹിബ്നു അബിൽഹുദൈൽ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 719, 719, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 30, 'عَنْ جَابِرِ بْنِ سَمُرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَا يَزَالُ هَذَا الدِّينُ قَائِمًا حَتَّى يَكُونَ عَلَيْكُمُ اثْنَا عَشَرَ خَلِيفَةً، كُلُّهُمْ تَجْتَمِعُ عَلَيْهِ الْأُمَّةُ". فَسَمِعْتُ كَلَامًا مِنَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لَمْ أَفْهَمْهُ، قُلْتُ لِأَبِي: مَا يَقُولُ؟ قَالَ: "كُلُّهُمْ مِنْ قُرَيْشٍ". (د,ت)', 'ജാബിറുബ്നു സമുറത്(റ): തിരുദൂതർ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "പന്ത്രണ്ട് ഖലീഫമാർ നിങ്ങൾക്കുമേൽ വന്നുപോകുന്നതു വരെ ഈ ദീൻ നിലനിൽക്കും. അവരെക്കുറിച്ചെല്ലാം സമുദായം ഏകോപിതരായിരിക്കും." ശേഷം എനിക്ക് മനസ്സിലാക്കാൻ കഴിയാത്ത എന്തോ പ്രവാചകർ(സ) പറയുന്നത് ഞാൻ കേട്ടു. ഞാൻ എന്റെ പിതാവിനോട് ചോദിച്ചു: എന്താണ് അവിടുന്ന് പറയുന്നത്? പ്രവാചകർ(സ) പറഞ്ഞു: "അവരെല്ലാം ഖുറൈശികളായിരിക്കും." (ദ,തു)', 'جَابِرِ بْنِ سَمُرَةَ', 'ജാബിറുബ്നു സമുറത്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 719, 719, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 31, 'عَنْ جَابِرِ بْنِ سَمُرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَا يَزَالُ هَذَا الدِّينُ عَزِيزًا إِلَى اثْنَيْ عَشَرَ خَلِيفَةً". قَالَ: فَكَبَّرَ النَّاسُ وَضَجُّوا، ثُمَّ قَالَ كَلِمَةً خَفِيفَةً، قُلْتُ لِأَبِي: يَا أَبَتِ مَا قَالَ؟ قَالَ: "كُلُّهُمْ مِنْ قُرَيْشٍ". وَفِي رِوَايَةٍ زَادَ: فَلَمَّا رَجَعَ إِلَى مَنْزِلِهِ أَتَتْهُ قُرَيْشٌ، فَقَالُوا: ثُمَّ يَكُونُ مَاذَا؟ قَالَ: "ثُمَّ يَكُونُ الْهَرْجُ". (م,د,ت)', 'ജാബിറുബ്നു സമുറ(റ): തിരുദൂതർ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "പന്ത്രണ്ട് ഖലീഫമാർ വരുന്നതുവരെ ഈ ദീൻ പ്രതാപത്തോടെ നിലനിൽക്കും." നിവേദകൻ പറയുന്നു: ജനങ്ങൾ അപ്പോൾ തക്ബീർ മുഴക്കുകയും ശബ്ദമുണ്ടാക്കുകയും ചെയ്തു. ശേഷം പ്രവാചകർ(സ) ശബ്ദം താഴ്ത്തി എന്തോ പറഞ്ഞു: ഞാൻ എന്റെ പിതാവിനോട് ചോദിച്ചു: പിതാവേ, തിരുമേനി(സ) എന്താണ് പറഞ്ഞത്? നബി(സ) പറഞ്ഞു: "അവരെല്ലാം ഖുറൈശികളാണ്." മറ്റൊരു നിവേദനത്തിൽ ഇതുകൂടിയുണ്ട്: തിരുമേനി(സ) വീട്ടിലേക്ക് മടങ്ങിയപ്പോൾ ഖുറൈശികൾ വന്നുചോദിച്ചു: ശേഷം എന്തുണ്ടാവും? തിരുമേനി(സ) പറഞ്ഞു: "പിന്നെയങ്ങോട്ട് കുഴപ്പങ്ങളായിരിക്കും." (മു,ദ,തു)', 'جَابِرِ بْنِ سَمُرَةَ', 'ജാബിറുബ്നു സമുറ(റ)', null, null, array['م','د','ت']::text[], array['മു','ദ','തു']::text[], null, null, 719, 719, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=13 and h.hadith_no=31), 1, 'وَفِي رِوَايَةٍ زَادَ: فَلَمَّا رَجَعَ إِلَى مَنْزِلِهِ أَتَتْهُ قُرَيْشٌ، فَقَالُوا: ثُمَّ يَكُونُ مَاذَا؟ قَالَ: "ثُمَّ يَكُونُ الْهَرْجُ". (م,د,ت)', 'മറ്റൊരു നിവേദനത്തിൽ ഇതുകൂടിയുണ്ട്: തിരുമേനി(സ) വീട്ടിലേക്ക് മടങ്ങിയപ്പോൾ ഖുറൈശികൾ വന്നുചോദിച്ചു: ശേഷം എന്തുണ്ടാവും? തിരുമേനി(സ) പറഞ്ഞു: "പിന്നെയങ്ങോട്ട് കുഴപ്പങ്ങളായിരിക്കും." (മു,ദ,തു)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 32, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ، عَنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ اللهَ يَبْعَثُ لِهَذِهِ الْأُمَّةِ عَلَى رَأْسِ كُلِّ مِائَةِ سَنَةٍ مَنْ يُجَدِّدُ لَهَا دِينَهَا". (د)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "തീർച്ചയായും, അല്ലാഹു എല്ലാ നൂറ് വർഷങ്ങളുടെയും തുടക്കത്തിൽ ആ വർഷങ്ങളിൽ അന്നത്തെ ദീനിനെ നവീകരിക്കുന്ന ഒരാളെ ഈ സമുദായത്തിനായി അയക്കുന്നതാണ്." (ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 720, 720, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 33, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا يَذْهَبُ اللَّيْلُ وَالنَّهَارُ حَتَّى يَمْلِكَ رَجُلٌ مِنَ الْمَوَالِي يُقَالُ لَهُ: جَهْجَاهُ". حَسَنٌ. (م,ت)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ജഹ്ജാഹ് എന്ന് പേരുള്ള, അടിമകളിൽപെട്ട ഒരാൾ അധികാരം കൈപറ്റുന്നത് വരെ ദിനരാത്രങ്ങൾ കഴിഞ്ഞുപോവുകയില്ല." (മു,തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','ت']::text[], array['മു','തു']::text[], null, null, 720, 720, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 34, 'عَنْ ثَوْبَانَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّمَا أَخَافُ عَلَى أُمَّتِي الْأَئِمَّةَ الْمُضِلِّينَ". قَالَ: وَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا تَزَالُ طَائِفَةٌ مِنْ أُمَّتِي عَلَى الْحَقِّ ظَاهِرِينَ، لَا يَضُرُّهُمْ مَنْ يَخْذُلُهُمْ، حَتَّى يَأْتِيَ أَمْرُ اللهِ". حَسَنٌ صَحِيحٌ. (م,ت,جه)', 'സൗബാൻ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിശ്ചയം എന്റെ സമുദായത്തിന് മേൽ ഞാൻ ഭയപ്പെടുന്നത് വഴിപിഴപ്പിക്കുന്ന നേതാക്കളെ മാത്രമാണ്." നിവേദകൻ പറയുന്നു: റസൂൽ(സ) പറഞ്ഞു: "എന്റെ സമുദായത്തിൽ ഒരു വിഭാഗം സത്യത്തിന്മേൽ പ്രകടമായി തുടർന്ന് കൊണ്ടേയിരിക്കും. അവരെ നിന്ദിക്കുന്നവർക്കവരെ ബുദ്ധിമുട്ടിക്കാൻ കഴിയില്ല, അല്ലാഹുവിന്റെ കൽപന വരുന്നത് വരെ." (മു,തു,ജ)', 'ثَوْبَانَ', 'സൗബാൻ(റ)', null, null, array['م','ت','جه']::text[], array['മു','തു','ജ']::text[], null, null, 720, 720, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 35, 'عَنْ عُمَرَ بْنِ الْخَطَّابِ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "أَلَا أُخْبِرُكُمْ بِخِيَارِ أُمَرَائِكُمْ وَشِرَارِهِمْ؟ خِيَارُهُمُ الَّذِينَ تُحِبُّونَهُمْ وَيُحِبُّونَكُمْ، وَتَدْعُونَ لَهُمْ وَيَدْعُونَ لَكُمْ. وَشِرَارُ أُمَرَائِكُمُ الَّذِينَ تُبْغِضُونَهُمْ وَيُبْغِضُونَكُمْ، وَتَلْعَنُونَهُمْ وَيَلْعَنُونَكُمْ". حَسَنٌ. (ت)', 'ഉമറുബ്നുൽ ഖത്താബ്(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങളുടെ നേതാക്കളിലെ നല്ലവരെയും ദുഷിച്ചവരെയും ഞാൻ നിങ്ങൾക്ക് അറിയിച്ച് തരട്ടെയോ? നിങ്ങൾ അവരെയും അവർ നിങ്ങളെയും സ്നേഹിക്കുന്നവരാണ് അവരിലെ നല്ലയാളുകൾ. അവർ നിങ്ങൾക്കും നിങ്ങൾ അവർക്കും പ്രാർത്ഥിക്കുകയും ചെയ്യും. നിങ്ങൾ അവരെയും അവർ നിങ്ങളെയും ദേഷ്യംവെക്കുന്നവരാണ് നിങ്ങളുടെ നേതാക്കളിലെ ദുഷ്ടർ, അവർ നിങ്ങളെയും നിങ്ങൾ അവരെയും ശപിക്കുകയും ചെയ്യുന്നു." (തു)', 'عُمَرَ بْنِ الْخَطَّابِ', 'ഉമറുബ്നുൽ ഖത്താബ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 720, 720, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 36, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ مِنْ أَعْظَمِ الْجِهَادِ كَلِمَةَ عَدْلٍ عِنْدَ سُلْطَانٍ جَائِرٍ". حَسَنٌ. (د,ت,جه)', 'അബൂസഈദുൽ ഖുദ്‌രി(റ): റസൂൽ(സ) പറഞ്ഞു: "നിശ്ചയം, അക്രമകാരിയായ ഭരണാധിപന്റെയടുക്കൽ നീതിയുടെ വചനം പറയൽ ഏറ്റവും ഉന്നതമായ വിശുദ്ധ യുദ്ധത്തിൽ പെട്ടതാണ്." (ദ,തു,ജ)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദുൽ ഖുദ്‌രി(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 721, 721, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 37, 'عَنْ زِيَادِ بْنِ كُسَيْبٍ الْعَدَوِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: كُنْتُ مَعَ أَبِي بَكْرَةَ تَحْتَ مِنْبَرِ ابْنِ عَامِرٍ وَهُوَ يَخْطُبُ، وَعَلَيْهِ ثِيَابٌ رِقَاقٌ، فَقَالَ أَبُو بِلَالٍ: انْظُرُوا إِلَى أَمِيرِنَا، يَلْبَسُ ثِيَابَ الْفُسَّاقِ. فَقَالَ أَبُو بَكْرَةَ: اسْكُتْ، سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَنْ أَهَانَ سُلْطَانَ اللهِ فِي الْأَرْضِ أَهَانَهُ اللهُ". حَسَنٌ. (ت)', 'സിയാദുബ്നു കുസൈബിൽ അദവി(റ): ഇബ്നുആമിർ(റ) തന്റെമേൽ ലളിത വസ്ത്രങ്ങളുമായി ഖുത്ബ ചെയ്ത് കൊണ്ടിരിക്കെ, അദ്ദേഹത്തിന്റെ മിമ്പറിന് താഴെ അബൂബക്റ(റ)വിന്റെ കൂടെ ഞാനുണ്ടായിരുന്നു. അപ്പോൾ അബൂബിലാൽ(റ) പറഞ്ഞു: നിങ്ങൾ നമ്മുടെ നേതാവിനെ നോക്കൂ, തെമ്മാടികളുടെ വസ്ത്രങ്ങളാണ് അദ്ധേഹം ധരിച്ചിരിക്കുന്നത്. അപ്പോൾ അബൂബക്റ(റ) പറഞ്ഞു: മിണ്ടാതിരിക്കുക, റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടിട്ടുണ്ട്: "ആരെങ്കിലും ഭൂമിയിൽ അല്ലാഹുവിന്റെ അധികാരത്തെ നിസ്സാരമാക്കിയാൽ അവനെ അല്ലാഹു നിസ്സാരനാക്കുന്നതാണ്." (തു)', 'زِيَادِ بْنِ كُسَيْبٍ الْعَدَوِيِّ', 'സിയാദുബ്നു കുസൈബിൽ അദവി(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 721, 721, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 38, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ كَرِهَ مِنْ أَمِيرِهِ شَيْئًا فَلْيَصْبِرْ، فَإِنَّهُ مَنْ خَرَجَ مِنَ السُّلْطَانِ شِبْرًا مَاتَ مِيتَةً جَاهِلِيَّةً، وَفِي رِوَايَةٍ أُخْرَى عَنْهُ قَالَ: مَنْ رَأَى مِنْ أَمِيرِهِ شَيْئًا يَكْرَهُهُ فَلْيَصْبِرْ عَلَيْهِ، فَإِنَّهُ مَنْ فَارَقَ الْجَمَاعَةَ شِبْرًا فَمَاتَ إِلَّا مَاتَ مِيتَةً جَاهِلِيَّةً". (خ)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "ആരെങ്കിലും തന്റെ നായകനിൽ നിന്ന് വല്ലതും വെറുക്കുന്നുവെങ്കിൽ അവൻ ക്ഷമിക്കട്ടെ. കാരണം, ആരെങ്കിലും നേതാവിൽ നിന്ന് (വഴിപ്പെടുന്നതിൽ നിന്ന്) ഒരു ചാൺ വ്യതിചലിച്ചാൽ അവൻ അജ്ഞതയുടെ മരണം വരിച്ചു." മറ്റൊരു നിവേദനത്തിൽ: റസൂൽ(സ) പറഞ്ഞു: "താൻ വെറുക്കുന്ന വല്ലതും ആരെങ്കിലും തന്റെ അമീറിൽ (നേതാവിൽ) കണ്ടാൽ അവനത് ക്ഷമിക്കട്ടെ. കാരണം, ആരെങ്കിലും കൂട്ടത്തിൽ നിന്ന് ഒരു ചാൺ അകന്ന് നിന്നാൽ അവൻ അജ്ഞതയുടെ മരണം മാത്രമേ വരിക്കുകയൊള്ളൂ." (ബു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 721, 721, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=13 and h.hadith_no=38), 1, 'وَفِي رِوَايَةٍ أُخْرَى عَنْهُ قَالَ: مَنْ رَأَى مِنْ أَمِيرِهِ شَيْئًا يَكْرَهُهُ فَلْيَصْبِرْ عَلَيْهِ، فَإِنَّهُ مَنْ فَارَقَ الْجَمَاعَةَ شِبْرًا فَمَاتَ إِلَّا مَاتَ مِيتَةً جَاهِلِيَّةً". (خ)', 'മറ്റൊരു നിവേദനത്തിൽ: റസൂൽ(സ) പറഞ്ഞു: "താൻ വെറുക്കുന്ന വല്ലതും ആരെങ്കിലും തന്റെ അമീറിൽ (നേതാവിൽ) കണ്ടാൽ അവനത് ക്ഷമിക്കട്ടെ. കാരണം, ആരെങ്കിലും കൂട്ടത്തിൽ നിന്ന് ഒരു ചാൺ അകന്ന് നിന്നാൽ അവൻ അജ്ഞതയുടെ മരണം മാത്രമേ വരിക്കുകയൊള്ളൂ." (ബു)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 39, 'عَنْ حُذَيْفَةَ بْنِ الْيَمَانِ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ النَّاسُ يَسْأَلُونَ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنِ الْخَيْرِ، وَكُنْتُ أَسْأَلُهُ عَنِ الشَّرِّ مَخَافَةَ أَنْ يُدْرِكَنِي، فَقُلْتُ: يَا رَسُولَ اللهِ، إِنَّا كُنَّا فِي جَاهِلِيَّةٍ وَشَرٍّ فَجَاءَنَا اللهُ بِهَذَا الْخَيْرِ، فَهَلْ بَعْدَ هَذَا الْخَيْرِ مِنْ شَرٍّ؟ قَالَ: "نَعَمْ". قُلْتُ: وَهَلْ بَعْدَ ذَلِكَ الشَّرِّ مِنْ خَيْرٍ؟ قَالَ: "نَعَمْ، وَفِيهِ دَخَنٌ". قُلْتُ: وَمَا دَخَنُهُ؟ قَالَ: "قَوْمٌ يَهْدُونَ بِغَيْرِ هَدْيِي، تَعْرِفُ مِنْهُمْ وَتُنْكِرُ". قُلْتُ: فَهَلْ بَعْدَ ذَلِكَ الْخَيْرِ مِنْ شَرٍّ؟ قَالَ: "نَعَمْ، دُعَاةٌ عَلَى أَبْوَابِ جَهَنَّمَ، مَنْ أَجَابَهُمْ إِلَيْهَا قَذَفُوهُ فِيهَا". قُلْتُ: يَا رَسُولَ اللهِ، صِفْهُمْ لَنَا. قَالَ: "هُمْ مِنْ جِلْدَتِنَا وَيَتَكَلَّمُونَ بِأَلْسِنَتِنَا". قُلْتُ: فَمَا تَأْمُرُنِي إِنْ أَدْرَكَنِي ذَلِكَ؟ قَالَ: "تَلْزَمُ جَمَاعَةَ الْمُسْلِمِينَ وَإِمَامَهُمْ". قُلْتُ: فَإِنْ لَمْ يَكُنْ لَهُمْ جماعَةٌ وَلَا إِمَامٌ؟ قَالَ: "فَاعْتَزِلْ تِلْكَ الْفِرَقَ كُلَّهَا، وَلَوْ أَنْ تَعَضَّ بِأَصْلِ شَجَرَةٍ حَتَّى يُدْرِكَكَ الْمَوْتُ وَأَنْتَ عَلَى ذَلِكَ". (خ)', 'ഹൂദൈഫതുബ്നുൽ യമാൻ(റ): ജനങ്ങൾ റസൂലുല്ലാഹി(സ)യോട് നന്മയെക്കുറിച്ച് ചോദിക്കുമായിരുന്നു. എന്നാൽ ഞാൻ തിന്മയെക്കുറിച്ച് ചോദിക്കുമായിരുന്നു, അവയിൽ ചെന്ന് പെടാതിരിക്കാൻ വേണ്ടിയായിരുന്നു അത്. അങ്ങനെ ഞാൻ ചോദിച്ചു: അല്ലാഹുവിന്റെ ദൂതരേ, ഞങ്ങൾ അജ്ഞതയിലും തിന്മകളിലുമായിരുന്നു. അപ്പോൾ ഞങ്ങൾക്ക് ഈ നന്മ അല്ലാഹു കൊണ്ട് വന്നു. ഇനി ഈ നന്മക്ക് ശേഷം വല്ല തിന്മയുമുണ്ടോ? അവിടന്നരുളി: "അതെ." ഞാൻ ചോദിച്ചു: ആ തിന്മക്കു ശേഷം വല്ല നന്മയുമുണ്ടോ? അവിടന്ന് പറഞ്ഞു: "അതെ, എന്നാൽ അതിൽ കുഴപ്പമുണ്ട്." ഞാൻ ചോദിച്ചു: എന്താണ് അതിലെ കുഴപ്പം? അവിടന്ന് പറഞ്ഞു: "എന്റെ ചര്യയല്ലാത്ത ചര്യ സ്വീകരിക്കുന്ന ഒരു വിഭാഗമാണത്. അവരിൽ നീ തൃപ്തിപ്പെടുന്നതും വെറുക്കുന്നതുമായ കാര്യങ്ങളുണ്ടാകും." ഞാൻ ചോദിച്ചു: ആ നന്മക്കു ശേഷം വല്ല തിന്മയുമുണ്ടോ? അവിടന്ന് പറഞ്ഞു: "അതെ, നരകവാതിലുകളിലേക്ക് ക്ഷണിക്കുന്ന ചിലർ. അവർക്ക് ഉത്തരം ചെയ്തവനെ അവരതിൽ വീഴ്ത്തും." ഞാൻ പറഞ്ഞു: അല്ലാഹുവിന്റെ ദൂതരേ, അവിടുന്ന് ഞങ്ങൾക്ക് അവരെക്കുറിച്ച് വിവരിച്ചുതന്നാലും. അവിടുന്ന് പറഞ്ഞു: "അവർ നമ്മുടെ വർഗ്ഗത്തിൽ നിന്നുള്ളവരും നമ്മുടെ വിഷയങ്ങൾ സംസാരിക്കുന്നവരുമായിരിക്കും." ഞാൻ പറഞ്ഞു: അല്ലാഹുവിന്റെ ദൂതരേ, ഞാനക്കാലം എത്തിക്കുന്നുവെങ്കിൽ എന്താണ് ചെയ്യേണ്ടത്? അവിടുന്നരുളി: "നീ മുസ്‌ലിംകളുടെ സംഘത്തെയും അവരുടെ നേതാവിനെയും ചേർന്ന്നിൽക്കുക." ഞാൻ ചോദിച്ചു: അവർക്ക് സംഘമോ നേതാവോ ഇല്ലെങ്കിലോ? അവിടുന്ന് പറഞ്ഞു: "അപ്പോൾ നീ ആ വിഭാഗങ്ങളിൽ നിന്ന് മുഴുവൻ അകന്ന് നിൽക്കുക. നീ ഒരു മരത്തിന്റെ വേരിൽ കടിച്ച് പിടിക്കുകയം നീ അങ്ങനെയായിരിക്കെ നിനക്ക് മരണം സംഭവിക്കുകയും ചെയ്താൽ പോലും." (ബു)', 'حُذَيْفَةَ بْنِ الْيَمَانِ', 'ഹൂദൈഫതുബ്നുൽ യമാൻ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 721, 722, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 40, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "إِنَّ أُمَّتِي لَا تَجْتَمِعُ عَلَى ضَلَالَةٍ، فَإِذَا رَأَيْتُمُ اخْتِلَافًا فَعَلَيْكُمْ بِالسَّوَادِ الْأَعْظَمِ". [ز: فِي سَنَدِهِ ضَعِيفٌ] (جه)', 'അനസുബ്നു മാലിക്(റ): റസൂലുല്ലാഹി(സ) പറയുന്നത് ഞാൻ കേട്ടു: "തീർച്ചയായും എന്റെ സമുദായം തിന്മയുടെ മേൽ സംഘടിക്കുകയില്ല. അതിനാൽ നിങ്ങൾ വല്ല ഭിന്നിപ്പും കണ്ടാൽ വലിയ ഭൂരിപക്ഷത്തിന്റെ കൂടെ നിൽക്കണം." പരമ്പരയിൽ ഒരു ബലഹീനനുണ്ട്. (ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: فِي سَنَدِهِ ضَعِيفٌ', null, 722, 722, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 41, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ، وَقَدْ شُكِيَ إِلَيْهِ مَا لَقِيَ النَّاسُ مِنَ الْحَجَّاجِ، فَقَالَ: اصْبِرُوا، فَإِنَّهُ لَا يَأْتِي عَلَيْكُمْ زَمَانٌ إِلَّا الَّذِي بَعْدَهُ شَرٌّ مِنْهُ حَتَّى تَلْقَوْا رَبَّكُمْ، سَمِعْتُهُ مِنْ نَبِيِّكُمْ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. (خ)', 'അനസുബ്നു മാലിക്(റ): ഹജ്ജാജിൽ നിന്ന് ജനങ്ങൾ അനുഭവിക്കുന്നത് അദ്ദേഹത്തോട് ആവലാതി പറയപ്പെട്ടപ്പോൾ അദ്ദേഹം പറഞ്ഞു: നിങ്ങൾ ക്ഷമിക്കുക. കാരണം നിങ്ങളുടെ നാഥനെ നിങ്ങൾ കണ്ടുമുട്ടുവോളം നിങ്ങൾക്ക് ഏത് കാലം വന്നാലും അതിന് പിറകെ വരുന്നത് അതിനേക്കാൾ മോശമായത് തന്നെയായിരിക്കും. ഇത് ഞാൻ നിങ്ങളുടെ പ്രവാചകനിൽ നിന്ന് കേട്ടതാണ്. (ബു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 722, 722, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 42, 'عَنْ عُبَادَةَ بْنِ الصَّامِتِ رَضِيَ اللهُ عَنْهُ قَالَ: دَعَانَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَبَايَعْنَاهُ، فَقَالَ فِيمَا أَخَذَ عَلَيْنَا: أَنْ بَايَعَنَا عَلَى السَّمْعِ وَالطَّاعَةِ فِي مَنْشَطِنَا وَمَكْرَهِنَا، وَعُسْرِنَا وَيُسْرِنَا، وَأَثَرَةً عَلَيْنَا، وَأَنْ لَا نُنَازِعَ الْأَمْرَ أَهْلَهُ، إِلَّا أَنْ تَرَوْا كُفْرًا بَوَاحًا، عِنْدَكُمْ مِنَ اللَّهِ فِيهِ بُرْهَانٌ. (خ)', 'ഉബാദത്തുബ്നു സ്വാമിത്(റ): തിരുനബി(സ) ഞങ്ങളെ ക്ഷണിച്ചു. ഞങ്ങൾ അവിടത്തോട് ബൈഅത്ത് ചെയ്തു. ഇക്കാര്യങ്ങൾ അവിടുന്ന് ഞങ്ങളോട് ഉടമ്പടി ചെയ്തതിൽ പെട്ടതാണ്: ഞങ്ങൾക്ക് ഉന്മേശമുണ്ടാകുന്ന നേരത്തും മടുപ്പ് തോന്നുന്ന സമയത്തും ഞങ്ങൾക്ക് പ്രയാസം നേരിടുന്ന നേരത്തും ആശ്വാസ സമയത്തും ഞങ്ങൾ (അങ്ങയെ) കേൾക്കുകയും അനുസരിക്കുകയും ചെയ്യും, ഞങ്ങളേക്കാൾ മറ്റുള്ളവർക്ക് മുൻഗണന നൽകും, അല്ലാഹുവിന്റെ ഭാഗത്തുനിന്ന് ലക്ഷ്യമുള്ളതായ പ്രകടമായ സത്യനിഷേധം കണ്ടാലൊഴികെ നേതൃത്വത്തിന്റെ ആളുകളോട് നേതൃത്വ വിഷയത്തിൽ ഞങ്ങൾ തർക്കിക്കുകയില്ല. (ബു)', 'عُبَادَةَ بْنِ الصَّامِتِ', 'ഉബാദത്തുബ്നു സ്വാമിത്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 722, 723, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 43, 'عَنْ وَائِلِ بْنِ حُجْرٍ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَرَجُلٌ سَأَلَهُ، فَقَالَ: أَرَأَيْتَ إِنْ كَانَ عَلَيْنَا أُمَرَاءُ، يَمْنَعُونَا حَقَّنَا وَيَسْأَلُونَا حَقَّهُمْ؟ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "اسْمَعُوا وَأَطِيعُوا، فَإِنَّمَا عَلَيْهِمْ مَا حُمِّلُوا وَعَلَيْكُمْ مَا حُمِّلْتُمْ". حَسَنٌ صَحِيحٌ. (م,ت)', 'വാഇലുബ്നു ഹുജ്ർ(റ): ഞങ്ങളുടെ അവകാശങ്ങൾ തടയുകയും സ്വന്തം അവകാശങ്ങൾ ഞങ്ങളോട് ചോദിക്കുകയും ചെയ്യുന്ന നേതാക്കൾ ഞങ്ങൾക്കുണ്ടായാൽ എന്തുചെയ്യണമെന്ന് പറഞ്ഞു തരിക എന്ന് ഒരാൾ റസൂൽ(സ)യോട് പറഞ്ഞപ്പോൾ അവിടന്ന് പറയുന്നത് ഞാൻ കേട്ടു: "നിങ്ങൾ അവരെ കേൾക്കുക, അവർക്കനുസരിക്കുകയും ചെയ്യുക. കാരണം നിശ്ചയം അവർക്ക് ഏൽപിക്കപ്പെട്ടത് അവരുടെ മേലിലാണ്. നിങ്ങൾക്ക് ഏൽപിക്കപ്പെട്ടത് നിങ്ങളുടെ മേലിലുമുണ്ടായിരിക്കും." (മു,തു)', 'وَائِلِ بْنِ حُجْرٍ', 'വാഇലുബ്നു ഹുജ്ർ(റ)', null, null, array['م','ت']::text[], array['മു','തു']::text[], null, null, 723, 723, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 44, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: خَطَبَنَا عُمَرُ رَضِيَ اللهُ عَنْهُ بِالْجَابِيَةِ فَقَالَ: يَا أَيُّهَا النَّاسُ، إِنِّي قُمْتُ فِيكُمْ كَمَقَامِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِينَا، فَقَالَ: "أُوصِيكُمْ بِأَصْحَابِي، ثُمَّ الَّذِينَ يَلُونَهُمْ، ثُمَّ الَّذِينَ يَلُونَهُمْ، ثُمَّ يَفْشُو الْكَذِبُ، حَتَّى يَحْلِفَ الرَّجُلُ وَلَا يُسْتَحْلَفُ، وَيَشْهَدَ الشَّاهِدُ وَلَا يُسْتَشْهَدُ، أَلَا، لَا يَخْلُوَنَّ رَجُلٌ بِامْرَأَةٍ إِلَّا كَانَ ثَالِثَهُمَا الشَّيْطَانُ، عَلَيْكُمْ بِالْجَمَاعَةِ، وَإِيَّاكُمْ وَالْفُرْقَةَ، فَإِنَّ الشَّيْطَانَ مَعَ الْوَاحِدِ، وَهُوَ مِنَ الِاثْنَيْنِ أَبْعَدُ، مَنْ أَرَادَ بُحْبُوحَةَ الْجَنَّةِ فَلْيَلْزَمِ الْجَمَاعَةَ. مَنْ سَرَّتْهُ حَسَنَتُهُ وَسَاءَتْهُ سَيِّئَتُهُ فَذَلِكُمُ الْمُؤْمِنُ". حَسَنٌ صَحِيحٌ. (ت,جه)', 'ഇബ്നുഉമർ(റ): ജാബിയ എന്ന സ്ഥലത്തുവെച്ച് ഉമർ(റ) ഞങ്ങളോട് പ്രസംഗിച്ചു. അദ്ദേഹം പറഞ്ഞു: ജനങ്ങളേ, ഞങ്ങൾക്കിടയിൽ റസൂലുല്ലാഹി(സ) നിന്നതുപോലെ ഞാൻ നിങ്ങൾക്കിടയിൽ നിൽക്കുന്നു. അവിടുന്ന് പറയുകയുണ്ടായി: "എന്റെ അനുചരരുടെ പിന്നെ അവരോടടുത്തവരുടെ, പിന്നെ അവരോടടുത്തവരുടെ വിഷയത്തിൽ ഞാൻ നിങ്ങളോട് വസിയ്യത്ത് ചെയ്യുന്നു. പിന്നീട് കള്ളം പറയൽ അധികമാകും. അങ്ങനെ സത്യംചെയ്യാൻ ആവശ്യപെടാതെത്തന്നെ ഒരാൾ സത്യംചെയ്യും. സാക്ഷിത്വം ചോദിക്കപ്പെടാതെ തന്നെ ഒരാൾ സാക്ഷ്യം വഹിക്കും. അറിയുക, ഒരു പുരുഷനും സ്ത്രീയും തനിച്ചായാൽ മൂന്നാമനായി പിശാചില്ലാതെയിരിക്കുകയില്ല തന്നെ. നിങ്ങൾ സംഘത്തിലായിരിക്കണം. വേറിട്ടുപോകൽ നിങ്ങൾ സൂക്ഷിക്കണം. കാരണം ഒറ്റയാന്റെ കൂടെ പിശാചുണ്ടാകും. രണ്ടാൾ ഉള്ളയിടത്ത് അവൻ ഏറെ ദൂരത്തുമായിരിക്കും. സ്വർഗ്ഗസുഖം ആരുദ്ദേശിക്കുന്നുവോ അവൻ സംഘത്തോട് കൂടെ എപ്പോഴുമുണ്ടായിരിക്കണം. ആർക്കങ്കിലും തന്റെ നന്മ സന്തോഷമുണ്ടാക്കുകയും തന്നിലെ ദുഷ്ടത ബുദ്ധിമുട്ടാക്കുകയും ചെയ്യുന്നുവെങ്കിൽ അവനാണ് യഥാർത്ഥ സത്യവിശ്വാസി." (തു,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 723, 723, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 45, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "يَدُ اللَّهِ مَعَ الْجَمَاعَةِ". (ت)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂലുല്ലാഹി(സ) പറഞ്ഞു: "അല്ലാഹുവിന്റെ കരം (സഹായം) സംഘത്തിന് കൂടെയാണ്." (തു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 723, 723, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 46, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ اللَّهَ لَا يَجْمَعُ أُمَّتِي - أَوْ قَالَ: أُمَّةَ مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - عَلَى ضَلَالَةٍ، وَيَدُ اللَّهِ مَعَ الْجَمَاعَةِ، وَمَنْ شَذَّ شَذَّ إِلَى النَّارِ". (ت)', 'ഇബ്നുഉമർ(റ): റസൂലുല്ലാഹി(സ) പറഞ്ഞു: "നിശ്ചയം, അല്ലാഹു എന്റെ സമുദായത്തെ - അല്ലെങ്കിൽ അവിടന്ന് പറഞ്ഞത്: മുഹമ്മദ്(സ)യുടെ സമുദായത്തെ എന്നാണ് - വഴികേടിൽ ഒരുമിച്ചുകൂട്ടുകയില്ല. അല്ലാഹുവിന്റെ കരം (സഹായം) സംഘത്തിന്റെ കൂടെയാണ്. ആരെങ്കിലും വേറിട്ടുനിന്നാൽ അവൻ നരകത്തിലെറിയപ്പെടും." (തു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 723, 724, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 47, 'عَنْ عَوْفِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَنْ يَجْمَعَ اللَّهُ عَلَى هَذِهِ الْأُمَّةِ سَيْفَيْنِ: سَيْفًا مِنْهَا، وَسَيْفًا مِنْ عَدُوِّهَا". (د)', 'ഔഫുബ്നു മാലിക്(റ): റസൂൽ(സ) പറഞ്ഞു: "ഈ സമുദായത്തിനെതിരിൽ രണ്ട് വാളുകൾ ഒരമിക്കുകയില്ല: ഒന്ന് ഈ സമുദായത്തിൽ നിന്ന് തന്നെ. ഒരു വാൾ അതിന്റെ ശത്രുവിൽ നിന്നും." (ദ)', 'عَوْفِ بْنِ مَالِكٍ', 'ഔഫുബ്നു മാലിക്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 724, 724, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 48, 'عَنْ جابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَا عَلَى الْأَرْضِ نَفْسٌ مَنْفُوسَةٌ الْيَوْمَ، تأْتِي عَلَيْهَا مِائَةُ سَنَةٍ". حَسَنٌ. (م,ت)', 'ജാബിർ(റ): റസൂലുല്ലാഹി(സ) പറഞ്ഞു: "ഇന്ന് ഭൂമിയിലുള്ള ജീവനുള്ള ഒരു ശരീരവും നൂറ് വർഷങ്ങൾ കഴിയുമ്പോൾ ഉണ്ടാവുകയില്ല." (മു,തു)', 'جابِرٍ', 'ജാബിർ(റ)', null, null, array['م','ت']::text[], array['മു','തു']::text[], null, null, 724, 724, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 49, 'عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: صَلَّى بِنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ذَاتَ لَيْلَةٍ صَلَاةَ الْعِشَاءِ آخِرَ حَيَاتِهِ، فَلَمَّا سَلَّمَ قَالَ: "أَرَأَيْتَكُمْ لَيْلَتَكُمْ هَذِهِ؟ عَلَى رَأْسِ مِائَةِ سَنَةٍ مِنْهَا لَا يَبْقَى مِمَّنْ هُوَ عَلَى ظَهْرِ الْأَرْضِ أَحَدٌ". قَالَ ابْنُ عُمَرَ رَضِيَ اللهُ عَنْهُ: فَوَهِلَ النَّاسُ فِي مَقَالَةِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ تلْكَ، فِيمَا يَتَحَدَّثُونَهُ مِنْ هَذِهِ الْأَحَادِيثِ عَنْ مِائَةِ سَنَةٍ، وَإِنَّمَا قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا يَبْقَى مِمَّنْ هُوَ الْيَوْمَ عَلَى ظَهْرِ الْأَرْضِ أَحَدٌ". يُرِيدُ بِذَلِكَ أَنْ يَنْخَرِمَ ذَلِكَ الْقَرْنُ. صَحِيحٌ. (ق,د,ت,ن)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): തന്റെ ജീവിതാവസാനങ്ങളിൽ, ഒരു രാത്രിയിൽ റസൂലുല്ലാഹി(സ) ഞങ്ങളുമായി ഇശാഅ് നിസ്കരിച്ചു. സലാം വീട്ടിയപ്പോൾ അവിടുന്ന് പറഞ്ഞു: "നിങ്ങളുടെ ഈ രാത്രിയെക്കുറിച്ച് നിങ്ങളുടെ അഭിപ്രായമെന്താണ്? ഈ രാത്രി തൊട്ട് നൂറ് വർഷം തികയുമ്പോൾ ഇന്ന് ഭൂമിക്ക് മുകളിലുള്ള ഒരാളും ഉണ്ടാവുകയില്ല." ഇബ്നുഉമർ(റ) പറഞ്ഞു: അപ്പോൾ റസൂലുല്ലാഹി(സ)യുടെ ആ വാക്ക് കാരണം ജനങ്ങൾ ഭയത്തിലായി. അവർ സംസാരിക്കുന്ന സംസാരങ്ങൾ നൂറ് വർഷത്തെക്കുറിച്ചായിരുന്നു. നിശ്ചയം റസൂൽ(സ) പറഞ്ഞത് "ഇന്ന് ഭൂമുഖത്തുള്ള ഒരാളും ശേഷിച്ചിരിക്കില്ല" എന്ന് മാത്രമാണ്. അതുകൊണ്ട് അവിടുന്ന് ഉദ്ദേശിക്കുന്നത് ആ നൂറ്റാണ്ട് കഴിഞ്ഞുപോകുമെന്നാണ്. (ബു,മു,ദ,തു,ന)', 'عَبْدِ اللَّهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['ق','د','ت','ن']::text[], array['ബു','മു','ദ','തു','ന']::text[], null, null, 724, 724, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 50, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "بُعِثْتُ أَنَا وَالسَّاعَةُ كَهَاتَيْنِ". وَجَمَعَ بَيْنَ إِصْبَعَيْهِ. (خ,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഞാനും അന്ത്യനാളും ഇവ രണ്ടും പോലെയാണ് നിയോഗിക്കപ്പെട്ടത്." അവിടന്ന് അവിടത്തെ രണ്ട് വിരലുകൾ കൂട്ടിപ്പിടിക്കുകയും ചെയ്തു. (ബു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ','جه']::text[], array['ബു','ജ']::text[], null, null, 724, 724, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 51, 'عَنْ عَوْفِ بْنِ مَالِكٍ الْأَشْجَعِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: أَتَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ فِي غَزْوَةِ تَبُوكَ، وَهُوَ فِي خِبَاءٍ مِنْ أَدَمٍ، فَجَلَسْتُ بِفِنَاءِ الْخِبَاءِ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أُدْخُلْ يَا عَوْفُ". فَقُلْتُ: بِكُلِّي يَا رَسُولَ اللَّهِ؟ قَالَ: "بِكُلِّكَ". ثُمَّ قَالَ: "يَا عَوْفُ، احْفَظْ خِلَالًا سِتًّا بَيْنَ يَدَيِ السَّاعَةِ: إِحْدَاهُنَّ مَوْتِي". قَالَ: فَوَجَمْتُ عِنْدَهَا وَجْمَةً شَدِيدَةً، فَقَالَ: "قُلْ: إِحْدَى، ثُمَّ فَتْحُ بَيْتِ الْمَقْدِسِ، ثُمَّ دَاءٌ يَظْهَرُ فِيكُمْ يَسْتَشْهِدُ اللَّهُ بِهِ ذَرَارِيَّكُمْ وَأَنْفُسَكُمْ وَيُزَكِّي بِهِ أَعْمَالَكُمْ، ثُمَّ تَكُونُ الْأَمْوَالُ فِيكُمْ حَتَّى يُعْطَى الرَّجُلُ مِائَةَ دِينَارٍ فَيَظَلَّ سَاخِطًا، وَفِتْنَةٌ تَكُونُ بَيْنَكُمْ لَا يَبْقَى بَيْتُ مُسْلِمٍ إِلَّا دَخَلَتْهُ، ثُمَّ تَكُونُ بَيْنَكُمْ وَبَيْنَ بَنِي الْأَصْفَرِ هُدْنَةٌ فَيَغْدِرُونَ بِكُمْ، فَيَسِيرُونَ إِلَيْكُمْ فِي ثَمَانِينَ غَايَةٍ، تَحْتَ كُلِّ غَايَةٍ اثْنَا عَشَرَ أَلْفًا". (خ,د,جه)', 'ഔഫുബിനു മാലികിൽ അശ്ജഈ(റ): തബൂഖ് യുദ്ധത്തിൽ തോലിന്റെ ഒരു കൂടാരത്തിൽ നബി(സ)യുടെ അടുത്ത് ഞാൻ ചെന്നു. കൂടാരത്തിന്റെ മുറ്റത്ത് ഞാൻ ഇരുന്നു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "ഓ ഔഫ് കടന്ന് വരിക." അപ്പോൾ ഞാൻ ചോദിച്ചു: ഞാൻ പൂർണ്ണമായി കടക്കട്ടെയോ? അവിടുന്ന് പറഞ്ഞു: "പൂർണ്ണമായും കടക്കുക." തിരുമേനി(സ) പറഞ്ഞു: "ഔഫ്, അന്ത്യനാളിന്റെ മുമ്പ് ആറ് കാര്യങ്ങളെ താങ്കൾ സൂക്ഷിക്കുക. അതിൽ ഒന്നാമത്തേത് എന്റെ മരണമാണ്." അദ്ദേഹം പറയുന്നു: അപ്പോൾ എനിക്ക് ശക്തമായി വേദനിച്ചു. അപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: "താങ്കൾ പറയുക, ഒന്ന്. പിന്നെ ബൈത്തുൽ മുഖദ്ദസ് കീഴക്കപ്പെടലാണ്. പിന്നെ നിങ്ങൾക്കൊരു രോഗം പ്രത്യക്ഷപ്പെടും. അല്ലാഹു നിങ്ങളെയും നിങ്ങളുടെ സന്താനങ്ങളെയും അതിന് ഇരകളാക്കും, അതുകൊണ്ട് നിങ്ങളുടെ പ്രവർത്തനങ്ങളെ അവൻ ശുദ്ധീകരിക്കുകയും ചെയ്യും. പിന്നെ നിങ്ങൾക്ക് ധാരാളം മുതൽ വരും. അങ്ങനെ നൂറ് ദീനാർ വരെ ഒരാൾക്ക് നൽകപ്പെട്ടാലും അയാൾ ദേഷ്യപ്പെടും. പിന്നെ നിങ്ങൾക്കിടയിൽ ഒരു ഫിത്നയുണ്ടാകും. എല്ലാ മുസ്‌ലിമിന്റെ വീട്ടിലും അതെത്തും. പിന്നെ നിങ്ങളുടെയും റോമക്കാരുടെയുമിടയിൽ ഒരു സന്ധിയുണ്ടാകും. അതിൽ അവർ നിങ്ങളെ വഞ്ചിക്കും. അങ്ങനെ എമ്പത് കൊടികളിലായി നിങ്ങളിലേക്ക് അവർ വരും. ഓരോ കൊടിക്ക് കീഴിലും പന്ത്രണ്ടായിരം പേരുണ്ടാകും." (ബു,ദ,ജ)', 'عَوْفِ بْنِ مَالِكٍ الْأَشْجَعِيِّ', 'ഔഫുബിനു മാലികിൽ അശ്ജഈ(റ)', null, null, array['خ','د','جه']::text[], array['ബു','ദ','ജ']::text[], null, null, 724, 725, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 52, 'عَنْ حُذَيْفَةَ بْنِ الْيَمَانِ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا تَقُومُ السَّاعَةُ حَتَّى تَقْتُلُوا إِمَامَكُمْ، وَتَجْتَلِدُوا بِأَسْيَافِكُمْ، وَيَرِثَ دُنْيَاكُمْ شِرَارُكُمْ". (ت,جه)', 'ഹുദൈഫതുബ്നുൽ യമാൻ(റ): റസൂൽ(സ) പറയുന്നു: "നിങ്ങളുടെ നേതാവിനെ കൊല്ലുന്നതുവരെയും നിങ്ങളുടെ വാളുകൾ കൊണ്ട് കൊലനടത്തുന്നതുവരെയും നിങ്ങളുടെ ദുൻയാവ് നിങ്ങളിലെ മോശപ്പെട്ടവർ അനന്തരമായി എടുക്കുന്നതുവരെയും അന്ത്യനാൾ സംഭവിക്കുകയില്ല." (തു,ജ)', 'حُذَيْفَةَ بْنِ الْيَمَانِ', 'ഹുദൈഫതുബ്നുൽ യമാൻ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 725, 725, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 53, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمًا بَارِزًا لِلنَّاسِ، فَأَتَاهُ رَجُلٌ فَقَالَ: يَا رَسُولَ اللَّهِ، مَتَى السَّاعَةُ؟ فَقَالَ: "مَا الْمَسْئُولُ عَنْهَا بِأَعْلَمَ مِنَ السَّائِلِ، وَلَكِنْ سَأُخْبِرُكَ عَنْ أَشْرَاطِهَا: إِذَا وَلَدَتِ الْأَمَةُ رَبَّتَهَا، فَذَاكَ مِنْ أَشْرَاطِهَا. وَإِذَا كَانَتِ الْحُفَاةُ الْعُرَاةُ رُءُوسَ النَّاسِ، فَذَاكَ مِنْ أَشْرَاطِهَا. وَإِذَا تَطَاوَلَ رِعَاءُ الْغَنَمِ فِي الْبُنْيَانِ، فَذَاكَ مِنْ أَشْرَاطِهَا. فِي خَمْسٍ لَا يَعْلَمُهُنَّ إِلَّا اللَّهُ". فَتَلَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: {إِنَّ اللَّهَ عِنْدَهُ عِلْمُ السَّاعَةِ وَيُنَزِّلُ الْغَيْثَ وَيَعْلَمُ مَا فِي الْأَرْحَامِ} الْآيَةَ. (جه)', 'അബൂഹുറൈറ(റ): ഒരു ദിവസം റസൂൽ(സ) ജനങ്ങളുടെ മുമ്പിൽ പുറത്ത് നിൽക്കുകയായിരുന്നു. അപ്പോൾ ഒരാൾ വന്നുചോദിച്ചു: തിരുദൂതരേ, എപ്പോഴാണ് അന്ത്യനാൾ? അപ്പോൾ അവിടുന്ന് പറഞ്ഞു: "അതിനെക്കുറിച്ച് ചോദിക്കപ്പെട്ടവൻ ചോദിച്ചവനേക്കാൾ അറിവുള്ളവനല്ല. പക്ഷേ, അതിന്റെ അടയാളങ്ങളെക്കുറിച്ച് നിനക്ക് ഞാൻ പറഞ്ഞുതരാം. അടിമസ്ത്രീ തന്റെ യജമാനനെ പ്രസവിക്കൽ, അത് അന്ത്യനാളിന്റെ അടയാളങ്ങളിൽ പെട്ടതാണ്. പാദം നഗ്നരായവരും വസ്ത്രമില്ലാത്തവരും ജനങ്ങളുടെ നേതാക്കളാകൽ അന്ത്യനാളിന്റെ അടയാളമാണ്. ആട്ടിടയന്മാർ കെട്ടിടങ്ങളുണ്ടാക്കാൻ മത്സരിച്ചാൽ അത് അന്ത്യനാളിന്റെ അടയാളമാകുന്നു. ഇനിയുള്ള അഞ്ച് കാര്യങ്ങൾ അല്ലാഹുവിന് മാത്രമേ അറിയുകയുള്ളൂ." തുടർന്ന് റസൂൽ(സ) ഇങ്ങനെ ഓതി: ''അന്ത്യനാളിനെക്കുറിച്ചുള്ള അറിവ് അല്ലാഹുവിന്റെ അടുക്കലാകുന്നു. മഴ വർഷിപ്പിക്കുന്നവൻ അവനാകുന്നു. ഗർഭാശയങ്ങളിലുള്ളതും അവനറിയും''. (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 725, 725, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 54, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: أَلَا أُحَدِّثُكُمْ حَدِيثًا سَمِعْتُهُ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، لَا يُحَدِّثُكُمْ بِهِ أَحَدٌ بَعْدِي، سَمِعْتُهُ مِنْهُ: "إِنَّ مِنْ أَشْرَاطِ السَّاعَةِ أَنْ يُرْفَعَ الْعِلْمُ، وَيَظْهَرَ الْجَهْلُ، وَيَفْشُوَ الزِّنَا، وَيُشْرَبَ الْخَمْرُ، وَيَذْهَبَ الرِّجَالُ، وَيَبْقَى النِّسَاءُ، حَتَّى يَكُونَ لِخَمْسِينَ امْرَأَةً قَيِّمٌ وَاحِدٌ". (ق,ت,جه)', 'അനസുബ്നു മാലിക്(റ): ഞാൻ റസൂൽ(സ)യിൽ നിന്ന് കേട്ട ഒരു ഹദീസ് നിങ്ങൾക്ക് പറഞ്ഞുതരട്ടെയോ, എന്റെ കാലശേഷം അതൊരാളും നിങ്ങൾക്ക് പറഞ്ഞുതരികയില്ല. ഞാൻ അത് തിരുമേനി(സ)യിൽ നിന്നും കേട്ടതാണ്: "നിശ്ചയം അറിവ് ഉയർത്തപ്പെടലും അജ്ഞത പരക്കലും വ്യഭിചാരം വ്യാപിക്കലും മദ്യം കഴിക്കപ്പെടലും അമ്പത് സ്ത്രീകൾക്ക് ഒരു പുരുഷനെന്ന നിലയിൽ പുരുഷന്മാർ ഇല്ലാതിരിക്കലും സ്ത്രീകൾ ബാക്കിയാകലും അന്ത്യനാളിന്റെ അടയാളങ്ങളിൽ പെട്ടതാകുന്നു." (ബു,മു,തു,ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ق','ت','جه']::text[], array['ബു','മു','തു','ജ']::text[], null, null, 726, 726, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 55, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا تَقُومُ السَّاعَةُ حَتَّى يَحْسُرَ الْفُرَاتُ عَنْ جَبَلٍ مِنْ ذَهَبٍ، فَيَقْتَتِلُ النَّاسُ عَلَيْهِ، فَيُقْتَلُ مِنْ كُلِّ عَشَرَةٍ تِسْعَةٌ". (جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "യൂഫ്രട്ടീസ് നദിയിൽ വെള്ളം വറ്റി സ്വർണ്ണമല വെളിവാകുന്നത് വരെ അന്ത്യനാൾ സംഭവിക്കുകയില്ല. ജനങ്ങൾ അതിന് വേണ്ടി പോരാടും. അങ്ങനെ അവരിലെ പത്തിൽ ഒമ്പതു പേരും വധിക്കപ്പെടും." (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 726, 726, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 56, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا تَقُومُ السَّاعَةُ حَتَّى يَفِيضَ الْمَالُ، وَتَظْهَرَ الْفِتَنُ، وَيَكْثُرَ الْهَرْجُ". قَالُوا: وَمَا الْهَرْجُ يَا رَسُولَ اللَّهِ؟ قَالَ: "الْقَتْلُ، الْقَتْلُ، الْقَتْلُ". ثَلَاثًا. (ق,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "കലഹം അധികരിക്കുന്നത് വരെയും ഫിത്ന പുറപ്പെടുന്നത് വരെയും സമ്പത്ത് കൂടുതലാകുന്നത് വരെയും അന്ത്യനാൾ സംഭവിക്കുകയില്ല." അവർ ചോദിച്ചു: എന്താണ് തിരുദൂതരേ ''കലഹം?'' അവിടുന്ന് പറഞ്ഞു: "കൊല, കൊല, കൊലയാണ്." മൂന്ന് പ്രാവശ്യം. (ബു,മു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','جه']::text[], array['ബു','മു','ജ']::text[], null, null, 726, 726, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 57, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "وَالَّذِي نَفْسِي بِيَدِهِ، لَا تَقُومُ السَّاعَةُ حَتَّى تُكَلِّمَ السِّبَاعُ الْإِنْسَ، وَحَتَّى تُكَلِّمَ الرَّجُلَ عَذَبَةُ سَوْطِهِ وَشِرَاكُ نَعْلِهِ، وَتُخْبِرَهُ فَخِذُهُ بِمَا أَحْدَثَ أَهْلُهُ مِنْ بَعْدِهِ". حَسَنٌ. (ت)', 'അബൂസഈദിൽ ഖുദ്‌രി(റ): റസൂൽ(സ) പറഞ്ഞു: "എന്റെ ശരീരം ആരുടെ കയ്യിലാണോ അവൻ തന്നെയാണ് സത്യം, പിടിമൃഗങ്ങൾ മനുഷ്യനോട് സംസാരിക്കുന്നത് വരെയും, തന്റെ വടിയുടെ അഗ്രവും ചെരുപ്പിന്റെ വാറും അവനോട് സംസാരിക്കുന്നത് വരെയും, താൻ പോയശേഷം തന്റെ ഭാര്യ ചെയ്തുകൂട്ടിയ കാര്യങ്ങൾ തന്റെ തുട അവന് പറഞ്ഞുകൊടുക്കുന്നതുവരെയും അന്ത്യനാൾ സംഭവിക്കുകയില്ല." (തു)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്‌രി(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 726, 726, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 58, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: انْفَلَقَ الْقَمَرُ عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "اشْهَدُوا". حَسَنٌ صَحِيحٌ. (م,ت)', 'ഇബ്നുഉമർ(റ): റസൂൽ(സ)യുടെ കാലത്ത് ചന്ദ്രൻ പിളർന്നു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ സാക്ഷികളാവുക." (മു,തു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['م','ت']::text[], array['മു','തു']::text[], null, null, 726, 726, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 59, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "تَبْلُغُ الْمَسَاكِنُ إِهَابَ، أَوْ: يَهَابَ". قَالَ زُهَيْرٌ: قُلْتُ لِسُهَيْلٍ: فَكَمْ ذَلِكَ مِنَ الْمَدِينَةِ؟ قَالَ: كَذَا وَكَذَا مِيلًا. (م)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "വീടുകൾ ഇഹാബ് - അല്ലെങ്കിൽ യഹാബ് - എന്ന സ്ഥലം വരെ എത്തും." സുഹൈർ(റ) പറയുന്നു: ഞാൻ സുഹൈൽ(റ)വിനോട് ചോദിച്ചു: അവിടേക്ക് മദീനയിൽ നിന്നെത്ര ദൂരമുണ്ട്? അദ്ദേഹം പറഞ്ഞു: ഇത്രയൊക്കെ മൈലുണ്ട്. (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 726, 727, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 60, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "يُخَرِّبُ الْكَعْبَةَ ذُو السُّوَيْقَتَيْنِ مِنَ الْحَبَشَةِ". (م)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഹബ്സീനിയക്കാരനായ രണ്ട് ചെറിയ തണ്ടൻ കാലുകളുള്ള വ്യക്തി കഅ്ബ പൊളിക്കും." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 727, 727, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 61, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مُنِعَتِ الْعِرَاقُ دِرْهَمَهَا وَقَفِيزَهَا، وَمُنِعَتِ الشَّأْمُ مُدْيَهَا وَدِينَارَهَا، وَمُنِعَتْ مِصْرُ إِرْدَبَّهَا وَدِينَارَهَا، وَعُدْتُمْ مِنْ حَيْثُ بَدَأْتُمْ، وَعُدْتُمْ مِنْ حَيْثُ بَدَأْتُمْ، وَعُدْتُمْ مِنْ حَيْثُ بَدَأْتُمْ". شَهِدَ عَلَى ذَلِكَ لَحْمُ أَبِي هُرَيْرَةَ وَدَمُهُ. (م)', 'അബൂഹുറൈറ(റ): ഇറാഖിന് അതിന്റെ ദിർഹമും അളവുയന്ത്രവും തടയപ്പെടും. ശാമിന് അതിന്റെ ദീനാറും അളവുയന്ത്രവും തടയപ്പെടും. മിസ്റിന് അതിന്റെ അളവുയന്ത്രവും ദീനാറും തടയപ്പെടും. നിങ്ങൾ തുടങ്ങിയതു പോലെ നിങ്ങൾ മടങ്ങും, നിങ്ങൾ തുടങ്ങിയതു പോലെ നിങ്ങൾ മടങ്ങും, നിങ്ങൾ തുടങ്ങിയതു പോലെ നിങ്ങൾ മടങ്ങും." അതിന് അബൂഹുറൈറയുടെ ഇറച്ചിയും രക്തവും സാക്ഷിയായിട്ടുണ്ട്. (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 727, 727, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 62, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَيْسَتِ السَّنَةُ بِأَنْ لَا تُمْطَرُوا، وَلَكِنِ السَّنَةُ أَنْ تُمْطَرُوا وَتُمْطَرُوا، وَلَا تُنْبِتُ الْأَرْضُ شَيْئًا". (م)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ക്ഷാമം എന്നാൽ മഴ വർഷിക്കാതിരിക്കലല്ല. മറിച്ച് മഴ കൂടുതലായി വർഷിക്കലും ഭൂമി ഒന്നിനെയും മുളപ്പിക്കാതിരിക്കലുമാകുന്നു." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 727, 727, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 63, 'عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِذَا فَعَلَتْ أُمَّتِي خَمْسَ عَشْرَةَ خَصْلَةً حَلَّ بِهَا الْبَلَاءُ". فَقِيلَ: وَمَا هُنَّ يَا رَسُولَ اللَّهِ؟ قَالَ: "إِذَا كَانَ الْمَغْنَمُ دُوَلًا، وَالْأَمَانَةُ مَغْنَمًا، وَالزَّكَاةُ مَغْرَمًا، وَأَطَاعَ الرَّجُلُ زَوْجَتَهُ، وَعَقَّ أُمَّهُ، وَبَرَّ صَدِيقَهُ، وَجَفَا أَبَاهُ، وَارْتَفَعَتِ الْأَصْوَاتُ فِي الْمَسَاجِدِ، وَكَانَ زَعِيمُ الْقَوْمِ أَرْذَلَهُمْ، وَأُكْرِمَ الرَّجُلُ مَخَافَةَ شَرِّهِ، وَشُرِبَتِ الْخُمُورُ، وَلُبِسَ الْحَرِيرُ، وَاتُّخِذَتِ الْقَيْنَاتُ وَالْمَعَازِفُ، وَلَعَنَ آخِرُ هَذِهِ الْأُمَّةِ أَوَّلَهَا، فَلْيَرْتَقِبُوا عِنْدَ ذَلِكَ رِيحًا حَمْرَاءَ، أَوْ خَسْفًا وَمَسْخًا". (ت)', 'അലിയ്യുബ്നു അബീത്വാലിബ്(റ): റസൂൽ(സ) പറഞ്ഞു: "എന്റെ സമുദായം പതിനഞ്ച് കാര്യങ്ങൾ ചെയ്താൽ അവർക്ക് ബുദ്ധിമുട്ടിറങ്ങും." അപ്പോൾ അവിടത്തോട് ചോദിക്കപ്പെട്ടു: അവ എന്തൊക്കെയാണ് തിരുദൂതരേ? അവിടുന്ന് പറഞ്ഞു: "യുദ്ധമുതൽ സ്വസമ്പാദ്യമാകൽ, വിശ്വസിച്ച് ഏൽപിച്ച സമ്പത്ത് ദാനമായി നൽകപ്പെട്ട സമ്പത്തുപോലെ ആകൽ, സകാത്ത് കടമാകൽ, ഒരാൾ തന്റെ മാതാവിന് എതിർ പ്രവർത്തിക്കുകയും ഭാര്യക്ക് വഴിപ്പെടുകയും ചെയ്യൽ, തന്റെ പിതാവിനോട് പിണങ്ങുകയും സുഹൃത്തിനോട് ഇണങ്ങുകയും ചെയ്യൽ, പള്ളികളിൽ ശബ്ദമുയരൽ, സമുദായത്തിലെ താഴ്ന്നവൻ(നീചൻ) നേതാവാകൽ, ഫിത്ന പേടിച്ച് ഒരാൾ ബഹുമാനിക്കപ്പെടൽ, മദ്യം കഴിക്കൽ, പട്ട് ധരിക്കൽ, സംഗാതോപകരണങ്ങളും പാട്ടുപാടുന്ന സ്ത്രീകളും ഉണ്ടാകൽ, ഈ സമുദായത്തിലെ അവസാനക്കാർ ആദ്യമുള്ളവരെ ശപിക്കൽ, ഇങ്ങനെയുണ്ടായാൽ അവർ ചുവപ്പ് കാറ്റ് അല്ലെങ്കിൽ കോലംമറിക്കലും ഭൂമി വിഴുങ്ങലും പ്രതീക്ഷിച്ചുകൊള്ളട്ടെ." (തു)', 'عَلِيِّ بْنِ أَبِي طَالِبٍ', 'അലിയ്യുബ്നു അബീത്വാലിബ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 727, 727, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 64, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِذَا اتُّخِذَ الْفَيْءُ دُوَلًا، وَالْأَمَانَةُ مَغْنَمًا، وَالزَّكَاةُ مَغْرَمًا، وَتُعُلِّمَ لِغَيْرِ الدِّينِ، وَأَطَاعَ الرَّجُلُ امْرَأَتَهُ وَعَقَّ أُمَّهُ، وَأَدْنَى صَدِيقَهُ وَأَقْصَى أَبَاهُ، وَظَهَرَتِ الْأَصْوَاتُ فِي الْمَسَاجِدِ، وَسَادَ الْقَبِيلَةَ فَاسِقُهُمْ، وَكَانَ زَعِيمُ الْقَوْمِ أَرْذَلَهُمْ، وَأُكْرِمَ الرَّجُلُ مَخَافَةَ شَرِّهِ، وَظَهَرَتِ الْقَيْنَاتُ وَالْمَعَازِفُ، وَشُرِبَتِ الْخُمُورُ، وَلَعَنَ آخِرُ هَذِهِ الْأُمَّةِ أَوَّلَهَا، فَلْيَرْتَقِبُوا عِنْدَ ذَلِكَ رِيحًا حَمْرَاءَ، وَزَلْزَلَةً وَخَسْفًا وَمَسْخًا وَقَذْفًا، وَآيَاتٍ تَتَابَعُ كَنِظَامٍ بَالٍ، قُطِعَ سِلْكُهُ فَتَتَابَعَ". (ت)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ശത്രുവിന്റെ മുതൽ (യുദ്ധം ചെയ്യാതെ ലഭിക്കുന്നത്) സ്വസമ്പത്തായി ഗണിക്കപ്പെടുകയും, സൂക്ഷിച്ചേൽപിച്ച സ്വത്ത് ദാനമായി നൽകപ്പെട്ടതു പോലെയാവുകയും, സകാത്ത് കടമായി വരികയും, ദീനിന് വേണ്ടിയല്ലാതെ പഠിപ്പിക്കപ്പെടുകയും, ഒരാൾ തന്റെ മാതാവിനെ വെറുപ്പിച്ച് ഭാര്യക്ക് വഴിപ്പെടുകയും, പിതാവിനെ അകലെയാക്കി തന്റെ സുഹൃത്തിനോട് അടുക്കുകയും, പള്ളികളിൽ ശബ്ദം പുറത്ത് വരുകയും, സമുദായത്തെ അവരിലെ തെമ്മാടി നയിക്കുകയും, ജനങ്ങളിൽ ഏറ്റവും നിന്ദ്യൻ അവരുടെ നേതാവാകുകയും, ഒരാളുടെ നാശത്തെ ഭയന്ന് അദ്ദേഹത്തെ ബഹുമാനിക്കപ്പെടുകയും, സംഗീതോപകരണങ്ങളും പാട്ടുപാടുന്ന സ്ത്രീകളും വെളിവാകുകയും, മദ്യം കുടിക്കുകയും, ഈ സമുദായത്തിന്റെ അവസാനക്കാർ ആദ്യക്കാരെ ശപിക്കുകയും ചെയ്താൽ ചുവന്ന കാറ്റിനെയും ഭൂകമ്പത്തെയും ഭൂമി വിഴുങ്ങലിനെയും കോലം മാറ്റലിനെയും കല്ലുകൊണ്ടുള്ള ഏറിനെയും നുരുമ്പിയ മാലയുടെ നൂല് പൊട്ടി അതിലെ മുത്തുകൾ വീഴുന്നത് പോലെ തുടരെ തുടരെയുള്ള ദൃഷ്ടാന്തങ്ങളെയും അവർ പ്രതീക്ഷിച്ചുകൊള്ളട്ടെ." (തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 728, 728, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 65, 'عَنْ عِمْرَانِ بْنِ حُصَيْنٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "فِي هَذِهِ الْأُمَّةِ خَسْفٌ وَمَسْخٌ وَقَذْفٌ". فَقَالَ رَجُلٌ مِنَ الْمُسْلِمِينَ: يَا رَسُولَ اللَّهِ، وَمَتَى ذَاكَ؟ قَالَ: "إِذَا ظَهَرَتِ الْقَيْنَاتُ وَالْمَعَازِفُ وَشُرِبَتِ الْخُمُورُ". (ت,جه)', 'ഇംറാനുബിൻ ഹുസൈൻ(റ): റസൂൽ(സ) പറയുന്നു: "ഈ സമുദായത്തിൽ കോലംമറിക്കലും ഭൂമി വിഴുങ്ങലും കല്ലുകൊണ്ടുള്ള ഏറും ഉണ്ട്." അപ്പോൾ മുസ്‌ലിംകളിൽ പെട്ട ഒരാൾ ചോദിച്ചു: അതെപ്പോഴാണ് തിരുദൂതരേ? അവിടുന്ന് പറഞ്ഞു: "സംഗീതോപകരണങ്ങളും പാട്ടുപാടുന്ന സ്ത്രീകളും വെളിവാകുകയും മദ്യപാനം ഉണ്ടാവുകയും ചെയ്താൽ." (തു,ജ)', 'عِمْرَانِ بْنِ حُصَيْنٍ', 'ഇംറാനുബിൻ ഹുസൈൻ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 728, 728, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 66, 'عَنْ صَفِيَّةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا يَنْتَهِي النَّاسُ عَنْ غَزْوِ هَذَا الْبَيْتِ حَتَّى يَغْزُوَ جَيْشٌ، حَتَّى إِذَا كَانُوا بِالْبَيْدَاءِ - أَوْ بِبَيْدَاءَ - مِنَ الْأَرْضِ خُسِفَ بِأَوَّلِهِمْ وَآخِرِهِمْ، وَلَمْ يَنْجُ أَوْسَطُهُمْ". قُلْتُ: يَا رَسُولَ اللَّهِ، فَمَنْ كَرِهَ مِنْهُمْ؟ قَالَ: "يَبْعَثُهُمُ اللَّهُ عَلَى مَا فِي أَنْفُسِهِمْ". حَسَنٌ صَحِيحٌ. (ت)', 'സ്വഫിയ്യ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഈ ഗേഹത്തോടുള്ള യുദ്ധത്തിൽ നിന്ന് ജനങ്ങൾ വിട്ടുനിൽക്കും. അവസാനം ഒരു സൈന്യം അതിനോട് യുദ്ധം ചെയ്യും. അങ്ങനെ അവർ ഒരു സമതലപ്രദേശത്തെത്തുമ്പോൾ അവരിലെ ആദ്യത്തെവരെയും അവസാനത്തെവരെയും ഭൂമി വിഴുങ്ങും. അവരിലെ മധ്യത്തിലുള്ളവർ രക്ഷപ്പെടുകയുമില്ല." ഞാൻ ചോദിച്ചു: തിരൂദൂതരേ, അവരിൽ നിർബന്ധിതരായി വരുന്ന ആളുകളുടെ അവസ്ഥയെന്താണ്? അവിടുന്ന് പറഞ്ഞു: "അവരുടെ മനസ്സുകളിലുള്ളതനുസരിച്ച് അല്ലാഹു അവരെ പുനർജനിപ്പിക്കും." (തു)', 'صَفِيَّةَ', 'സ്വഫിയ്യ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 728, 728, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 67, 'عَنْ عُبَيْدِ اللَّهِ بْنِ الْقِبْطِيَّةِ رَضِيَ اللهُ عَنْهُ قَالَ: دَخَلَ الْحَارِثُ بْنُ أَبِي رَبِيعَةَ وَعَبْدُ اللَّهِ بْنُ صَفْوَانَ وَأَنَا مَعَهُمَا عَلَى أُمِّ سَلَمَةَ أُمِّ الْمُؤْمِنِينَ رَضِيَ اللهُ عَنْهَا، فَسَأَلَاهَا عَنِ الْجَيْشِ الَّذِي يُخْسَفُ بِهِ؟ وَكَانَ ذَلِكَ فِي أَيَّامِ ابْنِ الزُّبَيْرِ، فَقَالَتْ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "يَعُوذُ عَائِذٌ بِالْبَيْتِ فَيُبْعَثُ إِلَيْهِ بَعْثٌ، فَإِذَا كَانُوا بِبَيْدَاءَ مِنَ الْأَرْضِ خُسِفَ بِهِمْ". فَقُلْتُ: يَا رَسُولَ اللهِ، فَكَيْفَ بِمَنْ كَانَ كَارِهًا؟ قَالَ: "يُخْسَفُ بِهِ مَعَهُمْ، وَلَكِنَّهُ يُبْعَثُ يَوْمَ الْقِيَامَةِ عَلَى نِيَّتِهِ". وَقَالَ أَبُو جَعْفَرٍ: هِيَ بَيْدَاءُ الْمَدِينَةِ. (م)', 'ഉബൈദില്ലാഹിബ്നു ഖിബ്തിയ്യ(റ): ഹാരിസുബ്നു അബീറബീഅ(റ)വും അബ്ദുല്ലാഹിബ്നു സ്വഫ്‌വാൻ(റ)വും അവരുടെ കൂടെ ഞാനും ഉമ്മുൽ മുഅ്മിനീൻ ഉമ്മുസലമ(റ)യുടെ സന്നിധിയിൽ ചെന്നു. ഭൂമി വിഴുങ്ങുന്ന സൈന്യത്തെക്കുറിച്ച് അവർ രണ്ട് പേരും മഹതിയോട് ചോദിച്ചു. അത് ഇബ്നുസുബൈർ(റ)വിന്റെ കാലത്തായിരുന്നു. അപ്പോൾ അവർ പറഞ്ഞു: റസൂൽ(സ) പറഞ്ഞു: "അഭയം പ്രാപിക്കുന്നവൻ (അല്ലാഹുവിന്റെ) ഭവനത്തിൽ (കഅ്ബയിൽ) അഭയം പ്രാപിക്കും. അപ്പോൾ അവനിലേക്ക് ഒരു സൈന്യം അയക്കപ്പെടും. അങ്ങനെ അവർ ഭൂമിയിലെ തരിശായ ഭാഗത്തെത്തിയാൽ അവരെ ഭൂമി വിഴുങ്ങും." അപ്പോൾ ഞാൻ ചോദിച്ചു: നിർബന്ധിതരായവരുട അവസ്ഥയെന്തായിരിക്കും തിരുദൂതരേ? അവിടുന്ന് പറഞ്ഞു: "അവനും അവരുടെ കൂടെ വിഴുങ്ങപ്പെടും. പക്ഷേ, അവൻ അന്ത്യനാളിൽ അവന്റെ നിയ്യത്തനുസരിച്ച് പുനർജനിക്കപ്പെടും." അബൂജഅ്ഫർ(റ) പറയുന്നു: അത് മദീനയിലെ തരിശ് ഭൂമിയാണ്. (മു)', 'عُبَيْدِ اللَّهِ بْنِ الْقِبْطِيَّةِ', 'ഉബൈദില്ലാഹിബ്നു ഖിബ്തിയ്യ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 728, 729, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 68, 'عَنْ عَبْدِ اللهِ بْنِ صَفْوَانَ رَضِيَ اللهُ عَنْهُ قَالَ: أَخْبَرَتْنِي حَفْصَةُ رَضِيَ اللهُ عَنْهَا: أَنَّهَا سَمِعَتْ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَيَؤُمَّنَّ هَذَا الْبَيْتَ جَيْشٌ يَغْزُونَهُ، حَتَّى إِذَا كَانُوا بِبَيْدَاءَ مِنَ الأَرْضِ خُسِفَ بِأَوْسَطِهِمْ، وَيَتَنَادَى أَوَّلُهُمْ آخِرَهُمْ فَيُخْسَفُ بِهِمْ، فَلَا يَبْقَى مِنْهُمْ إِلَّا الشَّرِيدُ الَّذِي يُخْبِرُ عَنْهُمْ". فَلَمَّا جَاءَ جَيْشُ الْحَجَّاجِ ظَنَّا أَنَّهُمْ هُمْ، فَقَالَ رَجُلٌ: أَشْهَدُ عَلَيْكَ أَنَّكَ لَمْ تَكْذِبْ عَلَى حَفْصَةَ، وَأَنَّ حَفْصَةَ لَمْ تَكْذِبْ عَلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (ن,جه)', 'അബ്ദുല്ലാഹിബ്നു സ്വഫ്‌വാൻ(റ): എന്നോട് ഹഫ്സ(റ) പറഞ്ഞു: റസൂൽ(സ) പറയുന്നത് അവർ കേട്ടു: "ഒരു സൈന്യം ഈ വീടിനെ അക്രമിക്കാൻ ഉദ്ദേശിക്കും. അങ്ങനെ അവർ ഒരു തരിശായ ഭൂമിയിലെത്തിയാൽ അവരിലെ മധ്യത്തിലുള്ളവരെ ഭൂമി വിഴുങ്ങും. അപ്പോൾ മുന്നിലുള്ളവർ പിന്നിലുള്ളവരെ വിളിക്കും. അന്നേരം അവരെയും ഭൂമി വിഴുങ്ങും. അവരെക്കുറിച്ച് (ജനങ്ങൾക്ക്) പറഞ്ഞുകൊടുക്കുന്ന, പിന്തിരിഞ്ഞ് ഓടിയ ഒരാളല്ലാതെ ആരും അവരിൽ നിന്ന് ശേഷിക്കുകയില്ല." ഹജ്ജാജിന്റെ സൈന്യം വന്നപ്പോൾ ഞങ്ങൾ വിചാരിച്ചു അവരാണ് ഇവരെന്ന്. അപ്പോൾ ഒരാൾ പറഞ്ഞു: താങ്കൾ ഹഫ്സ(റ)വിന്റെ മേൽ കള്ളം പറഞ്ഞിട്ടില്ലെന്നും ഹഫ്സ(റ) നബി(സ)യുടെ മേൽ കള്ളം പറഞ്ഞിട്ടില്ലെന്നും ഞാനിതാ താങ്കൾക്ക് സാക്ഷി നിൽക്കുന്നു. (ന,ജ)', 'عَبْدِ اللهِ بْنِ صَفْوَانَ', 'അബ്ദുല്ലാഹിബ്നു സ്വഫ്‌വാൻ(റ)', null, null, array['ن','جه']::text[], array['ന','ജ']::text[], null, null, 729, 729, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 69, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "يَكُونُ فِي آخِرِ الأُمَّةِ خَسْفٌ وَمَسْخٌ وَقَذْفٌ". قَالَتْ: قُلْتُ: يَا رَسُولَ اللهِ، أَنَهْلِكُ وَفِينَا الصَّالِحُونَ؟ قَالَ: "نَعَمْ، إِذَا ظَهَرَ الْخُبْثُ". (ت)', 'ആഇശ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഈ സമുദായത്തിന്റെ അന്ത്യത്തിൽ കോലം മറിക്കലും ഭൂമി വിഴുങ്ങലും എറിയലും ഉണ്ടാകും." അവർ ചോദിച്ചു: തിരുദൂതരേ, ഞങ്ങളിൽ നല്ലവരുണ്ടായിരിക്കെ ഞങ്ങൾ നശിപ്പിക്കപ്പെടുമോ? തിരുമേനി(സ) പറഞ്ഞു: "അതെ, മോശത്തരം പ്രകടമായാൽ." (തു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 729, 729, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 70, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "فِي ثَقِيفٍ كَذَّابٌ وَمُبِيرٌ". حَسَنٌ. (ت)', 'ഇബ്നുഉമർ(റ): റസൂൽ(സ) പറയുന്നു: "സഖീഫ് ഗോത്രത്തിൽ ഒരു കള്ളവാദിയും ക്രൂരനായ ഒരു നാശകാരിയും ഉണ്ടാകും." (തു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 729, 729, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 71, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "يَخْرُجُ فِي آخِرِ الزَّمَانِ قَوْمٌ أَحْدَاثُ الأَسْنَانِ، سُفَهَاءُ الأَحْلَامِ، يَقْرَءُونَ الْقُرْآنَ لَا يُجَاوِزُ تَرَاقِيَهُمْ، يَقُولُونَ مِنْ قَوْلِ خَيْرِ الْبَرِيَّةِ، يَمْرُقُونَ مِنَ الدِّينِ كَمَا يَمْرُقُ السَّهْمُ مِنَ الرَّمِيَّةِ". حَسَنٌ صَحِيحٌ. (ت,جه)', 'അബ്ദുല്ലാഹിബ്നുമസ്ഊദ്(റ): റസൂൽ(സ) പറയുന്നു: "അവസാന കാലത്ത് ചെറുപ്രായക്കാരായ, ബുദ്ധി കുറഞ്ഞ ഒരു സമൂഹം വരും. അവർ ഖുർആൻ ഓതുന്നവരായിരിക്കും. പക്ഷേ, അത് അവരുടെ തൊണ്ടക്കുഴിയിൽ നിന്നിറങ്ങുകയില്ല. സൃഷ്ടികളിൽ ഉത്തമരായവരുടെ - റസൂൽ(സ)യുടെ - വാക്കുകൾ അവർ പറയും. വേട്ടമൃഗത്തിൽ നിന്ന് അമ്പ് തെന്നിമാറുന്നത് പോലെ അവർ ദീനിൽ നിന്ന് തെന്നിമാറും. (തു,ജ)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നുമസ്ഊദ്(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 730, 730, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 72, 'عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ قَالَ: إِذَا حَدَّثْتُكُمْ عَنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَلَأَنْ أَخِرَّ مِنَ السَّمَاءِ أَحَبُّ إِلَيَّ مِنْ أَنْ أَكْذِبَ عَلَيْهِ، وَإِذَا حَدَّثْتُكُمْ فِيمَا بَيْنِي وَبَيْنَكُمْ فَإِنَّ الْحَرْبَ خَدْعَةٌ. سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "يَأْتِي فِي آخِرِ الزَّمَانِ قَوْمٌ حُدَثَاءُ الأَسْنَانِ، سُفَهَاءُ الأَحْلَامِ، يَقُولُونَ مِنْ خَيْرِ قَوْلِ الْبَرِيَّةِ، يَمْرُقُونَ مِنَ الإِسْلَامِ كَمَا يَمْرُقُ السَّهْمُ مِنَ الرَّمِيَّةِ، لَا يُجَاوِزُ إِيمَانُهُمْ حَنَاجِرَهُمْ، فَأَيْنَمَا لَقِيتُمُوهُمْ فَاقْتُلُوهُمْ، فَإِنَّ قَتْلَهُمْ أَجْرٌ لِمَنْ قَتَلَهُمْ يَوْمَ الْقِيَامَةِ". (خ)', 'അലി(റ): നിങ്ങളോട് ഞാൻ റസൂൽ(സ)യിൽ നിന്നുള്ള ഹദീസ് പറയുകയാണെങ്കിൽ തിരുമേനി(സ)യുടെ മേൽ കളവ് പറയുന്നതിനെക്കാൾ ആകാശത്തു നിന്ന് ഞാൻ വീഴുന്നതാണ് എനിക്കിഷ്ടം. എന്റെയും നിങ്ങളുടെയുമിടയിലുള്ള കാര്യങ്ങളാണ് പറയുന്നതെങ്കിൽ, നിശ്ചയം യുദ്ധം കുതന്ത്രമാണ്. റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു:"അവസാന കാലത്ത് ചെറുപ്രായക്കാരായ, ബുദ്ധി കുറഞ്ഞ ഒരു സമൂഹം വരും. അവർ സൃഷ്ടികളിൽ ഉത്തമരായവരുടെ(റസൂൽ(സ)യുടെ) വാക്കുകൾ പറയും. വേട്ടമൃഗത്തിൽ നിന്ന് അമ്പ് തെന്നിമാറുന്നതു പോലെ അവർ ദീനിൽ നിന്ന് തെന്നിമാറും. അവരുടെ വിശ്വാസം അവരുടെ തൊണ്ടക്കുഴി വിട്ട് കടക്കുകയില്ല. അവരെ എവിടെ വെച്ച് കണ്ടാലും നിങ്ങൾ വധിച്ചുകളയുക. അവരെ കൊന്നവർക്ക് അന്ത്യനാളിൽ ആ കൊല പ്രതിഫലമാണ്." (ബു)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 730, 730, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 73, 'عَنْ أُمِّ سَلَمَةَ رَضِيَ اللهُ عَنْهَا، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: أَنَّهُ ذَكَرَ الْجَيْشَ الَّذِي يُخْسَفُ بِهِمْ، فَقَالَتْ أُمُّ سَلَمَةَ: لَعَلَّ فِيهِمُ الْمُكْرَهَ؟ قَالَ: "إِنَّهُمْ يُبْعَثُونَ عَلَى نِيَّاتِهِمْ". حَسَنٌ. (ت,جه)', 'ഉമ്മുസലമ(റ): ഭൂമി വിഴുങ്ങുന്ന ഒരു സൈന്യത്തെക്കുറിച്ച് നബി(സ) പറഞ്ഞപ്പോൾ ഉമ്മുസലമ(റ) ചോദിച്ചു: അവരിൽ നിർബന്ധിതരുമുണ്ടാകാമല്ലോ? അവിടുന്ന് പറഞ്ഞു: "നിശ്ചയം അവർ അവരുടെ നിയ്യത്തിന്മേൽ പുനർജനിപ്പിക്കപ്പെടും." (തു,ജ)', 'أُمِّ سَلَمَةَ', 'ഉമ്മുസലമ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 730, 730, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 74, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِذَا أَنْزَلَ اللهُ بِقَوْمٍ عَذَابًا، أَصَابَ الْعَذَابُ مَنْ كَانَ فِيهِمْ، ثُمَّ بُعِثُوا عَلَى أَعْمَالِهِمْ". (خ)', 'ഇബ്നുഉമർ(റ): റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹു ഒരു സമുദായത്തിൽ ശിക്ഷ ഇറക്കിയാൽ അത് അവരിലെല്ലാവരെയും ബാധിക്കും. പിന്നെ അവരുടെ പ്രവർത്തനങ്ങക്കനുസരിച്ച് അവർ പുനർജ്ജനിപ്പിക്കപ്പെടും." (ബു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 730, 730, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 75, 'عَنْ حُذَيْفَةَ بْنِ الْيَمَانِ رَضِيَ اللهُ عَنْهُ: حَدَّثَنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ حَدِيثَيْنِ، قَدْ رَأَيْتُ أَحَدَهُمَا وَأَنَا أَنْتَظِرُ الآخَرَ. حَدَّثَنَا: "أَنَّ الأَمَانَةَ نَزَلَتْ فِي جَذْرِ قُلُوبِ الرِّجَالِ، ثُمَّ نَزَلَ الْقُرْآنُ، فَعَلِمُوا مِنَ الْقُرْآنِ وَعَلِمُوا مِنَ السُّنَّةِ". ثُمَّ حَدَّثَنَا عَنْ رَفْعِ الأَمَانَةِ فَقَالَ: "يَنَامُ الرَّجُلُ النَّوْمَةَ فَتُقْبَضُ الأَمَانَةُ مِنْ قَلْبِهِ، فَيَظَلُّ أَثَرُهَا مِثْلَ الْوَكْتِ. ثُمَّ يَنَامُ نَوْمَةً فَتُقْبَضُ الأَمَانَةُ مِنْ قَلْبِهِ، فَيَظَلُّ أَثَرُهَا مِثْلَ أَثَرِ الْمَجْلِ، كَجَمْرٍ دَحْرَجْتَهُ عَلَى رِجْلِكَ فَنَفِطَتْ، فَتَرَاهُ مُنْتَبِرًا، وَلَيْسَ فِيهِ شَيْءٌ". ثُمَّ أَخَذَ حَصَاةً فَدَحْرَجَهَا عَلَى رِجْلِهِ، قَالَ: "فَيُصْبِحُ النَّاسُ يَتَبَايَعُونَ، لَا يَكَادُ أَحَدُهُمْ يُؤَدِّي الأَمَانَةَ، حَتَّى يُقَالَ: إِنَّ فِي بَنِي فُلَانٍ رَجُلًا أَمِينًا، وَحَتَّى يُقَالَ لِلرَّجُلِ: مَا أَجْلَدَهُ وَأَظْرَفَهُ وَأَعْقَلَهُ، وَمَا فِي قَلْبِهِ مِثْقَالُ حَبَّةٍ مِنْ خَرْدَلٍ مِنْ إِيمَانٍ". قَالَ: وَلَقَدْ أَتَى عَلَيَّ زَمَانٌ، وَمَا أُبَالِي أَيُّكُمْ بَايَعْتُ فِيهِ: لَئِنْ كَانَ مُسْلِمًا لَيَرُدَّنَّهُ عَلَيَّ دِينُهُ، وَلَئِنْ كَانَ يَهُودِيًّا أَوْ نَصْرَانِيًّا لَيَرُدَّنَّهُ عَلَيَّ سَاعِيهِ، فَأَمَّا الْيَوْمَ: فَمَا كُنْتُ لأُبَايِعَ مِنْكُمْ إِلَّا فُلَانًا وَفُلَانًا. حَسَنٌ صَحِيحٌ. (ق,ت,جه)', 'ഹുദൈഫതുബ്നുൽ യമാൻ(റ): റസൂൽ(സ) ഞങ്ങൾക്ക് രണ്ട് സംഭവങ്ങൾ പറഞ്ഞ് തന്നു. അതിൽ നിന്നൊന്ന് ഞാൻ കണ്ടു. മറ്റേത് ഞാൻ പ്രതീക്ഷിക്കുകയും ചെയ്യുന്നു. അവിടന്ന് ഞങ്ങളോട് പറഞ്ഞു: "അമാനത്ത് മനുഷ്യ ഹൃദയങ്ങളിലിറങ്ങി, ശേഷം ഖുർആൻ ഇറങ്ങി, അപ്പോഴവർക്ക് ഖുർആനും സുന്നത്തും മനസ്സിലായി." പിന്നെ അമാനത്ത് ഉയർത്തപ്പെടുന്നതിനെക്കുറിച്ച് ഞങ്ങളോട് അവിടന്ന് സംസാരിച്ചു, അവിടുന്ന് പറഞ്ഞു: "ഒരാൾ ഒന്ന് ഉറങ്ങുന്നു, അപ്പോൾ അദ്ധേഹത്തിന്റെ ഹൃദയത്തിൽ നിന്ന് അമാനത്ത് പിടിക്കപ്പെടും. പിന്നെ അത് ഒരു ചെറിയ അടയാളമായി മാറും. പിന്നെ അവൻ ഒന്നുറങ്ങും, അപ്പോൾ ഹൃദയത്തിൽ നിന്ന് അമാനത്ത് പിടിക്കപ്പെടും. അപ്പോൾ അത് തീക്കനൽ കൊണ്ടതുപോലെയാകും. നിന്റെ കാലിൽ തീക്കനലിട്ടുരുട്ടിയാൽ അത് വീർത്ത് കുമിളയാകുന്നത് പോലെ. അതിൽ ഒന്നും തന്നെ ഉണ്ടായിരിക്കുകയില്ല." ശേഷം ഹുദൈഫ(റ) കുറച്ച് കല്ലെടുത്ത് കാലുകൊണ്ടുരുട്ടി. അവിടന്ന് പറഞ്ഞു: "ജനങ്ങൾ ബൈഅത്ത് ചെയ്ത് കൊണ്ടിരിക്കും. അവരിൽ ആരുംതന്നെ അമാനത്ത് വീട്ടുകയില്ല, അന്ന് ഇപ്രകാരം പോലും പറയപ്പെടും: ഇന്ന കുടുംബത്തിൽ വിശ്വസ്തനായ ഒരാളുണ്ട്. ഒരാളെക്കുറിച്ച് ഇങ്ങനെ പറയപ്പെടും: അവൻ എത്ര ശക്തിയുള്ളവനും ബുദ്ധിയുള്ളവനുമാകുന്നു. എന്നാൽ അവന്റെ ഹൃദയത്തിൽ കടുക് മണിയോളം പോലും ഈമാൻ ഉണ്ടാവുകയില്ല." നിവേദകൻ പറയുന്നു: എനിക്ക് ഒരു കാലം കഴിഞ്ഞ് പോയി, ഞാൻ ആരോടാണ് ഉടമ്പടി ചെയ്തതെന്ന് അന്ന് ഞാൻ പ്രശ്നമാക്കിയിരുന്നില്ല, അദ്ധേഹം മുസ്ലിമാണെങ്കിൽ അവന്റെ ദീൻ അവനെ എന്നിലേക്ക് മടക്കും. അവൻ ജൂതനോ ക്രിസ്ത്യാനിയോ ആണെങ്കിൽ അവന്റെ സഹായി അവനെ എന്നിലേക്ക് മടക്കും. എന്നാൽ ഇന്ന് ഇന്നവനോടും ഇന്നവനോടുമല്ലാതെ ഞാൻ ഉടമ്പടി ചെയ്യുകയില്ല. (ബു,മു,തു,ജ)', 'حُذَيْفَةَ بْنِ الْيَمَانِ', 'ഹുദൈഫതുബ്നുൽ യമാൻ(റ)', null, null, array['ق','ت','جه']::text[], array['ബു','മു','തു','ജ']::text[], null, null, 730, 731, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 76, 'عَنْ زِيَادِ بْنِ لَبِيدٍ رَضِيَ اللهُ عَنْهُ قَالَ: ذَكَرَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ شَيْئًا، فَقَالَ: "ذَاكَ عِنْدَ أَوَانِ ذَهَابِ الْعِلْمِ". قُلْتُ: يَا رَسُولَ اللهِ، وَكَيْفَ يَذْهَبُ الْعِلْمُ وَنَحْنُ نَقْرَأُ الْقُرْآنَ، وَنُقْرِئُهُ أَبْنَاءَنَا، وَيُقْرِئُهُ أَبْنَاؤُنَا أَبْنَاءَهُمْ، إِلَى يَوْمِ الْقِيَامَةِ؟ قَالَ: "ثَكِلَتْكَ أُمُّكَ زِيَادُ، إِنْ كُنْتُ لَأَرَاكَ مِنْ أَفْقَهِ رَجُلٍ بِالْمَدِينَةِ. أَوَلَيْسَ هَذِهِ الْيَهُودُ وَالنَّصَارَى يَقْرَءُونَ التَّوْرَاةَ وَالإِنْجِيلَ، لَا يَعْمَلُونَ بِشَيْءٍ مِمَّا فِيهِمَا". [فِي سَنَدِهِ إِنْقِطَاعٌ] (جه)', 'സിയാദുബ്നു ലബീദ്(റ): നബി(സ) ഒരു കാര്യം പ്രതിപാതിച്ചുകൊണ്ട് പറഞ്ഞു: "അത് ഇൽമ്(അറിവ്) പോകുന്ന സമയത്താണ്." ഞാൻ ചോദിച്ചു: തിരുദൂതരേ, ഞങ്ങൾ ഖുർആൻ ഓതുകയും ഞങ്ങളുടെ സന്താനങ്ങളെ ഓതിപ്പിക്കുകയും ഞങ്ങളുടെ സന്താനങ്ങൾ അവരുടെ സന്താനങ്ങളെയും അന്ത്യനാൾ വരെ ഓതിപ്പിക്കുകയും ചെയ്തുകൊണ്ടിരിക്കെ എങ്ങനെയാണ് ഇൽമ്(അറിവ്) ഇല്ലാതാകുക? അവിടന്ന് പറഞ്ഞു: "നിനക്ക് നാശം, മദീനയിലെ ഏറ്റവും അറിവുള്ളവരിലൊരാളായിട്ടായിരുന്നു താങ്കളെ ഞാൻ മനസ്സിലാക്കിയിരുന്നത്. ഈ ജൂതരും ക്രസ്ത്യാനികളും തൗറാത്തും ഇൻജീലും ഓതുന്നവരല്ലേ, എന്നിട്ടും അതിലുള്ള ഒന്നിനെക്കുറിച്ചും അവർ അറിവുള്ളവരല്ലല്ലോ?" ഇതിന്റെ പരമ്പരയിൽ ഭംഗമുണ്ട്. (ജ)', 'زِيَادِ بْنِ لَبِيدٍ', 'സിയാദുബ്നു ലബീദ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'فِي سَنَدِهِ إِنْقِطَاعٌ', null, 731, 731, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 77, 'عَنْ حُذَيْفَةَ بْنِ الْيَمَانِ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "يَدْرُسُ الإِسْلَامُ كَمَا يَدْرُسُ وَشْيُ الثَّوْبِ، حَتَّى لَا يُدْرَى مَا صِيَامٌ وَلَا صَلَاةٌ وَلَا نُسُكٌ وَلَا صَدَقَةٌ. وَلَيُسْرَى عَلَى كِتَابِ اللهِ عَزَّ وَجَلَّ فِي لَيْلَةٍ، فَلَا يَبْقَى فِي الأَرْضِ مِنْهُ آيَةٌ. وَتَبْقَى طَوَائِفُ مِنَ النَّاسِ، الشَّيْخُ الْكَبِيرُ وَالْعَجُوزُ، يَقُولُونَ: أَدْرَكْنَا آبَاءَنَا عَلَى هَذِهِ الْكَلِمَةِ: لَا إِلَهَ إِلَّا اللهُ، فَنَحْنُ نَقُولُهَا". فَقَالَ لَهُ صِلَةُ: مَا تُغْنِي عَنْهُمْ: لَا إِلَهَ إِلَّا اللهُ، وَهُمْ لَا يَدْرُونَ مَا صَلَاةٌ وَلَا صِيَامٌ وَلَا نُسُكٌ وَلَا صَدَقَةٌ؟ فَأَعْرَضَ عَنْهُ حُذَيْفَةُ، ثُمَّ رَدَّهَا عَلَيْهِ ثَلَاثًا، كُلَّ ذَلِكَ يُعْرِضُ عَنْهُ حُذَيْفَةُ، ثُمَّ أَقْبَلَ عَلَيْهِ فِي الثَّالِثَةِ فَقَالَ: يَا صِلَةُ، تُنْجِيهِمْ مِنَ النَّارِ. ثَلَاثًا. (جه)', 'ഹുദൈഫതുബിൻ യമാൻ(റ): റസൂൽ(സ) പറഞ്ഞു: "വസ്ത്രത്തിലെ ചിത്രപ്പണികൾ മായുന്നത് പോലെ ഇസ്ലാം നാമാവശേഷമാകും. അപ്പോൾ നോമ്പോ, നിസ്കാരമോ, ഹജ്ജോ, സ്വദഖയോ എന്തെന്ന് അറിയപ്പെടുകയില്ല. അല്ലാഹുവിന്റെ ഗ്രന്ഥം ഒറ്റ രാത്രികൊണ്ട് ഉയർത്തപ്പെടും, ഭൂമിയിൽ അതിലെ ഒറ്റ സൂക്തവും ശേഷിക്കുകയില്ല. ജനങ്ങളിൽ വൃദ്ധരും കിഴവികളുമായ ഒരു കൂട്ടം ആളുകൾ ശേഷിക്കും, അവർ പറയും: ഞങ്ങളുടെ പിതാക്കന്മാരെ ''ലാ ഇലാഹ ഇല്ലല്ലാഹു'' എന്ന ഈ കലിമയുമായിട്ടാണ് ഞങ്ങൾ കണ്ടത്, അത് ഞങ്ങളും പറയുന്നു." അപ്പോൾ സ്വില(റ) ചോദിച്ചു: നോമ്പും നിസ്കാരവും ഹജ്ജും സ്വദഖയും അറിയാതെ ''ലാ ഇലാഹ ഇല്ലല്ലാഹു'' മാത്രം അവർക്ക് മതിയാകുമോ? അപ്പോൾ ഹുദൈഫ(റ) മുഖം തിരിച്ചു. സ്വില(റ) മൂന്ന് പ്രാവശ്യം ചോദ്യമാവർത്തിച്ചു. അപ്പോഴെല്ലാം ഹുദൈഫ(റ) അതിൽ നിന്ന് മുഖം തിരിച്ചു. മൂന്നാമത്തെ പ്രാവശ്യം അദ്ദേഹത്തോട് പറഞ്ഞു: സ്വിലാ! അത് അവരെ നരകത്തിൽ നിന്ന് രക്ഷിക്കും. ഇത് മൂന്ന് പ്രാവശ്യം പറഞ്ഞു. (ജ)', 'حُذَيْفَةَ بْنِ الْيَمَانِ', 'ഹുദൈഫതുബിൻ യമാൻ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 732, 732, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 78, 'عَنْ أَبِي مُوسَى رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ مِنْ وَرَائِكُمْ أَيَّامًا، يَنْزِلُ فِيهَا الْجَهْلُ، وَيُرْفَعُ فِيهَا الْعِلْمُ، وَيَكْثُرُ فِيهَا الْهَرْجُ". قَالُوا: يَا رَسُولَ اللهِ، وَمَا الْهَرْجُ؟ قَالَ: "الْقَتْلُ". (ق,ت,جه)', 'അബൂമൂസാ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾക്കു പിറകെ ചില ദിവസങ്ങൾ വരും. അന്ന് അജ്ഞതയിറങ്ങുകയും അറിവ് ഉയർത്തപ്പെടുകയും ''ഹർജ്'' അധികരിക്കുകയും ചെയ്യും." അവർ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, ''ഹർജ്'' എന്നാൽ എന്താണ്? അവിടന്ന് പറഞ്ഞു: "കൊലയാണ്." (ബു,മു,തു,ജ)', 'أَبِي مُوسَى', 'അബൂമൂസാ(റ)', null, null, array['ق','ت','جه']::text[], array['ബു','മു','തു','ജ']::text[], null, null, 732, 732, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 79, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ - يَرْفَعُهُ - قَالَ: "يَتَقَارَبُ الزَّمَانُ، وَيَنْقُصُ الْعِلْمُ، وَيُلْقَى الشُّحُّ، وَتَظْهَرُ الْفِتَنُ، وَيَكْثُرُ الْهَرْجُ". قَالُوا: يَا رَسُولَ اللهِ، وَمَا الْهَرْجُ؟ قَالَ: "الْقَتْلُ". (جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറയുന്നു: "കാലം അടുക്കും, അറിവ് ചുരുങ്ങും, പിശുക്കുണ്ടാകും, ഫിത്ന പുറപ്പെടും, ഹർജ് അധികരിക്കും." അവർ ചോദിച്ചു: തിരുദൂതരേ, എന്താണ് ഹർജ്? അവിടന്ന് പറഞ്ഞു: "കൊല." (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 732, 732, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 80, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ اللهَ عَزَّ وَجَلَّ إِذَا أَرَادَ أَنْ يُهْلِكَ عَبْدًا نَزَعَ مِنْهُ الْحَيَاءَ، فَإِذَا نَزَعَ مِنْهُ الْحَيَاءَ لَمْ تَلْقَهُ إِلَّا مَقِيتًا مُمَقَّتًا. فَإِذَا لَمْ تَلْقَهُ إِلَّا مَقِيتًا مُمَقَّتًا نُزِعَتْ مِنْهُ الأَمَانَةُ، فَإِذَا نُزِعَتْ مِنْهُ الأَمَانَةُ لَمْ تَلْقَهُ إِلَّا خَائِنًا مُخَوَّنًا. فَإِذَا لَمْ تَلْقَهُ إِلَّا خَائِنًا مُخَوَّنًا نُزِعَتْ مِنْهُ الرَّحْمَةُ، فَإِذَا نُزِعَتْ مِنْهُ الرَّحْمَةُ لَمْ تَلْقَهُ إِلَّا رَجِيمًا مُلَعَّنًا. فَإِذَا لَمْ تَلْقَهُ إِلَّا رَجِيمًا مُلَعَّنًا نُزِعَتْ مِنْهُ رِبْقَةُ الإِسْلَامِ". [فِي سَنَدِهِ ضَعِيفٌ] (جه)', 'ഇബ്നുഉമർ(റ): റസൂൽ(സ) പറയുന്നു: "അല്ലാഹു ഒരാളെ നശിപ്പിക്കാൻ ഉദ്ദേശിച്ചാൽ അവനിൽ നിന്ന് ലജ്ജ എടുത്ത് കളയും. ലജ്ജ എടുത്ത് കളയപ്പെട്ടാൽ ദേഷ്യപ്പെടുന്നവനും മറ്റുള്ളവരെ ദേഷ്യപ്പെടുത്തുന്നവനുമായി മാത്രമേ നീ അവനെ കാണൂ. ദേഷ്യപ്പെടുന്നവനും മറ്റുള്ളവരെ ദേഷ്യംപിടിപ്പിക്കുന്നവനുമായി മാത്രം അവനെ നീ കണ്ടാൽ അവനിൽനിന്ന് അമാനത്ത് എടുത്ത് കളയപ്പെടും. അമാനത്ത് എടുത്ത് കളയപ്പെട്ടാൽ വഞ്ചിക്കുന്നവനും വഞ്ചിക്കപ്പെടുന്നവനുമായി മാത്രമേ നീ അവനെ കാണൂ. വഞ്ചിക്കുന്നവനും വഞ്ചിക്കപ്പെടുന്നവനുമായി മാത്രം അവനെ നീ കണ്ടാൽ അവനിൽനിന്ന് കരുണ എടുത്ത് കളയപ്പെടും. അവനിൽനിന്ന് കരുണ എടുത്തുകളയപ്പെട്ടാൽ ശപിക്കപ്പെട്ടവനും ആട്ടപ്പെട്ടവനുമായി മാത്രമേ നീ അവനെ കാണൂ. ശപിക്കപ്പെട്ടവനും ആട്ടപ്പെട്ടവനുമായി മാത്രം അവനെ നീ കണ്ടാൽ അവനിൽനിന്ന് ഇസ്ലാമിന്റെ ചങ്ങലകൾ എടുത്ത് കളയപ്പെടും." ഇതിന്റെ പരമ്പരയിൽ ഒരു ബലഹീനനുണ്ട്. (ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'فِي سَنَدِهِ ضَعِيفٌ', null, 732, 733, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 81, 'عَنْ أَبِي زُرْعَةَ رَضِيَ اللهُ عَنْهُ قَالَ: جَاءَ نَفَرٌ إِلَى مَرْوَانَ بِالْمَدِينَةِ، فَسَمِعُوهُ يُحَدِّثُ فِي الآيَاتِ: أَنَّ أَوَّلَهَا الدَّجَّالُ، قَالَ: فَانْصَرَفْتُ إِلَى عَبْدِ اللهِ بْنِ عَمْرٍو فَحَدَّثْتُهُ، فَقَالَ عَبْدُ اللهِ: لَمْ يَقُلْ شَيْئًا، سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "إِنَّ أَوَّلَ الآيَاتِ خُرُوجًا طُلُوعُ الشَّمْسِ مِنْ مَغْرِبِهَا، أَوِ الدَّابَّةُ عَلَى النَّاسِ ضُحًى، فَأَيَّتُهُمَا كَانَتْ قَبْلَ صَاحِبَتِهَا فَالأُخْرَى عَلَى أَثَرِهَا". قَالَ عَبْدُ اللهِ، وَكَانَ يَقْرَأُ الْكُتُبَ: وَأَظُنُّ أَوَّلَهُمَا خُرُوجًا طُلُوعُ الشَّمْسِ مِنْ مَغْرِبِهَا. (م,د,جه)', 'അബൂസുർഅ(റ): ഒരു സംഘമാളുകൾ മദീനയിൽ മർവാന്റെയടുക്കൽ വന്നു. അദ്ദേഹം (അന്ത്യനാളിന്റെ) ദൃഷ്ടാന്തങ്ങൾ വിവരിക്കുമ്പോൾ, അവയിൽ ഒന്നാമത്തേത് ദജ്ജാലാണ്, എന്ന് പറയുന്നത് അവർ കേട്ടു. നിവേദകൻ പറഞ്ഞു: ഞാനപ്പോൾ അബ്ദുല്ലാഹിബ്നുഅംറ്(റ)വിന്റെയടുത്ത് പോയി ആ ഹദീസ് പറഞ്ഞുകൊടുത്തു. അപ്പോൾ അബ്ദുല്ലാഹ്(റ) പറഞ്ഞു: അദ്ദേഹമൊന്നും പറഞ്ഞിട്ടില്ല. റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടിട്ടുണ്ട്: "നിശ്ചയമായും, പുറപ്പെടുന്ന ആദ്യത്തെ ദൃഷ്ടാന്തം സൂര്യൻ അതിന്റെ അസ്തമയ ദിക്കിൽനിന്നും ഉദിക്കലാണ്. അല്ലെങ്കിൽ പൂർവ്വാഹ്ന സമയത്ത് ജനങ്ങളിൽ വരുന്ന ഒരു ജീവി (ദാബ്ബതുൽ അർള്) ആണ്. ഇവ രണ്ടിൽ ഏതെങ്കിലുമൊന്ന് മറ്റേതിന്റെ മുമ്പേ ഉണ്ടായാൽ രണ്ടാമത്തേത് അതിന്റെ ഉടനെത്തന്നെയുണ്ടാകും." അബ്ദുല്ലാഹ്(റ) പറയുന്നു - അദ്ദേഹം ഗ്രന്ഥങ്ങൾ പാരായണം ചെയ്യാറുണ്ട് -: അവരണ്ടിൽ വെച്ച് ആദ്യത്തേത് സൂര്യൻ അതിന്റെ അസ്തമയ ദിക്കിൽനിന്ന് ഉദിക്കലാണെന്ന് ഞാൻ ഭാവിക്കുന്നു. (മു,ദ,ജ)', 'أَبِي زُرْعَةَ', 'അബൂസുർഅ(റ)', null, null, array['م','د','جه']::text[], array['മു','ദ','ജ']::text[], null, null, 733, 733, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 82, 'عَنْ حُذَيْفَةَ بْنِ أَسِيدٍ - أَبِي سَرِيحَةَ - قَالَ: اطَّلَعَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مِنْ غُرْفَةٍ، وَنَحْنُ نَتَذَاكَرُ السَّاعَةَ، فَقَالَ: "لَا تَقُومُ السَّاعَةُ حَتَّى تَكُونَ عَشْرُ آيَاتٍ: طُلُوعُ الشَّمْسِ مِنْ مَغْرِبِهَا، وَالدَّجَّالُ، وَالدُّخَانُ، وَالدَّابَّةُ، وَيَأْجُوجُ وَمَأْجُوجُ، وَخُرُوجُ عِيسَى ابْنِ مَرْيَمَ عَلَيْهِ السَّلَامُ. وَثَلَاثُ خُسُوفٍ: خَسْفٌ بِالْمَشْرِقِ، وَخَسْفٌ بِالْمَغْرِبِ، وَخَسْفٌ بِجَزِيرَةِ الْعَرَبِ. وَنَارٌ تَخْرُجُ مِنْ قَعْرِ عَدَنَ أَبْيَنَ، تَسُوقُ النَّاسَ إِلَى الْمَحْشَرِ، تَبِيتُ مَعَهُمْ إِذَا بَاتُوا، وَتَقِيلُ مَعَهُمْ إِذَا قَالُوا". (م,د,ت,جه)', 'ഹുദൈഫതുബ്നു അസീദ്(റ): ഞങ്ങൾ അന്ത്യനാളിനെക്കുറിച്ച് പറഞ്ഞ് കൊണ്ടിരിക്കെ അബൂസരീഹ(റ) പറഞ്ഞു: റസൂൽ(സ) ഒരു റൂമിൽ നിന്ന് ഇറങ്ങിവന്ന് പറഞ്ഞു: "പത്ത് ദൃഷ്ടാന്തങ്ങൾ ഉണ്ടാകുന്നത് വരെ അന്ത്യനാൾ സംഭവിക്കുകയില്ല: സൂര്യൻ അതിന്റെ അസ്തമയദിക്കിൽനിന്ന് ഉദിക്കൽ, ദജ്ജാൽ, പുക, മൃഗം (ദാബ്ബതുൽഅർള്), യഅ്ജൂജ് മഅ്ജൂജ്, ഈസബ്നുമർയം(അ), മൂന്ന് ഭൂമി വിഴുങ്ങലുകൾ: കിഴക്ക് ഭാഗത്ത് ഭൂമി വിഴുങ്ങൽ, പടിഞ്ഞാറ് ഭാഗത്ത് ഭൂമി വിഴുങ്ങൽ, അറേബ്യൻ ഭൂഖണ്ഡത്തിലും ഭൂമി വിഴുങ്ങൽ, (യമനിലെ ഒരു പട്ടണമായ) ഏഡനിലെ നദിയിൽ നിന്ന് പുറപ്പെടുന്ന വളരെ പ്രകടമായ തീ, അത് ജനങ്ങളെ ഒരു ജനക്കൂട്ടത്തിലേക്ക് തെളിക്കും, വൈകുന്നേര സമയത്ത് അത് അവരുടെ കൂടെയുണ്ടാകും, ഉച്ചയുറക്കിന്റെ സമയത്തും അത് അവരുടെ കൂടെയുണ്ടാകും." (മു,ദ,തു,ജ)', 'حُذَيْفَةَ بْنِ أَسِيدٍ - أَبِي سَرِيحَةَ - قَالَ', 'ഹുദൈഫതുബ്നു അസീദ്(റ)', null, null, array['م','د','ت','جه']::text[], array['മു','ദ','തു','ജ']::text[], null, null, 733, 733, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 83, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ، عَنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "بَادِرُوا بِالأَعْمَالِ سِتًّا: طُلُوعَ الشَّمْسِ مِنْ مَغْرِبِهَا، وَالدُّخَانَ، وَدَابَّةَ الأَرْضِ، وَالدَّجَّالَ، وَخُوَيْصَّةَ أَحَدِكُمْ، وَأَمْرَ الْعَامَّةِ". (م,جه)', 'അനസുബ്നു മാലിക്ക്(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ ആറ് കാര്യങ്ങൾക്ക് മുമ്പ് കർമ്മങ്ങളെക്കൊണ്ട് ഉളരുവീൻ: അസ്തമയ ദിക്കിൽനിന്നുള്ള സൂര്യോദയം, പുക, ദാബ്വതുൽഅർള് (അന്ത്യനാളോടടുത്ത് പ്രത്യക്ഷപ്പെടുന്ന ഒരു മൃഗം), ദജ്ജാൽ, നിങ്ങളിൽ ഓരോരുത്തന്റെയും മരണം, പൊതു വിപത്ത്." (മു,ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്ക്(റ)', null, null, array['م','جه']::text[], array['മു','ജ']::text[], null, null, 734, 734, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 84, 'عَنْ أَنَسِ بْنِ مَالِكٍ، عَنْ أَبِي قَتَادَةَ - رَضِيَ اللهُ عَنْهُمَا - قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "الآيَاتُ بَعْدَ الْمِائَتَيْنِ". [فِي سَنَدِهِ ضَعِيفَانِ] (جه)', 'അബൂഖതാദ(റ)വിൽ നിന്ന് അനസുബ്നു മാലിക്ക്(റ): റസൂൽ(സ) പറഞ്ഞു: "(അന്ത്യനാളിന്റെ) ദൃഷ്ടാന്തങ്ങൾ ഇരുനൂറിന് ശേഷമാണ്." ഇതിന്റെ സനദിൽ രണ്ട് ബലഹീനരുണ്ട്. (ജ)', 'أَنَسِ بْنِ مَالِكٍ، عَنْ أَبِي قَتَادَةَ -', 'അബൂഖതാദ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'فِي سَنَدِهِ ضَعِيفَانِ', null, 734, 734, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 85, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ، عَنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "أُمَّتِي عَلَى خَمْسِ طَبَقَاتٍ: فَأَرْبَعُونَ سَنَةً أَهْلُ بِرٍّ وَتَقْوَى، ثُمَّ الَّذِينَ يَلُونَهُمْ - إِلَى عِشْرِينَ وَمِائَةِ سَنَةٍ - أَهْلُ تَرَاحُمٍ وَتَوَاصُلٍ، ثُمَّ الَّذِينَ يَلُونَهُمْ - إِلَى سِتِّينَ وَمِائَةِ سَنَةٍ - أَهْلُ تَدَابُرٍ وَتَقَاطُعٍ، ثُمَّ الْهَرْجُ الْهَرْجُ، النَّجَا النَّجَا". وَفِي رِوَايَةٍ: قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أُمَّتِي عَلَى خَمْسِ طَبَقَاتٍ: كُلُّ طَبَقَةٍ أَرْبَعُونَ عَامًا. فَأَمَّا طَبَقَتِي وَطَبَقَةُ أَصْحَابِي فَأَهْلُ عِلْمٍ وَإِيمَانٍ، وَأَمَّا الطَّبَقَةُ الثَّانِيَةُ - مَا بَيْنَ الأَرْبَعِينَ إِلَى الثَّمَانِينَ - فَأَهْلُ بِرٍّ وَتَقْوَى". ثُمَّ ذَكَرَ نَحْوَهُ. [فِي سَنَدِهِ الأَوَّلِ ضَعِيفٌ، وَفِي الثَّانِي مَجْهُولَانِ] (جه)', 'അനസുബ്നുമാലിക്ക്(റ): റസൂൽ(സ) പറഞ്ഞു: "എന്റെ സമുദായം അഞ്ച് തട്ടുകളിലാണ്, നന്മയുടെയും ഭയഭക്തിയുടെയും ആളുകളാണ് നാൽപത് വർഷം, പിന്നെ അവരോടടുത്തവർ - നൂറ്റി ഇരുപത് വർഷം വരെ - പരസ്പര കാരുണ്യത്തിന്റെയും സഹവർത്തിത്തത്തിന്റെയും ആളുകളാണ്. പിന്നീട് അവരോടടുത്തവർ - നൂറ്റിയറുപത് വർഷം വരെ - പരസ്പര ശത്രുതയുടെയും ഭിന്നിപ്പിന്റെയും ആളുകളായിരിക്കും. പിന്നീട് പ്രക്ഷോഭങ്ങളും ലഹളകളുമായിരിക്കും. (അപ്പോൾ), രക്ഷനേടുവിൻ രക്ഷനേടുവിൻ." മറ്റൊരു നിവേദനത്തിൽ: റസൂലുല്ലാഹി(സ) പറഞ്ഞു: "എന്റെ സമുദായം അഞ്ച് നിലകളിലാണ്, എല്ലാ നിലയും നാൽപത് വർഷമാണ്. എന്റെ നിലയിലും എന്റെ അനുചരരുടെ നിലയിലുമുള്ളവർ ജ്ഞാനത്തിന്റെയും വിശ്വാസത്തിന്റെയും ആളുകളാണ്. ഇനി രണ്ടാമത്തെ പദവിയിലുള്ളവർ - നാൽപതിനും എൺപതിനുമിടയിൽ - നന്മയുടെയും ദൈവഭക്തിയുടെയും ആളുകളാണ്." പിന്നീടതുപോലെ അവിട്ന്ന് പറഞ്ഞു. ഇതിന്റെ ഒന്നാം സനദിൽ ഒരു ള‌ഈഫും, രണ്ടാമത്തേതിൽ രണ്ട് മജ്ഹൂലുമുണ്ട്. (ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നുമാലിക്ക്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'فِي سَنَدِهِ الأَوَّلِ ضَعِيفٌ، وَفِي الثَّانِي مَجْهُولَانِ', null, 734, 734, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=13 and h.hadith_no=85), 1, 'وَفِي رِوَايَةٍ: قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أُمَّتِي عَلَى خَمْسِ طَبَقَاتٍ: كُلُّ طَبَقَةٍ أَرْبَعُونَ عَامًا. فَأَمَّا طَبَقَتِي وَطَبَقَةُ أَصْحَابِي فَأَهْلُ عِلْمٍ وَإِيمَانٍ، وَأَمَّا الطَّبَقَةُ الثَّانِيَةُ - مَا بَيْنَ الأَرْبَعِينَ إِلَى الثَّمَانِينَ - فَأَهْلُ بِرٍّ وَتَقْوَى". ثُمَّ ذَكَرَ نَحْوَهُ. [فِي سَنَدِهِ الأَوَّلِ ضَعِيفٌ، وَفِي الثَّانِي مَجْهُولَانِ] (جه)', 'മറ്റൊരു നിവേദനത്തിൽ: റസൂലുല്ലാഹി(സ) പറഞ്ഞു: "എന്റെ സമുദായം അഞ്ച് നിലകളിലാണ്, എല്ലാ നിലയും നാൽപത് വർഷമാണ്. എന്റെ നിലയിലും എന്റെ അനുചരരുടെ നിലയിലുമുള്ളവർ ജ്ഞാനത്തിന്റെയും വിശ്വാസത്തിന്റെയും ആളുകളാണ്. ഇനി രണ്ടാമത്തെ പദവിയിലുള്ളവർ - നാൽപതിനും എൺപതിനുമിടയിൽ - നന്മയുടെയും ദൈവഭക്തിയുടെയും ആളുകളാണ്." പിന്നീടതുപോലെ അവിട്ന്ന് പറഞ്ഞു. ഇതിന്റെ ഒന്നാം സനദിൽ ഒരു ള‌ഈഫും, രണ്ടാമത്തേതിൽ രണ്ട് മജ്ഹൂലുമുണ്ട്. (ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 86, 'عَنْ أَبِي ذَرٍّ رَضِيَ اللهُ عَنْهُ قَالَ: دَخَلْتُ الْمَسْجِدَ حِينَ غَابَتِ الشَّمْسُ وَالنَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ جَالِسٌ، فَقَالَ: "يَا أَبَا ذَرٍّ، أَتَدْرِي أَيْنَ تَذْهَبُ هَذِهِ". قَالَ: قُلْتُ: اللهُ وَرَسُولُهُ أَعْلَمُ. قَالَ: "فَإِنَّهَا تَذْهَبُ تَسْتَأْذِنُ فِي السُّجُودِ فَيُؤْذَنُ لَهَا، وَكَأَنَّهَا قَدْ قِيلَ لَهَا: اطْلُعِي مِنْ حَيْثُ جِئْتِ، فَتَطْلُعُ مِنْ مَغْرِبِهَا". قَالَ: ثُمَّ قَرَأَ: {وَذَلِكَ مُسْتَقَرٌّ لَهَا}. قَالَ: وَذَلِكَ قِرَاءَةُ عَبْدِ اللهِ بْنِ مَسْعُودٍ. حَسَنٌ صَحِيحٌ. (ق,د,ت)', 'അബൂദർറ്(റ): സൂര്യൻ അസ്തമിച്ചപ്പോൾ ഞാൻ പള്ളിയിൽ പ്രവേശിച്ചു. അപ്പോൾ നബി(സ) അവിടെ ഇരിക്കുകയായിരുന്നു. അവിടന്ന് ചോദിച്ചു: "അബൂദർറ്, ഇത് (സൂര്യൻ) എങ്ങോട്ടാണ് പോകുന്നതെന്ന് നിനക്കറിയാമോ?" നിവേദകൻ പറയുന്നു: ഞാൻ പറഞ്ഞു: അല്ലാഹുവും അവന്റെ ദൂതരുമാണ് ഏറ്റവും അറിവുള്ളവർ. അവിടന്നരുളി: "എന്നാൽ നിശ്ചയമത് സുജൂദിലായി സമ്മതം ചോദിക്കാൻ പോകുന്നു. അപ്പോൾ അതിന് സമ്മതം നൽകപ്പെടുന്നു. അതിനോട് പറയപ്പെട്ടത് പോലെയുണ്ട്: നീ വന്ന ഭാഗത്തേക്ക് ഉദിക്കുക എന്ന്. അങ്ങനെ അത് അസ്തമയ ദിക്കിൽ നിന്ന് ഉദിക്കും." നിവേദകൻ പറയുന്നു: പിന്നീട് അവിടന്ന് ഓതി: ''അതിനുള്ള (സൂര്യനുള്ള) സ്ഥിര സ്ഥാനമാണത്.'' നിവേദകൻ പറയുന്നു: അത് അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)വിന്റെ ഖിറാഅത്ത് (പാരായണ ശൈലി) ആണ്. (ബു,മു,ദ,തു)', 'أَبِي ذَرٍّ', 'അബൂദർറ്(റ)', null, null, array['ق','د','ت']::text[], array['ബു','മു','ദ','തു']::text[], null, null, 734, 735, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 87, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَوَّلُ الآيَاتِ خُرُوجًا طُلُوعُ الشَّمْسِ مِنْ مَغْرِبِهَا، وَخُرُوجُ الدَّابَّةِ عَلَى النَّاسِ ضُحًى". قَالَ عَبْدُ اللهِ: فَأَيَّتُهُمَا مَا خَرَجَتْ قَبْلَ الأُخْرَى فَالأُخْرَى مِنْهَا قَرِيبٌ. قَالَ عَبْدُ اللهِ: وَلَا أَظُنُّهَا إِلَّا طُلُوعَ الشَّمْسِ مِنْ مَغْرِبِهَا. (م,د,جه)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): റസൂലുല്ലാഹി(സ) പറഞ്ഞു: ആദ്യമായി പുറപ്പെടുന്ന ദൃഷ്ടാന്തം പടിഞ്ഞാറു നിന്നുള്ള സൂര്യോദയവും ആ മൃഗം (ദാബതുൽ അർള്) പൂർവാഹനത്തിൽ ജനങ്ങളിൽ ഇറങ്ങലുമാണ്." അബ്ദുല്ല(റ) പറഞ്ഞു: അവരണ്ടിലേതാണോ ആദ്യം പുറപ്പെടുന്നത് അതിന്റെയടുത്ത് തന്നെ മറ്റേതും പുറപ്പെടുന്നതാണ്. അബ്ദുല്ല(റ) പറഞ്ഞു: പടിഞ്ഞാറുനിന്നുള്ള സൂര്യോദയം തന്നെയാണതെന്നു ഞാൻ ഭാവിക്കുന്നു. (മു,ദ,ജ)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['م','د','جه']::text[], array['മു','ദ','ജ']::text[], null, null, 735, 735, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 88, 'عَنْ صَفْوَانَ بْنِ عَسَّالٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ مِنْ قِبَلِ مَغْرِبِ الشَّمْسِ بَابًا مَفْتُوحًا، عَرْضُهُ سَبْعُونَ سَنَةً، فَلَا يَزَالُ ذَلِكَ الْبَابُ مَفْتُوحًا لِلتَّوْبَةِ حَتَّى تَطْلُعَ الشَّمْسُ مِنْ نَحْوِهِ، فَإِذَا طَلَعَتْ مِنْ نَحْوِهِ لَمْ يَنْفَعْ نَفْسًا إِيمَانُهَا لَمْ تَكُنْ آمَنَتْ مِنْ قَبْلُ أَوْ كَسَبَتْ فِي إِيمَانِهَا خَيْرًا". (جه)', 'സ്വഫ്വാനുബ്നു അസ്സാൽ (റ): റസൂൽ(സ) പറഞ്ഞു: "സൂര്യാസ്തമയ ദിക്കിൽ തീർച്ചയായും തുറക്കപ്പെട്ട ഒരു വാതിലുണ്ട്, എഴുപത് വർഷത്തെ വീതിയുണ്ടതിന്. ആ ഭാഗത്തുനിന്ന് സൂര്യനുദിക്കുന്നത് വരെ തൗബക്കായി ആ വാതിൽ തുറന്നുതന്നെയിരിക്കും. ആ ഭാഗത്തുനിന്ന് സൂര്യനുദിച്ചാൽ, മുമ്പേ വിശ്വാസം കൈകൊള്ളുകയോ ഈമാനിൽ നന്മ കൈവരിക്കുകയോ ചെയ്തിട്ടില്ലാത്ത ഒരാൾക്കും അന്നേരത്തെ വിശ്വാസം ഫലവത്താകുന്നതല്ല." (ജ)', 'صَفْوَانَ بْنِ عَسَّالٍ', 'സ്വഫ്വാനുബ്നു അസ്സാൽ (റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 735, 735, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 89, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "تَخْرُجُ الدَّابَّةُ وَمَعَهَا خَاتَمُ سُلَيْمَانَ بْنِ دَاوُدَ، وَعَصَا مُوسَى بْنِ عِمْرَانَ، عَلَيْهِمَا السَّلَامُ. فَتَجْلُو وَجْهَ الْمُؤْمِنِ بِالْعَصَا، وَتَخْطِمُ أَنْفَ الْكَافِرِ بِالْخَاتَمِ، حَتَّى أَنَّ أَهْلَ الْحِوَاءِ لَيَجْتَمِعُونَ، فَيَقُولُ هَذَا: يَا مُؤْمِنُ، وَيَقُولُ هَذَا: يَا كَافِرُ". (ت,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ആ മൃഗം (ദാബ്ബതുൽ അർള്) സുലൈമാനുബ്നു ദാവൂദ്(അ)ന്റെ മോതിരവും മൂസബ്നു ഇംറാൻ(അ)ന്റെ വടിയുമായി പുറപ്പെടും. അങ്ങനെ സത്യവിശ്വാസിയുടെ മുഖത്തെ ആ വടികൊണ്ട് തിളക്കമുള്ളതാക്കുകയും ആ മോതിരം കൊണ്ട് സത്യനിഷേധിയുടെ മൂക്കിന് അടിക്കുകയും ചെയ്യും. അങ്ങനെ അടുത്തുള്ള വീട്ടുകാർ ഒരുമിച്ചുകൂടിയാൽ ഒരാൾ: ഓ, സത്യവിശ്വാസിയേ എന്നും ഒരാൾ: ഓ, സത്യനിഷേധിയേ എന്നും വിളിക്കുന്ന അവസ്ഥയുണ്ടാകും." (തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 735, 735, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 90, 'عَنْ بُرَيْدَةَ رَضِيَ اللهُ عَنْهُ قَالَ: ذَهَبَ بِي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِلَى مَوْضِعٍ بِالْبَادِيَةِ، قَرِيبٍ مِنْ مَكَّةَ، فَإِذَا أَرْضٌ يَابِسَةٌ حَوْلَهَا رَمْلٌ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "تَخْرُجُ الدَّابَّةُ مِنْ هَذَا الْمَوْضِعِ". فَإِذَا فِتْرٌ فِي شِبْرٍ. قَالَ ابْنُ بُرَيْدَةَ: فَحَجَجْتُ بَعْدَ ذَلِكَ بِسِنِينَ، فَأَرَانَا عَصًا لَهُ، فَإِذَا هُوَ بِعَصَايَ هَذِهِ، هَكَذَا وَهَكَذَا. [فِي سَنَدِهِ ضَعِيفَانِ] (جه)', 'ബുറൈദത്(റ): മക്കക്കടുത്തുള്ള ബാദിയയിലെ ഒരു സ്ഥലത്തേക്ക് റസൂൽ(സ) എന്നെ കൂട്ടിക്കൊണ്ടുപോയി. അപ്പോൾ അത്, ചുറ്റും മണലുള്ള വരണ്ട ഭൂമിയാണ്. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "ഈ സ്ഥലത്തു നിന്നാണ് ദാബ്ബതുൽ അർള് പുറപ്പെടുക." ഒരു ചാൺ അളവ് മാത്രമുള്ളതായിരുന്നു ആ സ്ഥലം. ഇബ്നുബുറൈദത്(റ) പറഞ്ഞു: ഈ സംഭവശേഷം ഞാൻ ധാരാളം വർഷം ഹജ്ജ് ചെയ്തു. അദ്ദേഹം (ബുറൈദ) ഞങ്ങൾക്ക് തന്റെ ഒരു വടി കാണിച്ചുതന്നു, എന്റെ ഈ വടി പോലെയായിരുന്നു അത്, ഇങ്ങനെയും അങ്ങനെയും (നീളവും വീതിയും). ഈ ഹദീസിന്റെ സനദിൽ ഒരു ബലഹീനനുണ്ട്. (ജ)', 'بُرَيْدَةَ', 'ബുറൈദത്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'فِي سَنَدِهِ ضَعِيفَانِ', null, 735, 736, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 91, 'عَنْ ذِي مِخْمَرٍ رَضِيَ اللهُ عَنْهُ، وَكَانَ رَجُلًا مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَقَدْ سُئِلَ عَنِ الْهُدْنَةِ، فَقَالَ: سَمِعْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "سَتُصَالِحُكُمُ الرُّومُ صُلْحًا آمِنًا، ثُمَّ تَغْزُونَ أَنْتُمْ وَهُمْ عَدُوًّا، فَتَنْتَصِرُونَ وَتَغْنَمُونَ وَتَسْلَمُونَ، ثُمَّ تَنْصَرِفُونَ حَتَّى تَنْزِلُوا بِمَرْجٍ ذِي تُلُولٍ، فَيَرْفَعُ رَجُلٌ مِنْ أَهْلِ الصَّلِيبِ الصَّلِيبَ، فَيَقُولُ: غَلَبَ الصَّلِيبُ. فَيَغْضَبُ رَجُلٌ مِنَ الْمُسْلِمِينَ، فَيَقُومُ إِلَيْهِ فَيَدُقُّهُ، فَعِنْدَ ذَلِكَ تَغْدِرُ الرُّومُ، وَيَجْتَمِعُونَ لِلْمَلْحَمَةِ". وَفِي رِوَايَةٍ: "فَيَجْتَمِعُونَ لِلْمَلْحَمَةِ، فَيَأْتُونَ حِينَئِذٍ تَحْتَ ثَمَانِينَ غَايَةً، تَحْتَ كُلِّ غَايَةٍ اثْنَا عَشَرَ أَلْفًا". (د,جه)', 'ദൂമഖ്മർ(റ): അദ്ദേഹം നബി(സ)യുടെ അനുചരരിൽ പെട്ടവരായിരുന്നു. അദ്ദേഹത്തോട് ശത്രുക്കളോടുള്ള സന്ധിയെക്കുറിച്ച് ചോദിക്കപ്പെട്ടപ്പോൾ അദ്ദേഹം പറഞ്ഞു: നബി(സ) പറയുന്നത് ഞാൻ കേട്ടിട്ടുണ്ട്: "റോമക്കാർ നിങ്ങളോട് വളരെ നിർഭയമായൊരു സന്ധിചെയ്യും. പിന്നെ നിങ്ങളും അവരും ഒരു ശത്രുവിനെതിരെ യുദ്ധം ചെയ്യും. അതിൽ നിങ്ങൾ വിജയിക്കുകയും നിങ്ങൾക്ക് യുദ്ധമുതൽ ലഭിക്കുകയും നിങ്ങൾ രക്ഷപ്പെടുകയും ചെയ്യും. പിന്നെ നിങ്ങൾ പിരിഞ്ഞുപോവുകയും കുന്നുകൾ നിറഞ്ഞ ഒരു മേച്ചിൽപുറത്തിറങ്ങുകയും ചെയ്യും. അവിടെ എത്തിയാൽ കുരിശിന്റെയാളുകളിൽ നിന്ന് ഒരാൾ കുരിശ് ഉയർത്തി പറയും: കുരിശ് വിജയിച്ചിരിക്കുന്നു. അപ്പോൾ മുസ്ലിംകളിലൊരാൾക്ക് ദേഷ്യം പിടിക്കുകയും അയാൾ മറ്റെയാളുടെ അടുത്തുചെന്ന് ആ കുരിശ് പൊട്ടിക്കും. ആ സമയത്ത് റോമക്കാർ കരാർ ലംഘിക്കുകയും യുദ്ധത്തിന് വേണ്ടി ഒരുമിച്ചുകൂടുകയും ചെയ്യും." മറ്റൊരു റിപ്പോർട്ടിൽ: "അവർ യുദ്ധത്തിന് വേണ്ടി ഒരുമിച്ചുകൂടും. അങ്ങനെ എൺപത് പതാകകൾക്ക് കീഴിലായി അവർ വരും. ഓരോ പതാകക്ക് താഴെയും പന്ത്രണ്ടായിരം ആളുകളുണ്ടാകും." (ദ,ജ)', 'ذِي مِخْمَرٍ', 'ദൂമഖ്മർ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 736, 736, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=13 and h.hadith_no=91), 1, 'وَفِي رِوَايَةٍ: "فَيَجْتَمِعُونَ لِلْمَلْحَمَةِ، فَيَأْتُونَ حِينَئِذٍ تَحْتَ ثَمَانِينَ غَايَةً، تَحْتَ كُلِّ غَايَةٍ اثْنَا عَشَرَ أَلْفًا". (د,جه)', 'മറ്റൊരു നിവേദനിൽ: "അവർ യുദ്ധത്തിന് വേണ്ടി ഒരുമിച്ചുകൂടും. അങ്ങനെ എൺപത് പതാകകൾക്ക് കീഴിലായി അവർ വരും. ഓരോ പതാകക്ക് താഴെയും പന്ത്രണ്ടായിരം ആളുകളുണ്ടാകും." (ദ,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 92, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِذَا وَقَعَتِ الْمَلَاحِمُ بَعَثَ اللهُ بَعْثًا مِنَ الْمَوَالِي، هُمْ أَكْرَمُ الْعَرَبِ فَرَسًا وَأَجْوَدُهُ سِلَاحًا، يُؤَيِّدُ اللهُ بِهِمُ الدِّينَ". (جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഘോരയുദ്ധങ്ങൾ സംഭവിച്ചാൽ മോചിതരായ അടിമകളിൽപെട്ട ഒരു സംഘത്തെ അല്ലാഹു നിയോഗിക്കും. അവർ അറബികളിൽ വെച്ച് ഏറ്റവും നല്ല കുതിര സവാരിക്കാരും ഏറ്റവും നന്നായി ആയുധം ഉപയോഗിക്കുന്നവരുമാണ്. അവരെക്കൊണ്ട് അല്ലാഹു ദീനിനെ ശക്തിപ്പെടുത്തും." (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 736, 736, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 93, 'عَنْ جَابِرِ بْنِ سَمُرَةَ رَضِيَ اللهُ عَنْهُمَا، عَنْ نَافِعِ بْنِ عُتْبَةَ بْنِ أَبِي وَقَّاصٍ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "سَتُقَاتِلُونَ جَزِيرَةَ الْعَرَبِ، فَيَفْتَحُهَا اللهُ، ثُمَّ تُقَاتِلُونَ الرُّومَ فَيَفْتَحُهَا اللهُ، ثُمَّ تُقَاتِلُونَ الدَّجَّالَ فَيَفْتَحُهَا اللهُ". قَالَ جَابِرٌ: فَمَا يَخْرُجُ الدَّجَّالُ حَتَّى تُفْتَحَ الرُّومُ. (م,جه)', 'നാഫിഉബ്നു ഉത്ബതുബ്നു അബീവഖാസ്(റ)വിൽ നിന്നും ജാബിറുബ്നു സമുറ(റ): നബി(സ) പറഞ്ഞു: "അറേബ്യൻ ദ്വീപിനോട് നിങ്ങൾ യുദ്ധം ചെയ്യും, അതിൽ അല്ലാഹു വിജയം നൽകും. പിന്നെ നിങ്ങൾ റോമക്കാരോട് യുദ്ധം ചെയ്യും, അതിലും അല്ലാഹു വിജയം നൽകും. പിന്നെ നിങ്ങൾ ദജ്ജാലിനോട് യുദ്ധം ചെയ്യും, അതിലും അല്ലാഹു വിജയം നൽകും." ജാബിർ(റ) പറയുന്നു: റോം ജയിച്ചടക്കുന്നത് വരെ ദജ്ജാൽ പുറപ്പെടുകയില്ല. (മു,ജ)', 'جَابِرِ بْنِ سَمُرَةَ', 'നാഫിഉബ്നു ഉത്ബതുബ്നു അബീവഖാസ്(റ)', null, null, array['م','جه']::text[], array['മു','ജ']::text[], null, null, 736, 737, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 94, 'عَنْ مُعَاذِ بْنِ جَبَلٍ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "الْمَلْحَمَةُ الْكُبْرَى وَفَتْحُ الْقُسْطَنْطِينِيَّةِ وَخُرُوجُ الدَّجَّالِ فِي سَبْعَةِ أَشْهُرٍ". (د,ت,جه)', 'മുആദുബ്നു ജബൽ(റ): നബി(സ) പറഞ്ഞു: "ഏറ്റവും വലിയ യുദ്ധവും കോൺസ്റ്റാന്റിനോപ്പിൾ ജയിച്ചടക്കലും ദജ്ജാൽ പുറപ്പെടലും ഏഴ് മാസങ്ങൾക്കുള്ളിലാണ്." (ദ,തു,ജ)', 'مُعَاذِ بْنِ جَبَلٍ', 'മുആദുബ്നു ജബൽ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 737, 737, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 95, 'عَنْ عَبْدِ اللهِ بْنِ بُسْرٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "بَيْنَ الْمَلْحَمَةِ وَفَتْحِ الْمَدِينَةِ سِتُّ سِنِينَ، وَيَخْرُجُ الدَّجَّالُ فِي السَّابِعَةِ". (د,جه)', 'അബ്ദുല്ലാഹിബ്നു ബുസ്ർ(റ): റസൂൽ(സ) പറഞ്ഞു: "വലിയ കൂട്ടക്കശാപ്പിനും പട്ടണം(കോൺസ്റ്റാന്റിനോപ്പിൾ) ജയിച്ചടക്കുന്നതിനുമിടയിൽ ആറ് വർഷമുണ്ട്, ഏഴാം വർഷം ദജ്ജാൽ പുറപ്പെടും." (ദ,ജ)', 'عَبْدِ اللهِ بْنِ بُسْرٍ', 'അബ്ദുല്ലാഹിബ്നു ബുസ്ർ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 737, 737, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 96, 'عَنْ عَمْرِو بْنِ عَوْفٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا تَقُومُ السَّاعَةُ حَتَّى تَكُونَ أَدْنَى مَسَالِحِ الْمُسْلِمِينَ بِبَوْلَاءَ". ثُمَّ قَالَ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "يَا عَلِيُّ، يَا عَلِيُّ، يَا عَلِيُّ". قَالَ: بِأَبِي وَأُمِّي. قَالَ: "إِنَّكُمْ سَتُقَاتِلُونَ بَنِي الأَصْفَرِ، وَيُقَاتِلُهُمُ الَّذِينَ مِنْ بَعْدِكُمْ، حَتَّى تَخْرُجَ إِلَيْهِمْ رُوقَةُ الإِسْلَامِ أَهْلُ الْحِجَازِ، الَّذِينَ لَا يَخَافُونَ فِي اللهِ لَوْمَةَ لَائِمٍ، فَيَفْتَتِحُونَ الْقُسْطَنْطِينِيَّةَ بِالتَّسْبِيحِ وَالتَّكْبِيرِ، فَيُصِيبُونَ غَنَائِمَ لَمْ يُصِيبُوا مِثْلَهَا، حَتَّى يَقْتَسِمُوا بِالأَتْرِسَةِ، وَيَأْتِي آتٍ فَيَقُولُ: إِنَّ الْمَسِيحَ قَدْ خَرَجَ فِي بِلَادِكُمْ. أَلَا وَهِيَ كِذْبَةٌ، فَالآخِذُ نَادِمٌ وَالتَّارِكُ نَادِمٌ". (جه)', 'അംറുബ്നു ഔഫ്(റ): റസൂൽ(സ) പറഞ്ഞു: "മുസ്ലിംകളുടെ ഏറ്റവും അടുത്തുള്ള കാവൽകേന്ദ്രം ബൗലാഅ് എന്ന സ്ഥലത്താകുന്നതുവരെ അന്ത്യനാൾ സംഭവിക്കുകയില്ല." പിന്നെ റസൂൽ(സ) വിളിച്ചു: "ഓ അലി, ഓ അലി, ഓ അലി." അലി(റ) പറഞ്ഞു: എന്റെ മാതാപിതാക്കൾ അങ്ങേക്ക് ദണ്ഡമാണ്. റസൂൽ(സ) പറഞ്ഞു: "നിശ്ചയം നിങ്ങൾ ബനുൽഅസ്ഫറിനോട് (റോമക്കാരോട്) യുദ്ധം ചെയ്യും, നിങ്ങൾക്ക് ശേഷമുള്ളവരും അവരോട് യുദ്ധം ചെയ്യും, അങ്ങനെ ഹിജാസുകാരിൽ പെട്ട ഇസ്ലാമിലെ കുറച്ച് സൽവ്യക്തിത്വങ്ങൾ അവരിലേക്ക് ചെല്ലും. അവർ അല്ലാഹുവിന്റെ കാര്യത്തിൽ ഒരു ആക്ഷേപകന്റെ ആക്ഷേപവും ഭയക്കാത്തവരാണ്. അങ്ങനെ അവർ തക്ബീറോടും തസ്ബീഹോടും കൂടെ കോൺസ്റ്റാന്റിനോപ്പിൾ കീഴടക്കും. മുമ്പ് ലഭിക്കാത്ത തരത്തിലുള്ള യുദ്ധമുതൽ അവർക്ക് ലഭിക്കും. അവർ അതിനെ (ആധിക്യം കാരണം) പരിചകൾ കൊണ്ട് വിഹിതം വെക്കും. അപ്പോൾ ഒരാൾ വന്ന് പറയും: നിങ്ങളുടെ നാട്ടിൽ ദജ്ജാൽ പുറപ്പെട്ടിരിക്കുന്നു. അറിയുക, അത് കളവാണ്, ആ വാക്ക് സ്വീകരിച്ചവൻ ഖേദിക്കുന്നതാണ് (ഉപദേശം കളവാണെന്ന് വ്യക്തമായ കാരണം), ആ വാക്ക് തിരസ്കരിച്ചവനും ഖേദിക്കുന്നതാണ് (കാരണം, തയ്യാറെടുക്കാനുള്ള ഒരു മുന്നറിയിപ്പാണത്)." (ജ)', 'عَمْرِو بْنِ عَوْفٍ', 'അംറുബ്നു ഔഫ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 737, 737, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 97, 'عَنْ عَوْفِ بْنِ مَالِكٍ الأَشْجَعِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "تَكُونُ بَيْنَكُمْ وَبَيْنَ بَنِي الأَصْفَرِ هُدْنَةٌ، فَيَغْدِرُونَ بِكُمْ، فَيَسِيرُونَ إِلَيْكُمْ فِي ثَمَانِينَ غَايَةً، تَحْتَ كُلِّ غَايَةٍ اثْنَا عَشَرَ أَلْفًا". (جه)', 'ഔഫ്ബ്നുമാലികുൽ അശ്ജഈ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾക്കും ബനുൽഅസ്ഫറി(റോമക്കാർ)നുമിടയിൽ സന്ധിയുണ്ടാകും, അവർ നിങ്ങളെ ചതിക്കും, അങ്ങനെ അവർ നിങ്ങളിലേക്ക് എൺപത് പതാകകൾക്ക് കീഴിലായി വരും, ഓരോ പതാകക്ക് കീഴിലും പന്ത്രണ്ടായിരം ആളുകളുണ്ടായിരിക്കും." (ജ)', 'عَوْفِ بْنِ مَالِكٍ الأَشْجَعِيِّ', 'ഔഫ്ബ്നുമാലികുൽ അശ്ജഈ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 737, 737, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 98, 'عَنْ مُعَاذِ بْنِ جَبَلٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "عُمْرَانُ بَيْتِ الْمَقْدِسِ خَرَابُ يَثْرِبَ، وَخَرَابُ يَثْرِبَ خُرُوجُ الْمَلْحَمَةِ، وَخُرُوجُ الْمَلْحَمَةِ فَتْحُ قُسْطَنْطِينِيَّةَ، وَفَتْحُ الْقُسْطَنْطِينِيَّةِ خُرُوجُ الدَّجَّالِ". ثُمَّ ضَرَبَ بِيَدِهِ عَلَى فَخِذِ الَّذِي حَدَّثَهُ أَوْ مَنْكِبِهِ ثُمَّ قَالَ: "إِنَّ هَذَا لَحَقٌّ كَمَا أَنَّكَ هَاهُنَا، أَوْ كَمَا أَنَّكَ قَاعِدٌ". يَعْنِي مُعَاذَ بْنَ جَبَلٍ. (د)', 'മുആദുബ്നു ജബൽ(റ): റസൂൽ(സ) പറഞ്ഞു: "ബൈത്തുൽ മുഖദ്ദസ് ജനനിബിഢമാകൽ മദീന വിജനമാകലാണ്. മദീന വിജനമാകൽ യുദ്ധം പൊട്ടിപ്പുറപ്പെടലാണ്. യുദ്ധം പൊട്ടിപ്പുറപ്പെടൽ കോൺസ്റ്റാന്റിനോപ്പിൾ ജയിച്ചടക്കലാണ്. കോൺസ്റ്റാന്റിനോപ്പിൾ ജയിച്ചടക്കൽ ദജ്ജാൽ പുറപ്പെടലാണ്." പിന്നെ നബി(സ) ഈ ഹദീസ് പറഞ്ഞുകൊടുത്തവന്റെ തുടയിലോ ചുമലിലോ അടിച്ചിട്ട് പറഞ്ഞു: "നീ ഇവിടെ ഇരിക്കുന്നതുപോലെ അല്ലെങ്കിൽ ഇവിടെ ഉള്ളതുപോലെ ഇതെല്ലാം വാസ്തവമാണ്." അഥവാ മുആദുബ്നു ജബൽ(റ) (അദ്ദേഹത്തോടാണ് നബി(സ) ഇത് പറയുന്നത്) (ദ)', 'مُعَاذِ بْنِ جَبَلٍ', 'മുആദുബ്നു ജബൽ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 738, 738, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 99, 'عَنْ أَبِي الدَّرْدَاءِ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ فُسْطَاطَ الْمُسْلِمِينَ يَوْمَ الْمَلْحَمَةِ بِالْغُوطَةِ، إِلَى جَانِبِ مَدِينَةٍ يُقَالُ لَهَا دِمَشْقُ، مِنْ خَيْرِ مَدَائِنِ الشَّامِ". (د)', 'അബുദ്ദർദാഅ്(റ): റസൂൽ(സ) പറഞ്ഞു: "യുദ്ധദിവസം മുസ്ലിംകളുടെ കോട്ട (അഭയകേന്ദ്രം), സിറിയയിലെ ഏറ്റവും നല്ല പട്ടണമായ, ദിമിശ്ഖ് എന്ന് പറയപ്പെടുന്ന പട്ടണത്തിന്റെ ഒരു ഭാഗത്തുള്ള ഒഴിഞ്ഞ വിശാലമായ പ്രദേശമായിരിക്കും." (ദ)', 'أَبِي الدَّرْدَاءِ', 'അബുദ്ദർദാഅ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 738, 738, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 100, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "يُوشِكُ الْمُسْلِمُونَ أَنْ يُحَاصَرُوا إِلَى الْمَدِينَةِ، حَتَّى يَكُونَ أَبْعَدَ مَسَالِحِهِمْ سَلَاحُ". قَالَ الزُّهْرِيُّ: وَسَلَاحُ قَرِيبٌ مِنْ خَيْبَرَ. (د)', 'ഇബ്നുഉമർ(റ): റസൂൽ(സ) പറഞ്ഞു: "മദീനയിൽ മുസ്ലിംകൾക്ക് ഉപരോധമേർപ്പെടുത്തപ്പെട്ടേക്കും, അങ്ങനെ അവരുടെ ഏറ്റവും വിദൂരത്തുള്ള കാവൽപുര (കാവൽക്കോട്ട) ''സലാഹ്'' എന്ന പ്രദേശമാകും." സുഹ്‌രി(റ) പറയുന്നു: ''സലാഹ്'' എന്നാൽ ഖൈബറിനോടടുത്ത ദേശമാണ്. (ദ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 738, 738, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 101, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا تَقُومُ السَّاعَةُ حَتَّى تُقَاتِلُوا قَوْمًا صِغَارَ الأَعْيُنِ، ذُلْفَ الأُنُوفِ، كَأَنَّ وُجُوهَهُمُ الْمَجَانُّ الْمُطْرَقَةُ. وَلَا تَقُومُ السَّاعَةُ حَتَّى تُقَاتِلُوا قَوْمًا نِعَالُهُمُ الشَّعَرُ". (ق,د,ت,ن,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "കണ്ണുകൾ ചെറുതായ, മൂക്കുകൾ പരുപരുത്ത് പതിഞ്ഞ, മുഖങ്ങൾ തോൽ വെക്കപ്പെട്ട പരിചകൾ പോലെയായ ഒരു വിഭാഗത്തോട് നിങ്ങൾ യുദ്ധം ചെയ്യുന്നത് വരെ അന്ത്യനാൾ സംഭവിക്കുകയില്ല. രോമം കൊണ്ടുണ്ടാക്കുന്ന ചെരുപ്പ് ധരിക്കുന്ന ഒരു വിഭാഗത്തോട് നിങ്ങൾ യുദ്ധം ചെയ്യുന്നത് വരെ അന്ത്യനാൾ സംഭവിക്കുകയില്ല." (ബു,മു,ദ,തു,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 738, 738, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 102, 'عَنْ عَمْرِو بْنِ تَغْلِبَ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "إِنَّ مِنْ أَشْرَاطِ السَّاعَةِ أَنْ تُقَاتِلُوا قَوْمًا عِرَاضَ الْوُجُوهِ، كَأَنَّ وُجُوهَهُمُ الْمَجَانُّ الْمُطْرَقَةُ، وَإِنَّ مِنْ أَشْرَاطِ السَّاعَةِ أَنْ تُقَاتِلُوا قَوْمًا يَنْتَعِلُونَ الشَّعَرَ". (خ,جه)', 'അംറുബ്നു തഗ്‌ലിബ്(റ): നബി(സ) പറയുന്നത് ഞാൻ കേട്ടു: "മുഖങ്ങൾ വീതിയുള്ള, തോൽ വെക്കപ്പെട്ട പരിചകൾ പോലെയുള്ള മുഖങ്ങളുള്ള ഒരു വിഭാഗത്തോട് നിങ്ങൾ യുദ്ധം ചെയ്യൽ അന്ത്യനാളിന്റെ അടയാളങ്ങളിൽ പെട്ടതാണ്. രോമം കൊണ്ടുള്ള ചെരുപ്പ് ധരിക്കുന്ന ഒരു വിഭാഗത്തോട് നിങ്ങൾ യുദ്ധം ചെയ്യൽ അന്ത്യനാളിന്റെ അടയാളങ്ങളിൽ പെട്ടതാണ്." (ബു,ജ)', 'عَمْرِو بْنِ تَغْلِبَ', 'അംറുബ്നു തഗ്‌ലിബ്(റ)', null, null, array['خ','جه']::text[], array['ബു','ജ']::text[], null, null, 739, 739, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 103, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا تَقُومُ السَّاعَةُ حَتَّى تُقَاتِلُوا قَوْمًا صِغَارَ الأَعْيُنِ، عِرَاضَ الْوُجُوهِ، كَأَنَّ أَعْيُنَهُمْ حَدَقُ الْجَرَادِ، كَأَنَّ وُجُوهَهُمُ الْمَجَانُّ الْمُطْرَقَةُ، يَنْتَعِلُونَ الشَّعَرَ وَيَتَّخِذُونَ الدَّرَقَ، يَرْبُطُونَ خَيْلَهُمْ بِالنَّخْلِ". (جه)', 'അബൂസഈദിൽ ഖുദ്‌രി(റ): റസൂൽ(സ) പറഞ്ഞു: "കണ്ണുകൾ ചെറുതായ, മുഖങ്ങൾ വീതിയുള്ള ഒരു വിഭാഗത്തോട് നിങ്ങൾ യുദ്ധം ചെയ്യുന്നത് വരെ അന്ത്യനാൾ സംഭവിക്കുകയില്ല. വെട്ടുകിളിയുടെ കണ്ണ് പോലെയായിരിക്കും അവരുടെ കണ്ണുകൾ. തോൽ വെക്കപ്പെട്ട പരിച പോലെയായിരിക്കും അവരുടെ മുഖങ്ങൾ. അവർ രോമം കൊണ്ടുള്ള ചെരുപ്പായിരിക്കും ധരിക്കുക. തോൽ മാത്രം ഉപയോഗിച്ചുണ്ടാക്കിയ പരിചയായിരിക്കും അവർ ഉപയോഗിക്കുക. ഈത്തപ്പനയിലായിരിക്കും അവരുടെ കുതിരകളെ അവർ ബന്ധിക്കുക." (ജ)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്‌രി(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 739, 739, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 104, 'عَنْ أَبِي سُكَيْنَةَ - رَجُلٌ مِنَ الْمُحَرَّرِينَ - عَنْ رَجُلٍ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ: "دَعُوا الْحَبَشَةَ مَا وَدَعُوكُمْ، وَاتْرُكُوا التُّرْكَ مَا تَرَكُوكُمْ". (د,ن)', 'അബൂസുകൈന(റ): - സ്വതന്ത്രരാക്കപ്പെട്ടവരിലൊരാളായ - അദ്ദേഹം നബി(സ)യുടെ അനുചരരിൽ പെട്ട ഒരാളിൽ നിന്നും നിവേദനം: നബി(സ) പറഞ്ഞു: "നിങ്ങളെ ഒഴിച്ചിടുന്ന കാലത്തോളം അബ്സീനിയയെ നിങ്ങൾ ഒഴിച്ചിടുക, നിങ്ങളെ ഉപേക്ഷിക്കുന്നിടത്തോളം തുർക്കിയെ നിങ്ങൾ ഉപേക്ഷിക്കുക." (ദ,ന)', 'أَبِي سُكَيْنَةَ - رَجُلٌ مِنَ الْمُحَرَّرِينَ - عَنْ رَجُلٍ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ', 'അബൂസുകൈന(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 739, 739, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 105, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "اتْرُكُوا الْحَبَشَةَ مَا تَرَكُوكُمْ، فَإِنَّهُ لَا يَسْتَخْرِجُ كَنْزَ الْكَعْبَةِ إِلَّا ذُو السُّوَيْقَتَيْنِ مِنَ الْحَبَشَةِ". (د)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): നബി(സ)പറഞ്ഞു: "നിങ്ങളെ ഉപേക്ഷിക്കുന്നിടത്തോളം അബ്സീനിയയെ നിങ്ങൾ ഒഴിവാക്കുക. കാരണം അബ്സീനിയയിലെ രണ്ട് കുള്ളൻ കാലുകളുള്ളവനല്ലാതെ കഅ്ബയുടെ നിധി പുറത്തെടുക്കുകയില്ല." (ദ)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 739, 739, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 106, 'عَنْ ثَوْبَانَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "يُوشِكُ الأُمَمُ أَنْ تَدَاعَى عَلَيْكُمْ كَمَا تَدَاعَى الأَكَلَةُ إِلَى قَصْعَتِهَا". فَقَالَ قَائِلٌ: وَمِنْ قِلَّةٍ نَحْنُ يَوْمَئِذٍ؟ قَالَ: "بَلْ أَنْتُمْ يَوْمَئِذٍ كَثِيرٌ، وَلَكِنَّكُمْ غُثَاءٌ كَغُثَاءِ السَّيْلِ، وَلَيَنْزِعَنَّ اللهُ مِنْ صُدُورِ عَدُوِّكُمُ الْمَهَابَةَ مِنْكُمْ، وَلَيَقْذِفَنَّ اللهُ فِي قُلُوبِكُمُ الْوَهْنَ". فَقَالَ قَائِلٌ: يَا رَسُولَ اللهِ، وَمَا الْوَهْنُ؟ قَالَ: "حُبُّ الدُّنْيَا وَكَرَاهِيَةُ الْمَوْتِ". (د)', 'സൗബാൻ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഭക്ഷണം കഴിക്കുന്നവർ തങ്ങളുടെ തളികകളിലേക്ക് മുന്നിടും പോലെ മറ്റു സമുദായക്കാർ നിങ്ങൾക്കെതിരിൽ സംഘടിക്കാനടുത്തിരിക്കുന്നു." അപ്പോൾ ഒരാൾ ചോദിച്ചു: ആ സമയത്ത് ഞങ്ങൾ തുച്ഛമായത് കൊണ്ടാകുമോ അത് സംഭവിക്കുക? റസൂൽ(സ) പറഞ്ഞു: "അല്ല, നിങ്ങൾ ആ സമയത്ത് ധാരാളമായിരിക്കും. പക്ഷേ, മഴവെള്ളപ്പാച്ചിലിലെ ചവറുകൾ പോലെ ചവറുകളായിരിക്കും നിങ്ങൾ. നിങ്ങളുടെ ശത്രുക്കളുടെ ഹൃദയങ്ങളിൽ നിന്നും നിങ്ങളോടുള്ള ഭയത്തെ അല്ലാഹു ഇല്ലാതാക്കും. നിങ്ങളുടെ ഹൃദയങ്ങളിൽ അല്ലാഹു ''വഹ്ൻ'' (ബലക്ഷയം) ഇട്ടുതരും." അപ്പോൾ ഒരാൾ ചോദിച്ചു: തിരുദൂതരേ, എന്താണ് ''വഹ്ൻ''? റസൂൽ(സ) പറഞ്ഞു: "ദുൻയാവിനോടുള്ള പ്രേമവും മരണത്തോടുള്ള വെറുപ്പും." (ദ)', 'ثَوْبَانَ', 'സൗബാൻ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 739, 740, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 107, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "قَدْ مَاتَ كِسْرَى فَلَا كِسْرَى بَعْدَهُ، وَإِذَا هَلَكَ قَيْصَرُ فَلَا قَيْصَرَ بَعْدَهُ، وَالَّذِي نَفْسِي بِيَدِهِ لَتُنْفَقَنَّ كُنُوزُهُمَا فِي سَبِيلِ اللهِ". (م,ت)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "കിസ്റ മരിച്ചിരിക്കുന്നു. ഇനി അവന് ശേഷം ഒരു കിസ്റയില്ല. ഖൈസർ നശിച്ചാൽ അതിന് ശേഷം ഒരു ഖൈസറില്ല. എന്റെ ശരീരം ആരുടെ കരങ്ങളിലാണോ അവനെത്തന്നെ സത്യം, അവർ രണ്ടുപേരുടെയും നിധികൾ അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ ചെലവഴിക്കപ്പെടും." (മു,തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','ت']::text[], array['മു','തു']::text[], null, null, 740, 740, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 108, 'عَنْ جَابِرِ بْنِ سَمُرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَتَفْتَحَنَّ عِصَابَةٌ مِنَ الْمُسْلِمِينَ - أَوْ مِنَ الْمُؤْمِنِينَ - كَنْزَ آلِ كِسْرَى الَّذِي فِي الأَبْيَضِ". قَالَ قُتَيْبَةُ: "مِنَ الْمُسْلِمِينَ". وَلَمْ يَشُكَّ. (م)', 'ജാബിറുബ്നു സമുറ(റ): റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "മുസ്ലിംകളിൽ നിന്ന് - അല്ലെങ്കിൽ മുഅ്മിനീങ്ങളിൽ - ഒരു വിഭാഗം വെള്ളക്കോട്ടയിലുള്ള കിസ്റാ കുടുംബത്തിന്റെ നിധി ജയിച്ചടക്കും." ഖുതൈബ(റ) പറഞ്ഞു: "മുസ്ലിംകളിൽ നിന്ന്" (എന്ന് തന്നെയാണ് നബി(സ) പറഞ്ഞത്). അദ്ദേഹം സംശയിച്ചിട്ടില്ല. (മു)', 'جَابِرِ بْنِ سَمُرَةَ', 'ജാബിറുബ്നു സമുറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 740, 740, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 109, 'عَنْ أَبِي بَكْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "يَنْزِلُ نَاسٌ مِنْ أُمَّتِي بِغَائِطٍ يُسَمُّونَهُ الْبَصْرَةَ، عِنْدَ نَهْرٍ يُقَالُ لَهُ دِجْلَةُ، يَكُونُ عَلَيْهِ جِسْرٌ، يَكْثُرُ أَهْلُهَا وَتَكُونُ مِنْ أَمْصَارِ الْمُهَاجِرِينَ - وَفِي رِوَايَةٍ: تَكُونُ مِنْ أَمْصَارِ الْمُسْلِمِينَ - فَإِذَا كَانَ فِي آخِرِ الزَّمَانِ جَاءَ بَنُو قَنْطُورَاءَ - عِرَاضُ الْوُجُوهِ، صِغَارُ الأَعْيُنِ - حَتَّى يَنْزِلُوا عَلَى شَطِّ النَّهْرِ، فَيَتَفَرَّقُ أَهْلُهَا ثَلَاثَ فِرَقٍ: فِرْقَةٌ يَأْخُذُونَ أَذْنَابَ الْبَقَرِ وَالْبَرِّيَّةِ وَهَلَكُوا، وَفِرْقَةٌ يَأْخُذُونَ لأَنْفُسِهِمْ وَكَفَرُوا، وَفِرْقَةٌ يَجْعَلُونَ ذَرَارِيَّهُمْ خَلْفَ ظُهُورِهِمْ وَيُقَاتِلُونَهُمْ، وَهُمُ الشُّهَدَاءُ". (د)', 'അബൂബക്റ(റ): റസൂൽ(സ) പറഞ്ഞു: "എന്റെ സമുദായത്തിലെ ചില ആളുകൾ, ബസ്വറ എന്ന് നിങ്ങൾ വിളിക്കുന്ന ദേശത്തെ, വിശാലമായ പതിഞ്ഞ ഭൂമിയിൽ, ടൈഗ്രീസ് എന്ന് വിളിക്കപ്പെടുന്ന നദിക്കരികെ ഇറങ്ങും. ആ നദിക്ക് മീതെ ഒരു പാലമുണ്ടാകും. ബസ്വറ നിവാസികൾ അധികരിക്കും. അത് മുഹാജിറുകളുടെ പ്രവിശ്യകളിൽ പെട്ടതായിരിക്കും - മറ്റൊരു റിപ്പോർട്ടിൽ: അത് മുസ്ലിംകളുടെ പ്രവിശ്യകളിൽ പെട്ടവയായിരിക്കും - അങ്ങനെ അവസാന കാലമായാൽ കണ്ണുകൾ ചെറുതായ, മുഖം വീതി കൂടിയ, ഖൻത്വൂറാഇന്റെ മക്കൾ (തുർക്കികൾ) വരും. അവർ ഈ നദിയുടെ ഒരു തീരത്തിറങ്ങും. അപ്പോൾ ബസ്വറ നിവാസികൾ മൂന്നു വിഭാഗമാകും. ഒരു വിഭാഗം പശുക്കളുടെ വാൽ പിടിച്ചും തരിശു ഭൂമി നോക്കിയും (കൃഷിയിലും മറ്റുമായി) ഏർപ്പെടും. അവർ നശിച്ചുപോകും. മറ്റൊരു വിഭാഗം സ്വാർത്ഥ താൽപര്യങ്ങൾ സംരക്ഷിക്കാൻ രംഗത്തിറങ്ങും. അവർ സത്യനിഷേധികളായി മാറും. മൂന്നാമത്തെ വിഭാഗം തങ്ങളുടെ സന്താനങ്ങളെ പിന്നിൽ നിർത്തി ശത്രുക്കളോട് യുദ്ധം ചെയ്യുന്നവരാണ്. അവരാണ് രക്തസാക്ഷികൾ." (ദ)', 'أَبِي بَكْرَةَ', 'അബൂബക്റ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 740, 741, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=13 and h.hadith_no=109), 1, 'وَفِي رِوَايَةٍ: تَكُونُ مِنْ أَمْصَارِ الْمُسْلِمِينَ - فَإِذَا كَانَ فِي آخِرِ الزَّمَانِ جَاءَ بَنُو قَنْطُورَاءَ - عِرَاضُ الْوُجُوهِ، صِغَارُ الأَعْيُنِ - حَتَّى يَنْزِلُوا عَلَى شَطِّ النَّهْرِ، فَيَتَفَرَّقُ أَهْلُهَا ثَلَاثَ فِرَقٍ: فِرْقَةٌ يَأْخُذُونَ أَذْنَابَ الْبَقَرِ وَالْبَرِّيَّةِ وَهَلَكُوا، وَفِرْقَةٌ يَأْخُذُونَ لأَنْفُسِهِمْ وَكَفَرُوا، وَفِرْقَةٌ يَجْعَلُونَ ذَرَارِيَّهُمْ خَلْفَ ظُهُورِهِمْ وَيُقَاتِلُونَهُمْ، وَهُمُ الشُّهَدَاءُ". (د)', 'മറ്റൊരു നിവേദനിൽ: അത് മുസ്ലിംകളുടെ പ്രവിശ്യകളിൽ പെട്ടവയായിരിക്കും - അങ്ങനെ അവസാന കാലമായാൽ കണ്ണുകൾ ചെറുതായ, മുഖം വീതി കൂടിയ, ഖൻത്വൂറാഇന്റെ മക്കൾ (തുർക്കികൾ) വരും. അവർ ഈ നദിയുടെ ഒരു തീരത്തിറങ്ങും. അപ്പോൾ ബസ്വറ നിവാസികൾ മൂന്നു വിഭാഗമാകും. ഒരു വിഭാഗം പശുക്കളുടെ വാൽ പിടിച്ചും തരിശു ഭൂമി നോക്കിയും (കൃഷിയിലും മറ്റുമായി) ഏർപ്പെടും. അവർ നശിച്ചുപോകും. മറ്റൊരു വിഭാഗം സ്വാർത്ഥ താൽപര്യങ്ങൾ സംരക്ഷിക്കാൻ രംഗത്തിറങ്ങും. അവർ സത്യനിഷേധികളായി മാറും. മൂന്നാമത്തെ വിഭാഗം തങ്ങളുടെ സന്താനങ്ങളെ പിന്നിൽ നിർത്തി ശത്രുക്കളോട് യുദ്ധം ചെയ്യുന്നവരാണ്. അവരാണ് രക്തസാക്ഷികൾ." (ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 110, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ لَهُ: "يَا أَنَسُ، إِنَّ النَّاسَ يُمَصِّرُونَ أَمْصَارًا، وَإِنَّ مِصْرًا مِنْهَا يُقَالُ لَهُ الْبَصْرَةُ أَوِ الْبُصَيْرَةُ، فَإِنْ أَنْتَ مَرَرْتَ بِهَا - أَوْ دَخَلْتَهَا - فَإِيَّاكَ وَسِبَاخَهَا وَكِلَاءَهَا وَسُوقَهَا وَبَابَ أُمَرَائِهَا، وَعَلَيْكَ بِضَوَاحِيهَا، فَإِنَّهُ يَكُونُ بِهَا خَسْفٌ وَقَذْفٌ وَرَجْفٌ، وَقَوْمٌ يَبِيتُونَ يُصْبِحُونَ قِرَدَةً وَخَنَازِيرَ". (د)', 'അനസുബ്നു മാലിക്(റ): റസൂൽ(സ) അദ്ദേഹത്തോട് പറഞ്ഞു: "അനസേ, നിശ്ചയം ജനങ്ങൾ ഓരോ പ്രവിശ്യകൾ കെട്ടിപ്പടുക്കും. അതിലൊരു പട്ടണം ബസ്വറയെന്നോ ബുസൈ്വറയെന്നോ ആയിരിക്കും വിളിക്കപ്പെടുക. നീ അതിലൂടെ നടക്കാനിടയായാൽ - അല്ലെങ്കിൽ നീ അവിടെ പ്രവേശിച്ചാൽ - നിന്നെയും അവിടുത്തെ ഉപ്പുഭൂമിയെയും തുറമുഖത്തെയും അങ്ങാടികളെയും അവിടുത്തെ നേതാക്കന്മാരുടെ കവാടത്തെയും നീ സൂക്ഷിക്കുക. പട്ടണത്തിന് പുറത്തെ വെളിപ്രദേശങ്ങളിൽ നീ കഴിയുക. നിശ്ചയം, അവിടെ ഭൂമി വിഴുങ്ങലും ശക്തിയായ കല്ലെറിയലും ഭൂമികുലുക്കവും ഉണ്ടാകും. അന്തിയുറങ്ങി പ്രഭാതമാകുമ്പോൾ കുരങ്ങന്മാരും പന്നികളുമായി മാറുന്ന ഒരു വിഭാഗവും അവിടെയുണ്ടാകും." (ദ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 741, 741, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 111, 'عَنْ صَالِحِ بْنِ دِرْهَمٍ قَالَ: انْطَلَقْنَا حَاجِّينَ فَإِذَا رَجُلٌ، فَقَالَ لَنَا: إِلَى جَنْبِكُمْ قَرْيَةٌ يُقَالُ لَهَا الأُبُلَّةُ؟ قُلْنَا: نَعَمْ، قَالَ: مَنْ يَضْمَنُ لِي مِنْكُمْ أَنْ يُصَلِّيَ لِي فِي مَسْجِدِ الْعَشَّارِ رَكْعَتَيْنِ أَوْ أَرْبَعًا، وَيَقُولَ هَذِهِ لأَبِي هُرَيْرَةَ؟ سَمِعْتُ خَلِيلِي رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "إِنَّ اللهَ يَبْعَثُ مِنْ مَسْجِدِ الْعَشَّارِ يَوْمَ الْقِيَامَةِ شُهَدَاءَ، لَا يَقُومُ مَعَ شُهَدَاءِ بَدْرٍ غَيْرُهُمْ". (د)', 'സ്വാലിഹുബ്നു ദിർഹം(റ): ഞങ്ങൾ ഹജ്ജിന് വേണ്ടി പോയപ്പോൾ അവിടെ വെച്ച് ഒരു മനുഷ്യൻ ഞങ്ങളോട് ചോദിച്ചു: നിങ്ങളുടെ ആ ഭാഗത്ത് ''ഉബുല്ലത്'' എന്ന് പറയപ്പെടുന്നൊരു ഗ്രാമമുണ്ടോ? ഞങ്ങൾ പറഞ്ഞു: അതെ. അയാൾ ചോദിച്ചു: നിങ്ങളിലാരാണ് എനിക്കുവേണ്ടി ''മസ്ജിദുൽ അശ്ശാറിൽ'' രണ്ടോ നാലോ റക്അത് നമസ്കരിക്കാമെന്നും അബൂഹുറൈറ(റ)വിനോട് ഇപ്രകാരം പറയാമെന്നും ഏൽക്കുക: എന്റെ പ്രിയഭാജനം റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടിട്ടുണ്ട്: "അല്ലാഹു അന്ത്യനാളിൽ മസ്ജിദുൽ അശ്ശാറിൽ നിന്നും രക്തസാക്ഷികളെ നിയോഗിക്കും. ബദ്റിലെ രക്തസാക്ഷികളോടൊപ്പം അവരല്ലാത്തവർ നിൽക്കുകയില്ല." (ദ)', 'صَالِحِ بْنِ دِرْهَمٍ قَالَ', 'സ്വാലിഹുബ്നു ദിർഹം(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 741, 741, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 112, 'عَنْ قُرَّةَ بْنِ إِيَاسٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِذَا فَسَدَ أَهْلُ الشَّامِ فَلَا خَيْرَ فِيكُمْ، لَا تَزَالُ طَائِفَةٌ مِنْ أُمَّتِي مَنْصُورِينَ، لَا يَضُرُّهُمْ مَنْ خَذَلَهُمْ حَتَّى تَقُومَ السَّاعَةُ". حَسَنٌ صَحِيحٌ. (ت,جه)', 'ഖുർറതുബ്നു ഇയാസ്(റ): തിരുദൂതർ(സ) പറഞ്ഞു: "സിറിയക്കാർ മോശക്കാരായാൽ നിങ്ങളിൽ ഒരു നന്മയുമുണ്ടാകില്ല. എന്റെ സമുദായത്തിൽ നിന്നൊരു വിഭാഗം സഹായിക്കപ്പെട്ടവരായിക്കൊണ്ടിരിക്കും. അന്ത്യനാൾ സംഭവിക്കും വരെ അവരെ നിന്ദ്യരാക്കുന്നവർ അവർക്ക് ഒരു ബുദ്ധിമുട്ടും വരുത്തുകയില്ല." (തു,ജ)', 'قُرَّةَ بْنِ إِيَاسٍ', 'ഖുർറതുബ്നു ഇയാസ്(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 741, 742, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=29 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 113, 'عَنْ مُعَاوِيَةَ بْنِ حَيْدَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قُلْتُ: يَا رَسُولَ اللهِ، أَيْنَ تَأْمُرُنِي؟ قَالَ: "هَا هُنَا". وَنَحَا بِيَدِهِ نَحْوَ الشَّامِ. حَسَنٌ صَحِيحٌ. (ت)', 'മുആവിയതുബ്നു ഹൈദ(റ): ഞാൻ ചോദിച്ചു: തിരുദൂതരേ, എവിടേക്ക് പോകാനാണ് അങ്ങെന്നോട് കൽപിക്കുന്നത്? റസൂൽ(സ) പറഞ്ഞു: "ഇവിടെ." നബി(സ) തന്റെ കൈ കൊണ്ട് സിറിയക്ക് നേരെ ചൂണ്ടിക്കാണിച്ചു. (തു)', 'مُعَاوِيَةَ بْنِ حَيْدَةَ', 'മുആവിയതുബ്നു ഹൈദ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 742, 742, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=29 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 114, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا تَقُومُ السَّاعَةُ حَتَّى تُقَاتِلُوا قَوْمًا نِعَالُهُمُ الشَّعَرُ". وَقَدْ تَقَدَّمَ الْحَدِيثُ بِطُولِهِ، وَقَالَ فِي آخِرِ هَذِهِ الرِّوَايَةِ: "وَلَيَأْتِيَنَّ عَلَى أَحَدِكُمْ زَمَانٌ، لَأَنْ يَرَانِي أَحَبُّ إِلَيْهِ مِنْ أَنْ يَكُونَ لَهُ مِثْلُ أَهْلِهِ وَمَالِهِ". (خ)', 'അബൂഹുറൈറ(റ): തിരുമേനി(സ) പറഞ്ഞു: "രോമം കൊണ്ട് ചെരുപ്പുകൾ നിർമ്മിച്ച ഒരു ജനതയുമായി നിങ്ങൾ യുദ്ധം ചെയ്യുന്നത് വരെ അന്ത്യനാൾ സംഭവിക്കുകയില്ല." ഈ ഹദീസ് അതിന്റെ ദീർഘരൂപത്തിൽ മുമ്പ് വന്നിട്ടുണ്ട്. ഈ നിവേദനത്തിന്റെ അവസാനം റസൂൽ(സ) ഇതുകൂടി പറഞ്ഞു: "നിങ്ങളിലൊരാൾക്ക് എന്നെ കാണുന്നത് തന്റെ ധനത്തേക്കാളും സന്താനങ്ങളേക്കാളും പ്രിയങ്കരമായി തോന്നുന്ന ഒരു കാലം വരും." (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 742, 742, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=29 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 115, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا تَقُومُ السَّاعَةُ حَتَّى تُقَاتِلُوا خُوزًا وَكِرْمَانَ مِنَ الأَعَاجِمِ حُمْرَ الْوُجُوهِ، فُطْسَ الأُنُوفِ، صِغَارَ الأَعْيُنِ، كَأَنَّ وُجُوهَهُمُ الْمَجَانُّ الْمُطْرَقَةُ، نِعَالُهُمُ الشَّعَرُ". (خ)', 'അബൂഹുറൈറ(റ): തിരുമേനി(സ) പറഞ്ഞു: "അനറബികളായ ഖുസാ, കിർമാൻ എന്നീ ദേശക്കാരോട് നിങ്ങൾ യുദ്ധംചെയ്യുന്നത് വരെ അന്ത്യനാൾ സംഭവിക്കുകയില്ല. അവരുടെ മുഖങ്ങൾ ചുവന്നതും മൂക്കുകൾ പതിഞ്ഞതും കണ്ണുകൾ ചെറിയവയുമായിരിക്കും. അവരുടെ മുഖങ്ങൾ തോൽ വെക്കപ്പെട്ട പരിചകൾ പോലെയും അവരുടെ ചെരുപ്പുകൾ രോമത്തിന്റേതും ആയിരിക്കും." (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 742, 742, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=29 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 116, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا تَقُومُ السَّاعَةُ حَتَّى يُقَاتِلَ الْمُسْلِمُونَ الْيَهُودَ، فَيَقْتُلُهُمُ الْمُسْلِمُونَ، حَتَّى يَخْتَبِئَ الْيَهُودِيُّ مِنْ وَرَاءِ الْحَجَرِ وَالشَّجَرِ، فَيَقُولُ الْحَجَرُ أَوِ الشَّجَرُ: يَا مُسْلِمُ يَا عَبْدَ اللهِ، هَذَا يَهُودِيٌّ خَلْفِي، فَتَعَالَ فَاقْتُلْهُ. إِلَّا الْغَرْقَدَ فَإِنَّهُ مِنْ شَجَرِ الْيَهُودِ". (ق,ت)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "മുസ്ലിംകൾ ജൂതരോട് യുദ്ധംചെയ്യുന്നത് വരെ അന്ത്യനാൾ സംഭവിക്കുകയില്ല. അങ്ങനെ മുസ്ലിംകൾ അവരെ കൊന്നൊടുക്കും. എത്രത്തോളമെന്നാൽ ജൂതൻ കല്ലിന്റെയോ മരത്തിന്റെയോ പിന്നിലൊളിക്കുമ്പോൾ ആ കല്ലോ മരമോ വിളിച്ചുപറയും: ഓ മുസ്ലിമേ, ഓ അല്ലാഹുവിന്റെ ദാസാ, ഇതാ എന്റെ പിന്നിലൊരു ജൂതൻ. നീ വന്ന് അവനെ വധിക്കുക. പക്ഷേ, ഓർക്കിഡ് ചെടിയൊഴിച്ച്. നിശ്ചയം അത് ജൂതന്മാരുടെ വൃക്ഷങ്ങളിൽ പെട്ടതാണ്." (ബു,മു,തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','ت']::text[], array['ബു','മു','തു']::text[], null, null, 742, 742, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 117, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا تَقُومُ السَّاعَةُ حَتَّى يَنْزِلَ الرُّومُ بِالأَعْمَاقِ أَوْ بِدَابِقَ، فَيَخْرُجُ إِلَيْهِمْ جَيْشٌ مِنَ الْمَدِينَةِ مِنْ خِيَارِ أَهْلِ الأَرْضِ يَوْمَئِذٍ، فَإِذَا تَصَافُّوا قَالَتِ الرُّومُ: خَلُّوا بَيْنَنَا وَبَيْنَ الَّذِينَ سَبَوْا مِنَّا نُقَاتِلْهُمْ، فَيَقُولُ الْمُسْلِمُونَ: لَا وَاللهِ، لَا نُخَلِّي بَيْنَكُمْ وَبَيْنَ إِخْوَانِنَا، فَيُقَاتِلُونَهُمْ فَيَنْهَزِمُ ثُلُثٌ لَا يَتُوبُ اللهُ عَلَيْهِمْ أَبَدًا، وَيُقْتَلُ ثُلُثُهُمْ أَفْضَلُ الشُّهَدَاءِ عِنْدَ اللهِ، وَيَفْتَتِحُ الثُّلُثُ، لَا يُفْتَنُونَ أَبَدًا، فَيَفْتَتِحُونَ قُسْطَنْطِينِيَّةَ، فَبَيْنَمَا هُمْ يَقْتَسِمُونَ الْغَنَائِمَ، قَدْ عَلَّقُوا سُيُوفَهُمْ بِالزَّيْتُونِ إِذْ صَاحَ فِيهِمُ الشَّيْطَانُ: إِنَّ الْمَسِيحَ قَدْ خَلَفَكُمْ فِي أَهْلِيكُمْ، فَيَخْرُجُونَ، وَذَلِكَ بَاطِلٌ، فَإِذَا جَاءُوا الشَّامَ خَرَجَ، فَبَيْنَمَا هُمْ يُعِدُّونَ لِلْقِتَالِ يُسَوُّونَ الصُّفُوفَ إِذْ أُقِيمَتِ الصَّلَاةُ، فَيَنْزِلُ عِيسَى بْنُ مَرْيَمَ عَلَيْهِ السَّلَامُ، فَأَمَّهُمْ، فَإِذَا رَآهُ عَدُوُّ اللهِ ذَابَ كَمَا يَذُوبُ الْمِلْحُ فِي الْمَاءِ، فَلَوْ تَرَكَهُ لَانْذَابَ حَتَّى يَهْلِكَ، وَلَكِنْ يَقْتُلُهُ اللهُ بِيَدِهِ، فَيُرِيهِمْ دَمَهُ فِي حَرْبَتِهِ". (م)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "റോമക്കാർ അഅ്മാഖിലോ ദാബിഖിലോ (വടക്കൻ സിറിയയിലെ രണ്ട് സ്ഥലങ്ങൾ) ഇറങ്ങുന്നത് വരെ അന്ത്യനാൾ സംഭവിക്കുകയില്ല. അപ്പോൾ ആ സമയത്ത് ഭൂമിയിലുള്ള ഏറ്റവും ഉത്തമരിൽ പെട്ടൊരു സൈന്യം മദീനയിൽ നിന്നും അവരിലേക്ക് പുറപ്പെടും. അങ്ങനെ അവർ അണിയണിയായി നിന്നാൽ റോമക്കാർ പറയും: ഞങ്ങളെയും ഞങ്ങളിൽ നിന്നും നിങ്ങൾ പിടിച്ചവരെയും നിങ്ങൾ വിട്ടേക്കുക, (അവരിൽ നിന്നും പിടിക്കപ്പെട്ടവർ ഇസ്ലാം സ്വീകരിച്ചിരിക്കും) ഞങ്ങൾ അവരോട് യുദ്ധം ചെയ്യട്ടെ. അപ്പോൾ മുസ്ലിംകൾ പറയും: ഇല്ല, അല്ലാഹു സത്യം, ഞങ്ങളുടെ സഹോദരങ്ങളെ നിങ്ങൾക്ക് ഞങ്ങൾ വിട്ടുതരില്ല. അങ്ങനെ അവർ റോമക്കാരോട് യുദ്ധം ചെയ്യും. അതിൽ മൂന്നിലൊരു ഭാഗം പിന്തിരിഞ്ഞോടും. അല്ലാഹു ഒരിക്കലും അവരുടെ പശ്ചാത്താപം സ്വീകരിക്കില്ല. അവരിൽ മൂന്നിലൊരു ഭാഗം കൊല്ലപ്പെടും. അവർ അല്ലാഹുവിന്റെ അടുക്കൽ രക്തസാക്ഷികളിലെ ശ്രേഷ്ഠരായിരിക്കും. മൂന്നിലൊരു ഭാഗം വിജയം വരിക്കും. അവർ ഒരിക്കലും ഫിത്നയിലകപ്പെടില്ല. അങ്ങനെ അവർ കോൺസ്റ്റാന്റിനോപ്പിൾ കീഴടക്കും. അങ്ങനെ സൈതൂൺ മരത്തിൽ വാളുകൾ തൂക്കിയിട്ട് അവർ യുദ്ധമുതലുകൾ ഓഹരി വെക്കുമ്പോൾ പിശാച് വന്ന് അവരോട് പറയും: നിശ്ചയം മസീഹ് - ദജ്ജാൽ - നിങ്ങളുടെ കുടുംബങ്ങളിൽ ഇറങ്ങിയിരിക്കുന്നു. അപ്പോൾ അവർ പുറപ്പെടും. പിശാച് പറഞ്ഞത് കളവായിരിക്കും. അങ്ങനെ അവർ സിറിയയിൽ ചെന്നാൽ ദജ്ജാൽ പുറപ്പെടും. അങ്ങനെയവർ അണികൾ ശരിപ്പെടുത്തി യുദ്ധത്തിനൊരുങ്ങുമ്പോൾ നിസ്കാരം നിർവഹിക്കപ്പെടും. അപ്പോൾ ഈസബ്നു മർയം(അ) ഇറങ്ങിവന്ന് അവർക്ക് ഇമാമത്ത് നിൽക്കും. ഈസാ നബി(അ)നെ അല്ലാഹുവിന്റെ ശത്രു കണ്ടാൽ വെള്ളത്തിൽ ഉപ്പ് അലിയുംപോലെ അവൻ ഉരുകിപ്പോകും. അവനെ ഉപേക്ഷിച്ചിട്ടാൽ അവൻ മരിക്കും വരെ ഉരുകിക്കൊണ്ടിരിക്കും. പക്ഷേ, ഈസാ നബി(സ)യുടെ കരം കൊണ്ട് അല്ലാഹു ദജ്ജാലിനെ വധിക്കും. എന്നിട്ട് ഈസാ നബി(അ) തന്റെ കുന്തത്തിലുള്ള അവന്റെ രക്തം അവർക്ക് കാണിച്ചുകൊടുക്കും." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 743, 743, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 118, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "يُوشِكُ الْفُرَاتُ يَحْسِرُ عَنْ كَنْزٍ - وَفِي رِوَايَةٍ: جَبَلٍ - مِنْ ذَهَبٍ، فَمَنْ حَضَرَهُ فَلَا يَأْخُذْ مِنْهُ شَيْئًا". (ق,د,ت,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "യൂഫ്രട്ടീസ് നദിയിൽ സ്വർണത്തിന്റെ ഒരു മല - മറ്റൊരു നിവേദനത്തിൽ: നിധി - പ്രത്യക്ഷപ്പെടാൻ സമയം അടുത്തിരിക്കുന്നു. ആരെങ്കിലും അവിടെ സന്നിഹിതരാവുകയാണെങ്കിൽ അതിൽ നിന്ന് ഒന്നുംതന്നെ എടുക്കരുത്." (ബു,മു,ദ,തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], null, null, 743, 743, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=32 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=13 and h.hadith_no=118), 1, 'وَفِي رِوَايَةٍ: جَبَلٍ - مِنْ ذَهَبٍ، فَمَنْ حَضَرَهُ فَلَا يَأْخُذْ مِنْهُ شَيْئًا". (ق,د,ت,جه)', 'മറ്റൊരു നിവേദനത്തിൽ: നിധി - പ്രത്യക്ഷപ്പെടാൻ സമയം അടുത്തിരിക്കുന്നു. ആരെങ്കിലും അവിടെ സന്നിഹിതരാവുകയാണെങ്കിൽ അതിൽ നിന്ന് ഒന്നുംതന്നെ എടുക്കരുത്." (ബു,മു,ദ,തു,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 119, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَوْ لَمْ يَبْقَ مِنَ الدُّنْيَا إِلَّا يَوْمٌ لَطَوَّلَ اللهُ ذَلِكَ الْيَوْمَ، حَتَّى يَبْعَثَ فِيهِ رَجُلًا مِنِّي - أَوْ مِنْ أَهْلِ بَيْتِي - يُوَاطِئُ اسْمُهُ اسْمِي، وَاسْمُ أَبِيهِ اسْمَ أَبِي، يَمْلأُ الأَرْضَ قِسْطًا وَعَدْلًا كَمَا مُلِئَتْ ظُلْمًا وَجَوْرًا". وَ فِي رِوَايَةٍ: "لَا تَذْهَبُ - أَوْ: لَا تَنْقَضِي الدُّنْيَا - حَتَّى يَمْلِكَ الْعَرَبَ رَجُلٌ مِنْ أَهْلِ بَيْتِي، يُوَاطِئُ اسْمُهُ اسْمِي". (د)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): നബി(സ) പറഞ്ഞു: "ദുനിയാവിലെ ഒരു ദിനം മാത്രം ശേഷിക്കുമ്പോൾ അല്ലാഹു ആ ദിനത്തെ വലിച്ച് നീട്ടും, അങ്ങനെ എന്നിൽ നിന്ന് - അല്ലെങ്കിൽ എന്റെ കുടുംബത്തിൽ നിന്ന് - ഒരാളെ അല്ലാഹു നിയോഗിക്കും. അദ്ദേഹത്തിന്റെ പേര് എന്റെ പേരിനോട് സമാനമായതായിരിക്കും. അദ്ദേഹത്തിന്റെ പിതാവിന്റെ പേര് എന്റെ പിതാവിന്റെ പേരായിരിക്കും. ഭൂമിയിലാകമാനം അദ്ദേഹം നീതിയും സമത്വവും നിറക്കും, അക്രമവും അനീതിയും ഭൂമിയിൽ നിറഞ്ഞിരുന്നത് പോലെ." മറ്റൊരു നിവേദനം: "എന്റെ കുടുംബത്തിൽ പെട്ട ഒരാൾ അറബികൾക്കുമേൽ ആധിപത്യം സ്ഥാപിക്കുന്നത് വരെ ഈ ദുനിയാവ് നശിക്കുകയില്ല - അല്ലെങ്കിൽ ദുനിയാവ് അവസാനിക്കുകയില്ല - അദ്ദേഹത്തിന്റെ പേര് എന്റെ പേരിനോട് യോജിച്ചതായിരിക്കും." (ദ)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 744, 744, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=13 and h.hadith_no=119), 1, null, 'മറ്റൊരു നിവേദനം: "എന്റെ കുടുംബത്തിൽ പെട്ട ഒരാൾ അറബികൾക്കുമേൽ ആധിപത്യം സ്ഥാപിക്കുന്നത് വരെ ഈ ദുനിയാവ് നശിക്കുകയില്ല - അല്ലെങ്കിൽ ദുനിയാവ് അവസാനിക്കുകയില്ല - അദ്ദേഹത്തിന്റെ പേര് എന്റെ പേരിനോട് യോജിച്ചതായിരിക്കും." (ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 120, 'عَنْ أُمِّ سَلَمَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "الْمَهْدِيُّ مِنْ عِتْرَتِي مِنْ وَلَدِ فَاطِمَةَ". (د,جه)', 'ഉമ്മുസലമ(റ): റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "മഹ്ദി ഫാത്തിമയുടെ സന്തതികളിൽ പെട്ട എന്റെ കുടുംബക്കാരനാണ്." (ദ,ജ)', 'أُمِّ سَلَمَةَ', 'ഉമ്മുസലമ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 744, 744, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 121, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "الْمَهْدِيُّ مِنِّي، أَجْلَى الْجَبْهَةِ، أَقْنَى الأَنْفِ، يَمْلأُ الأَرْضَ قِسْطًا وَعَدْلًا كَمَا مُلِئَتْ جَوْرًا وَظُلْمًا، يَمْلِكُ سَبْعَ سِنِينَ". (د)', 'അബൂസഈദിൽഖുദ്രി(റ): റസൂൽ(സ) പറഞ്ഞു: "മഹ്ദി എന്നിൽ നിന്നുള്ളയാളാണ്. വിശാല നെറ്റിത്തടവും ഉയർന്ന മൂക്കും ഉള്ളയാളാണ്. ഭൂമിയിൽ അക്രമവും അനീതിയും നിറഞ്ഞത് പോലെ, അദ്ദേഹം ഭൂമിയിലാകമാനം നീതിയും സമത്വവും നിറക്കും. ഏഴ് വർഷം അദ്ദേഹം ഭരണം നടത്തും." (ദ)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽഖുദ്രി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 744, 744, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 122, 'عَنْ أُمِّ سَلَمَةَ رَضِيَ اللهُ عَنْهَا، زَوْجِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "يَكُونُ اخْتِلَافٌ عِنْدَ مَوْتِ خَلِيفَةٍ، فَيَخْرُجُ رَجُلٌ مِنْ أَهْلِ الْمَدِينَةِ هَارِبًا إِلَى مَكَّةَ، فَيَأْتِيهِ نَاسٌ مِنْ أَهْلِ مَكَّةَ فَيُخْرِجُونَهُ وَهُوَ كَارِهٌ، فَيُبَايِعُونَهُ بَيْنَ الرُّكْنِ وَالْمَقَامِ، وَيُبْعَثُ إِلَيْهِ بَعْثٌ مِنْ أَهْلِ الشَّامِ. فَيُخْسَفُ بِهِمْ بِالْبَيْدَاءِ بَيْنَ مَكَّةَ وَالْمَدِينَةِ، فَإِذَا رَأَى النَّاسُ ذَلِكَ أَتَاهُ أَبْدَالُ الشَّامِ وَعَصَائِبُ أَهْلِ الْعِرَاقِ، فَيُبَايِعُونَهُ بَيْنَ الرُّكْنِ وَالْمَقَامِ، ثُمَّ يَنْشَأُ رَجُلٌ مِنْ قُرَيْشٍ أَخْوَالُهُ كَلْبٌ، فَيَبْعَثُ إِلَيْهِمْ بَعْثًا فَيَظْهَرُونَ عَلَيْهِمْ، وَذَلِكَ بَعْثُ كَلْبٍ، وَالْخَيْبَةُ لِمَنْ لَمْ يَشْهَدْ غَنِيمَةَ كَلْبٍ، فَيَقْسِمُ الْمَالَ، وَيَعْمَلُ فِي النَّاسِ بِسُنَّةِ نَبِيِّهِمْ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَيُلْقِي الإِسْلَامُ بِجِرَانِهِ فِي الأَرْضِ، فَيَلْبَثُ سَبْعَ سِنِينَ - وَفِي رِوَايَةٍ: تِسْعَ سِنِينَ - ثُمَّ يُتَوَفَّى وَيُصَلِّي عَلَيْهِ الْمُسْلِمُونَ". وَفِي رِوَايَةٍ: قَالَتْ: قُلْتُ: يَا رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَكَيْفَ بِمَنْ كَانَ كَارِهًا؟ قَالَ: "يُخْسَفُ بِهِمْ، وَلَكِنْ يُبْعَثُ يَوْمَ الْقِيَامَةِ عَلَى نِيَّتِهِ". (م,د)', 'പ്രവാചക പത്നി ഉമ്മുസലമ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഒരു ഖലീഫയുടെ മരണാനന്തരം ഭിന്നതകൾ ഉണ്ടാകും. അപ്പോൾ മദീനക്കാരനായ ഒരാൾ മക്കയിലേക്ക് ഒളിച്ചോടും. മക്കക്കാർ അദ്ദേഹത്തെ സമീപിച്ച് നിർബന്ധിച്ച് പുറത്ത് കൊണ്ട് വരും. റുക്നിനും മഖാമിനുമിടയിൽ വെച്ച് അവർ അദ്ദേഹത്തെ ബൈഅത്ത് ചെയ്യും. അദ്ദേഹത്തിനെതിരെ ശാമിൽ നിന്ന് ഒരു സൈന്യം അയക്കപ്പെടും. മക്കയുടെയും മദീനയുടെയും ഇടയിലെ ''ബൈദാഅ്'' എന്ന സ്ഥലത്ത് വെച്ച് ഭൂമി അവരെ വിഴുങ്ങും. ഇത് കണ്ട് ശാമിലെ അബ്ദാലുകളും ഇറാക്കിലെ ഉന്നതരും അദ്ദേഹത്തിന്റെ അടുത്ത് വരും. റുക്നിനും മഖാമിനും ഇടയിൽ വെച്ച് അവർ അദ്ദേഹത്തെ ബൈഅത്ത് ചെയ്യും. ശേഷം ഖുറൈശിയായ ഒരാൾ വരും. അദ്ദേഹത്തിന്റെ മാതൃസഹോദരങ്ങൾ കൽബ് ഗോത്രക്കാരായിരിക്കും. അപ്പോൾ ആ ഖലീഫ അയാൾക്കെതിരെ സൈന്യത്തെ അയക്കുകയും അവരെ കീഴ്പെടുത്തുകയും ചെയ്യും. ഇതാണ് കൽബിന്റെ സൈന്യം. കൽബിന്റെ യുദ്ധമുതലിന് സാക്ഷിയാകാത്തവർക്കാണ് നാശം. ഖലീഫ സ്വത്ത് വീതം വെക്കും. പ്രവാചക ചര്യകൊണ്ട് ജനങ്ങൾക്കിടയിൽ ഭരണം നടത്തും. ഭൂമിയിൽ ഇസ്ലാം വേരുറക്കും. ഏഴ് വർഷം - ഒരു നിവേദന പ്രകാരം: ഒമ്പത് വർഷം - അദ്ദേഹം ജീവിക്കും. ശേഷം വഫാതാവുകയും മുസ്ലിംകൾ അദ്ദേഹത്തിനുമേലിൽ നിസ്കരിക്കുകയും ചെയ്യും." മറ്റൊരു നിവേദനം: മഹതി പറയുന്നു: ഞാൻ ചോദിച്ചു: റസൂലേ, നിർബന്ധിതനായി ആ സൈന്യത്തിൽ കൂടിയവന്റെ അവസ്ഥയെന്താണ്? പ്രവാചകർ(സ) പറഞ്ഞു: "അവരെയും (ഭൂമി) വിഴുങ്ങും, പക്ഷെ, അന്ത്യനാളിൽ അവരുടെ കരുത്ത് അനുസരിച്ച് അവർ പുനർജനിപ്പിക്കപ്പെടും." (മു,ദ)', 'أُمِّ سَلَمَةَ', 'പ്രവാചക പത്നി ഉമ്മുസലമ(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 744, 745, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=13 and h.hadith_no=122), 1, 'وَفِي رِوَايَةٍ: تِسْعَ سِنِينَ - ثُمَّ يُتَوَفَّى وَيُصَلِّي عَلَيْهِ الْمُسْلِمُونَ".', 'മറ്റൊരു നിവേദനം: മഹതി പറയുന്നു: ഞാൻ ചോദിച്ചു: റസൂലേ, നിർബന്ധിതനായി ആ സൈന്യത്തിൽ കൂടിയവന്റെ അവസ്ഥയെന്താണ്? പ്രവാചകർ(സ) പറഞ്ഞു: "അവരെയും (ഭൂമി) വിഴുങ്ങും, പക്ഷെ, അന്ത്യനാളിൽ അവരുടെ കരുത്ത് അനുസരിച്ച് അവർ പുനർജനിപ്പിക്കപ്പെടും." (മു,ദ)');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=13 and h.hadith_no=122), 2, 'وَفِي رِوَايَةٍ: قَالَتْ: قُلْتُ: يَا رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَكَيْفَ بِمَنْ كَانَ كَارِهًا؟ قَالَ: "يُخْسَفُ بِهِمْ، وَلَكِنْ يُبْعَثُ يَوْمَ الْقِيَامَةِ عَلَى نِيَّتِهِ". (م,د)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 123, 'عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ، وَنَظَرَ إِلَى ابْنِهِ الْحَسَنِ فَقَالَ: إِنَّ ابْنِي هَذَا سَيِّدٌ، كَمَا سَمَّاهُ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَسَيَخْرُجُ مِنْ صُلْبِهِ رَجُلٌ يُسَمَّى بِاسْمِ نَبِيِّكُمْ، يُشْبِهُهُ فِي الْخُلُقِ وَلَا يُشْبِهُهُ فِي الْخَلْقِ، يَمْلأُ الأَرْضَ عَدْلًا. (د)', 'അലി(റ): തന്റെ മകൻ ഹസൻ(റ)വിനെ നോക്കിക്കൊണ്ട് അലി(റ) പറഞ്ഞു: എന്റെ ഈ പുത്രൻ, പ്രവാചകർ(സ) അവനെ വിളിച്ചത് പോലെത്തന്നെ നേതാവാണ്. അവന്റെ മുതുകിൽ നിന്ന് ഒരാൾ പുറപ്പെടും. അദ്ദേഹത്തിന് നിങ്ങളുടെ നബിയുടെ അതേ പേരായിരിക്കും ഉണ്ടാവുക. അദ്ദേഹത്തിന് സ്വഭാവത്തിൽ നിങ്ങളുടെ പ്രവാചകരോട് സാമ്യതയുണ്ടാകും, എന്നാൽ രൂപത്തിൽ സാമ്യതയുണ്ടാവില്ല. ഭൂമിയാകമാനം അദ്ദേഹം നീതി നിറക്കും. (ദ)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 745, 745, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 124, 'عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "يَخْرُجُ رَجُلٌ مِنْ وَرَاءِ النَّهْرِ يُقَالُ لَهُ: الْحَارِثُ بْنُ حَرَّاثٍ، عَلَى مُقَدِّمَتِهِ رَجُلٌ يُقَالُ لَهُ: مَنْصُورٌ، يُوَطِّئُ - أَوْ يُمَكِّنُ - لِآلِ مُحَمَّدٍ كَمَا مَكَّنَتْ قُرَيْشٌ لِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَجَبَ عَلَى كُلِّ مُؤْمِنٍ نَصْرُهُ". أَوْ قَالَ: "إِجَابَتُهُ". (د)', 'അലി(റ): പ്രവാചകർ(സ) പറഞ്ഞു: "മാവറാഉന്നഹ്റിൽ നിന്ന് ഹാരിസുബ്നുഹർറാസ് എന്നയാൾ പുറപ്പെടും. അദ്ദേഹത്തിന്റെ മുൻ നിര സൈന്യത്തിൽ മൻസൂർ എന്ന വ്യക്തിയുണ്ടാകും. ഖുറൈശികൾ തിരുദൂതർ(സ)ക്ക് സൗകര്യപ്പെടുത്തിക്കൊടുത്ത പോലെ അദ്ദേഹം മുഹമ്മദ്(സ)യുടെ കുടുംബത്തിന് സ്ഥാപിച്ച് കൊടുക്കും - അല്ലെങ്കിൽ കാര്യം സൗകര്യപ്പെടുത്തിക്കൊടുക്കും - അദ്ദേഹത്തെ സഹായിക്കൽ ഓരോ വിശ്വാസിക്കും നിർബന്ധമാണ്." അല്ലെങ്കിൽ ഇപ്രകാരമാണ് പറഞ്ഞത്: "അദ്ദേഹത്തിന് ഉത്തരം നൽകൽ." (ദ)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 745, 745, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 125, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: خَشِينَا أَنْ يَكُونَ بَعْدَ نَبِيِّنَا حَدَثٌ، فَسَأَلْنَا نَبِيَّ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "إِنَّ فِي أُمَّتِي الْمَهْدِيَّ، يَخْرُجُ يَعِيشُ خَمْسًا، أَوْ: سَبْعًا، أَوْ: تِسْعًا". قَالَ: قُلْنَا: وَمَا ذَاكَ؟ قَالَ: "سِنِينَ". قَالَ: "فَيَجِيءُ إِلَيْهِ رَجُلٌ فَيَقُولُ: يَا مَهْدِيُّ، أَعْطِنِي أَعْطِنِي". قَالَ: "فَيَحْثِي لَهُ فِي ثَوْبِهِ مَا اسْتَطَاعَ أَنْ يَحْمِلَهُ". حَسَنٌ. (ت,جه)', 'അബൂസഈദുൽഖുദ്രി(റ): നമ്മുടെ പ്രവാചകർക്ക് ശേഷം പല അനിഷ്ട സംഭവങ്ങളും നടക്കുമെന്ന് ഞങ്ങൾ ഭയന്നു. അപ്പോൾ ഞങ്ങൾ പ്രവാചകർ(സ)യോട് (അതിനെക്കുറിച്ച്) ചോദിച്ചു. പ്രവാചകർ(സ) പ്രതിവചിച്ചു: "എന്റെ സമുദായത്തിൽ മഹ്ദി പുറപ്പെടും. അഞ്ചോ, ഏഴോ, ഒമ്പതോ അദ്ദേഹം ജീവിക്കും." നിവേദകൻ പറയുന്നു: ഞങ്ങൾ ചോദിച്ചു: അതെന്താണ്? തിരുദൂതർ(സ) പറഞ്ഞു: "വർഷങ്ങൾ." പ്രവാചകർ(സ) പറയുന്നു: "അദ്ദേഹത്തിന്റെയടുക്കൽ ഒരാൾ വരും, എന്നിട്ട് പറയും: മഹ്ദീ, എനിക്ക് എന്തെങ്കിലും നൽകൂ. തന്റെ വസ്ത്രത്തിൽ തനിക്ക് ചുമക്കാൻ കഴിയുന്നയത്രയും മഹ്ദി അയാൾക്ക് വാരിക്കോരിക്കൊടുക്കും." (തു,ജ)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദുൽഖുദ്രി(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 745, 746, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 126, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: بَيْنَمَا نَحْنُ عِنْدَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذْ أَقْبَلَ فِتْيَةٌ مِنْ بَنِي هَاشِمٍ، فَلَمَّا رَآهُمُ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ اغْرَوْرَقَتْ عَيْنَاهُ وَتَغَيَّرَ لَوْنُهُ، قَالَ: فَقُلْتُ: مَا نَزَالُ نَرَى فِي وَجْهِكَ شَيْئًا نَكْرَهُهُ؟ فَقَالَ: "إِنَّا أَهْلُ بَيْتٍ اخْتَارَ اللهُ لَنَا الآخِرَةَ عَلَى الدُّنْيَا، وَإِنَّ أَهْلَ بَيْتِي سَيَلْقَوْنَ بَعْدِي بَلَاءً وَتَشْرِيدًا وَتَطْرِيدًا، حَتَّى يَأْتِيَ قَوْمٌ مِنْ قِبَلِ الْمَشْرِقِ مَعَهُمْ رَايَاتٌ سُودٌ، فَيَسْأَلُونَ الْخَيْرَ فَلَا يُعْطَوْنَهُ، فَيُقَاتِلُونَ فَيُنْصَرُونَ، فَيُعْطَوْنَ مَا سَأَلُوا فَلَا يَقْبَلُونَهُ، حَتَّى يَدْفَعُوهَا إِلَى رَجُلٍ مِنْ أَهْلِ بَيْتِي فَيَمْلَؤُهَا قِسْطًا كَمَا مَلَئُوهَا جَوْرًا، فَمَنْ أَدْرَكَ ذَلِكَ مِنْكُمْ فَلْيَأْتِهِمْ وَلَوْ حَبْوًا عَلَى الثَّلْجِ". [ز: فِي سَنَدِهِ ضَعِيفٌ] (جه)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): ഞങ്ങൾ പ്രവാചകർ(സ)യുടെ തിരുസന്നിധിയിൽ ഇരിക്കുകയായിരുന്നു. അപ്പോൾ ബനൂഹാശിമിൽ പെട്ട ഒരു സംഘം യുവാക്കൾ കടന്ന് വന്നു. അവരെ കണ്ടപ്പോൾ റസൂൽ(സ)യുടെ കണ്ണുകൾ നിറഞ്ഞു, അവിടത്തെ മുഖം വിവർണ്ണമായി. നിവേദകൻ പറയുന്നു: ഞാൻ ചോദിച്ചു: റസൂലേ, ഞങ്ങൾക്ക് അനിഷ്ടമായ എന്തോ അങ്ങയുടെ മുഖത്ത് ഞങ്ങൾ കണ്ട് കൊണ്ടിരിക്കുന്നുണ്ടല്ലോ? റസൂൽ(സ) പറഞ്ഞു: "നിശ്ചയം ഞങ്ങൾ അഹ്ലുബൈതാണ്. അല്ലാഹു ഞങ്ങൾക്ക് പരലോകത്തെ ഇഹലോകത്തിനുമേൽ തിരഞ്ഞെടുത്തിരിക്കുന്നു. എന്റെ അഹ്ലുബൈത്ത് എനിക്ക് ശേഷം വിപത്തുകളും നാടുകടത്തലുകളും ഒറ്റപ്പെടുത്തലുകളും അഭിമുഖീകരിക്കും. അങ്ങനെയിരിക്കെ കിഴക്ക് നിന്ന് ഒരു സമൂഹം വരും, അവരുടെ അടുത്ത് കറുത്ത കൊടികളുണ്ടാകും. അവർ നന്മയെ ചോദിക്കും. അവർക്കത് നൽകപ്പെടുകയില്ല. അപ്പോൾ അവർ യുദ്ധം ചെയ്യുകയും സഹായിക്കപ്പെടുകയും ചെയ്യും. അപ്പോൾ അവർ ചോദിച്ചത് നൽകപ്പെടും. പക്ഷെ, അവരത് സ്വീകരിക്കുകയില്ല. ശേഷം അതിനെ അവർ എന്റെ കുടുംബത്തിൽ പെട്ട ഒരു വ്യക്തിക്ക് കൈമാറും. അദ്ദേഹം അതിനെ നീതി കൊണ്ട് നിറക്കും, മുന്നെ അനീതി കൊണ്ട് നിറക്കപ്പെട്ടിരുന്നത് പോലെ. നിങ്ങളിൽ നിന്ന് ആരെങ്കിലും അക്കാലത്തുണ്ടെങ്കിൽ അവരുടെ അടുത്തേക്ക് പോകണം. മഞ്ഞുകട്ടയുടെ മുകളിലൂടെ ഇഴഞ്ഞിട്ടാണെങ്കിൽ പോലും." (ജ)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: فِي سَنَدِهِ ضَعِيفٌ', null, 746, 746, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 127, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "يَكُونُ فِي أُمَّتِي الْمَهْدِيُّ، إِنْ قُصِرَ فَسَبْعٌ، وَإِلَّا فَتِسْعٌ. فَتَنْعَمُ فِيهِ أُمَّتِي نِعْمَةً لَمْ يَنْعَمُوا مِثْلَهَا قَطُّ، تُؤْتَى أُكُلَهَا وَلَا تَدَّخِرُ مِنْهُمْ شَيْئًا، وَالْمَالُ يَوْمَئِذٍ كُدُوسٌ، فَيَقُومُ الرَّجُلُ فَيَقُولُ: يَا مَهْدِيُّ، أَعْطِنِي. فَيَقُولُ: خُذْ". (ت,جه)', 'അബൂസഈദിൽ ഖുദ്രി(റ): നബി(സ) പറഞ്ഞു: "എന്റെ ഉമ്മത്തിൽ മഹ്ദി വരും. ചുരുങ്ങിയത് ഏഴ് അല്ലെങ്കിൽ ഒമ്പത് വർഷം അദ്ദേഹം ജീവിക്കും. ആ കാലഘട്ടത്തിൽ എന്റെ ഉമ്മത്ത് മുമ്പെങ്ങും അനുഭവിച്ചിട്ടില്ലാത്ത വിധം സുഖസൗകര്യങ്ങളുള്ള ജീവിതം ആസ്വദിക്കും. ഭൂമി അതിന്റെ ഫലങ്ങളെ പുറപ്പെടീക്കും. അതിൽ നിന്ന് ഒന്നിനെയും പിടിച്ചുവെക്കുകയില്ല. അന്ന് ധനം കുന്നുകൂടും. അന്ന് ഒരാൾ എഴുന്നേറ്റുനിന്ന് പറയും: മഹ്ദീ, എനിക്ക് എന്തെങ്കിലും തരൂ. അപ്പോൾ മഹ്ദി പറയും: എടുത്തോളൂ." (തു,ജ)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്രി(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 746, 746, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 128, 'عَنْ ثَوْبَانَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "يَقْتَتِلُ عِنْدَ كَنْزِكُمْ ثَلَاثَةٌ، كُلُّهُمُ ابْنُ خَلِيفَةٍ، ثُمَّ لَا يَصِيرُ إِلَى وَاحِدٍ مِنْهُمْ. ثُمَّ تَطْلُعُ الرَّايَاتُ السُّودُ مِنْ قِبَلِ الْمَشْرِقِ، فَيَقْتُلُونَكُمْ قَتْلًا لَمْ يَقْتُلْهُ قَوْمٌ". ثُمَّ ذَكَرَ شَيْئًا لَا أَحْفَظُهُ، فَقَالَ: "فَإِذَا رَأَيْتُمُوهُ فَبَايِعُوهُ وَلَوْ حَبْوًا عَلَى الثَّلْجِ، فَإِنَّهُ خَلِيفَةُ اللهِ الْمَهْدِيُّ". (جه)', 'സൗബാൻ(റ): തിരുദൂതർ(സ) പറയുന്നു: "നിങ്ങളുടെ നിധിയുടെ അടുത്തുവെച്ച് മൂന്നാളുകൾ യുദ്ധം ചെയ്യും. എല്ലാവരും ഒരു ഖലീഫയുടെ മക്കളാണ്. അവരിൽ നിന്ന് ഒരാളിലേക്കും അത് എത്തുകയില്ല. പിന്നെ കിഴക്ക് നിന്നും കറുത്ത പതാകകൾ പ്രത്യക്ഷപ്പെടും. മുമ്പൊരു സമൂഹവും കൊല്ലപ്പെടാത്ത വിധം നിങ്ങളിലെ അസംഖ്യം പേരെ അവർ വധിക്കും. പിന്നെയെന്തോ അവിടുന്ന് പറഞ്ഞു: അത് ഞാനോർക്കുന്നില്ല. തിരുമേനി(സ) പറഞ്ഞു: "നിങ്ങൾ അദ്ദേഹത്തെ കണ്ടാൽ അദ്ദേഹത്തെ ബൈഅത്ത് ചെയ്യുക. മഞ്ഞിനു മുകളിൽ ഇഴഞ്ഞുപോയിട്ടാണെങ്കിലും ശരി. കാരണം, അല്ലാഹുവിന്റെ പ്രതിനിധിയായ മഹ്ദിയാണത്." (ജ)', 'ثَوْبَانَ', 'സൗബാൻ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 746, 747, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 129, 'عَنْ عَلِيٍّ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "الْمَهْدِيُّ مِنَّا أَهْلَ الْبَيْتِ، يُصْلِحُهُ اللَّهُ فِي لَيْلَةٍ". (جه)', 'അലി(റ): നബി(സ) പറഞ്ഞു: "മഹ്ദി നമ്മിൽ അഥവാ അഹ്ലുബൈത്തിൽ പെട്ടവനാണ്. അല്ലാഹു അദ്ദേഹത്തെ ഒറ്റ രാത്രി കൊണ്ട് ശരിപ്പെടുത്തിയെടുക്കും." (ജ)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 747, 747, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 130, 'عَنْ سَعِيدِ بْنِ الْمُسَيَّبِ رَضِيَ اللَّهُ عَنْهُ قَالَ: كُنَّا عِنْدَ أُمِّ سَلَمَةَ رَضِيَ اللَّهُ عَنْهَا، فَتَذَاكَرْنَا الْمَهْدِيَّ، فَقَالَتْ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "الْمَهْدِيُّ مِنْ وَلَدِ فَاطِمَةَ". (د,جه)', 'സഈദുബ്നു മുസയ്യിബ്(റ): ഞങ്ങൾ ഉമ്മുസലമ(റ)യുടെ സന്നിധിയിലായിരുന്നു. മഹതി ഞങ്ങളോട് മഹ്ദിയെക്കുറിച്ച് സംസാരിച്ചു. അവർ പറഞ്ഞു: പ്രവാചകർ(സ) പറയുന്നതായി ഞാൻ കേട്ടിട്ടുണ്ട്: "മഹ്ദി ഫാതിമ(റ)യുടെ സന്തതികളിൽ പെട്ടയാളാണ്." (ദ,ജ)', 'سَعِيدِ بْنِ الْمُسَيَّبِ', 'സഈദുബ്നു മുസയ്യിബ്(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 747, 747, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 131, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "نَحْنُ – وَلَدَ عَبْدِ الْمُطَّلِبِ – سَادَةُ أَهْلِ الْجَنَّةِ، أَنَا وَحَمْزَةُ وَعَلِيٌّ وَجَعْفَرٌ وَالْحَسَنُ وَالْحُسَيْنُ وَالْمَهْدِيُّ". (جه)', 'അനസുബ്നു മാലിക്(റ): തിരുദൂതർ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "ഞങ്ങൾ അബ്ദുൽ മുത്ത്വലിബിന്റെ സന്തതികൾ സ്വർഗ്ഗവാസികളുടെ നേതാക്കളാണ്. ഞാനും ഹംസയും അലിയും ജഅ്ഫറും ഹസനും ഹുസൈനും മഹ്ദിയും." (ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 747, 747, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 132, 'عَنْ عَبْدِ اللَّهِ بْنِ الْحَارِثِ بْنِ جَزْءٍ الزُّبَيْدِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "يَخْرُجُ نَاسٌ مِنَ الْمَشْرِقِ، فَيُوَطِّئُونَ لِلْمَهْدِيِّ". يَعْنِي سُلْطَانَهُ. [ز: فِي إِسْنَادِهِ ضَعِيفَانِ] (جه)', 'അബ്ദുല്ലാഹിബ്നുൽ ഹാരിസുബ്നു ജസ്ഉസ്സുബീദി(റ): തിരുദൂതർ(സ) പറഞ്ഞു: "കിഴക്കുനിന്നും ഒരു സംഘം ആളുകൾ വരും. അവർ മഹ്ദിക്ക് വഴിതെളിയിച്ച് കൊടുക്കും." അതായത് അദ്ദേഹത്തിന്റെ ഭരണത്തിന്. പരമ്പരയിൽ രണ്ട് ബലഹീനരുണ്ട്. (ജ)', 'عَبْدِ اللَّهِ بْنِ الْحَارِثِ بْنِ جَزْءٍ الزُّبَيْدِيِّ', 'അബ്ദുല്ലാഹിബ്നുൽ ഹാരിസുബ്നു ജസ്ഉസ്സുബീദി(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: فِي إِسْنَادِهِ ضَعِيفَانِ', null, 747, 747, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 133, 'عَنِ الْجُرَيْرِيِّ رَضِيَ اللَّهُ عَنْهُ، عَنْ أبي نضرة رَضِيَ اللَّهُ عَنْهُ قَالَ: كُنَّا عِنْدَ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا فَقَالَ: يُوشِكُ أَهْلُ الْعِرَاقِ أَنْ لَا يُجْبَى إِلَيْهِمْ قَفِيزٌ وَلَا دِرْهَمٌ. قُلْنَا: مِنْ أَيْنَ ذَاكَ؟ قَالَ: مِنْ قِبَلِ الْعَجَم، يَمْنَعُونَ ذَاكَ. ثُمَّ قَالَ: يُوشِكُ أَهْلُ الشَّامِ أَنْ لَا يُجْبَى إِلَيْهِمْ دِينَارٌ وَلَا مُدْيٌ. قُلْنَا: مِنْ أَيْنَ ذَاكَ؟ قَالَ: مِنْ قِبَلِ الرُّومِ. ثُمَّ أَسْكَتَ هُنَيَّةً، ثُمَّ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "يَكُونُ فِي آخِرِ أُمَّتِي خَلِيفَةٌ يَحْثِي الْمَالَ حَثْيًا، لَا يَعُدُّهُ عَدَدًا". قَالَ: قُلْتُ لِأَبِي نَضْرَةَ وَأَبِي الْعَلَاءِ: [أَتَرَيَانِ] أَنَّهُ عُمَرُ بْنُ عَبْدِ الْعَزِيزِ؟ فَقَالَا: لَا. (م)', 'അബൂനള്റത്(റ)വിൽ നിന്ന് ജുറൈരീ(റ): ഞങ്ങൾ ജാബിറുബ്നു അബ്ദില്ല(റ)യുടെ സന്നിധിയിലായിരുന്നു. അദ്ദേഹം പറഞ്ഞു: ഇറാഖുകാർക്ക് അവരുടെ നാണയവും അളവുപാത്രവും തടയപ്പെടും. (വിദേശികൾ അവരുടെ മേൽ ആധിപത്യം ചെലുത്തും). ഞങ്ങൾ ചോദിച്ചു: ആരുടെ ഭാഗത്തുനിന്നായിരിക്കും അത്? അദ്ദേഹം പറഞ്ഞു: അനറബികളുടെ ഭാഗത്തുനിന്ന്. അവർ അതിനെ തടയും. പിന്നെ അദ്ദേഹം പറഞ്ഞു: ശാമുകാർക്ക് അവരുടെ ദീനാറും അളവുപാത്രവും തടയപ്പെടും. ഞങ്ങൾ ചോദിച്ചു: ആരുടെ ഭാഗത്തുനിന്നായിരിക്കും അത് സംഭവിക്കുന്നത്? അദ്ദേഹം പറഞ്ഞു: റോമക്കാരുടെ ഭാഗത്തുനിന്നാണ്. ശേഷം അദ്ദേഹം കുറച്ചുസമയം മൗനം പാലിച്ചു. പിന്നീട് പറഞ്ഞു: തിരുദൂതർ(സ) പറഞ്ഞു: "എന്റെ ഉമ്മത്തിന്റെ അവസാനത്തിൽ ധനം വാരിക്കോരി നൽകുന്ന ഒരു പ്രതിനിധി വരും. അദ്ദേഹം അതിനെ അളന്നുകണക്കാക്കുകയില്ല." നിവേദകൻ പറയുന്നു: ഞാൻ അബൂനള്റത്തിനോടും അബുൽ അലാഇനോടും ചോദിച്ചു: ആ ഖലീഫ ഉമറുബ്നു അബ്ദിൽ അസീസാണെന്ന് നിങ്ങൾക്കഭിപ്രായമുണ്ടോ? അപ്പോൾ അവർ രണ്ടുപേരും പറഞ്ഞു: ഇല്ല. (മു)', 'الْجُرَيْرِيِّ', 'അബൂനള്റത്(റ)', null, null, array['م']::text[], array['മു']::text[], 'أَتَرَيَانِ', null, 747, 748, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=34 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 134, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: خَرَجْنَا حُجَّاجًا أَوْ عُمَّارًا، وَمَعَنَا ابْنُ صَائِدٍ، قَالَ: فَنَزَلْنَا مَنْزِلًا فتفرَّق النَّاسُ، وَبَقِيتُ أَنَا وَهُوَ، فَاسْتَوْحَشْتُ مِنْهُ وَحْشَةً شَدِيدَةً مِمَّا يُقَالُ عَلَيْهِ، قَالَ: وَجَاءَ بِمَتَاعِهِ فَوَضَعَهُ مَعَ مَتَاعِي، فَقُلْتُ: إِنَّ الْحَرَّ شَدِيدٌ، فَلَوْ وَضَعْتَهُ تَحْتَ تِلْكَ الشَّجَرَةِ، قَالَ: فَفَعَلَ. قَالَ: فَرُفِعَتْ لَنَا غَنَمٌ، فَانْطَلَقَ فَجَاءَ بِعُسٍّ فَقَالَ: اشْرَبْ أَبَا سَعِيدٍ، فَقُلْتُ: إِنَّ الْحَرَّ شَدِيدٌ، وَاللَّبَنُ حَارٌّ. مَا بِي إِلَّا أَنِّي أَكْرَهُ أَنْ أَشْرَبَ عَنْ يَدِهِ، أَوْ قَالَ: آخُذَ عَنْ يَدِهِ. فَقَالَ: أَبَا سَعِيدٍ، لَقَدْ هَمَمْتُ أَنْ آخُذَ حَبْلًا فَأُعَلِّقَهُ بِشَجَرَةٍ ثُمَّ أَخْتَنِقَ مِمَّا يَقُولُ لِيَ النَّاسُ، يَا أَبَا سَعِيدٍ، مَنْ خَفِيَ عَلَيْهِ حَدِيثُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَا خَفِيَ عَلَيْكُمْ مَعْشَرَ الْأَنْصَارِ، أَلَسْتُ مِنْ أَعْلَمِ النَّاسِ بِحَدِيثِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ أَلَيْسَ قَدْ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "هُوَ كَافِرٌ". وَأَنَا مُسْلِمٌ؟ أَوَلَيْسَ قَدْ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "هُوَ عَقِيمٌ لَا يُولَدُ لَهُ". وَقَدْ تَرَكْتُ وَلَدِي بِالْمَدِينَةِ؟ أَوَلَيْسَ قَدْ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا يَدْخُلُ الْمَدِينَةَ وَلَا مَكَّةَ". وَقَدْ أَقْبَلْتُ مِنَ الْمَدِينَةِ وَأَنَا أُرِيدُ مَكَّةَ؟ قَالَ أَبُو سَعِيدٍ الْخُدْرِيُّ رَضِيَ اللَّهُ عَنْهُ: حَتَّى كِدْتُ أَنْ أَعْذِرَهُ، ثُمَّ قَالَ: أَمَا وَاللَّهِ إِنِّي لَأَعْرِفُهُ، وَأَعْرِفُ مَوْلِدَهُ وَأَيْنَ هُوَ الْآنَ. قَالَ: قُلْتُ لَهُ: تَبًّا لَكَ سَائِرَ الْيَوْمِ. (م,ت,جه)', 'അബൂസഈദിൽ ഖുദ്രി(റ): ഞങ്ങൾ ഹജ്ജോ ഉംറയോ ചെയ്യാൻ വേണ്ടി പുറപ്പെട്ടു. ഞങ്ങളുടെ കൂടെ ഇബ്നുസ്വയ്യാദ് ഉണ്ടായിരുന്നു. നിവേദകൻ പറയുന്നു: ഞങ്ങൾ ഒരു സ്ഥലത്ത് ഇറങ്ങി. ജനങ്ങൾ വേർപിരിഞ്ഞു. ഞാനും അവനും ശേഷിച്ചു. അവന്റെ മേൽ ആരോപിക്കപ്പെടുന്നകാര്യം (ഇബ്നുസ്വാഇദ് ദജ്ജാലാണെന്ന്) ആലോചിച്ച് ഞാൻ അതിശക്തമായി ഭയപ്പെട്ടു. നിവേദകൻ പറയുന്നു: അവൻ തന്റെ യാത്രാസാമഗ്രികൾ കൊണ്ടുവന്ന് എന്റെ സാമഗ്രികളുടെ കൂടെ വെച്ചു. അപ്പോൾ ഞാൻ പറഞ്ഞു: ചൂട് ശക്തമാണ്. ആ വൃക്ഷച്ചുവട്ടിൽ വെക്കുന്നതായിരിക്കും നല്ലത്. അവൻ അത് അവിടേക്ക് വെച്ചു. ഞങ്ങൾക്ക് ഒരാടിനെ നൽകപ്പെട്ടു. അവൻ പോയി ഒരു കോപ്പ കൊണ്ടുവന്നു. എന്നിട്ട് പറഞ്ഞു: അബൂസഈദ്, പാൽ കുടിക്കൂ. അപ്പോൾ ഞാൻ പറഞ്ഞു: ചൂട് ശക്തമാണ്. പാൽ ചൂടുസ്വഭാവമുള്ളതാണ് (എനിക്ക് വേണ്ട). അവന്റെ കയ്യിൽ നിന്ന് വാങ്ങി കുടിക്കുന്നത് ഞാൻ വെറുത്തു എന്നതല്ലാതെ അങ്ങനെ പറയാൻ വേറെ കാരണങ്ങളൊന്നുമില്ലായിരുന്നു. അല്ലെങ്കിൽ നിവേദകൻ പറഞ്ഞത്: അവന്റെ കയ്യിൽ നിന്ന് വാങ്ങുന്നത് എന്നാണ്. അവൻ പറഞ്ഞു: അബൂസഈദ്, ജനങ്ങൾ എന്നെക്കുറിച്ച് പറയുന്നത് കേട്ടിട്ട് ഒരു കയറെടുത്ത് മരത്തിൽ ബന്ധിച്ച് തൂങ്ങിമരിക്കാനാണെനിക്ക് തോന്നുന്നത്. അബൂസഈദ്, തിരുദൂതർ(സ) പറയുന്നത് വല്ലവർക്കും അവ്യക്തമായി പോയാലും നിങ്ങൾ അൻസാരികൾക്ക് അത് മനസ്സിലാവാതെ പോവില്ലല്ലോ. താങ്കൾ തിരുദൂതർ(സ)യുടെ വചനങ്ങൾ നന്നായി മനസ്സിലാക്കുന്നവരുടെ കൂട്ടത്തിൽ പെട്ടവരുമാണല്ലോ? "അവൻ (ദജ്ജാൽ) കാഫിറാണ്" എന്ന് പ്രവാചകർ(സ) പറഞ്ഞിട്ടില്ലേ. ഞാൻ മുസ്ലിമല്ലേ? പ്രവാചകർ(സ) പറഞ്ഞിട്ടില്ലേ: "അവൻ സന്താനമുണ്ടാകാത്തവനാണ്." ഞാനെന്റെ സന്താനത്തെ മദീനയിൽ ഉപേക്ഷിച്ചിട്ടല്ലേ പോന്നത്? "അവൻ മക്കയിലും മദീനയിലും പ്രവേശിക്കുകയില്ല" എന്ന് തിരുമേനി(സ) പറഞ്ഞിട്ടില്ലേ? ഞാൻ മദീനയിൽ നിന്ന് മക്കയിലേക്കല്ലേ പോകുന്നത്? അബൂസഈദിൽ ഖുദ്രി(റ) പറയുന്നു: എനിക്കവനോട് കാരണം ബോധിപ്പിക്കണമെന്ന് തോന്നി. പിന്നീടവൻ പറഞ്ഞു: നിശ്ചയം അല്ലാഹുവാണ് സത്യം, അവനെ ഞാനറിയും. അവന്റെ ജന്മസ്ഥലവും ഇപ്പോൾ അവനെവിടെയാണെന്നും ഞാനറിയും. അബൂസഈദ്(റ) പറയുന്നു: ഞാനവനോട് പറഞ്ഞു: നിനക്കെന്നും നാശം. (മു,തു,ജ)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്രി(റ)', null, null, array['م','ت','جه']::text[], array['മു','തു','ജ']::text[], null, null, 748, 749, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 135, 'عَنْ أَبِي سَعِيدٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ ابْنَ صَيَّادٍ سَأَلَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ تُرْبَةِ الْجَنَّةِ، فَقَالَ: "دَرْمَكَةٌ بَيْضَاءُ، مِسْكٌ خَالِصٌ". (م)', 'അബൂസഈദ്(റ): ഇബ്നുസ്വയ്യാദ് നബി(സ)യോട് സ്വർഗ്ഗത്തിലെ മണ്ണിനെക്കുറിച്ച് ചോദിച്ചു. പ്രവാചകർ(സ) പറഞ്ഞു: "നേർത്തു വെളുത്തതാണ്. തനി കസ്തൂരിയാണ്." (മു)', 'أَبِي سَعِيدٍ', 'അബൂസഈദ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 749, 749, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 136, 'عَنْ مُحَمَّدِ بْنِ الْمُنْكَدِرِ رَضِيَ اللَّهُ عَنْهُ قَالَ: رَأَيْتُ جَابِرَ بْنَ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا يَحْلِفُ بِاللَّهِ أَنَّ ابْنَ صَائِدٍ الدَّجَّالُ، فَقُلْتُ: أَتَحْلِفُ بِاللَّهِ؟ قَالَ: إِنِّي سَمِعْتُ عُمَرَ يَحْلِفُ عَلَى ذَلِكَ عِنْدَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَلَمْ يُنْكِرْهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. (م,د)', 'മുഹമ്മദുബ്നുൽ മുൻകദിർ(റ): നിശ്ചയം ഇബ്നുസ്വാഇദ് ദജ്ജാലാണെന്ന് ജാബിറുബ്നു അബ്ദില്ല(റ) അല്ലാഹുവിനെക്കൊണ്ട് സത്യം ചെയ്യുന്നത് ഞാൻ കണ്ടു. ഞാൻ ചോദിച്ചു: നീ അല്ലാഹുവിനെക്കൊണ്ട് സത്യം ചെയ്യുകയാണോ? അദ്ദേഹം പറഞ്ഞു: തിരുമേനി(സ)യുടെ സന്നിധിയിൽ ഉമർ(റ) അപ്രകാരം സത്യംചെയ്യുന്നതായി ഞാൻ കേട്ടിട്ടുണ്ട്. എന്നാൽ അവിടുന്ന് അദ്ദേഹത്തെ തടഞ്ഞിട്ടില്ല. (മു,ദ)', 'مُحَمَّدِ بْنِ الْمُنْكَدِرِ', 'മുഹമ്മദുബ്നുൽ മുൻകദിർ(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 749, 749, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 137, 'عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ عُمَرَ بْنَ الْخَطَّابِ رَضِيَ اللَّهُ عَنْهُ انْطَلَقَ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي رَهْطٍ قِبَلَ ابْنِ صَيَّادٍ، حَتَّى وَجَدَهُ يَلْعَبُ مَعَ الصِّبْيَانِ عِنْدَ أُطُمِ بَنِي مَغَالَةَ، وَقَدْ قَارَبَ ابْنُ صَيَّادٍ يَوْمَئِذٍ الْحُلُمَ، فَلَمْ يَشْعُرْ حَتَّى ضَرَبَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ظَهْرَهُ بِيَدِهِ، ثُمَّ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِابْنِ صَيَّادٍ: "أَتَشْهَدُ أَنِّي رَسُولُ اللَّهِ". فَنَظَرَ إِلَيْهِ ابْنُ صَيَّادٍ، فَقَالَ: أَشْهَدُ أَنَّكَ رَسُولُ الْأُمِّيِّينَ. فَقَالَ ابْنُ صَيَّادٍ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَتَشْهَدُ أَنِّي رَسُولُ اللَّهِ؟ فَرَفَضَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَقَالَ: "آمَنْتُ بِاللَّهِ وَبِرُسُلِهِ". ثُمَّ قَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَاذَا تَرَى". قَالَ ابْنُ صَيَّادٍ: يَأْتِينِي صَادِقٌ وَكَاذِبٌ. فَقَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "خُلِّطَ عَلَيْكَ الْأَمْرُ". ثُمَّ قَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنِّي قَدْ خَبَأْتُ لَكَ خَبِيئًا". فَقَالَ ابْنُ صَيَّادٍ: هُوَ الدُّخُّ. فَقَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "اخْسَأْ، فَلَنْ تَعْدُوَ قَدْرَكَ". فَقَالَ عُمَرُ بْنُ الْخَطَّابِ رَضِيَ اللَّهُ عَنْهُ: ذَرْنِي يَا رَسُولَ اللَّهِ، أَضْرِبْ عُنُقَهُ. فَقَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنْ يَكُنْهُ فَلَنْ تُسَلَّطَ عَلَيْهِ، وَإِنْ لَمْ يَكُنْهُ فَلَا خَيْرَ لَكَ فِي قَتْلِهِ". وَقَالَ سَالِمُ بْنُ عَبْدِ اللَّهِ: سَمِعْتُ عَبْدَ اللَّهِ بْنَ عُمَرَ رَضِيَ اللَّهُ عَنْهُ يَقُولُ: انْطَلَقَ بَعْدَ ذَلِكَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأُبَيُّ بْنُ كَعْبٍ الْأَنْصَارِيُّ إِلَى النَّخْلِ الَّتِي فِيهَا ابْنُ صَيَّادٍ، حَتَّى إِذَا دَخَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ النَّخْلَ طَفِقَ يَتَّقِي بِجُذُوعِ النَّخْلِ، وَهُوَ يَخْتِلُ أَنْ يَسْمَعَ مِنِ ابْنِ صَيَّادٍ شَيْئًا قَبْلَ أَنْ يَرَاهُ ابْنُ صَيَّادٍ، فَرَآهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ مُضْطَجِعٌ عَلَى فِرَاشٍ فِي قَطِيفَةٍ لَهُ فِيهَا زَمْزَمَةٌ، فَرَأَتْ أُمُّ ابْنِ صَيَّادٍ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ يَتَّقِي بِجُذُوعِ النَّخْلِ، فَقَالَتْ لِابْنِ صَيَّادٍ: يَا صَافِ – وَهُوَ اسْمُ ابْنِ صَيَّادٍ – هَذَا مُحَمَّدٌ. فَثَارَ ابْنُ صَيَّادٍ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَوْ تَرَكَتْهُ بَيَّنَ". قَالَ سَالِمٌ: قَالَ عَبْدُ اللَّهِ بْنُ عُمَرَ رَضِيَ اللَّهُ عَنْهُ: فَقَامَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي النَّاسِ فَأَثْنَى عَلَى اللَّهِ بِمَا هُوَ لَهُ أَهْلٌ، ثُمَّ ذَكَرَ الدَّجَّالَ فَقَالَ: "إِنِّي لَأُنْذِرُكُمُوهُ، مَا مِنْ نَبِيٍّ إِلَّا وَقَدْ أَنْذَرَهُ قَوْمَهُ، لَقَدْ أَنْذَرَهُ نُوحٌ قَوْمَهُ، وَلَكِنْ أَقُولُ لَكُمْ فِيهِ قَوْلًا لَمْ يَقُلْهُ نَبِيٌّ لِقَوْمِهِ: تَعَلَّمُوا أَنَّهُ أَعْوَرُ، وَأَنَّ اللَّهَ تَبَارَكَ وَتَعَالَى لَيْسَ بِأَعْوَرَ". قَالَ ابْنُ شِهَابٍ: وَأَخْبَرَنِي عُمَرُ بْنُ ثَابِتٍ الْأَنْصَارِيُّ: أَنَّهُ أخبره بعض أصحاب رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ يَوْمَ حَذَّرَ النَّاسَ الدَّجَّالَ: "إِنَّهُ مَكْتُوبٌ بَيْنَ عَيْنَيْهِ كَافِرٌ، يَقْرَؤُهُ مَنْ كَرِهَ عَمَلَهُ. أَوْ: يَقْرَؤُهُ كُلُّ مُؤْمِنٍ". وَقَالَ: "تَعَلَّمُوا أَنَّهُ لَنْ يَرَى أَحَدٌ مِنْكُمْ رَبَّهُ عَزَّ وَجَلَّ حَتَّى يَمُوتَ". (ق,د,ت)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): ഉമറുബ്നുൽ ഖത്താബ്(റ) റസൂലുല്ലാഹി(സ)യുടെ കൂടെ ഒരു സംഘത്തിൽ ഇബ്നുസ്വയ്യാദിന്റെ അടുത്തേക്ക് പോയി. ബനൂമഗാലയുടെ കോട്ടക്കരികിൽ അവൻ കുട്ടികളുടെ കൂടെ കളിക്കുന്നതായി കണ്ടു. ഇബ്നുസ്വയ്യാദ് അപ്പോൾ പ്രായപൂർത്തിയാകാനടുത്ത കുട്ടിയായിരുന്നു. നബി(സ) അവന്റെ പുറത്ത് തട്ടുന്നതുവരെ ഞങ്ങളുടെ സാന്നിധ്യം അവൻ അറിഞ്ഞില്ല. ശേഷം റസൂൽ(സ) അവനോട് ചോദിച്ചു: "ഞാൻ അല്ലാഹുവിന്റെ ദൂതനാണെന്ന് നീ സാക്ഷ്യം വഹിക്കുന്നുണ്ടോ?" അപ്പോൾ അവൻ പ്രവാചകർ(സ)യെ നോക്കി, എന്നിട്ട് പറഞ്ഞു: താങ്കൾ നിരക്ഷരരുടെ ദൂതരാണെന്ന് ഞാൻ സാക്ഷ്യം വഹിക്കുന്നു. പിന്നീട് ഇബ്നുസ്വയ്യാദ് ചോദിച്ചു: ഞാൻ അല്ലാഹുവിന്റെ ദൂതരാണെന്ന് താങ്കൾ സാക്ഷ്യം വഹിക്കുന്നുണ്ടോ? അപ്പോൾ തിരുമേനി(സ) അവനെ നിരസിച്ചു. എന്നിട്ട് പറഞ്ഞു: "അല്ലാഹുവിനെക്കൊണ്ടും അവന്റെ പ്രവാചകരെക്കൊണ്ടും ഞാൻ വിശ്വസിച്ചു." അവിടുന്ന് ചോദിച്ചു: "നീ എന്താണ് കാണുന്നത്?" ഇബ്നുസ്വയ്യാദ് പറഞ്ഞു: സത്യം പറയുന്നവരും കളവ് പറയുന്നവരും എന്റടുത്ത് വരുന്നു. അപ്പോൾ നബി(സ) അവനോട് പറഞ്ഞു: "കാര്യങ്ങൾ നിനക്ക് കൂട്ടിലർത്തപ്പെട്ടിരിക്കുന്നു." പിന്നെ നബി(സ) പറഞ്ഞു: "ഞാൻ നിനക്ക് വേണ്ടി ഒരു കാര്യം രഹസ്യമാക്കി വെച്ചിരിക്കുന്നു." അപ്പോൾ ഇബ്നുസ്വയ്യാദ് ചോദിച്ചു: അത് പുകയല്ലേ? റസൂൽ(സ) അവനോട് പറഞ്ഞു: "നീ നിന്ദ്യനാവുക, നിനക്ക് ഇതിലേറെ ഒന്നും കഴിയില്ല." അപ്പോൾ ഉമറുബ്നുൽ ഖത്താബ്(റ) പറഞ്ഞു: തിരുദൂതരേ, എന്നെ വിട്ടേക്കുക, ഞാൻ അവനെ വധിക്കട്ടെ. അപ്പോൾ റസൂൽ(സ) ഉമർ(റ)വിനോട് പറഞ്ഞു: "അവൻ ദജ്ജാലാണെങ്കിൽ അവനെ കീഴ്പ്പെടുത്താൻ നിനക്കാവില്ല. ദജ്ജാലല്ലെങ്കിൽ അവനെ വധിക്കുന്നതുകൊണ്ട് നിനക്കൊരു നന്മയും ലഭിക്കാനുമില്ല." സാലിമുബ്നു അബ്ദില്ല(റ) പറയുന്നു: അബ്ദുല്ലാഹിബ്നു ഉമർ(റ) പറയുന്നത് ഞാൻ കേട്ടു: അതിന് ശേഷം റസൂൽ(സ)യും ഉബയ്യുബ്നു കഅ്ബുൽ അൻസാരി(റ)വും ഇബ്നുസ്വയ്യാദുള്ള ഈത്തപ്പനത്തോട്ടത്തിലേക്ക് പോയി. നബി(സ) തോട്ടത്തിൽ കടന്നയുടനെ ഈത്തപ്പനക്ക് പിന്നിൽ ഒളിക്കാൻ തുടങ്ങി. ഇബ്നുസ്വയ്യാദ് തന്നെ കാണുന്നതിനു മുമ്പ് ഇബ്നുസ്വയ്യാദിൽ നിന്നും വല്ലതും രഹസ്യമായി കേൾക്കാൻ കഴിയുമോ എന്ന് അവിടന്ന് നോക്കുകയായിരുന്നു. അപ്പോൾ വില്ലൂസ് പട്ടിനാലുള്ള തന്റെ വിരിപ്പിൽ അവനുറങ്ങുന്നത് റസൂൽ(സ) കണ്ടു. അതിൽ നിന്നും ഒരു മുഴക്കം കേൾക്കുന്നുണ്ട്. പക്ഷേ, റസൂൽ(സ) ആ ഈത്തപ്പനക്ക് പിന്നിൽ ഒളിഞ്ഞിരിക്കുന്നത് ഇബ്നുസ്വയ്യാദിന്റെ ഉമ്മ കണ്ടു. അവൾ ഇബ്നുസ്വയ്യാദിനോട് പറഞ്ഞു: ഓ സ്വാഫ് - ഇബ്നുസ്വയ്യാദിന്റെ പേരാണത് - ഇതാ മുഹമ്മദ്, അപ്പോഴേക്കും ഇബ്നുസ്വയ്യാദിളകി. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "അവൾ (ഉണർത്താതെ) വിട്ടിരുന്നെങ്കിൽ എല്ലാം വ്യക്തമാകുമായിരുന്നു." സാലിം(റ) പറയുന്നു: അബ്ദുല്ലാഹിബ്നു ഉമർ(റ) പറഞ്ഞു: അങ്ങനെ റസൂൽ(സ) ജനങ്ങൾക്ക് മുന്നിൽ എഴുന്നേറ്റുനിന്ന് സ്തുത്യർഹനായ അല്ലാഹുവിനെ പുകഴ്ത്തി. പിന്നെ ദജ്ജാലിനെക്കുറിച്ച് പറയാൻ തുടങ്ങി. നബി(സ) പറഞ്ഞു: "അവനെക്കുറിച്ച് നിങ്ങൾക്ക് ഞാൻ മുന്നറിയിപ്പ് നൽകുന്നു. ഏതൊരു പ്രവാചകനും തന്റെ സമുദായത്തിന് അവനെക്കുറിച്ച് മുന്നറിയിപ്പ് കൊടുത്തിട്ടുണ്ട്. നൂഹ്(അ) തന്റെ സമുദായത്തിന് അവനെക്കുറിച്ച് മുന്നറിയിപ്പ് നൽകിയിട്ടുണ്ട്. പക്ഷേ, ഒരു പ്രവാചകനും തന്റെ സമുദായത്തിന് നൽകാത്ത കുറച്ച് മുന്നറിയിപ്പാണ് നിങ്ങൾക്ക് ഞാൻ നൽകുന്നത്. നിങ്ങളറിയുക, അവൻ ഒറ്റക്കണ്ണനാണ്, നിശ്ചയം അല്ലാഹു ഒറ്റക്കണ്ണനല്ല." ഇബ്നുശിഹാബ് എന്നവർ പറയുന്നു: ഉമറുബ്നു സാബിതുൽ അൻസാരി(റ) എന്നോട് പറഞ്ഞു: നബി(സ)യുടെ ചില അനുചരർ അദ്ദേഹത്തോട് പറഞ്ഞു: റസൂൽ(സ) ജനങ്ങളോട് ദജ്ജാലിനെക്കുറിച്ച് മുന്നറിയിപ്പ് നൽകിയ ദിവസം പറഞ്ഞു: "അവന്റെ രണ്ട് കണ്ണുകൾക്കുമിടയിൽ ''കാഫിർ'' (സത്യനിഷേധി) എന്നെഴുതപ്പെട്ടിട്ടുണ്ട്. അവന്റെ ചെയ്തികൾ വെറുക്കുന്ന ഏതൊരുത്തന്നും അത് വായിക്കാൻ കഴിയും. അല്ലെങ്കിൽ റസൂൽ(സ) പറഞ്ഞത്: എല്ലാ സത്യവിശ്വാസികളും അത് വായിക്കും എന്നാണ്." എന്നിട്ട് റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളറിയുക, നിങ്ങളിലൊരാളും തന്റെ റബ്ബിനെ മരണം വരിക്കുന്നത് വരെ കാണുകയില്ല." (ബു,മു,ദ,തു)', 'عَبْدِ اللَّهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['ق','د','ت']::text[], array['ബു','മു','ദ','തു']::text[], null, null, 749, 751, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 138, 'قَالَ ابن عمر: انْطَلَقَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأُبَيُّ بْنُ كَعْبٍ يَأْتِيَانِ النَّخْلَ الَّذِي فِيهِ ابْنُ صَيَّادٍ، حَتَّى إِذَا دَخَلَ النَّخْلَ طَفِقَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَتَّقِي بِجُذُوعِ النَّخْلِ وَهُوَ يَخْتِلُ ابن صَيَّادٍ أَنْ يَسْمَعَ مِنِ ابْنِ صَيَّادٍ شَيْئًا قَبْلَ أَنْ يَرَاهُ، وَابْنُ صَيَّادٍ مُضْطَجِعٌ عَلَى فِرَاشِهِ فِي قَطِيفَةٍ لَهُ فِيهَا رَمْزَةٌ، فَرَأَتْ أُمُّ ابْنِ صَيَّادٍ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ يَتَّقِي بِجُذُوعِ النَّخْلِ، فَقَالَتْ لِابْنِ صَيَّادٍ: أَيْ صَافِ، وَهُوَ اسْمُهُ، فَثَارَ ابْنُ صَيَّادٍ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَوْ تَرَكَتْهُ بَيَّنَ". (خ)', 'ഇബ്നുഉമർ(റ): നബി(സ)യും ഉബയ്യുബ്നു കഅ്ബ്(റ)വും ഇബ്നുസയ്യാദ് ഉള്ള ഈത്തപ്പനത്തോട്ടത്തിലേക്ക് പോയി. ഈത്തപ്പനത്തോട്ടത്തിൽ പ്രവേശിച്ചയുടനെ, ഇബ്നുസയ്യാദിനെ കാണുംമുമ്പ് അവനിൽ നിന്ന് വല്ലതും കേൾക്കാൻവേണ്ടി, ഇബ്നുസയ്യാദിനെ വീക്ഷിച്ചുകൊണ്ട്, റസൂൽ(സ) ഈത്തപ്പനത്തടികൾക്കിപ്പുറത്ത് മറഞ്ഞുനിന്നു. ഇബ്നുസയ്യാദ് വരയും കുറിയുമുള്ള തന്റെ ഒരു വിരിപ്പിൽ കിടക്കുകയായിരുന്നു. നബി(സ) ഈത്തപ്പനകൾക്കപ്പുറം മറഞ്ഞുനിൽക്കുന്നത് ഇബ്നുസയ്യാദിന്റെ ഉമ്മ കണ്ടു. അവൾ ഇബ്നുസയ്യാദിനെ സ്വാഫീ എന്ന് വിളിച്ചു. അത് ഇബ്നുസയ്യാദിന്റെ പേരാണ്. ഉടനെ ഇബ്നുസയ്യാദ് എഴുന്നേറ്റു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "അവൾ അവനെ ഒഴിവാക്കിയിരുന്നെങ്കിൽ (വിളിച്ചില്ലായിരുന്നെങ്കിൽ) കാര്യം വ്യക്തമാകുമായിരുന്നു." (ബു)', null, 'ഇബ്നുഉമർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 751, 751, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 139, 'عَنِ ابْنِ عَوْنٍ رَضِيَ اللَّهُ عَنْهُ، عَنْ نَافِعٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ نَافِعٌ رَضِيَ اللَّهُ عَنْهُ يَقُولُ: ابْنُ صَيَّادٍ، قَالَ: قَالَ ابْنُ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا: لَقِيتُهُ مَرَّتَيْنِ، قَالَ: فَلَقِيتُهُ فَقُلْتُ لِبَعْضِهِمْ: هَلْ تُحَدِّثُونَ أنه هو؟ قَالَ: لَا وَاللَّهِ. قَالَ: قُلْتُ: كَذَبْتَنِي وَاللَّهِ، لَقَدْ أَخْبَرَنِي بَعْضُكُمْ أَنَّهُ لَنْ يَمُوتَ حَتَّى يَكُونَ أَكْثَرَكُمْ مَالًا وَوَلَدًا، فَكَذَلِكَ هُوَ زَعَمُوا الْيَوْمَ. قَالَ: فَتَحَدَّثْنَا، ثُمَّ فَارَقْتُهُ. قَالَ: فَلَقِيتُهُ لَقِيَةً أُخْرَى وَقَدْ نَفَرَتْ عَيْنُهُ. قَالَ: فَقُلْتُ: مَتَى فَعَلَتْ عَيْنُكَ مَا أَرَى؟ قَالَ: لَا أَدْرِي. [قَالَ]: قُلْتُ: لَا تَدْرِي وَهِيَ فِي رَأْسِكَ؟ قَالَ: إِنْ شَاءَ اللَّهُ خَلَقَهَا فِي عَصَاكَ هَذِهِ. قَالَ: فَنَخَرَ كَأَشَدِّ نَخِيرِ حِمَارٍ سَمِعْتُ. قَالَ: فَزَعَمَ بَعْضُ أَصْحَابِي أَنِّي ضَرَبْتُهُ بِعَصًا كَانَتْ مَعِي حَتَّى تَكَسَّرَتْ، وَأَنَا وَاللَّهِ فَمَا شَعَرْتُ، قَالَ: وَجَاءَ حَتَّى دَخَلَ عَلَى أُمِّ الْمُؤْمِنِينَ، فَحَدَّثَهَا، فَقَالَتْ: مَا تُرِيدُ إِلَيْهِ؟ أَلَمْ تَعْلَمْ أَنَّهُ قَدْ قَالَ: "إِنَّ أَوَّلَ مَا يَبْعَثُهُ عَلَى النَّاسِ غَضَبٌ يَغْضَبُهُ". (م)', 'നാഫിഅ്(റ)വിൽ നിന്ന് ഇബ്നുഔൻ(റ): നാഫിഅ്(റ) ഇബ്നുസ്വയ്യാദ് എന്നായിരുന്നു പറയാറുണ്ടായിരുത്. ഇബ്നുഉമർ(റ) പറഞ്ഞിട്ടുണ്ട്: അവനെ ഞാൻ രണ്ട് പ്രവാവശ്യം കണ്ടിട്ടുണ്ട്. അങ്ങനെ ഒരിക്കൽ അവനെ ഞാൻ കണ്ടപ്പോൾ അവരിൽ ചിലയാളുകളോട് ഞാൻ ചോദിച്ചു: ഇബ്നുസ്വയ്യാദ് തന്നെയാണ് ദജ്ജാലെന്ന് നിങ്ങൾ പറയുന്നുവോ? അവർ പറഞ്ഞു: അല്ലാഹു സത്യം, അങ്ങനെ പറയുന്നില്ല. ഇബ്നുഉമർ(റ) പറയുന്നു: ഞാൻ പറഞ്ഞു: അല്ലാഹു സത്യം, നിങ്ങളെന്നോട് കളവ് പറഞ്ഞിരിക്കുന്നു. തീർച്ചയായും നിങ്ങളിലേറ്റവും കുടുതൽ സന്താനങ്ങളും സമ്പത്തുമുള്ളവൻ അവനാകുന്നത് വരെ അവൻ മരിക്കുകയില്ലെന്ന് നിങ്ങളിൽ ചിലരെന്നോട് പറഞ്ഞിട്ടുണ്ടല്ലോ. ഇന്ന് അവൻ ആ അവസ്ഥയിലാണെന്നാണല്ലോ അവർ അവനെക്കുറിച്ച് പറയുന്നത്. ഇബ്നുഉമർ(റ) പറയുന്നു: അങ്ങനെ ഞങ്ങൾ സംസാരിച്ചു അവനുമായി പിരിഞ്ഞുപോയി. ഇബ്നുഉമർ(റ) പറയുന്നു: അങ്ങനെ മറ്റൊരു പ്രാവശ്യം ഞാൻ അവനെ കണ്ടപ്പോൾ അവന്റെ കണ്ണ് വീർത്തിട്ടുണ്ടായിരുന്നു. അപ്പോൾ ഞാൻ ചോദിച്ചു: നിന്റെ കണ്ണ് എപ്പോഴാണ് ഇങ്ങനെയായത്? അവൻ പറഞ്ഞു: എനിക്കറിയില്ല. ഞാൻ ചോദിച്ചു: അത് നിന്റെ തലയിലായിട്ടുപോലും നീ അറിഞ്ഞില്ലേ? അപ്പോൾ അവൻ പറഞ്ഞു: അല്ലാഹു ഉദ്ദേശിച്ചിരുന്നുവെങ്കിൽ അതിനെ നിന്റെ ഈ വടിയിലും സൃഷ്ടിക്കുമായിരുന്നു. ഇബ്നുഉമർ(റ) പറയുന്നു: ആ സമയത്ത് കഴുതയുടെ ശബ്ദത്തേക്കാളും ശക്തിയായി അവൻ ചീറി. അപ്പോൾ എന്റെ ചില കൂട്ടുകാർ പറഞ്ഞു: എന്റെ വടി പൊട്ടുവോളം ഞാനവനെ അടിച്ചതാകുമെന്ന്. അല്ലാഹു സത്യം, ഞാനാണെങ്കിൽ ഒന്നും അറിഞ്ഞിട്ടില്ല താനും. ഇബ്നുഉമർ(റ) പറയുന്നു: അങ്ങനെ ഞാൻ ഉമ്മുൽ മുഅ്മിനീൻ ആഇശ(റ)യുടെ അടുത്തുചെന്ന് മഹതിയോട് സംസാരിച്ചു. മഹതി ചോദച്ചു: നീ എന്താണ് അവനെക്കൊണ്ടുദ്ദേശിക്കുന്നത്? "ജനങ്ങൾക്കെതിരെ അവനെ ഇളക്കിവിടുന്ന ആദ്യ ഹേതു അവനുണ്ടാകുന്ന ഒരു ദേഷ്യമാണ്" എന്ന് റസൂൽ(സ) പറഞ്ഞത് നീ അറിഞ്ഞിട്ടില്ലേ? (മു)', 'ابْنِ عَوْنٍ', 'നാഫിഅ്(റ)', null, null, array['م']::text[], array['മു']::text[], 'قَالَ', null, 751, 752, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 140, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: لَقِيَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ابْنَ صَائِدٍ فِي بَعْضِ طُرُقِ الْمَدِينَةِ فَاحْتَبَسَهُ، وَهُوَ غُلَامٌ يَهُودِيٌّ، وَلَهُ ذُؤَابَةٌ، وَمَعَهُ أَبُو بَكْرٍ وَعُمَرُ رَضِيَ اللَّهُ عَنْهُمَا، فَقَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "تَشْهَدُ أَنِّي رَسُولُ اللَّهِ". فَقَالَ: أَتَشْهَدُ أَنْتَ أَنِّي رَسُولُ اللَّهِ؟ فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "آمَنْتُ بِاللَّهِ وَمَلَائِكَتِهِ وَكُتُبِهِ وَرُسُلِهِ وَالْيَوْمِ الْآخِرِ". قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَا تَرَى". قَالَ: أَرَى عَرْشًا فَوْقَ الْمَاءِ. فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "تَرَى عَرْشَ إِبْلِيسَ فَوْقَ الْبَحْرِ". قَالَ: "فَمَا تَرَى". قَالَ: أَرَى صَادِقًا وَكَاذِبِينَ. أَوْ: صَادِقِينَ وَكَاذِبًا. قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لُبِسَ عَلَيْهِ" فَدَعَاهُ. حَسَنٌ. (م,ت)', 'അബൂസഈദുൽ ഖുദ്രി(റ): മദീനയിലെ ഒരു ഊടുവഴിയിൽ വെച്ച് റസൂൽ(സ) ഇബ്നുസ്വാഇദിനെ കണ്ടപ്പോൾ അവനോട് നിൽക്കാനാവശ്യപ്പെട്ടു. അവൻ ഒരു ജൂതസന്താനമാണ്. അവന്റെ മുടിയുടെ മുൻവശത്ത് ഒരു കുടുമയുണ്ട്. റസൂൽ(സ)യോടുകൂടെ അബൂബക്കർ(റ)വും ഉമർ(റ)വുമുണ്ട്. അപ്പോൾ റസൂൽ(സ) അവനോട് ചോദിച്ചു: "ഞാൻ അല്ലാഹുവിന്റെ ദൂതരാണെന്ന് നീ സാക്ഷ്യം വഹിക്കുന്നുവോ?" അവൻ ചോദിച്ചു: ഞാൻ അല്ലാഹുവിന്റെ ദൂതനാണെന്ന് നിങ്ങൾ സാക്ഷ്യം വഹിക്കുമോ? അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "ഞാൻ അല്ലാഹുവിനെക്കൊണ്ടും അവന്റെ മാലാഖമാരെക്കൊണ്ടും അവന്റെ ഗ്രന്ഥങ്ങൾ കൊണ്ടും അവന്റെ ദൂതന്മാരെക്കൊണ്ടും അന്ത്യനാൾ കൊണ്ടും വിശ്വസിച്ചിരിക്കുന്നു." റസൂൽ(സ) ചോദിച്ചു: "നീ എന്താണ് കാണുന്നത്?" അവൻ പറഞ്ഞു: ഞാൻ വെള്ളത്തിനു മുകളിൽ ഒരു സിംഹാസനം കാണുന്നു. നബി(സ) പറഞ്ഞു: "കടലിനു മുകളിലുള്ള ഇബ്ലീസിന്റെ സിംഹാസനമാണ് നീ കാണുന്നത്." ശേഷം നബി(സ) ചോദിച്ചു: "പിന്നെയെന്താണ് നീ കാണുന്നത്?" അവൻ പറഞ്ഞു: ഞാൻ സത്യസന്ധനെയും നുണയന്മാരെയും കാണുന്നു - അല്ലെങ്കിൽ സത്യസന്ധരെയും ഒരു നുണയനെയും കാണുന്നു. റസൂൽ(സ) പറഞ്ഞു: "അവന് കാര്യങ്ങൾ അവ്യക്തമാക്കപ്പെട്ടിരിക്കുന്നു." എന്നിട്ട് റസൂൽ(സ) അവനെ വിട്ടയച്ചു. ഹദീസ് ഹസനാണ്. (മു,തു)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദുൽ ഖുദ്രി(റ)', null, null, array['م','ت']::text[], array['മു','തു']::text[], null, null, 752, 752, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 141, 'عَنْ أَبِي بَكْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "يَمْكُثُ أَبُو الدَّجَّالِ وَأُمُّهُ ثَلَاثِينَ عَامًا لَا يُولَدُ لَهُمَا وَلَدٌ، ثُمَّ يُولَدُ لَهُمَا غُلَامٌ أَعْوَرُ، أَضَرُّ شَيْءٍ وَأَقَلُّهُ مَنْفَعَةً، تَنَامُ عَيْنَاهُ وَلَا يَنَامُ قَلْبُهُ". ثُمَّ نَعَتَ لَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَبَوَيْهِ، فَقَالَ: "أَبُوهُ طِوَالٌ، ضَرْبُ اللَّحْمِ، كَأَنَّ أَنْفَهُ مِنْقَارٌ. وَأُمُّهُ فِرْضَاخِيَّةٌ طَوِيلَةُ الْيَدَيْنِ". فَقَالَ أَبُو بَكْرَةَ رَضِيَ اللَّهُ عَنْهُ: فَسَمِعْنَا بِمَوْلُودٍ فِي الْيَهُودِ بِالْمَدِينَةِ، فَذَهَبْتُ أَنَا وَالزُّبَيْرُ بْنُ الْعَوَّامِ حَتَّى دَخَلْنَا عَلَى أَبَوَيْهِ، فَإِذَا نَعْتُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِيهِمَا، فَقُلْنَا: هَلْ لَكُمَا وَلَدٌ؟ فَقَالَا: مَكَثْنَا ثَلَاثِينَ عَامًا لَا يُولَدُ لَنَا وَلَدٌ، ثُمَّ وُلِدَ لَنَا غُلَامٌ أَعْوَرُ، أَضَرُّ شَيْءٍ وَأَقَلُّهُ مَنْفَعَةً، تَنَامُ عَيْنَاهُ وَلَا يَنَامُ قَلْبُهُ. قَالَ: فَخَرَجْنَا مِنْ عِنْدِهِمَا فَإِذَا هُوَ مُنْجَدِلٌ فِي الشَّمْسِ فِي قَطِيفَةٍ لَهُ، وَلَهُ هَمْهَمَةٌ، فَتَكَشَّفَ عَنْ رَأْسِهِ فَقَالَ: مَا قُلْتُمَا؟ قُلْنَا: وَهَلْ سَمِعْتَ مَا قُلْنَا؟ قَالَ: نَعَمْ، تَنَامُ عَيْنَايَ وَلَا يَنَامُ قَلْبِي. حَسَنٌ. (ت)', 'അബൂബക്റ(റ): തിരുദൂതർ(സ) പറഞ്ഞു: "ദജ്ജാലിന്റെ മാതാപിതാക്കൾക്ക് മുപ്പത് വർഷം ഒരു സന്താനവും പിറക്കില്ല. പിന്നെ അവർക്ക് ഒറ്റക്കണ്ണനായൊരു കുട്ടി ജനിക്കും. അവൻ ദ്രോഹം അധികരിച്ചവനും ഉപകാരം കുറഞ്ഞവനുമായിരിക്കും. അവന്റെ കണ്ണുകൾ ഉറങ്ങും, ഹൃദയം ഉറങ്ങില്ല." റസൂൽ(സ) അവന്റെ മാതാപിതാക്കളെക്കുറിച്ച് ഞങ്ങൾക്ക് പറഞ്ഞുതന്നു. അവിടുന്ന് പറഞ്ഞു: "അവന്റെ പിതാവ് നീളമുള്ളയാളാണ്. തീരെ മെലിഞ്ഞവനും മൂക്ക് പക്ഷിക്കൊക്ക് പോലെയുള്ളവനുമായിരിക്കും. അവന്റെ മാതാവ് തടിച്ചവളും കൈ നീളമുള്ളവളുമായിരിക്കും." അബൂബക്റ(റ) പറയുന്നു: അങ്ങനെ മദീനയിൽ ഒരു ജൂതക്കുട്ടിയെക്കുറിച്ച് ഞങ്ങൾ കേട്ടു. ഞാനും സുബൈറുബ്നുൽ അവ്വാം(റ)വും ചേർന്ന് അവന്റെ മാതാപിതാക്കളുടെയടുത്ത് ചെന്നു. അപ്പോഴതാ, രണ്ടുപേരും റസൂൽ(സ) വിവരിച്ചതുപോലെ. ഞങ്ങൾ ചോദിച്ചു: നിങ്ങൾക്ക് വല്ല സന്താനവുമുണ്ടോ? അവർ പറഞ്ഞു: മുപ്പത് വർഷം സന്താനങ്ങളൊന്നും പിറക്കാതെ ഞങ്ങൾ കാത്തിരുന്നു. പിന്നെ ഒറ്റക്കണ്ണനായൊരു കുട്ടി ഞങ്ങൾക്ക് പിറന്നു. ഏറ്റവും വലിയ ഉപദ്രവവും വളരെ കുറച്ചു മാത്രം ഉപകാരവുമുള്ളൊരു കുട്ടി. അവന്റെ കണ്ണുകളുറങ്ങിയാലും ഹൃദയമുറങ്ങില്ല. അബൂബക്റ(റ) പറയുന്നു: ഞങ്ങൾ അവരുടെയടുത്തുനിന്നും തിരിച്ചു പോന്നപ്പോഴതാ, അവൻ മുഴക്കശബ്ദത്തോടെ തന്റെ വില്ലൂസ് പട്ടിനാലുള്ളൊരു പുതപ്പിൽ വെയിലത്ത് കിടക്കുന്നു. അവൻ തന്റെ പുതപ്പ് മാറ്റി തല വെളിവാക്കി, എന്നിട്ട് ചോദിച്ചു: നിങ്ങളെന്താണ് പറഞ്ഞത്? ഞങ്ങൾ ചോദിച്ചു: ഞങ്ങൾ പറഞ്ഞത് നീ കേട്ടുവോ? അവൻ പറഞ്ഞു: അതെ, എന്റെ കണ്ണുറങ്ങിയാലും ഹൃദയമുറങ്ങുകയില്ല. (തു)', 'أَبِي بَكْرَةَ', 'അബൂബക്റ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 752, 753, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 142, 'عَنْ نَافِعٍ قَالَ: كَانَ ابْنُ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا يَقُولُ: وَاللَّهِ مَا أَشُكُّ أَنَّ الْمَسِيحَ الدَّجَّالَ ابْنُ صَيَّادٍ. (د)', 'നാഫിഅ്(റ): ഇബ്നുഉമർ(റ) പറയാറുണ്ടായിരുന്നു: അല്ലാഹു സത്യം, ലോകം ചുറ്റുന്ന ദജ്ജാൽ ഇബ്നുസ്വയ്യാദാണെന്നതിൽ എനിക്കൊരു സംശയവുമില്ല. (ദ)', 'نَافِعٍ قَالَ', 'നാഫിഅ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 753, 753, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 143, 'عَنْ جَابِرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: فَقَدْنَا ابْنَ صَيَّادٍ يَوْمَ الْحَرَّةِ. (د)', 'ജാബിർ(റ): ''ഹർറ'' (മദീനക്കാരും യസീദുബ്നു മുആവിയയും തമ്മിലുള്ള യുദ്ധം) ദിനത്തോടെയാണ് ഇബ്നുസ്വയ്യാദിനെ ഞങ്ങൾ കാണാതായത്. (ദ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 753, 753, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 144, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا تَقُومُ السَّاعَةُ حَتَّى يَخْرُجَ ثَلَاثُونَ دَجَّالُونَ، كُلُّهُمْ يَزْعُمُ أَنَّهُ رَسُولُ اللَّهِ". (د)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "മുപ്പത് ദജ്ജാലുകൾ പുറപ്പെടുന്നത് വരെ അന്ത്യനാൾ സംഭവിക്കുകയില്ല. അവരിലോരോരുത്തരും താൻ അല്ലാഹുവിന്റെ ദൂതനാണെന്ന് വാദിക്കും." (ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 753, 753, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 145, 'عَنْ إِبْرَاهِيمَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ عُبَيْدَةُ السَّلْمَانِيُّ بِهَذَا الْخَبَرِ، قَالَ: فَذَكَرَ نَحْوَهُ، فَقُلْتُ لَهُ: أَتَرَى هَذَا مِنْهُمْ؟ يَعْنِي الْمُخْتَارَ، فَقَالَ عُبَيْدَةُ: أَمَا إِنَّهُ مِنَ الرُّءُوسِ. (م,د)', 'ഇബ്റാഹിം(റ): ഉബൈദതുസ്സൽമാനി(റ) ഈ ഹദീസ് ഉദ്ധരിച്ച് തുടർഭാഗങ്ങളും പറഞ്ഞു. അപ്പോൾ ഞാൻ അദ്ദേഹത്തോട് ചോദിച്ചു: ഇയാൾ അഥവാ മുഖ്താർ ആ കൂട്ടത്തിൽ പെട്ടവനാണെന്ന് നിങ്ങൾക്കഭിപ്രായമുണ്ടോ? അപ്പോൾ ഉബൈദ(റ) പറഞ്ഞു: തീർച്ചയായും അദ്ദേഹം അവരുടെ നേതാക്കളിൽ പെട്ടവനാണ്. (മു,ദ)', 'إِبْرَاهِيمَ', 'ഇബ്റാഹിം(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 753, 753, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 146, 'عَنْ أَبِي عُبَيْدَةَ بْنِ الْجَرَّاحِ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "إِنَّهُ لَمْ يَكُنْ نَبِيٌّ بَعْدَ نُوحٍ إِلَّا وَقَدْ أَنْذَرَ الدَّجَّالَ قَوْمَهُ، وَإِنِّي أُنْذِرُكُمُوهُ". فَوَصَفَهُ لَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَقَالَ: "لَعَلَّهُ سَيُدْرِكُهُ مَنْ قَدْ رَآنِي وَسَمِعَ كَلَامِي". قَالُوا: يَا رَسُولَ اللَّهِ، كَيْفَ قُلُوبُنَا يَوْمَئِذٍ؟ أَمِثْلُهَا الْيَوْمَ؟ قَالَ: "أَوْ خَيْرٌ". (د,ت)', 'അബൂഉബൈദതുൽ ജർറാഹ്(റ): നബി(സ) പറയുന്നത് ഞാൻ കേട്ടു: "നൂഹ് നബി(അ)മിന് ശേഷം ദജ്ജാലിനെക്കുറിച്ച് തന്റെ സമുദായത്തിന് മുന്നറിയിപ്പ് നൽകിയിട്ടല്ലാതെ ഒരു പ്രവാചകനും വന്നിട്ടില്ല. ഞാനും ദജ്ജാലിനെക്കുറിച്ച് നിങ്ങളോട് മുന്നറിയിപ്പ് നൽകുന്നു." എന്നിട്ട് റസൂൽ(സ) അവനെ ഞങ്ങൾക്ക് വിശേഷിപ്പിച്ചുതന്നു. അവിടുന്ന് പറയുകയും ചെയ്തു: "എന്നെ കണ്ടവനും എന്റെ സംസാരം കേട്ടവനും അവനെ കണ്ടേക്കാം." അവർ ചോദിച്ചു: തിരുദൂതരേ, അന്നേദിവസം ഞങ്ങളുടെ ഹൃദയങ്ങൾ എങ്ങനെയിരിക്കും? ഇന്നത്തെപ്പോലെത്തന്നെയാകുമോ? അവിടുന്ന് പറഞ്ഞു: "അതിനേക്കാൾ ഉത്തമമായിരിക്കും." (ദ,തു)', 'أَبِي عُبَيْدَةَ بْنِ الْجَرَّاحِ', 'അബൂഉബൈദതുൽ ജർറാഹ്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 753, 754, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=36 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 147, 'عَنْ أَبِي بَكْرٍ الصِّدِّيقِ رَضِيَ اللَّهُ عَنْهُ قَالَ: حَدَّثَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "الدَّجَّالُ يَخْرُجُ مِنْ أَرْضٍ بِالْمَشْرِقِ يُقَالُ لَهَا: خُرَاسَانُ، يَتْبَعُهُ أَقْوَامٌ كَأَنَّ وُجُوهَهُمُ الْمَجَانُّ الْمُطْرَقَةُ". حسن. (ت,جه)', 'അബൂബക്കർ സിദ്ദീഖ്(റ): റസൂൽ(സ) ഞങ്ങളോട് പറഞ്ഞു: "കിഴക്കു ഭാഗത്ത് ഖുറാസാൻ എന്ന് പേരുള്ള ഒരു സ്ഥലത്തുനിന്നാണ് ദജ്ജാൽ പുറപ്പെടുക. അവനെ കുറച്ച് സമുദായങ്ങൾ പിന്തുടരും. അവരുടെ മുഖങ്ങൾ തോൽ വെച്ച പരിചകളെ പോലെയായിരിക്കും." (തു,ജ)', 'أَبِي بَكْرٍ الصِّدِّيقِ', 'അബൂബക്കർ സിദ്ദീഖ്(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 754, 754, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=36 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 148, 'عَنْ مُعَاذِ بْنِ جَبَلٍ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "الْمَلْحَمَةُ الْعُظْمَى، وَفَتْحُ الْقُسْطَنْطِينِيَّةِ، وَخُرُوجُ الدَّجَّالِ، فِي سَبْعَةِ أَشْهُرٍ". حسن. (د,ت,جه)', 'മുആദുബ്നു ജബൽ(റ): റസൂൽ(സ) പറഞ്ഞു: "കൊല അധികരിക്കുന്ന വലിയ യുദ്ധം, ഇസ്താംബൂൾ (കോൺസ്റ്റാന്റിനോപ്പിൾ) കീഴടക്കൽ, ദജ്ജാൽ പുറപ്പെടൽ ഇവയെല്ലാം ഏഴ് മാസത്തിനുള്ളിലാണ്." (ദ,തു,ജ)', 'مُعَاذِ بْنِ جَبَلٍ', 'മുആദുബ്നു ജബൽ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 754, 754, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 149, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: فَتْحُ الْقُسْطَنْطِينِيَّةِ مَعَ قِيَامِ السَّاعَةِ. (د,ت)', 'അനസുബ്നു മാലിക്(റ): അന്ത്യനാൾ സംഭവിക്കുന്നതോടു കൂടെ കോൺസ്റ്റാന്റിനോപ്പിൾ (ഇസ്താംബൂൾ) കീഴടക്കപ്പെടും. (ദ,തു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 754, 754, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 150, 'عَنْ جَابِرِ بْنِ سَمُرَةَ، عَنْ نَافِعِ بْنِ عُتْبَةَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: كُنَّا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي غَزْوَةٍ، قَالَ: فَأَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَوْمٌ مِنْ قِبَلِ الْمَغْرِبِ عَلَيْهِمْ ثِيَابُ الصُّوفِ، فَوَافَقُوهُ عِنْدَ أَكَمَةٍ، فَإِنَّهُمْ لَقِيَامٌ، وَرَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَاعِدٌ، قَالَ: فَقَالَتْ لِي نَفْسِي: ائْتِهِمْ فَقُمْ بَيْنَهُمْ وَبَيْنَهُ لَا يَغْتَالُونَهُ. قَالَ: ثُمَّ قُلْتُ: لَعَلَّهُ نَجِيٌّ مَعَهُمْ، فَأَتَيْتُهُمْ فَقُمْتُ بَيْنَهُمْ وَبَيْنَهُ، قَالَ: فَحَفِظْتُ مِنْهُ أَرْبَعَ كَلِمَاتٍ أَعُدُّهُنَّ فِي يَدِي، قَالَ: "تَغْزُونَ جَزِيرَةَ الْعَرَبِ فَيَفْتَحُهَا اللَّهُ عَزَّ وَجَلَّ، ثُمَّ فَارِسَ فَيَفْتَحُهَا اللَّهُ عَزَّ وَجَلَّ، ثُمَّ تَغْزُونَ الرُّومَ فَيَفْتَحُهَا اللَّهُ عَزَّ وَجَلَّ، ثُمَّ تَغْزُونَ الدَّجَّالَ فَيَفْتَحُهُ اللَّهُ عَزَّ وَجَلَّ". قَالَ: فَقَالَ نَافِعٌ: يَا جَابِرُ، لَا نَرَى أَنَّ الدَّجَّالَ يَخْرُجُ حَتَّى تُفْتَحَ الرُّومُ. (م)', 'നാഫിഉബ്നു ഉത്ബ(റ)വിൽ നിന്ന് ജാബിറുബ്നു സമുറ(റ): ഞങ്ങൾ റസൂൽ(സ)യുടെ കൂടെ ഒരു യുദ്ധത്തിലായിരുന്നു. നിവേദകൻ പറയുന്നു: അപ്പോൾ നബി(സ)യുടെയടുത്ത് പടിഞ്ഞാറ് ഭാഗത്തുനിന്നുള്ള ഒരു സമുദായം വന്നു. അവർ രോമവസത്രം ധരിച്ചിട്ടുണ്ടായിരുന്നു. ഒരു കുറ്റിക്കാടിനടുത്തുവെച്ച് അവർ തിരുമേനി(സ)യെ കണ്ടുമുട്ടി. അവർ നിൽക്കുകയും റസൂൽ(സ) ഇരിക്കുകയുമായിരുന്നു. നിവേദകൻ പറയുന്നു: നീ അവരുടെ അടുത്ത് പോയി നബി(സ)ക്കും അവർക്കും ഇടയിൽ നിൽക്കുക, അവർ അവിടുത്തെ അക്രമിക്കാതിരിക്കാൻ വേണ്ടി എന്ന് ഞാൻ സ്വയം പറഞ്ഞു. അദ്ദേഹം പറയുന്നു: പിന്നെ ഞാൻ പറഞ്ഞു: നബി(സ) അവരുമായി സ്വകാര്യം പറയുകയായിരിക്കാം. അങ്ങനെ ഞാൻ അവരുടെയടുക്കൽ ചെന്നു. അവർക്കും നബി(സ)ക്കും ഇടയിൽ ഞാൻ നിൽക്കുകയും ചെയ്തു. നിവേദകൻ പറയുന്നു: അങ്ങനെ ഞാൻ നാല് കാര്യങ്ങൾ നബി(സ)യിൽ നിന്ന് പഠിച്ചു. ഞാൻ എന്റെ കൈ കൊണ്ട് അവ എണ്ണിത്തരാം. നബി(സ) പറഞ്ഞു: "നിങ്ങൾ അറേബ്യൻ ഉപദ്വീപുമായി യുദ്ധം ചെയ്യും. അങ്ങനെ അല്ലാഹു അത് കീഴടക്കിത്തരും. പിന്നെ പേർഷ്യക്കാരുമായി യുദ്ധം ചെയ്യും, അങ്ങനെ അതും കീഴടക്കിത്തരും. പിന്നെ നിങ്ങൾ റോമുമായി യുദ്ധം ചെയ്യും, അതും അല്ലാഹു കീഴടക്കിത്തരും. ശേഷം നിങ്ങൾ ദജ്ജാലുമായി യുദ്ധം ചെയ്യും, അല്ലാഹു അവനെയും കീഴടക്കിത്തരും." നിവേദകൻ പറയുന്നു: അപ്പോൾ നാഫിഅ്(റ) പറഞ്ഞു: ഓ ജാബിർ, റോം കീഴടക്കപ്പെടും വരെ ദജ്ജാൽ പുറപ്പെടുമെന്ന് നമുക്ക് തോന്നുന്നില്ല. (മു)', 'جَابِرِ بْنِ سَمُرَةَ، عَنْ نَافِعِ بْنِ عُتْبَةَ', 'നാഫിഉബ്നു ഉത്ബ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 754, 755, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=38 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 151, 'عَنْ يُسَيْرِ بْنِ جَابِرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: هَاجَتْ رِيحٌ حَمْرَاءُ بِالْكُوفَةِ، فَجَاءَ رَجُلٌ لَيْسَ لَهُ هِجِّيرَى إِلَّا: يَا عَبْدَ اللَّهِ بْنَ مَسْعُودٍ جَاءَتِ السَّاعَةُ. قَالَ: فَقَعَدَ وَكَانَ مُتَّكِئًا، فَقَالَ: إِنَّ السَّاعَةَ لَا تَقُومُ حَتَّى لَا يُقْسَمَ مِيرَاثٌ، وَلَا يُفْرَحَ بِغَنِيمَةٍ، ثُمَّ قَالَ بِيَدِهِ هَكَذَا وَنَحَّاهَا نَحْوَ الشَّأْمِ: فَقَالَ: عَدُوٌّ يَجْمَعُونَ لِأَهْلِ الْإِسْلَامِ وَيَجْمَعُ لَهُمْ أَهْلُ الْإِسْلَامِ. قُلْتُ: الرُّومَ تَعْنِي؟ قَالَ: نَعَمْ، وَتَكُونُ عِنْدَ ذَاكُمُ الْقِتَالِ رَدَّةٌ شَدِيدَةٌ، فَيَشْتَرِطُ الْمُسْلِمُونَ شُرْطَةً لِلْمَوْتِ لَا تَرْجِعُ إِلَّا غَالِبَةً، فَيَقْتَتِلُونَ حَتَّى يحجز بَيْنَهُمُ اللَّيْلُ، فَيَفِيءُ هَؤُلَاءِ وَهَؤُلَاءِ كُلٌّ غير غالب وتفنى الشُّرْطَةُ، ثُمَّ يَشْتَرِطُ الْمُسْلِمُونَ شُرْطَةً لِلْمَوْتِ لَا تَرْجِعُ إِلَّا غَالِبَةً، فَيَقْتَتِلُونَ حَتَّى يحجز بَيْنَهُمُ اللَّيْلُ، فَيَفِيءُ هَؤُلَاءِ وَهَؤُلَاءِ كُلٌّ غير غالب وتفنى الشُّرْطَةُ، ثُمَّ يَشْتَرِطُ الْمُسْلِمُونَ شُرْطَةً لِلْمَوْتِ لَا تَرْجِعُ إِلَّا غَالِبَةً، فَيَقْتَتِلُونَ حَتَّى يُمْسُوا، فَيَفِيءُ هَؤُلَاءِ وَهَؤُلَاءِ كُلٌّ غير غالب وتفنى الشُّرْطَةُ، فَإِذَا كَانَ يَوْمُ الرَّابِعِ نَهَدَ إِلَيْهِمْ بَقِيَّةُ أَهْلِ الْإِسْلَامِ، فَيَجْعَلُ اللَّهُ الدَّبْرَةَ عَلَيْهِمْ، فَيَقْتَتِلُونَ مَقْتَلَةً – إِمَّا قَالَ: لَا يُرَى مِثْلُهَا، وَإِمَّا قَالَ – لَمْ يُرَ مِثْلُهَا، حَتَّى إِنَّ الطَّائِرَ لَيَمُرُّ بِجَنَبَاتِهِمْ فَمَا يُخَلِّفُهُمْ حَتَّى يَخِرَّ مَيِّتًا، فَيَتَعَادُّ بَنُو الْأَبِ كَانُوا مِائَةً، فَلَا يَجِدُونَهُ بَقِيَ مِنْهُمْ إِلَّا الرَّجُلُ الْوَاحِدُ، فَبِأَيِّ غَنِيمَةٍ يُفْرَحُ، أَوْ أَيُّ مِيرَاثٍ يُقَاسَمُ، فَبَيْنَمَا هُمْ كَذَلِكَ إِذْ سَمِعُوا بِبَأْسٍ هُوَ أَكْبَرُ مِنْ ذَلِكَ، فَجَاءَهُمُ الصَّرِيخُ: إِنَّ الدَّجَّالَ قَدْ خَلَفَهُمْ فِي ذَرَارِيِّهِمْ، فَيَرْفُضُونَ مَا فِي أَيْدِيهِمْ وَيُقْبِلُونَ، فَيَبْعَثُونَ عَشَرَةَ فَوَارِسَ طَلِيعَةً. قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنِّي لَأَعْرِفُ أَسْمَاءَهُمْ وَأَسْمَاءَ آبَائِهِمْ وَأَلْوَانَ خُيُولِهِمْ، هُمْ خَيْرُ فَوَارِسَ عَلَى ظَهْرِ الْأَرْضِ يَوْمَئِذٍ. أَوْ: مِنْ خَيْرِ فَوَارِسَ عَلَى ظَهْرِ الْأَرْضِ يَوْمَئِذٍ". (م)', 'യുസൈറുബ്നു ജാബിർ(റ): കൂഫയിൽ ഒരു ചുവന്ന കാറ്റ് വീശി. അപ്പോൾ ഒരാൾ വന്നു. അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്, അന്ത്യനാൾ എത്തിയിരിക്കുന്നു എന്ന് പറയലല്ലാതെ മറ്റൊരു ജോലിയും അദ്ദേഹത്തിനില്ല. നിവേദകൻ പറയുന്നു: അപ്പോൾ അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ) ഇരുന്നു. അദ്ദേഹം ചാരിയിരിക്കുകയായിരുന്നു. അദ്ദേഹം പറഞ്ഞു: അനന്തരസ്വത്ത് വീതിക്കപ്പെടാതിരിക്കുകയും യുദ്ധമുതൽ കൊണ്ട് സന്തോഷിക്കാതിരിക്കുകയും ചെയ്യുന്ന കാലത്തോളം അന്ത്യനാൾ സംഭവിക്കുകയില്ല. പിന്നെ തന്റെ കൈ കൊണ്ട് ആംഗ്യം കാണിക്കുകയും ശാമിന്റെ ഭാഗത്തേക്ക് സൂചിപ്പിക്കുകയും ചെയ്തുകൊണ്ട് അദ്ദേഹം പറഞ്ഞു: ഒരു ശത്രു ഉണ്ടാകും. മുസ്ലിംകൾ അതിന് വേണ്ടിയും അത് മുസ്ലിംകൾക്ക് വേണ്ടിയും ഒരുമിക്കും. ഞാൻ ചോദിച്ചു: താങ്കൾ റോം ആണോ ഉദ്ദേശിക്കുന്നത്? അദ്ദേഹം പറഞ്ഞു: അതെ, ആ യുദ്ധത്തിന് ശക്തമായ തിരിച്ചടിയുമുണ്ടാകും. അപ്പോൾ മുസ്ലിംകൾ മരിക്കാൻ തയ്യാറുള്ള ചാവേറുകളെ ഉണ്ടാക്കും. വിജയിച്ചിട്ടല്ലാതെ അവർ മടങ്ങുകയില്ല. രാത്രി അവർക്കിടയിൽ മറയാകുന്നത് വരെ അവർ യുദ്ധം ചെയ്തുകൊണ്ടിരിക്കും. അങ്ങനെ രണ്ടു കൂട്ടരും ജയമില്ലാതെ മടങ്ങുകയും ചാവേറുകൾ ഇല്ലാതാകുകയും ചെയ്യും. അപ്പോൾ മുസ്ലിംകൾ മരിക്കാൻ തയ്യാറുള്ള ചാവേറുകളെ ഉണ്ടാക്കും. വിജയിച്ചിട്ടല്ലാതെ അവർ മടങ്ങുകയില്ല. രാത്രി അവർക്കിടയിൽ മറയാകുന്നത് വരെ അവർ യുദ്ധം ചെയ്തുകൊണ്ടിരിക്കും. എന്നാൽ രണ്ടു കൂട്ടരും ജയമില്ലാതെ മടങ്ങുകയും ചാവേറുകൾ ഇല്ലാതാകുകയും ചെയ്യും. വീണ്ടും മുസ്ലിംകൾ മറ്റൊരു ചാവേർസൈന്യത്തെ ഉണ്ടാക്കും. ജയിച്ചിട്ടല്ലാതെ അവർ മടങ്ങുകയില്ല. വൈകുന്നേരം വരെ അവർ യുദ്ധം ചെയ്യും. എന്നാൽ ആർക്കും ജയമില്ലാതെ രണ്ടുകൂട്ടരും മടങ്ങിവരും. ആ ചാവേർ ഇല്ലാതാകുകയും ചെയ്യും. നാലാമത്തെ ദിവസം ബാക്കിയുള്ള മുസ്ലിംകൾ അവരിലേക്ക് വരും. അപ്പോൾ അല്ലാഹു അവരെ (ശത്രുവിനെ) പരാജയപ്പെടുത്തും. അപ്പോൾ അതുവരെ കാണപ്പെടാത്ത - അല്ലെങ്കിൽ: കാണപ്പെട്ടിട്ടില്ലാത്ത - ഒരു യുദ്ധം അവർ ചെയ്യും. എത്രത്തോളമെന്നാൽ, അവരുടെ അരികിലൂടെ ഒരു പക്ഷി പറന്നാൽ അവരെ മറികടക്കും മുമ്പ് അത് മരിച്ചുവീഴും. അങ്ങനെ ഒരു പിതാവിന്റെ നൂറ് സന്താനങ്ങൾ ഒരുമിക്കും. പക്ഷേ, അവരിൽ ഒരാളെ മാത്രമേ അവശേഷിച്ചതായി അവർക്ക് കാണാനാകൂ. അപ്പോൾ പിന്നെ ഏത് മുതലിനെക്കുറിച്ചാണ് അല്ലെങ്കിൽ ഏത് അനന്തരസ്വത്ത് വീതിക്കപ്പെടുന്നതിനെക്കുറിച്ചാണ് സന്തോഷിക്കുക? അങ്ങനെയിരിക്കുമ്പോഴാണ് അതിനേക്കാൾ വലിയ ഒരു കുഴപ്പത്തെക്കുറിച്ച് അവർ കേൾക്കുന്നത്. ഒരട്ടഹാസം വരും: നിശ്ചയം ദജ്ജാൽ അവരുടെ മക്കളിൽ സ്വാധീനം ചെലുത്തിയിരിക്കുന്നു. അപ്പോഴവർ തങ്ങളുടെ പക്കലുള്ളതെല്ലാം ഉപേക്ഷിച്ച് മുന്നോട്ടു നടക്കും. ആദ്യം അവർ പത്ത് കുതിരപ്പടയാളികളെ പറഞ്ഞയക്കും. റസൂൽ(സ) പറഞ്ഞു: "അവരുടെ പേരും അവരുടെ പിതാക്കന്മാരുടെ പേരും അവരുടെ കുതിരകളുടെ നിറങ്ങളും എനിക്കറിയാം. അന്ന് ഭൂമുഖത്തുള്ള ഏറ്റവും ഉത്തമരായ കുതിരപ്പടയാളികളായിരിക്കും അവർ. അല്ലെങ്കിൽ അന്ന് ഭൂമുഖത്തുള്ള ഏറ്റവും ഉത്തമരായ കുതിരപ്പടയാളികളിൽപ്പെട്ടവരായിരിക്കുമർ." (മു)', 'يُسَيْرِ بْنِ جَابِرٍ', 'യുസൈറുബ്നു ജാബിർ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 755, 756, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=38 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 152, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، أَنَّهُ سُئِلَ عَنِ الدَّجَّالِ فَقَالَ: "أَلَا إِنَّ رَبَّكُمْ لَيْسَ بِأَعْوَرَ، أَلَا وَإِنَّهُ أَعْوَرُ، عَيْنُهُ الْيُمْنَى كَأَنَّهَا عِنَبَةٌ طَافِيَةٌ". صحيح. (ت)', 'ഇബ്നുഉമർ(റ): നബി(സ)യോട് ദജ്ജാലിനെക്കുറിച്ച് ചോദിച്ചപ്പോൾ അവിടന്ന് പറഞ്ഞു: "അറിയുക, നിങ്ങളുടെ രക്ഷിതാവ് ഒറ്റക്കണ്ണനല്ല. അറിയുക, നിശ്ചയം അവൻ (ദജ്ജാൽ) ഒറ്റക്കണ്ണനാകുന്നു. അവന്റെ വലതു കണ്ണ് തൂങ്ങിനിൽക്കുന്ന മുന്തിരി പോലെയായിരിക്കും." (തു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 756, 756, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 153, 'عَنْ رِبْعِيِّ بْنِ حِرَاشٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: اجْتَمَعَ حُذَيْفَةُ وَأَبُو مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُمَا، فَقَالَ حُذَيْفَةُ: "لَأَنَا بِمَا مَعَ الدَّجَّالِ أَعْلَمُ مِنْهُ، إِنَّ مَعَهُ بَحْرًا مِنْ مَاءٍ وَنَهْرًا مِنْ نَارٍ، فَالَّذِي تَرَوْنَ أَنَّهُ مِنْ نَارٍ مَاءٌ، وَالَّذِي تَرَوْنَ أَنَّهُ مَاءٌ نَارٌ، فَمَنْ أَدْرَكَ ذَلِكَ مِنْكُمْ فَأَرَادَ الْمَاءَ فَلْيَشْرَبْ مِنَ الَّذِي يَرَى أَنَّهُ نَارٌ، فَإِنَّهُ سَيَجِدُهُ مَاءً". قَالَ أَبُو مَسْعُودٍ الْبَدْرِيُّ رَضِيَ اللَّهُ عَنْهُ: هَكَذَا سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ. (ق,د)', 'രിബ്ഇയ്യുബ്നു ഹിറാശ്(റ): ഹുദൈഫ(റ)വും അബൂമസ്ഊദ്(റ)വും ഒരുമിച്ചു. അപ്പോൾ ഹുദൈഫ(റ) പറഞ്ഞു: "ദജ്ജാലിന്റെയടുത്തുള്ളതിനെക്കുറിച്ച് അവനേക്കാൾ കൂടുതൽ അറിവുള്ളവനാണ് ഞാൻ. അവന്റെ കൂടെ വെള്ളത്തിന്റെ ഒരു കടലും തീയിന്റെ ഒരു പുഴയുമുണ്ട്. തീയാണെന്ന് നിങ്ങൾ കരുതുന്നത് വെള്ളമായിരിക്കും. വെള്ളമാണെന്ന് കരുതുന്നത് തീയുമായിരിക്കും. നിങ്ങളാരെങ്കിലും ആ സന്ദർഭത്തിലുണ്ടാവുകയും വെള്ളം ഉദ്ദേശിക്കുകയും ചെയ്യുകയാണെങ്കിൽ തീയാണെന്ന് മനസ്സിലാക്കിയതിൽ നിന്ന് അവൻ കുടിക്കട്ടെ, കാരണം അത് വെള്ളമായിട്ടായിരിക്കും അവന് ലഭിക്കുക." അബൂമസ്ഊദുൽ ബദ്രി(റ) പറയുന്നു: നബി(സ) ഇപ്രകാരം പറയുന്നത് ഞാൻ കേട്ടിട്ടുണ്ട്. (ബു,മു,ദ)', 'رِبْعِيِّ بْنِ حِرَاشٍ', 'രിബ്ഇയ്യുബ്നു ഹിറാശ്(റ)', null, null, array['ق','د']::text[], array['ബു','മു','ദ']::text[], null, null, 756, 756, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 154, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ: "مَا بُعِثَ نَبِيٌّ إِلَّا قَدْ أَنْذَرَ أُمَّتَهُ الدَّجَّالَ الْأَعْوَرَ الْكَذَّابَ، أَلَا وَإِنَّهُ أَعْوَرُ، وَإِنَّ رَبَّكُمْ لَيْسَ بِأَعْوَرَ، وَإِنَّ بَيْنَ عَيْنَيْهِ مَكْتُوبًا كَافِرٌ". وَفِي رِوَايَةٍ: "ك ف ر". وَفِي رِوَايَةٍ: "يَقْرَؤُهُ كُلُّ مُسْلِمٍ". (ق,د,ت)', 'അനസുബ്നു മാലിക്(റ): നബി(സ) പറഞ്ഞു: "തന്റെ സമുദായത്തോട് കള്ളവാദിയും ഒറ്റക്കണ്ണനുമായ ദജ്ജാലിനെക്കുറിച്ച് മുന്നറിയിപ്പ് നൽകിയിട്ടല്ലാതെ ഒരു പ്രവാചകനും വന്നിട്ടില്ല. അറിയുക, അവൻ ഒറ്റക്കണ്ണനാണ്. നിങ്ങളുടെ നാഥൻ ഒറ്റക്കണ്ണനല്ല. അവന്റെ കണ്ണുകൾക്കിടയിൽ കാഫിർ (സത്യനിഷേധി) - മറ്റൊരു റിപ്പോർട്ടിൽ: കഫറ (സത്യനിഷേധിയായി) - എന്ന് എഴുതപ്പെട്ടിരിക്കും." മറ്റൊരു റിപ്പോർട്ടിൽ: "എല്ലാ മുസ്ലിംകളും അത് വായിക്കും." (ബു,മു,ദ,തു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ق','د','ت']::text[], array['ബു','മു','ദ','തു']::text[], null, null, 756, 757, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=13 and h.hadith_no=154), 1, 'وَفِي رِوَايَةٍ: "ك ف ر".', 'മറ്റൊരു നിവേദനിൽ: കഫറ (സത്യനിഷേധിയായി) - എന്ന് എഴുതപ്പെട്ടിരിക്കും."');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=13 and h.hadith_no=154), 2, 'وَفِي رِوَايَةٍ: "يَقْرَؤُهُ كُلُّ مُسْلِمٍ". (ق,د,ت)', 'മറ്റൊരു നിവേദനിൽ: "എല്ലാ മുസ്ലിംകളും അത് വായിക്കും." (ബു,മു,ദ,തു)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 155, 'عَنْ عِمْرَانَ بْنِ حُصَيْنٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ سَمِعَ بِالدَّجَّالِ فَلْيَنْأَ عَنْهُ، فَوَاللَّهِ إِنَّ الرَّجُلَ لَيَأْتِيهِ وَهُوَ يَحْسِبُ أَنَّهُ مُؤْمِنٌ فَيَتَّبِعُهُ، مِمَّا يَبْعَثُ بِهِ مِنَ الشُّبُهَاتِ. أَوْ: لِمَا يَبْعَثُ بِهِ مِنَ الشُّبُهَاتِ". (د)', 'ഇംറാനുബ്നു ഹുസ്വൈൻ(റ): റസൂൽ(സ) പറഞ്ഞു: "ആരെങ്കിലും ദജ്ജാലിനെ കുറിച്ച് കേട്ടാൽ അവനിൽ നിന്ന് വിദൂരമായി നിൽക്കട്ടെ. അല്ലാഹുവാണ് സത്യം, ദജ്ജാലിന്റെ അടുക്കൽ ചെല്ലുകയും അവൻ മുഅ്മിനാണെന്ന് വിചാരിച്ച് അവനെ പിന്തുടരുകയും ചെയ്യുന്നവരുണ്ട്. കാരണം അവൻ സംശയിപ്പിക്കുന്ന പല കാര്യങ്ങളും കൊണ്ടുവരും." (ദ)', 'عِمْرَانَ بْنِ حُصَيْنٍ', 'ഇംറാനുബ്നു ഹുസ്വൈൻ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 757, 757, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 156, 'عَنْ عُبَادَةَ بْنِ الصَّامِتِ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنِّي قَدْ حَدَّثْتُكُمْ عَنِ الدَّجَّالِ، حَتَّى خَشِيتُ أَنْ لَا تَعْقِلُوا، إِنَّ مَسِيحَ الدَّجَّالِ رَجُلٌ قَصِيرٌ أَفْحَجُ جَعْدٌ أَعْوَرُ مَطْمُوسُ الْعَيْنِ، لَيْسَ بِنَاتِئَةٍ وَلَا حَجْرَاءَ، فَإِنْ أُلْبِسَ عَلَيْكُمْ فَاعْلَمُوا أَنَّ رَبَّكُمْ لَيْسَ بِأَعْوَرَ". (د)', 'ഉബാദതുബ്നു സ്വാമിത്(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങൾക്ക് മനസ്സിലാകുന്നില്ലേയെന്ന് ഞാൻ ഭയപ്പെടുവോളം നിങ്ങളോട് ദജ്ജാലിനെക്കുറിച്ച് ഞാൻ പറഞ്ഞുതന്നു. നിശ്ചയം സഞ്ചാരിയായ ദജ്ജാൽ കുറിയവനും കാലുകൾ അകലെയാക്കി വെക്കുന്നവനുമാണ്. മുടി ചുരുണ്ടവനും ഒറ്റക്കണ്ണനും കണ്ണ് കാണാത്തവനുമാണവൻ. അധികം തടിച്ചവനോ മെലിഞ്ഞവനോ അല്ല. ഇനി നിങ്ങൾക്ക് സംശയം വന്നാൽ നിങ്ങൾ അറിയുക: നിങ്ങളുടെ നാഥൻ ഒറ്റക്കണ്ണനല്ല." (ദ)', 'عُبَادَةَ بْنِ الصَّامِتِ', 'ഉബാദതുബ്നു സ്വാമിത്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 757, 757, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 157, 'عَنْ عَامِرِ بْنِ شَرَاحِيلَ الشَّعْبِيِّ – شَعْبُ هَمْدَانَ – أَنَّهُ سَأَلَ فَاطِمَةَ بِنْتَ قَيْسٍ، أُخْتَ الضَّحَّاكِ بْنِ قَيْسٍ رَضِيَ اللَّهُ عَنْهُمَا، وَكَانَتْ مِنَ الْمُهَاجِرَاتِ الْأُوَلِ، فَقَالَ: حَدِّثِينِي حَدِيثًا سَمِعْتِيهِ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، لَا تُسْنِدِيهِ إِلَى أَحَدٍ غَيْرِهِ، فَقَالَتْ: لَئِنْ شِئْتَ لَأَفْعَلَنَّ، فَقَالَ لَهَا: أَجَلْ حَدِّثِينِي، فَقَالَتْ: نَكَحْتُ ابْنَ الْمُغِيرَةِ رَضِيَ اللَّهُ عَنْهُ وَهُوَ مِنْ خِيَارِ شَبَابِ قُرَيْشٍ يَوْمَئِذٍ، فَأُصِيبَ فِي أَوَّلِ الْجِهَادِ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَلَمَّا تَأَيَّمْتُ خَطَبَنِي عَبْدُ الرَّحْمَنِ بْنُ عَوْفٍ رَضِيَ اللَّهُ عَنْهُ فِي نَفَرٍ مِنْ أَصْحَابِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَخَطَبَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى مَوْلَاهُ أُسَامَةَ بْنِ زَيْدٍ رَضِيَ اللَّهُ عَنْهُمَا، وَكُنْتُ قَدْ حُدِّثْتُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ أَحَبَّنِي فَلْيُحِبَّ أُسَامَةَ". فَلَمَّا كَلَّمَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قُلْتُ: أَمْرِي بِيَدِكَ فَأَنْكِحْنِي مَنْ شِئْتَ، فَقَالَ: "انْتَقِلِي إِلَى أُمِّ شَرِيكٍ". – وَأُمُّ شَرِيكٍ امْرَأَةٌ غَنِيَّةٌ مِنَ الْأَنْصَارِ، عَظِيمَةُ النَّفَقَةِ فِي سَبِيلِ اللَّهِ، يَنْزِلُ عَلَيْهَا الضِّيفَانُ – فَقُلْتُ: سَأَفْعَلُ. فَقَالَ: "لَا تَفْعَلِي، إِنَّ أُمَّ شَرِيكٍ امْرَأَةٌ كَثِيرَةُ الضِّيفَانِ، فَإِنِّي أَكْرَهُ أَنْ يَسْقُطَ عَنْكِ خِمَارُكِ، أَوْ يَنْكَشِفَ الثَّوْبُ عَنْ سَاقَيْكِ، فَيَرَى الْقَوْمُ مِنْكِ بَعْضَ مَا تَكْرَهِينَ، وَلَكِنِ انْتَقِلِي إِلَى ابْنِ عَمِّكِ عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ أُمِّ مَكْتُومٍ" – وَهُوَ رَجُلٌ مِنْ بَنِي فِهْرٍ، فِهْرِ قُرَيْشٍ، وَهُوَ مِنَ الْبَطْنِ الَّذِي هِيَ مِنْهُ – فَانْتَقَلْتُ إِلَيْهِ، فَلَمَّا انْقَضَتْ عِدَّتِي سَمِعْتُ نِدَاءَ الْمُنَادِي – مُنَادِي رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ – يُنَادِي الصَّلَاةَ جَامِعَةً، فَخَرَجْتُ إِلَى الْمَسْجِدِ، فَصَلَّيْتُ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَكُنْتُ فِي صَفِّ النِّسَاءِ الَّتِي تَلِي ظُهُورَ الْقَوْمِ، فَلَمَّا قَضَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَلَاتَهُ جَلَسَ عَلَى الْمِنْبَرِ وَهُوَ يَضْحَكُ، فَقَالَ: "لِيَلْزَمْ كُلُّ إِنْسَانٍ مُصَلَّاهُ". ثُمَّ قَالَ: "أَتَدْرُونَ لِمَ جَمَعْتُكُمْ". قَالُوا: اللَّهُ وَرَسُولُهُ أَعْلَمُ، قَالَ: "إِنِّي وَاللَّهِ مَا جَمَعْتُكُمْ لِرَغْبَةٍ وَلَا لِرَهْبَةٍ، وَلَكِنْ جَمَعْتُكُمْ لِأَنَّ تَمِيمًا الدَّارِيَّ كَانَ رَجُلًا نَصْرَانِيًّا، فَجَاءَ فَبَايَعَ وَأَسْلَمَ، وَحَدَّثَنِي حَدِيثًا وَافَقَ الَّذِي كُنْتُ أُحَدِّثُكُمْ عَنْ مَسِيحِ الدَّجَّالِ، حَدَّثَنِي: أَنَّهُ رَكِبَ فِي سَفِينَةٍ بَحْرِيَّةٍ مَعَ ثَلَاثِينَ رَجُلًا مِنْ لَخْمٍ وَجُذَامَ، فَلَعِبَ بِهِمُ الْمَوْجُ شَهْرًا فِي الْبَحْرِ، ثُمَّ أَرْفَئُوا إِلَى جَزِيرَةٍ فِي الْبَحْرِ حَتَّى مَغْرِبِ الشَّمْسِ، فَجَلَسُوا فِي أَقْرُبِ السَّفِينَةِ فَدَخَلُوا الْجَزِيرَةَ، فَلَقِيَتْهُمْ دَابَّةٌ أَهْلَبُ كَثِيرُ الشَّعَرِ، لَا يَدْرُونَ مَا قُبُلُهُ مِنْ دُبُرِهِ مِنْ كَثْرَةِ الشَّعَرِ، فَقَالُوا: وَيْلَكَ مَا أَنْتَ؟ فَقَالَتْ: أَنَا الْجَسَّاسَةُ، قَالُوا: وَمَا الْجَسَّاسَةُ؟ قَالَتْ: أَيُّهَا الْقَوْمُ، انْطَلِقُوا إِلَى هَذَا الرَّجُلِ فِي الدَّيْرِ، فَإِنَّهُ إِلَى خَبَرِكُمْ بِالْأَشْوَاقِ، قَالَ: لَمَّا سَمَّتْ لَنَا رَجُلًا فَرِقْنَا مِنْهَا أَنْ تَكُونَ شَيْطَانَةً، قَالَ: فَانْطَلَقْنَا سِرَاعًا حَتَّى دَخَلْنَا الدَّيْرَ فَإِذَا فِيهِ أَعْظَمُ إِنْسَانٍ رَأَيْنَاهُ قَطُّ خَلْقًا، وَأَشَدُّهُ وِثَاقًا، مَجْمُوعَةٌ يَدَاهُ إِلَى عُنُقِهِ، مَا بَيْنَ رُكْبَتَيْهِ إِلَى كَعْبَيْهِ بِالْحَدِيدِ، قُلْنَا: وَيْلَكَ مَا أَنْتَ؟ قَالَ: قَدْ قَدَرْتُمْ عَلَى خَبَرِي، فَأَخْبِرُونِي مَا أَنْتُمْ؟ قَالُوا: نَحْنُ أُنَاسٌ مِنَ الْعَرَبِ، رَكِبْنَا فِي سَفِينَةٍ بَحْرِيَّةٍ فَصَادَفْنَا الْبَحْرَ حِينَ اغْتَلَمَ، فَلَعِبَ بِنَا الْمَوْجُ شَهْرًا، ثُمَّ أَرْفَأْنَا إِلَى جَزِيرَتِكَ هَذِهِ، فَجَلَسْنَا فِي أَقْرُبِهَا فَدَخَلْنَا الْجَزِيرَةَ، فَلَقِيَتْنَا دَابَّةٌ أَهْلَبُ، كَثِيرُ الشَّعَرِ، لَا يُدْرَى مَا قُبُلُهُ مِنْ دُبُرِهِ مِنْ كَثْرَةِ الشَّعَرِ، فَقُلْنَا: وَيْلَكِ مَا أَنْتِ؟ فَقَالَتْ: أَنَا الْجَسَّاسَةُ، قُلْنَا: وَمَا الْجَسَّاسَةُ؟ قَالَتْ: اعْمِدُوا إِلَى هَذَا الرَّجُلِ فِي الدَّيْرِ، فَإِنَّهُ إِلَى خَبَرِكُمْ بِالْأَشْوَاقِ، فَأَقْبَلْنَا إِلَيْكَ سِرَاعًا، وَفَزِعْنَا مِنْهَا، وَلَمْ نَأْمَنْ أَنْ تَكُونَ شَيْطَانَةً. فَقَالَ: أَخْبِرُونِي عَنْ نَخْلِ بَيْسَانَ، قُلْنَا: عَنْ أَيِّ شَأْنِهَا تَسْتَخْبِرُ؟ قَالَ: أَسْأَلُكُمْ عَنْ نَخْلِهَا، هَلْ يُثْمِرُ؟ قُلْنَا لَهُ: نَعَمْ، قَالَ: أَمَا إِنَّهُ يُوشِكُ أَنْ لَا تُثْمِرَ، قَالَ: أَخْبِرُونِي عَنْ بُحَيْرَةِ الطَّبَرِيَّةِ، قُلْنَا: عَنْ أَيِّ شَأْنِهَا تَسْتَخْبِرُ؟ قَالَ: هَلْ فِيهَا مَاءٌ؟ قَالُوا: هِيَ كَثِيرَةُ الْمَاءِ، قَالَ: أَمَا إِنَّ مَاءَهَا يُوشِكُ أَنْ يَذْهَبَ، قَالَ: أَخْبِرُونِي عَنْ عَيْنِ زُغَرَ، قَالُوا: عَنْ أَيِّ شَأْنِهَا تَسْتَخْبِرُ؟ قَالَ: هَلْ فِي الْعَيْنِ مَاءٌ؟ وَهَلْ يَزْرَعُ أَهْلُهَا بِمَاءِ الْعَيْنِ؟ قُلْنَا لَهُ: نَعَمْ، هِيَ كَثِيرَةُ الْمَاءِ، وَأَهْلُهَا يَزْرَعُونَ مِنْ مَائِهَا، قَالَ: أَخْبِرُونِي عَنْ نَبِيِّ الْأُمِّيِّينَ، مَا فَعَلَ؟ قَالُوا: قَدْ خَرَجَ مِنْ مَكَّةَ وَنَزَلَ يَثْرِبَ، قَالَ: أَقَاتَلَهُ الْعَرَبُ؟ قُلْنَا: نَعَمْ، قَالَ: كَيْفَ صَنَعَ بِهِمْ؟ فَأَخْبَرْنَاهُ أَنَّهُ قَدْ ظَهَرَ عَلَى مَنْ يَلِيهِ مِنَ الْعَرَبِ وَأَطَاعُوهُ، قَالَ لَهُمْ: قَدْ كَانَ ذَلِكَ؟ قُلْنَا: نَعَمْ، قَالَ: أَمَا إِنَّ ذَاكَ خَيْرٌ لَهُمْ أَنْ يُطِيعُوهُ، وَإِنِّي مُخْبِرُكُمْ عَنِّي: إِنِّي أَنَا الْمَسِيحُ [الدَّجَّالُ]. وَإِنِّي أُوشِكُ أَنْ يُؤْذَنَ لِي فِي الْخُرُوجِ فَأَخْرُجَ، فَأَسِيرَ فِي الْأَرْضِ، فَلَا أَدَعَ قَرْيَةً إِلَّا هَبَطْتُهَا فِي أَرْبَعِينَ لَيْلَةً، غَيْرَ مَكَّةَ وَطَيْبَةَ، فَهُمَا مُحَرَّمَتَانِ عَلَيَّ كِلْتَاهُمَا، كُلَّمَا أَرَدْتُ أَنْ أَدْخُلَ وَاحِدَةً – أَوْ وَاحِدًا – مِنْهُمَا اسْتَقْبَلَنِي مَلَكٌ بِيَدِهِ السَّيْفُ صَلْتًا، يَصُدُّنِي عَنْهَا، وَإِنَّ عَلَى كُلِّ نَقْبٍ مِنْهَا مَلَائِكَةً يَحْرُسُونَهَا". قَالَتْ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَطَعَنَ بِمِخْصَرَتِهِ فِي الْمِنْبَرِ: "هَذِهِ طَيْبَةُ، هَذِهِ طَيْبَةُ، هَذِهِ طَيْبَةُ – يَعْنِي الْمَدِينَةَ – أَلَا هَلْ كُنْتُ حَدَّثْتُكُمْ ذَلِكَ". فَقَالَ النَّاسُ: نَعَمْ. "فَإِنَّهُ أَعْجَبَنِي حَدِيثُ تَمِيمٍ، أَنَّهُ وَافَقَ الَّذِي كُنْتُ أُحَدِّثُكُمْ عَنْهُ، وَعَنِ الْمَدِينَةِ وَمَكَّةَ، أَلَا إِنَّهُ فِي بَحْرِ الشَّأْمِ أَوْ بَحْرِ الْيَمَنِ، لَا بَلْ مِنْ قِبَلِ الْمَشْرِقِ مَا هُوَ، مِنْ قِبَلِ الْمَشْرِقِ مَا هُوَ، مِنْ قِبَلِ الْمَشْرِقِ مَا هُوَ". وَأَوْمَأَ بِيَدِهِ إِلَى الْمَشْرِقِ. قَالَتْ: فَحَفِظْتُ هَذَا مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. (م,د)', 'ഹമദാനിൽപ്പെട്ട ആമിറുബ്നു ശറാഹീലു ശഅ്ബി(റ): അദ്ദേഹം ളഹാകുബ്നു ഖൈസ്(റ)വിന്റെ സഹോദരിയായ ഫാത്തിമ ബിൻത് ഖൈസ്(റ)യോട് - അവർ ആദ്യ മുഹാജിറുകളിൽപ്പെട്ടവരായിരുന്നു - പറഞ്ഞു: റസൂൽ(സ)യിൽ നിന്നും നിങ്ങൾ കേട്ട ഒരു സംഭവം എനിക്ക് പറഞ്ഞുതരിക. അതിന്റെ സനദിനിടയിൽ വേറെ ആരും വരരുത്. അവർ പറഞ്ഞു: അങ്ങനെ താങ്കൾ ആവശ്യപ്പെടുകയാണെങ്കിൽ ഞാൻ ചെയ്യാം. അപ്പോൾ അവരോടദ്ദേഹം പറഞ്ഞു: അതെ, പറയുക. അവർ പറഞ്ഞു: ഞാൻ ഇബ്നുമുഗീറ(റ)വിനെ വിവാഹം കഴിച്ചു. അന്നേരം അദ്ദേഹം ഖുറൈശികളിലെ ഏറ്റവും നല്ല യുവാക്കളിൽപ്പെട്ടവനായിരുന്നു. അങ്ങനെ റസൂൽ(സ)യുടെ കൂടെയുള്ള ആദ്യ ധർമ്മയുദ്ധത്തിൽ അദ്ദേഹം രക്തസാക്ഷിയായി. അങ്ങനെ ഞാൻ വിധവയായപ്പോൾ അബ്ദുർറഹ്മാനുബ്നു ഔഫ്(റ) റസൂൽ(സ)യുടെ അനുചരരിൽപ്പെട്ട ഒരു സംഘത്തോടൊപ്പം എന്നോട് വിവാഹാഭ്യർത്ഥന നടത്തി. റസൂൽ(സ)യുടെ അടിമ ഉസാമതുബ്നു സൈദ്(റ)വിന് വേണ്ടി തിരുമേനി(സ)യും എന്നോട് വിവാഹാഭ്യർത്ഥന നടത്തിയിരുന്നു. എന്നോട് പറയപ്പെട്ടു: റസൂൽ(സ) പറഞ്ഞിരിക്കുന്നു: "എന്നെ സ്നേഹിക്കുന്നവർ ഉസാമയെയും സ്നേഹിക്കട്ടെ." അങ്ങനെ എന്നോട് റസൂൽ(സ) സംസാരിച്ചപ്പോൾ ഞാൻ പറഞ്ഞു: തന്റെ കാര്യങ്ങൾ അങ്ങയുടെ കരങ്ങളിലാണ്. അങ്ങ് ഉദ്ദേശിക്കുന്നവർക്ക് എന്നെ വിവാഹം ചെയ്തുകൊടുക്കുക. അപ്പോൾ അവിടുന്ന് പറഞ്ഞു: "നീ ഉമ്മുശരീക്കിന്റെ അടുത്തുചെല്ലുക." ഉമ്മുശരീക്ക് അൻസാരികളിൽപ്പെട്ട സമ്പന്നയായ സ്ത്രീയാണ്. അല്ലാഹുവിന്റെ മാർഗത്തിൽ നന്നായി ചെലവഴിക്കുന്നവരുമാണ്. ധാരാളം അതിഥികൾ അവിടെ വരാറുമുണ്ട്. അപ്പോൾ ഞാൻ പറഞ്ഞു: ഞാൻ അങ്ങനെ ചെയ്യാം. അപ്പോൾ അവിടുന്ന് പറഞ്ഞു: "അങ്ങനെ ചെയ്യേണ്ട. കാരണം ഉമ്മുശരീക് ധാരാളം അതിഥികളുള്ള സ്ത്രീയാണ്. നിന്റെ മുഖമക്കന ഊരിപ്പോകുന്നതും തണ്ടങ്കാലിൽ നിന്ന് വസ്ത്രം പോകുന്നതും ഞാൻ ഇഷ്ടപ്പെടുന്നില്ല. അങ്ങനെയായാൽ നീ വെറുക്കുന്ന ഭാഗങ്ങൾ ജനങ്ങൾ കാണും. അതുകൊണ്ട് നിന്റെ സഹോദരപുത്രൻ അബ്ദുല്ലാഹിബ്നു അംറുബ്നു ഉമ്മിമക്തൂമിന്റെ അടുത്തുചെല്ലുക." അദ്ദേഹം ഖുറൈശിലെ ബനൂഫിഹ്റിൽപ്പെട്ടവരാണ്. അദ്ദേഹവും അവരുടെ ഗോത്രത്തിൽ പെട്ടയാളാണ്. അങ്ങനെ ഞാൻ അദ്ദേഹത്തിന്റെയടുക്കൽ ചെന്നു. എന്റെ ഇദ്ദ തീർന്നപ്പോൾ റസൂൽ(സ)യുടെ വാർത്ത എത്തിക്കുന്നവൻ (വിളിച്ചുപറയുന്നവൻ) വിളിച്ചുപറയുന്നത് ഞാൻ കേട്ടു: അസ്സലാത്തു ജാമിഅഃ അങ്ങനെ ഞാൻ പള്ളിയിൽ പോയി റസൂൽ(സ)യുടെ കൂടെ നിസ്കരിച്ചു. പുരുഷന്മാരുടെ സ്വഫിന്റെ തൊട്ടുപിന്നിലുള്ള സ്ത്രീകളുടെ സ്വഫിലായിരുന്നു ഞാൻ. അങ്ങനെ നിസ്കാരം കഴിഞ്ഞപ്പോൾ തിരുമേനി(സ) മിമ്പറിലിരുന്നു. അവിടുന്ന് ചിരിക്കുന്നുണ്ടായിരുന്നു. നബി(സ) പറഞ്ഞു: "എല്ലാവരും നിസ്കരിച്ചിടത്തു തന്നെ ഇരിക്കുക." ശേഷം അവിടുന്ന് ചോദിച്ചു: "എന്തിനാണ് നിങ്ങളെ ഒരുമിച്ചുകൂട്ടിയതെന്ന് നിങ്ങൾക്കറിയുമോ?" അവർ പറഞ്ഞു: അല്ലാഹുവും അവന്റെ ദൂതരുമാണ് ഏറ്റവും അറിയുന്നവർ. നബി(സ) പറഞ്ഞു: "ഞാൻ നിങ്ങളെ ഒരുമിച്ചുകൂട്ടിയത് വല്ലതിനെയും കുറിച്ച് പേടിപ്പെടുത്താനോ ആഗ്രഹിപ്പിക്കാനോ അല്ല. മറിച്ച് ഈ കാര്യം പറയാനാണ്. തമീമുദ്ദാരി ക്രിസ്ത്യാനിയായിരുന്നു. പക്ഷേ, അദ്ദേഹം ബൈഅത്തുചെയ്ത് മുസ്ലിമായിട്ടുണ്ട്. സഞ്ചാരിയായ ദജ്ജാലിനെ കുറിച്ച് ഞാൻ നിങ്ങളോട് പറഞ്ഞതിനോട് യോജിക്കുന്ന ഒരു സംഭവം അദ്ദേഹം എനിക്ക് പറഞ്ഞുതന്നു. അദ്ദേഹം എന്നോട് പറഞ്ഞു: അദ്ദേഹം ലഖ്മ്, ജുദാം ഗോത്രങ്ങളിലെ മുപ്പതാളുകളുമായി കപ്പലിൽ യാത്രചെയ്യുകയായിരുന്നു. അവർ ഒരു മാസത്തോളം തിരമാലയിൽ അകപ്പെട്ടു. പിന്നെ അവർ പടിഞ്ഞാറുള്ള കടലിലെ ഒരു ദ്വീപിൽ അഭയം തേടി. അങ്ങനെ ചെറിയ തോണികളിലായി അവർ ദ്വീപിലെത്തി. അപ്പോൾ അവർ കട്ടിയുള്ള ധാരാളം മുടിയുള്ള ഒരു മൃഗത്തെ കണ്ടു. മുടി അധികരിച്ചതിനാൽ അതിന്റെ മുൻവശം ഏതെന്നോ പിൻവശം ഏതെന്നോ തിരിച്ചറിഞ്ഞിരുന്നില്ല. അപ്പോൾ അവർ ചോദിച്ചു: നാശം, ഏതാണ് നീ? അത് പറഞ്ഞു: ഞാൻ ചാരനാകുന്നു. അവർ ചോദിച്ചു: എന്ത് ചാരൻ? അത് പറഞ്ഞു: ഓ സമൂഹമേ, നിങ്ങൾ ഈ കോട്ടയിലുള്ള ആളുടെ അടുത്തുപോകുക. കാരണമദ്ദേഹം നിങ്ങളുടെ വിഷയത്തിൽ താൽപര്യമുള്ളവനാണ്. അദ്ദേഹം പറയുന്നു: ആ മൃഗം ഒരാളുടെ പേര് പറഞ്ഞപ്പോൾ അത് പിശാചാകുമോ എന്ന് ഞങ്ങൾ പേടിച്ചു. അങ്ങനെ ഞങ്ങൾ പെട്ടെന്ന് പോയി കോട്ടയിൽ പ്രവേശിച്ചു. അന്നേരം ഞങ്ങൾ ഇതുവരെ കണ്ടിട്ടുള്ള സൃഷ്ടികളിൽവെച്ച് ഏറ്റവും വലിയ മനുഷ്യൻ! ഏറ്റവും ശക്തമായ ബന്ധനത്തിൽ കഴിയുന്നയാൾ, അവന്റെ രണ്ട് കൈകൾ ചുമലിലേക്ക് കൂട്ടപ്പെട്ടിരിക്കുന്നു. രണ്ട് മുട്ടിൻകാലും മടമ്പ് വരെ ഇരുമ്പ് കൊണ്ട് ബന്ധിക്കപ്പെട്ടിരിക്കുന്നു. ഞങ്ങൾ ചോദിച്ചു: നിനക്ക് നാശം, നീ ആരാണ്? അവൻ പറഞ്ഞു: എന്നെക്കുറിച്ച് നിങ്ങൾ അറിഞ്ഞു. ഇനി നിങ്ങളാരാണെന്ന് പറയുക. അവർ പറഞ്ഞു: ഞങ്ങൾ അറേബ്യയിൽ നിന്നുള്ളവരാണ്. ഞങ്ങൾ ഒരു കപ്പലിൽ കയറി. കടൽ ക്ഷോഭിച്ചപ്പോൾ തിരമാല ഒരു മാസത്തോളം ഞങ്ങളെ കളിപ്പിച്ചു. (തിരമാലയിൽ കപ്പൽ ആടിയുലഞ്ഞു). പിന്നെ ഞങ്ങൾ താങ്കളുടെ ഈ ദ്വീപിൽ അഭയം തേടി. അങ്ങനെ ചെറിയ ബോട്ടുകളിലായി ഈ ദ്വീപിലെത്തി. മുടി അധികമുള്ളതിനാൽ മുൻഭാഗവും പിൻഭാഗവും തിരിച്ചറിയാൻ സാധിക്കാത്ത വിധം കട്ടിയുള്ള ധാരാളം മുടിയുള്ള ഒരു മൃഗത്തെ ഞങ്ങൾ കണ്ടു. അപ്പോൾ ഞങ്ങൾ ചോദിച്ചു: നാശം, നീ ഏതാണ്? അത് പറഞ്ഞു: ഞാൻ ചാരനാണ്. ഞങ്ങൾ ചോദിച്ചു: എന്ത് ചാരൻ? അത് പറഞ്ഞു: ആ കോട്ടയിലുള്ള ആളുടെ അടുത്ത് നിങ്ങൾ പോകുക. കാരണം അദ്ദേഹം നിങ്ങളെക്കുറിച്ചറിയാൻ ആഗ്രഹമുള്ളയാളാണ്. അങ്ങനെ പെട്ടെന്ന് ഞങ്ങൾ താങ്കളുടെ അടുത്തുവന്നു. ഞങ്ങൾ പരിഭ്രാന്തരായിരുന്നു. അത് ഒരു പിശാചാണോ എന്ന് ഞങ്ങൾ ഭയക്കുകയും ചെയ്തു. അയാൾ പറഞ്ഞു: ബൈസാനിലെ ഈത്തപ്പനത്തോട്ടത്തെക്കുറിച്ച് വിവരിക്കുക. ഞങ്ങൾ ചോദിച്ചു: അതിന്റെ ഏത് കാര്യത്തെക്കുറിച്ചാണ് താങ്കൾക്കറിയേണ്ടത്? അയാൾ പറഞ്ഞു: അതിലെ ഈത്തപ്പന ഫലം കായ്ക്കുന്നുണ്ടോ എന്നാണ് ഞാൻ നിങ്ങളോട് ചോദിക്കുന്നത്. ഞങ്ങൾ പറഞ്ഞു: അതെ. അയാൾ പറഞ്ഞു: എങ്കിൽ അത് ഫലം കായ്ക്കാതിരിക്കാൻ അടുത്തിരിക്കുന്നു. അയാൾ പറഞ്ഞു: ത്വബ്രിയ്യ തടാകത്തെക്കുറിച്ച് പറയുക. ഞങ്ങൾ ചോദിച്ചു: അതിന്റെ ഏത് കാര്യമാണ് താങ്കൾക്കറിയേണ്ടത്? അയാൾ ചോദിച്ചു: അതിൽ വെള്ളമുണ്ടോ? അവർ പറഞ്ഞു: അത് ധാരാളം വെള്ളമുള്ളതാണ്. അയാൾ പറഞ്ഞു: എങ്കിൽ അതിലെ വെള്ളം വറ്റാൻ അടുത്തിരിക്കുന്നു. അയാൾ പറഞ്ഞു: സുഅർ എന്ന സ്ഥലത്തെ അരുവിയെക്കുറിച്ച് എന്നോട് പറയുക. അവർ ചോദിച്ചു: അതിന്റെ ഏത് കാര്യമാണ് താങ്കൾക്കറിയേണ്ടത്? അയാൾ ചോദിച്ചു: അതിൽ വെള്ളമുണ്ടോ? ആ വെള്ളം കൊണ്ട് അതിന്റെയാളുകൾ കൃഷിചെയ്യാറുണ്ടോ? ഞങ്ങൾ പറഞ്ഞു: അതെ. അത് ധാരാളം വെള്ളമുള്ളതാണ്. അവിടെയുള്ള ജനങ്ങൾ അതുകൊണ്ടാണ് കൃഷിചെയ്യുന്നത്. അയാൾ പറഞ്ഞു: നിരക്ഷരരുടെ പ്രവാചകൻ എന്തൊക്കെ ചെയ്തുവെന്ന് എന്നോട് പറയുക. അവർ പറഞ്ഞു: അദ്ദേഹം മക്കയിൽ നിന്നും പോയി മദീനയിൽ താമസിച്ചിരിക്കുന്നു. അയാൾ ചോദിച്ചു: അറബികൾ അദ്ദേഹവുമായി യുദ്ധം ചെയ്തുവോ? ഞങ്ങൾ പറഞ്ഞു: അതെ. അയാൾ ചോദിച്ചു: എന്താണദ്ദേഹം അവരെ ചെയ്തത്? പ്രവാചകൻ അറബികളിൽ തന്റെ സമീപത്തുള്ളവരുടെ മേൽ വിജയംവരിക്കുകയും അവർ ആ പ്രവാചകനെ അനുസരിക്കുകയും ചെയ്യുന്നുവെന്ന് ഞങ്ങൾ പറഞ്ഞു. അവരോട് അയാൾ ചോദിച്ചു: അത് ഉണ്ടായോ? ഞങ്ങൾ പറഞ്ഞു: അതെ. അയാൾ പറഞ്ഞു: എങ്കിൽ അദ്ദേഹത്തെ അനുസരിക്കലാണ് അവർക്കുത്തമം. ഇനി ഞാൻ എന്നെക്കുറിച്ച് പറഞ്ഞുതരാം: ഞാനാണ് ചുറ്റിസഞ്ചരിക്കുന്ന ദജ്ജാൽ. ഞാൻ പുറത്തുവരാൻ അടുത്തിട്ടുണ്ട്. ഞാൻ പുറപ്പെടുകയും ചെയ്യും. അങ്ങനെ ഭൂമിയിൽ ഞാൻ ചുറ്റിസഞ്ചരിക്കും. നാൽപത് രാത്രികളിലായി എല്ലാ ഗ്രാമങ്ങളിലും ഞാൻ കാലുകുത്തും. മക്കയും ത്വയ്ബ(മദീന)യും ഒഴികെ. അവ രണ്ടും എനിക്ക് നിഷിദ്ധമാണ്. ഞാൻ അവയിലൊന്നിൽ പ്രവേശിക്കാനുദ്ദേശിക്കുമ്പോഴെല്ലാം കയ്യിൽ തിളങ്ങുന്ന വാളുമായി ഒരു മാലാഖ എന്നെ നേരിട്ട് അതിൽ നിന്ന് തടയും. അവയിലേക്കുള്ള ഓരോ കവാടത്തിലും അവയെ സംരക്ഷിക്കുന്ന മലക്കുകളുണ്ടാകും." നിവേദക പറയുന്നു: മിമ്പറിൽ അവിടുത്തെ വടി കുത്തിക്കൊണ്ട് നബി(സ) പറഞ്ഞു: "ഇതാണ് ത്വയ്ബ, ഇതാണ് ത്വയ്ബ, ഇതാണ് ത്വയ്ബ - അഥവാ മദീന - അറിയുക, ഇത് നിങ്ങളോട് ഞാൻ പറഞ്ഞിരുന്നില്ലേ?" ജനങ്ങൾ പറഞ്ഞു: അതെ. "നിശ്ചയം തമീമിന്റെ ഈ സംഭവം എന്നെ അത്ഭുതപ്പെടുത്തിയിരിക്കുന്നു. കാരണം അവനെക്കുറിച്ചും മക്കയെയും മദീനയെക്കുറിച്ചും ഞാൻ നിങ്ങളോട് പറഞ്ഞിരുന്നതിനോട് അത് യോജിച്ചിരിക്കുന്നു. അറിയുക, അവൻ ശാമിലെയോ യമനിലെയോ കടലിലാണ്. അല്ല, മറിച്ച് കിഴക്കുഭാഗത്താണ്, കിഴക്കുഭാഗത്താണ്, കിഴക്കുഭാഗത്താണവൻ." തിരുമേനി(സ) കൈ കൊണ്ട് കിഴക്കുഭാഗം സൂചിപ്പിക്കുകയും ചെയ്തു. ഫാതിമ(റ) പറയുന്നു: റസൂൽ(സ)യിൽ നിന്ന് ഞാനിത് മനഃപാഠമാക്കുകയും ചെയ്തു. (മു,ദ)', 'عَامِرِ بْنِ شَرَاحِيلَ الشَّعْبِيِّ – شَعْبُ هَمْدَانَ – أَنَّهُ سَأَلَ فَاطِمَةَ بِنْتَ قَيْسٍ، أُخْتَ الضَّحَّاكِ بْنِ قَيْسٍ', 'ഹമദാനിൽപ്പെട്ട ആമിറുബ്നു ശറാഹീലു ശഅ്ബി(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], 'الدَّجَّالُ', null, 757, 760, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 158, 'عَنْ فَاطِمَةَ بِنْتِ قَيْسٍ رَضِيَ اللَّهُ عَنْهَا: أَنَّ نَبِيَّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَعِدَ الْمِنْبَرَ فَضَحِكَ، فَقَالَ: "إِنَّ تَمِيمًا الدَّارِيَّ حَدَّثَنِي بِحَدِيثٍ فَفَرِحْتُ بِهِ، فَأَحْبَبْتُ أَنْ أُحَدِّثَكُمْ، حَدَّثَنِي: أَنَّ نَاسًا مِنْ أَهْلِ فِلَسْطِينَ رَكِبُوا سَفِينَةً فِي الْبَحْرِ، فَجَالَتْ بِهِمْ حَتَّى قَذَفَتْهُمْ فِي جَزِيرَةٍ مِنْ جَزَائِرِ الْبَحْرِ، فَإِذَا هُمْ بِدَابَّةٍ لَبَّاسَةٍ نَاشِرَةٍ شَعْرَهَا، فَقَالُوا: مَا أَنْتِ؟ قَالَتْ: أَنَا الْجَسَّاسَةُ. قَالُوا: فَأَخْبِرِينَا. قَالَتْ: لَا أُخْبِرُكُمْ وَلَا أَسْتَخْبِرُكُمْ، وَلَكِنِ ائْتُوا أَقْصَى الْقَرْيَةِ فَإِنَّ ثَمَّ مَنْ يُخْبِرُكُمْ وَيَسْتَخْبِرُكُمْ، فَأَتَيْنَا أَقْصَى الْقَرْيَةِ فَإِذَا رَجُلٌ مُوثَقٌ بِسِلْسِلَةٍ، فَقَالَ: أَخْبِرُونِي عَنْ عَيْنِ زُغَرَ؟ قُلْنَا: مَلْأَى تَدْفُقُ. قَالَ: أَخْبِرُونِي عَنِ الْبُحَيْرَةِ؟ قُلْنَا: مَلْأَى تَدْفُقُ. قَالَ: أَخْبِرُونِي عَنْ نَخْلِ بَيْسَانَ، الَّذِي بَيْنَ الْأُرْدُنِّ وَفِلَسْطِينَ، هَلْ أَطْعَمَ؟ قُلْنَا: نَعَمْ. قَالَ: أَخْبِرُونِي عَنِ النَّبِيِّ، هَلْ بُعِثَ؟ قُلْنَا: نَعَمْ. قَالَ: أَخْبِرُونِي كَيْفَ النَّاسُ إِلَيْهِ؟ قُلْنَا: سِرَاعٌ. قَالَ: فَنَزَّى نَزْوَةً حَتَّى كَادَ، قُلْنَا: فَمَا أَنْتَ؟ قَالَ: أَنَا الدَّجَّالُ وَإِنَّهُ يَدْخُلُ الْأَمْصَارَ كُلَّهَا إِلَّا طَيْبَةَ، وَطَيْبَةُ: الْمَدِينَةُ". حسن صحيح. (ت)', 'ഫാത്വിമത് ബിൻത് ഖൈസ്(റ): നബി(സ) മിമ്പറിൽ കയറിയിട്ട് ചിരിച്ചുകൊണ്ട് പറഞ്ഞു: "തമീമുദ്ദാരി എന്നോടൊരു സംഭവം പറഞ്ഞു: ഞാനതുകാരണം സന്തോഷിക്കുകയും ചെയ്തു. അത് നിങ്ങളോട് പറയാൻ ഞാൻ ആഗ്രഹിക്കുന്നു. തമീമുദ്ദാരി എന്നോട് പറഞ്ഞു: ഫലസ്തീനിലെ കുറച്ചാളുകൾ കപ്പലിൽ യാത്രതുടങ്ങി. കപ്പൽ തിരമാലയിൽ ആടിയുലഞ്ഞു. അവർ കടലിലെ ഒരു ദ്വീപിലേക്കെറിയപ്പെട്ടു. അവിടെ ധാരാളം മുടിയുള്ള മുടി വിടർത്തിയിട്ട ഒരു മൃഗത്തെ കണ്ടു. അവർ ചോദിച്ചു: നീ എന്താണ്? അത് പറഞ്ഞു: ഞാൻ ചാരനാണ്. അവർ പറഞ്ഞു: നീ ഞങ്ങൾക്ക് പറഞ്ഞുതരിക. അത് പറഞ്ഞു: ഞാൻ നിങ്ങളോട് പറയുന്നില്ല, ചോദിക്കുന്നുമില്ല. മറിച്ച് ഈ ഗ്രാമത്തിന്റെ അങ്ങേയറ്റത്ത് പോകുക. അവിടെ നിങ്ങളോട് ചോദിക്കുന്നവനും പറയുന്നവനുമുണ്ട്. അങ്ങനെ ഞങ്ങൾ അവിടെ പോയപ്പോൾ അവിടെ ചങ്ങല കൊണ്ട് ബന്ധിക്കപ്പെട്ട ഒരാളുണ്ടായിരുന്നു. അയാൾ പറഞ്ഞു: ''സുഗർ'' എന്ന സ്ഥലത്തെ അരുവിയെക്കുറിച്ച് എനിക്ക് പറഞ്ഞുതരിക. ഞങ്ങൾ പറഞ്ഞു: അത് നിറഞ്ഞ വെള്ളമുള്ളമുള്ളതും വെള്ളം നിറഞ്ഞൊലിക്കുന്നതുമാണ്. അയാൾ പറഞ്ഞു: തടാകത്തെക്കുറിച്ച് എനിക്ക് പറഞ്ഞുതരിക. അവർ പറഞ്ഞു: അത് നിറഞ്ഞ വെള്ളമുള്ളതും ശക്തിയായി വെള്ളം ചൊരിയുന്നതുമാണ്. അയാൾ പറഞ്ഞു: ഫലസ്തീനിന്റെയും ജോർദാന്റെയുമിടയിലുള്ള ബയ്സാൻ എന്ന സ്ഥലത്തെ ഈത്തപ്പനത്തോട്ടത്തെക്കുറിച്ച് എന്നോട് പറയുക. അത് ഫലം തരുന്നോ? ഞങ്ങൾ പറഞ്ഞു: അതെ. അയാൾ പറഞ്ഞു: പ്രവാചകനെക്കുറിച്ച് നിങ്ങൾ പറയുക. അദ്ദേഹം നിയോഗിതനായോ? ഞങ്ങൾ പറഞ്ഞു: അതെ. അയാൾ പറഞ്ഞു: ജനങ്ങൾ അദ്ദേഹത്തോട് എങ്ങനെയാണ് പെരുമാറുന്നത്? ഞങ്ങൾ പറഞ്ഞു: ജനങ്ങൾ അദ്ദേഹത്തിൽ വിശ്വസിക്കാനുള്ള ധൃതിയിലാണ്. അന്നേരമയാൾ ആ ബന്ധനത്തിൽ നിന്ന് രക്ഷപ്പെടാൻ വേണ്ടി ചാടി. ഞങ്ങൾ ചോദിച്ചു: എങ്കിൽ നീയേതാണ്? അയാൾ പറഞ്ഞു: ദജ്ജാലാകുന്നു. ദജ്ജാൽ എല്ലാ നാടുകളിലും പ്രവേശിക്കും. ''ത്വയ്ബ'' എന്ന സ്ഥലമല്ലാതെ. ത്വയ്ബ എന്നാൽ മദീനയാകുന്നു." (തു)', 'فَاطِمَةَ بِنْتِ قَيْسٍ', 'ഫാത്വിമത് ബിൻത് ഖൈസ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 760, 761, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 159, 'عَنْ فَاطِمَةَ بِنْتِ قَيْسٍ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: صَلَّى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ذَاتَ يَوْمٍ وَصَعِدَ الْمِنْبَرَ، وَكَانَ لَا يَصْعَدُ عَلَيْهِ قَبْلَ ذَلِكَ إِلَّا يَوْمَ الْجُمُعَةِ، فَاشْتَدَّ ذَلِكَ عَلَى النَّاسِ، فَمِنْ بَيْنِ قَائِمٍ وَجَالِسٍ، فَأَشَارَ إِلَيْهِمْ بِيَدِهِ أَنِ اقْعُدُوا: "فَإِنِّي – وَاللَّهِ – مَا قُمْتُ مَقَامِي هَذَا لِأَمْرٍ يَنْفَعُكُمْ، لِرَغْبَةٍ وَلَا لِرَهْبَةٍ. وَلَكِنَّ تَمِيمًا الدَّارِيَّ أَتَانِي فَأَخْبَرَنِي خَبَرًا مَنَعَنِي الْقَيْلُولَةَ، مِنَ الْفَرَحِ وَقُرَّةِ الْعَيْنِ، فَأَحْبَبْتُ أَنْ أَنْشُرَ عَلَيْكُمْ فَرَحَ نَبِيِّكُمْ. أَلَا إِنَّ ابْنَ عَمٍّ لِتَمِيمٍ الدَّارِيِّ أَخْبَرَنِي: أَنَّ الرِّيحَ أَلْجَأَتْهُمْ إِلَى جَزِيرَةٍ لَا يَعْرِفُونَهَا، فَقَعَدُوا فِي قَوَارِبِ السَّفِينَةِ فَخَرَجُوا فِيهَا، فَإِذَا هُمْ بِشَيْءٍ أَهْدَبَ أَسْوَدَ، قَالُوا لَهُ: مَا أَنْتَ؟ قَالَ: أَنَا الْجَسَّاسَةُ، قَالُوا: أَخْبِرِينَا، قَالَتْ: مَا أَنَا بِمُخْبِرَتِكُمْ شَيْئًا، وَلَا سَائِلَتِكُمْ. وَلَكِنْ هَذَا الدَّيْرُ، قَدْ رَمَقْتُمُوهُ، فَأْتُوهُ، فَإِنَّ فِيهِ رَجُلًا بِالْأَشْوَاقِ إِلَى أَنْ تُخْبِرُوهُ وَيُخْبِرَكُمْ. فَأَتَوْهُ فَدَخَلُوا عَلَيْهِ، فَإِذَا هُمْ بِشَيْخٍ مُوثَقٍ، شَدِيدِ الْوَثَاقِ، يُظْهِرُ الْحُزْنَ، شَدِيدِ التَّشَكِّي، فَقَالَ لَهُمْ: مِنْ أَيْنَ؟ قَالُوا: مِنَ الشَّامِ. قَالَ: مَا فَعَلَتِ الْعَرَبُ؟ قَالُوا: نَحْنُ قَوْمٌ مِنَ الْعَرَبِ، عَمَّ تَسْأَلُ؟ قَالَ: مَا فَعَلَ هَذَا الرَّجُلُ الَّذِي خَرَجَ فِيكُمْ؟ قَالُوا: خَيْرًا، نَاوَى قَوْمًا، فَأَظْهَرَهُ اللَّهُ عَلَيْهِمْ، فَأَمْرُهُمُ الْيَوْمَ جَمِيعٌ: إِلَهُهُمْ وَاحِدٌ، وَدِينُهُمْ وَاحِدٌ، قَالَ: مَا فَعَلَتْ عَيْنُ زُغَرَ؟ قَالُوا: خَيْرًا، يَسْقُونَ مِنْهَا زُرُوعَهُمْ، وَيَسْتَقُونَ مِنْهَا لِسَقْيِهِمْ. قَالَ: فَمَا فَعَلَ نَخْلٌ بَيْنَ عَمَّانَ وَبَيْسَانَ؟ قَالُوا: يُطْعِمُ ثَمَرَهُ كُلَّ عَامٍ. قَالَ: فَمَا فَعَلَتْ بُحَيْرَةُ الطَّبَرِيَّةِ؟ قَالُوا: تَدَفَّقُ جَنَبَاتُهَا مِنْ كَثْرَةِ الْمَاءِ. قَالَ: فَزَفَرَ ثَلَاثَ زَفَرَاتٍ، ثُمَّ قَالَ: لَوِ انْفَلَتُّ مِنْ وَثَاقِي هَذَا لَمْ أَدَعْ أَرْضًا إِلَّا وَطِئْتُهَا بِرِجْلَيَّ هَاتَيْنِ، إِلَّا طَيْبَةَ، لَيْسَ لِي عَلَيْهَا سَبِيلٌ". قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِلَى هَذَا يَنْتَهِي فَرَحِي، هَذِهِ طَيْبَةُ. وَالَّذِي نَفْسِي بِيَدِهِ، مَا فِيهَا طَرِيقٌ ضَيِّقٌ وَلَا وَاسِعٌ، وَلَا سَهْلٌ وَلَا جَبَلٌ، إِلَّا وَعَلَيْهِ مَلَكٌ شَاهِرٌ سَيْفَهُ إِلَى يَوْمِ الْقِيَامَةِ". (م,د,ت,جه)', 'ഫാത്വിമത് ബിൻത് ഖൈസ്(റ): ഒരു ദിവസം റസൂൽ(സ) നിസ്കരിക്കുകയും ശേഷം മിമ്പറിൽ കയറുകയും ചെയ്തു. അതിന് മുമ്പ് വെള്ളിയാഴ്ച ദിവസം മാത്രമേ അവിടുന്ന് മിമ്പറിൽ കയറാറുണ്ടായിരുന്നുള്ളു. അതുകൊണ്ട് ജനങ്ങൾക്ക് ഉൽക്കണ്ഠയുണ്ടായി. അവരിൽ നിൽക്കുന്നവരും ഇരിക്കുന്നവരുമുണ്ടായിരുന്നു. അവിടുന്ന് അവരോട് ഇരിക്കാൻ വേണ്ടി കൈ കൊണ്ട് ആംഗ്യം കാണിച്ചു. "അല്ലാഹുവാണ് സത്യം, ഞാൻ ഇവിടെ എഴുന്നേറ്റുനിന്നത് നിങ്ങൾക്ക് ഉപകാരമുള്ള ഒരു കാര്യത്തെക്കുറിച്ച് പറയാനോ, അല്ലെങ്കിൽ ആഗ്രഹിപ്പിക്കാനോ ഭയപ്പെടുത്താനോ അല്ല. മറിച്ച് തമീമുദ്ദാരി എന്റെയടുത്തുവന്ന് ഒരു വാർത്ത പറഞ്ഞു. അതിന്റെ കൺകുളിർമയും സന്തോഷവും കാരണം അത് എന്റെ പകലിലെ ഉറക്കം തടസ്സപ്പെടുത്തിയിരിക്കുന്നു. അതുകൊണ്ട് നിങ്ങളുടെ പ്രവാചകന്റെ സന്തോഷം നിങ്ങൾക്ക് മുമ്പിൽ പങ്കുവെക്കാൻ ഞാനാഗ്രഹിക്കുന്നു. അറിയുക, തമീമുദ്ദാരിയുടെ പിതൃവ്യപുത്രൻ എന്നോട് പറഞ്ഞു: കാറ്റ് അവരറിയാത്ത ഒരു ദ്വീപിലേക്ക് അവരെ കൊണ്ടെത്തിച്ചു. അവർ ചെറിയ ബോട്ടുകളിലിരുന്ന് ആ ദ്വീപിലേക്ക് പുറപ്പെട്ടു. അപ്പോൾ അവിടെ ഒരു കറുത്ത, ധാരാളം മുടിയുള്ള ഒരു വസ്തുവുണ്ടായിരുന്നു. അതിനോടവർ ചോദിച്ചു: നീ ഏതാണ്? അത് പറഞ്ഞു: ഞാൻ ഒരു ചാരനാണ്. അവർ പറഞ്ഞു: ഞങ്ങളോട് പറയുക. അത് പറഞ്ഞു: ഞാൻ നിങ്ങളോടൊന്നും പറയുന്നവനും ചോദിക്കുന്നവനുമല്ല. മറിച്ച് നിങ്ങൾ ഈ കാണുന്ന കോട്ടയിലേക്ക് പോകുക. അവിടെ ആഗ്രഹത്തോടെ നിങ്ങളോട് ചോദിക്കുന്നവനും പറയുന്നവനുമുണ്ട്. അങ്ങനെ അവർ അവിടെ ചെന്ന് അതിൽ പ്രവേശിച്ചു. ശക്തമായ പരാതികളുള്ള ദുഃഖിതനായ, നന്നായി ബന്ധിക്കപ്പെട്ട ഒരു വൃദ്ധനെ അവൻ അവിടെ കണ്ടു. അവരോടയാൾ ചോദിച്ചു: നിങ്ങളെവിടെ നിന്നാണ്? അവർ പറഞ്ഞു: ശാമിൽ നിന്ന്. അയാൾ ചോദിച്ചു: അറബികൾ എന്തുചെയ്തു? അവർ പറഞ്ഞു: ഞങ്ങൾ അറബികളാണ്. എന്തിനെക്കുറിച്ചാണ് താങ്കൾ ചോദിക്കുന്നത്? അയാൾ ചോദിച്ചു: നിങ്ങളിലേക്ക് വന്ന ആ മനുഷ്യൻ എന്താണ് ചെയ്യുന്നത്? അവർ പറഞ്ഞു: സൽപ്രവർത്തനം, സമുദായത്തിന്റെ ആവശ്യങ്ങൾ അദ്ദേഹം നിറവേറ്റുന്നു. അപ്പോൾ അല്ലാഹു അദ്ദേഹത്തിന് അവരുടെ മേൽ വിജയം നൽകി. ഇപ്പോൾ ജനങ്ങളെല്ലാം ഒരേ അവസ്ഥയിലാണ്: അവരുടെ ആരാധ്യൻ ഒന്നുമാത്രമാണ്. അവരുടെ മതവും ഒന്നുമാത്രമാണ്. അയാൾ ചോദിച്ചു: ''സുഗർ'' എന്ന സ്ഥലത്തെ അരുവിയെക്കുറിച്ച് എന്താണ് പറയുന്നത്? അവർ പറഞ്ഞു: നല്ലത്, ജനങ്ങൾ അതിൽനിന്ന് കൃഷി നനക്കുകയും കുടിക്കാനുപയോഗിക്കുകയും ചെയ്യുന്നു. അയാൾ ചോദിച്ചു: ഒമാനിന്റെയും ബയ്സാന്റെയും ഇടയിലുള്ള ഈത്തപ്പനയെക്കുറിച്ച് എന്താണ് പറയുന്നത്? അവർ പറഞ്ഞു: എല്ലാ വർഷവും അത് ഫലം നൽകുന്നു. അയാൾ ചോദിച്ചു: ത്വബ്രിയയിലെ ചെറിയ തടാകം എങ്ങനെയുണ്ട്? അവർ പറഞ്ഞു: വെള്ളം അധികരിച്ചത് കാരണം അത് നിറഞ്ഞൊലിക്കുന്നു. അപ്പോൾ അയാൾ മൂന്ന് പ്രാവശ്യം ദീർഘശ്വാസം വലിച്ചു. ശേഷം  പറഞ്ഞു: ഞാൻ ഈ കെട്ടിൽ നിന്ന് മോചിതനായാൽ ഒരു ഭൂമിയും എന്റെ ഈ കാലുകൾ കൊണ്ട് ചവിട്ടാതെ ഒഴിവാക്കുകയില്ല, ത്വയ്ബയൊഴികെ. അതിലെത്താൻ എനിക്കൊരു മാർഗവുമില്ല." നബി(സ) പറയുന്നു: "എന്റെ സന്തോഷം ഇതാണ്, ഇത് ത്വയ്ബ(മദീന)യാണ്. എന്റെ ശരീരം ആരുടെ കയ്യിലാണോ അവൻ തന്നെ സത്യം, അതിൽ കുടുസ്സായതോ വിശാലമായതോ ആയ ഒരു വഴിയും ഇല്ല, നിരപ്പായ സ്ഥലമോ മലകളോ ഇല്ല, അവിടെയെല്ലാം ഊരിപ്പിടിച്ച വാളുമായി നിൽക്കുന്ന ഒരു മാലാഖ അന്ത്യനാൾ വരെ ഉണ്ടായിട്ടല്ലാതെ." (മു,ദ,തു,ജ)', 'فَاطِمَةَ بِنْتِ قَيْسٍ', 'ഫാത്വിമത് ബിൻത് ഖൈസ്(റ)', null, null, array['م','د','ت','جه']::text[], array['മു','ദ','തു','ജ']::text[], null, null, 761, 762, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 160, 'عَنْ فَاطِمَةَ بِنْتِ قَيْسٍ رَضِيَ اللَّهُ عَنْهَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَخَّرَ الْعِشَاءَ الْآخِرَةَ ذَاتَ لَيْلَةٍ، ثُمَّ خَرَجَ فَقَالَ: "إِنَّهُ حَبَسَنِي حَدِيثٌ كَانَ يُحَدِّثُنِيهِ تَمِيمٌ الدَّارِيُّ عَنْ رَجُلٍ كَانَ فِي جَزِيرَةٍ مِنْ جَزَائِرِ الْبَحْرِ: فَإِذَا أَنَا بِامْرَأَةٍ تَجُرُّ شَعْرَهَا، قَالَ: مَا أَنْتِ؟ قَالَتْ: أَنَا الْجَسَّاسَةُ، اذْهَبْ إِلَى ذَلِكَ الْقَصْرِ. فَأَتَيْتُهُ، فَإِذَا رَجُلٌ يَجُرُّ شَعْرَهُ مُسَلْسَلٌ فِي الْأَغْلَالِ، يَنْزُو فِيمَا بَيْنَ السَّمَاءِ وَالْأَرْضِ، فَقُلْتُ: مَنْ أَنْتَ؟ قَالَ: أَنَا الدَّجَّالُ، خَرَجَ نَبِيُّ الْأُمِّيِّينَ بَعْدُ؟ قُلْتُ: نَعَمْ، قَالَ: أَطَاعُوهُ أَمْ عَصَوْهُ؟ قُلْتُ: بَلْ أَطَاعُوهُ، قَالَ: ذَاكَ خَيْرٌ لَهُمْ". (د)', 'ഫാത്വിമതു ബിൻത് ഖൈസ്(റ): റസൂൽ(സ) ഒരു രാത്രി ഇശാഅ് പിന്തിച്ച് നിസ്കരിച്ചു. പിന്നെ പുറത്തുവന്ന് പറഞ്ഞു: "കടലിലെ ഒരു ദ്വീപിലുണ്ടായിരുന്ന ഒരാളെക്കുറിച്ച് തമീമുദ്ദാരി പറഞ്ഞ സംഭവമാണ് എന്നെ തടഞ്ഞുവെച്ചത്. തമീം പറയുന്നു: അങ്ങനെ ഞാൻ, മുടി വലിച്ചുകൊണ്ടിരിക്കുന്ന ഒരു സ്ത്രീയുടെ മുമ്പിലെത്തി. നീ എന്താണെന്ന് അവളോട് ചോദിച്ചു. അവൾ പറഞ്ഞു: ഞാൻ ചാരവനിതയാണ്. താങ്കൾ ആ കോട്ടയിലേക്ക് പോകുക. ഞാൻ അവിടെ ചെന്നു. അപ്പോൾ ചങ്ങലയാൽ ബന്ധിക്കപ്പെട്ട തന്റെ മുടി വലിച്ചുകൊണ്ടിരിക്കുന്ന ഒരാൾ അവിടെ ഉണ്ടായിരുന്നു. അവൻ ആകാശത്തേക്കും ഭൂമിയിലേക്കും ചാടുന്നു. ഞാൻ ചോദിച്ചു: നീ ആരാണ്? അവൻ പറഞ്ഞു: ഞാൻ ദജ്ജാലാണ്. നിരക്ഷകരുടെ പ്രവാചകൻ വന്നിട്ടുണ്ടോ? ഞാൻ പറഞ്ഞു: അതെ. അദ്ദേഹം ചോദിച്ചു: ജനങ്ങൾ അദ്ദേഹത്തെ അംഗീകരിക്കുന്നോ അതോ എതിർക്കുന്നോ? ഞാൻ പറഞ്ഞു: അംഗീകരിക്കുന്നു. അവൻ പറഞ്ഞു: അതാണവർക്കുത്തമം. (ദ)', 'فَاطِمَةَ بِنْتِ قَيْسٍ', 'ഫാത്വിമതു ബിൻത് ഖൈസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 763, 763, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 161, 'عَنْ فَاطِمَةَ بِنْتِ قَيْسٍ رَضِيَ اللَّهُ عَنْهَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَلَّى الظُّهْرَ ثُمَّ صَعِدَ الْمِنْبَرَ، وَكَانَ لَا يَصْعَدُ عَلَيْهِ إِلَّا يَوْمَ جُمُعَةٍ قَبْلَ يَوْمِئِذٍ، ثُمَّ ذَكَرَ هَذِهِ الْقِصَّةَ. (د,ت,ن,جه)', 'ഫാത്വിമത് ബിൻത് ഖൈസ്(റ): നബി(സ) ളുഹ്ർ നിസ്കരിച്ച് മിമ്പറിൽ കയറി. അതിനുമുമ്പ് വെള്ളിയാഴ്ചയല്ലാതെ അവിടുന്ന് മിമ്പറിൽ കയറാറില്ലായിരുന്നു. ശേഷം ഈ സംഭവം പറയുകയും ചെയ്തു. (ദ,തു,ന,ജ)', 'فَاطِمَةَ بِنْتِ قَيْسٍ', 'ഫാത്വിമത് ബിൻത് ഖൈസ്(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 763, 763, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 162, 'عَنْ أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ، عَنْ جَابِرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ذَاتَ يَوْمٍ عَلَى الْمِنْبَرِ: "إِنَّهُ بَيْنَمَا أُنَاسٌ يَسِيرُونَ فِي الْبَحْرِ فَنَفِدَ طَعَامُهُمْ، فَرُفِعَتْ لَهُمْ جَزِيرَةٌ، فَخَرَجُوا يُرِيدُونَ الْخَبَرَ، فَلَقِيَتْهُمُ الْجَسَّاسَةُ". قُلْتُ لِأَبِي سَلَمَةَ: وَمَا الْجَسَّاسَةُ؟ قَالَ: امْرَأَةٌ تَجُرُّ شَعْرَ جِلْدِهَا وَرَأْسِهَا، "قَالَتْ: فِي هَذَا الْقَصْرِ". فَذَكَرَ الْحَدِيثَ، وَسَأَلَ عَنْ نَخْلِ بَيْسَانَ، وَعَنْ عَيْنِ زُغَرَ، قَالَ: هُوَ الْمَسِيحُ، فَقَالَ لِي ابْنُ أَبِي سَلَمَةَ: إِنَّ فِي هَذَا الْحَدِيثِ شَيْئًا مَا حَفِظْتُهُ، قَالَ: شَهِدَ جَابِرٌ أَنَّهُ هُوَ ابْنُ صَيَّادٍ، قُلْتُ: فَإِنَّهُ قَدْ مَاتَ، قَالَ: وَإِنْ مَاتَ، قُلْتُ: فَإِنَّهُ أَسْلَمَ، قَالَ: وَإِنْ أَسْلَمَ، قُلْتُ: فَإِنَّهُ قَدْ دَخَلَ الْمَدِينَةَ، قَالَ: وَإِنْ دَخَلَ الْمَدِينَةَ. (د)', 'ജാബിർ(റ)വിൽ നിന്ന് അബൂസമലതുബ്നി അബ്ദിർറഹ്മാൻ(റ): റസൂൽ(സ) ഒരു ദിവസം മിമ്പറിൽ കയറി പറഞ്ഞു: "കുറച്ചാളുകൾ കടലിലൂടെ യാത്രചെയ്യുകയായിരുന്നു. അങ്ങനെ അവരുടെ ഭക്ഷണം തീർന്നു. അവർ ഒരു ദ്വീപ് കണ്ടു. വിവരങ്ങളറിയുവാൻ വേണ്ടി അവർ ദ്വീപിലേക്ക് പോയി. അപ്പോൾ അവർ ഒരു ചാരവനിതയെ കണ്ടു." ഞാൻ അബൂസലമ(റ)വിനോട് ചോദിച്ചു: എന്താണ് ജസ്സാസ? അദ്ദേഹം പറഞ്ഞു: തന്റെ ചർമ്മത്തിലെയും തലയിലെയും മുടി നിലത്തിട്ട് വലിക്കുന്ന ഒരു സ്ത്രീയാണത്. "ആ സ്ത്രീ പറഞ്ഞു: ഈ കോട്ടയിലുണ്ട്." പിന്നെ സംഭവം പറഞ്ഞു: അയാൾ ബൈസാനിലെ ഈത്തപ്പനത്തോട്ടത്തെക്കുറിച്ചും സുഗറിലെ അരുവിയെക്കുറിച്ചും ചോദിച്ചു. അദ്ദേഹം പറഞ്ഞു: അവൻ ചുറ്റിസഞ്ചരിക്കുന്നവൻ (ദജ്ജാൽ) ആണ്. അപ്പോൾ ഇബ്നുഅബീസലമ(റ) എന്നോട് പറഞ്ഞു: ഈ ഹദീസിൽ ഞാൻ മനഃപ്പാഠമാക്കിയിട്ടില്ലാത്ത ഒരു കാര്യമുണ്ട്. അദ്ദേഹം പറഞ്ഞു: ഇബ്നുസ്സ്വയ്യാദാണതെന്ന് ജാബിർ(റ) ഉറപ്പിച്ചുപറഞ്ഞു. ഞാൻ ചോദിച്ചു: അവൻ മരിച്ചിട്ടുണ്ടല്ലോ. അദ്ദേഹം പറഞ്ഞു: അവൻ മരിച്ചിട്ടുണ്ടെങ്കിലും. ഞാൻ ചോദിച്ചു: അവൻ മുസ്ലിമായിട്ടുണ്ടല്ലോ. അദ്ദേഹം പറഞ്ഞു: അവൻ മുസ്ലിമായിട്ടുണ്ടെങ്കിലും. ഞാൻ ചോദിച്ചു: അവൻ മദീനയിൽ പ്രവേശിച്ചിട്ടുണ്ടല്ലോ. അദ്ദേഹം പറഞ്ഞു: അവൻ മദീനയിൽ പ്രവേശിച്ചിട്ടുണ്ടെങ്കിലും. (ദ)', 'أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ، عَنْ جَابِرٍ', 'ജാബിർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 763, 764, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 163, 'عَنْ حُذَيْفَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَأَنَا أَعْلَمُ بِمَا مَعَ الدَّجَّالِ مِنْهُ، مَعَهُ نَهْرَانِ يَجْرِيَانِ: أَحَدُهُمَا رَأْيَ الْعَيْنِ مَاءٌ أَبْيَضُ، وَالْآخَرُ رَأْيَ الْعَيْنِ نَارٌ تَأَجَّجُ، فَإِمَّا أَدْرَكَهُ أَحَدٌ فَلْيَأْتِ النَّهْرَ الَّذِي يَرَاهُ نَارًا، وَلْيُغَمِّضْ ثُمَّ لْيُطَأْطِئْ رَأْسَهُ فَيَشْرَبَ [مِنْهُ] فَإِنَّهُ مَاءٌ بَارِدٌ. وَإِنَّ الدَّجَّالَ مَمْسُوحُ الْعَيْنِ، عَلَيْهَا ظَفَرَةٌ غَلِيظَةٌ، مَكْتُوبٌ بَيْنَ عَيْنَيْهِ كَافِرٌ، يَقْرَؤُهُ كُلُّ مُؤْمِنٍ، كَاتِبٍ وَغَيْرِ كَاتِبٍ". (م)', 'ഹുദൈഫ(റ): റസൂൽ(സ) പറഞ്ഞു: "ദജ്ജാലിന്റെയടുത്തുള്ളതിനെക്കുറിച്ച് അവനേക്കാൾ അറിയുന്നവനാണ് ഞാൻ. അവന്റെയടുത്ത് ഒഴുകുന്ന രണ്ട് നദികളുണ്ട്. അതിൽ ഒന്ന് ഒറ്റനോട്ടത്തിൽ ശുദ്ധമായ വെള്ളവും മറ്റൊന്ന് ഒറ്റനോട്ടത്തിൽ തിളങ്ങുന്ന തീയുമായിരിക്കും. ആരെങ്കിലും അവനെ കണ്ടാൽ തീയായി കാണുന്ന നദിയിൽ ചെല്ലട്ടെ. ശേഷം കണ്ണടച്ച് തലതാഴ്ത്തി അതിൽ നിന്ന് കുടിക്കട്ടെ. കാരണം അത് തണുത്ത വെള്ളമായിരിക്കും. നിശ്ചയം ദജ്ജാൽ കണ്ണ് മായ്ക്കപ്പെട്ടവനാണ്. ആ കണ്ണിന്മേൽ കട്ടിയുള്ള കൺപോളയുണ്ടായിരിക്കും. രണ്ട് കണ്ണിന്റെയുമിടയിൽ ''കാഫിർ'' എന്നെഴുതപ്പെട്ടിരിക്കും. അത് എല്ലാ സത്യവിശ്വാസിയും വായിക്കും, എഴുത്തറിയുന്നവനായാലും അല്ലെങ്കിലും." (മു)', 'حُذَيْفَةَ', 'ഹുദൈഫ(റ)', null, null, array['م']::text[], array['മു']::text[], 'مِنْهُ', null, 764, 764, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 164, 'عَنْ حُذَيْفَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "الدَّجَّالُ أَعْوَرُ الْعَيْنِ الْيُسْرَى، جُفَالُ الشَّعَرِ، مَعَهُ جَنَّةٌ وَنَارٌ، فَنَارُهُ جَنَّةٌ وَجَنَّتُهُ نَارٌ". (م,جه)', 'ഹുദൈഫ(റ): റസൂൽ(സ) പറഞ്ഞു: "ദജ്ജാൽ ഇടത് കണ്ണു പൊട്ടിയവനും ധാരാളം മുടിയുള്ളവനുമാകുന്നു. അവന്റെ കൂടെ സ്വർഗവും നരകവുമുണ്ട്. പക്ഷേ, അവന്റെ നരകം സ്വർഗവും സ്വർഗം നരകവുമാണ്." (മു,ജ)', 'حُذَيْفَةَ', 'ഹുദൈഫ(റ)', null, null, array['م','جه']::text[], array['മു','ജ']::text[], null, null, 764, 764, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 165, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: حَدَّثَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمًا حَدِيثًا طَوِيلًا عَنِ الدَّجَّالِ، فَكَانَ فِيمَا حَدَّثَنَا قَالَ: "يَأْتِي – وَهُوَ مُحَرَّمٌ عَلَيْهِ أَنْ يَدْخُلَ نِقَابَ الْمَدِينَةِ – فَيَنْتَهِي إِلَى بَعْضِ السِّبَاخِ الَّتِي تَلِي الْمَدِينَةَ، فَيَخْرُجُ إِلَيْهِ يَوْمَئِذٍ رَجُلٌ هُوَ خَيْرُ النَّاسِ – أَوْ: مِنْ خَيْرِ النَّاسِ – فَيَقُولُ لَهُ: أَشْهَدُ أَنَّكَ الدَّجَّالُ الَّذِي حَدَّثَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَدِيثَهُ، فَيَقُولُ الدَّجَّالُ: أَرَأَيْتُمْ إِنْ قَتَلْتُ هَذَا ثُمَّ أَحْيَيْتُهُ، أَتَشُكُّونَ فِي الْأَمْرِ؟ فَيَقُولُونَ: لَا، قَالَ: فَيَقْتُلُهُ ثُمَّ يُحْيِيهِ، فَيَقُولُ حِينَ يُحْيِيهِ: وَاللَّهِ مَا كُنْتُ فِيكَ قَطُّ أَشَدَّ بَصِيرَةً مِنِّي الْآنَ، قَالَ: فَيُرِيدُ الدَّجَّالُ أَنْ يَقْتُلَهُ فَلَا يُسَلَّطُ عَلَيْهِ". قَالَ أَبُو إِسْحَقَ: يُقَالُ: إِنَّ هَذَا الرَّجُلَ هُوَ الْخَضِرُ عَلَيْهِ السَّلَامُ. (م)', 'അബൂസഇൗദിൽ ഖുദ്രി(റ): ഒരു ദിവസം ദജ്ജാലിനെക്കുറിച്ച് റസൂൽ(സ) ധാരാളമായി പറഞ്ഞു. കൂട്ടത്തിൽ ഇങ്ങനെ പറഞ്ഞു: "അവൻ വരും - മദീനയിലേക്കുള്ള പ്രവേശന സ്ഥലങ്ങളിൽ പ്രവേശിക്കൽ അവന് നിഷിദ്ധമാക്കപ്പെട്ടിരിക്കും - അങ്ങനെ മദീനക്കടുത്തുള്ള സസ്യങ്ങൾ മുളക്കാത്ത ഒരു സ്ഥലത്ത് വരെയെത്തും. അപ്പോൾ ജനങ്ങളിൽ വെച്ച് ഏറ്റവും നല്ല - അല്ലെങ്കിൽ: ജനങ്ങളിലെ നല്ലവരിൽപ്പെട്ട മനുഷ്യൻ അവന്റെയടുത്ത് ചെന്ന് പറയും: റസൂൽ(സ) ഞങ്ങളോട് പറഞ്ഞുതന്നിട്ടുള്ള ദജ്ജാലാണ് നീ എന്ന് ഞാൻ സാക്ഷ്യംവഹിക്കുന്നു. അപ്പോൾ ദജ്ജാൽ പറയും: ഞാൻ ഇവനെ വധിച്ചതിന് ശേഷം ജീവിപ്പിച്ചാൽ എന്റെ കാര്യത്തിൽ നിങ്ങൾ സംശയിക്കുമോ? അവർ പറയും: ഇല്ല. അപ്പോൾ അവൻ അയാളെ കൊല്ലുകയും പിന്നെ ജീവിപ്പിക്കുകയും ചെയ്യും. അവൻ ജീവിപ്പിക്കുമ്പോൾ അവനോട് ഇയാൾ പറയും: ഇപ്പോൾ നിന്റെ വിഷയത്തിൽ ഞാൻ കൂടുതൽ ഉൾക്കാഴ്ചയുള്ളവനായി. നബി(സ) പറഞ്ഞു: "അപ്പോൾ ദജ്ജാൽ അയാളെ കൊല്ലാൻ ശ്രമിക്കും. പക്ഷേ, അയാളുടെ മേൽ ഒരു ആധിപത്യവും ദജ്ജാലിനുണ്ടാവുകയില്ല." അബൂഇസ്ഹാഖ്(റ) പറയുന്നു: ഈ മനുഷ്യൻ ഖിള്ർ(അ) ആകുന്നു. (മു)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഇൗദിൽ ഖുദ്രി(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 764, 764, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 166, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "يَخْرُجُ الدَّجَّالُ، فَيَتَوَجَّهُ قِبَلَهُ رَجُلٌ مِنَ الْمُؤْمِنِينَ، فَتَلْقَاهُ الْمَسَالِحُ مَسَالِحُ الدَّجَّالِ، فَيَقُولُونَ لَهُ: أَيْنَ تَعْمِدُ؟ فَيَقُولُ: أَعْمِدُ إِلَى هَذَا الَّذِي خَرَجَ، قَالَ: فَيَقُولُونَ لَهُ: أَوَ مَا تُؤْمِنُ بِرَبِّنَا؟ فَيَقُولُ: مَا بِرَبِّنَا خَفَاءٌ، فَيَقُولُونَ: اقْتُلُوهُ، فَيَقُولُ بَعْضُهُمْ لِبَعْضٍ: أَلَيْسَ قَدْ نَهَاكُمْ رَبُّكُمْ أَنْ تَقْتُلُوا أَحَدًا دُونَهُ؟ قَالَ: فَيَنْطَلِقُونَ بِهِ إِلَى الدَّجَّالِ، فَإِذَا رَآهُ الْمُؤْمِنُ قَالَ: يَا أَيُّهَا النَّاسُ هَذَا الدَّجَّالُ الَّذِي ذَكَرَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. قَالَ: فَيَأْمُرُ الدَّجَّالُ بِهِ فَيُشَبَّحُ، فَيَقُولُ: خُذُوهُ وَشُجُّوهُ، فَيُوسَعُ ظَهْرُهُ وَبَطْنُهُ ضَرْبًا، قَالَ: فَيَقُولُ: أَوَ مَا تُؤْمِنُ بِي؟ قَالَ: فَيَقُولُ: أَنْتَ الْمَسِيحُ الْكَذَّابُ، قَالَ: فَيُؤْمَرُ بِهِ فَيُؤْشَرُ بِالْمِنْشَارِ، مِنْ مَفْرِقِهِ حَتَّى يُفَرَّقَ بَيْنَ رِجْلَيْهِ، قَالَ: ثُمَّ يَمْشِي الدَّجَّالُ بَيْنَ الْقِطْعَتَيْنِ، ثُمَّ يَقُولُ لَهُ: قُمْ، فَيَسْتَوِي قَائِمًا، قَالَ: ثُمَّ يَقُولُ لَهُ: أَتُؤْمِنُ بِي؟ فَيَقُولُ: مَا ازْدَدْتُ فِيكَ إِلَّا بَصِيرَةً، قَالَ: ثُمَّ يَقُولُ: يَا أَيُّهَا النَّاسُ، إِنَّهُ لَا يَفْعَلُ بَعْدِي بِأَحَدٍ مِنَ النَّاسِ، قَالَ: فَيَأْخُذُهُ الدَّجَّالُ لِيَذْبَحَهُ، فَيُجْعَلَ مَا بَيْنَ رَقَبَتِهِ إِلَى تَرْقُوَتِهِ نُحَاسًا، فَلَا يَسْتَطِيعُ إِلَيْهِ سَبِيلًا، قَالَ: فَيَأْخُذُ بِيَدَيْهِ وَرِجْلَيْهِ فَيَقْذِفُ بِهِ، فَيَحْسِبُ النَّاسُ أَنَّمَا قَذَفَهُ إِلَى النَّارِ، وَإِنَّمَا أُلْقِيَ فِي الْجَنَّةِ". فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "هَذَا أَعْظَمُ النَّاسِ شَهَادَةً عِنْدَ رَبِّ الْعَالَمِينَ". (م)', 'അബൂസഇൗദിൽ ഖുദ്‌രി(റ): റസൂൽ(സ) പറഞ്ഞു: "ദജ്ജാൽ പുറപ്പെടുമ്പോൾ മുഅ്മിനീങ്ങളിൽ പെട്ട ഒരാൾ അവന്റെയടുത്ത് വരും. അപ്പോൾ ദജ്ജാലിന്റെ സായുധ സംഘം അദ്ദേഹത്തെ നേരിടും. അവർ ചോദിക്കും: താങ്കൾ എവിടേക്കാണ്? അദ്ദേഹം പറയും: ഇപ്പോൾ പുറത്തുവന്ന ആ മനുഷ്യന്റെയടുത്തേക്കാണ്. അപ്പോൾ അവർ ചോദിക്കും: ഞങ്ങളുടെ നാഥനിൽ താങ്കൾ വിശ്വസിക്കുന്നില്ലേ? അദ്ദേഹം പറയും: നമ്മുടെ നാഥന് ഒരു അവ്യക്തതയുമില്ല. അവർ പറയും: നിങ്ങളവനെ കൊല്ലുക. അപ്പോൾ അവരിൽ ചിലർ പരസ്പരം പറയും: താനല്ലാതെ ആരെങ്കിലും ഒരാളെ വധിക്കുന്നത് നിങ്ങളുടെ നാഥൻ നിങ്ങൾക്ക് നിരോധിച്ചിട്ടില്ലേ?" റസൂൽ(സ) പറയുന്നു: "അപ്പോൾ അദ്ദേഹവുമായി അവർ ദജ്ജാലിന്റെയടുത്ത് പോകും. അങ്ങനെ ദജ്ജാലിനെ കാണുമ്പോൾ മുഅ്മിൻ പറയും: ജനങ്ങളേ, ഇതാണ് റസൂൽ(സ) പറഞ്ഞ ദജ്ജാൽ." നബി(സ) പറയുന്നു: "അപ്പോൾ അദ്ദേഹത്തെ നീട്ടിക്കിടത്താൻ ദജ്ജാൽ കൽപിക്കും. എന്നിട്ട് പറയും: അവനെ പിടിച്ച് തല പുറത്തെടുക്കുക. അങ്ങനെ അദ്ദേഹത്തിന്റെ മുതുകും വയറും മുറിക്കാൻ പാകത്തിന് കിടത്തപ്പെടും. എന്നിട്ട് ദജ്ജാൽ ചോദിക്കും: നീ എന്നിൽ വിശ്വസിക്കുന്നില്ലെയോ? അദ്ദേഹം പറയും: നീ നുണയനായ മസീഹ് (ചുറ്റിസഞ്ചരിക്കുന്നവൻ) ആണ്. അപ്പോൾ ദജ്ജാൽ കൽപിച്ചതനുസരിച്ച് അദ്ദേഹത്തിന്റെ മൂർദ്ധാവ് മുതൽ കാലുകൾ വരെ ഒരു ഇൗർച്ചവാൾ കൊണ്ട് ഇൗർന്ന് മുറിക്കപ്പെടും." അവിടുന്ന് പറയുന്നു: "പിന്നെ ആ രണ്ട് കഷ്ണങ്ങൾക്കിടയിലൂടെ ദജ്ജാൽ നടക്കും. പിന്നെ അദ്ദേഹത്തോട് പറയും: എണീക്കുക. അപ്പോഴദ്ദേഹം നേരെ എഴുന്നേറ്റ് നിൽക്കും." തിരുമേനി(സ) പറയുന്നു: "പിന്നെ അവൻ അദ്ദേഹത്തോട് ചോദിക്കും: നീ എന്നിൽ വിശ്വസിക്കുമോ? അദ്ദേഹം പറയും: നിന്റെ വിഷയത്തിൽ എനിക്കുള്ള ഉൾക്കാഴ്ച വർധിച്ചിട്ടേയുള്ളൂ." തിരുമേനി(സ) പറയുന്നു: "പിന്നെ അദ്ദേഹം പറയും: ജനങ്ങളേ, എന്റെ ശേഷം ആരോടും അവൻ ഇങ്ങനെ കാട്ടുകയില്ല." തിരുമേനി(സ) പറയുന്നു: "അപ്പോൾ ദജ്ജാൽ അദ്ദേഹത്തെ കൊല്ലാൻ വേണ്ടി പിടിക്കുകയും അദ്ദേഹത്തിന്റെ ചുമലെല്ല് മുതൽ താടിയെല്ല് വരെയുള്ള ഭാഗത്ത് ചെമ്പ് വെക്കപ്പെടുകയും ചെയ്യും. അപ്പോൾ അവന് അദ്ദേഹത്തെ ഒന്നും ചെയ്യാൻ കഴിയുകയില്ല. ഉടനെ അദ്ദേഹത്തിന്റെ രണ്ട് കയ്യും കാലും പിടിച്ച് അവനെറിയും. നരകത്തിലേക്കാണ് അവൻ അദ്ദേഹത്തെ എറിഞ്ഞതെന്നാണ് ജനങ്ങൾ വിചാരിക്കുക. പക്ഷേ, സ്വർഗത്തിലേക്കാണ് അദ്ദേഹം എറിയപ്പെട്ടിട്ടുണ്ടാവുക." റസൂൽ(സ) പറഞ്ഞു: "ഇദ്ദേഹമാണ് രക്ഷിതാവിന്റെയടുക്കൽ ഏറ്റവും വലിയ രക്തസാക്ഷി." (മു)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഇൗദിൽ ഖുദ്‌രി(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 765, 765, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 167, 'عَنِ الْمُغِيرَةِ بْنِ شُعْبَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: مَا سَأَلَ أَحَدٌ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الدَّجَّالِ أَكْثَرَ مِمَّا سَأَلْتُ، قَالَ: "وَمَا يُنْصِبُكَ مِنْهُ؟ إِنَّهُ لَا يَضُرُّكَ". قَالَ: قُلْتُ: يَا رَسُولَ اللَّهِ، إِنَّهُمْ يَقُولُونَ إِنَّ مَعَهُ الطَّعَامَ وَالْأَنْهَارَ؟ قَالَ: "هُوَ أَهْوَنُ عَلَى اللَّهِ مِنْ ذَلِكَ". (ق,جه)', 'മുഗീറതുബ്നു ശുഅ്ബ(റ): റസൂൽ(സ)യോട് ദജ്ജാലിനെക്കുറിച്ച് ഞാൻ ചോദിച്ചതിനേക്കാൾ കൂടുതലായി ആരും ചോദിച്ചിട്ടില്ല. അവിടുന്ന് ചോദിച്ചു: "അവനിൽ നിന്ന് താങ്കൾക്കെന്താണ് ബുദ്ധിമുട്ട്? കാരണം അവൻ താങ്കളെ ബുദ്ധിമുട്ടാക്കുകയില്ലല്ലോ?" മുഗീറ(റ) പറയുന്നു: ഞാൻ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, അവന്റെ പക്കൽ ഭക്ഷണവും നദികളുമുണ്ടെന്ന് ജനങ്ങൾ പറയുന്നു? അവിടുന്ന് പറഞ്ഞു: "അവൻ അല്ലാഹുവിങ്കൽ അതിനേക്കാൾ നിസ്സാരമാണ്." (ബു,മു,ജ)', 'الْمُغِيرَةِ بْنِ شُعْبَةَ', 'മുഗീറതുബ്നു ശുഅ്ബ(റ)', null, null, array['ق','جه']::text[], array['ബു','മു','ജ']::text[], null, null, 766, 766, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 168, 'عَنِ النُّعْمَانِ بْنِ سَالِمٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ يَعْقُوبَ بْنَ عَاصِمِ بْنِ عُرْوَةَ بْنِ مَسْعُودٍ الثَّقَفِيَّ يَقُولُ: سَمِعْتُ عَبْدَ اللَّهِ بْنَ عَمْرٍو، وَجَاءَهُ رَجُلٌ فَقَالَ: مَا هَذَا الْحَدِيثُ الَّذِي تُحَدِّثُ بِهِ؟ تَقُولُ: إِنَّ السَّاعَةَ تَقُومُ إِلَى كَذَا وَكَذَا؟ فَقَالَ: سُبْحَانَ اللَّهِ – أَوْ: لَا إِلَهَ إِلَّا اللَّهُ، أَوْ كَلِمَةً نَحْوَهُمَا – لَقَدْ هَمَمْتُ أَنْ لَا أُحَدِّثَ أَحَدًا شَيْئًا أَبَدًا، إِنَّمَا قُلْتُ: إِنَّكُمْ سَتَرَوْنَ بَعْدَ قَلِيلٍ أَمْرًا عَظِيمًا: يُحَرَّقُ الْبَيْتُ، وَيَكُونُ وَيَكُونُ، ثُمَّ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "يَخْرُجُ الدَّجَّالُ فِي أُمَّتِي فَيَمْكُثُ أَرْبَعِينَ – لَا أَدْرِي أَرْبَعِينَ يَوْمًا أَوْ أَرْبَعِينَ شَهْرًا، أَوْ أَرْبَعِينَ عَامًا – فَيَبْعَثُ اللَّهُ عِيسَى بْنَ مَرْيَمَ، كَأَنَّهُ عُرْوَةُ بْنُ مَسْعُودٍ، فَيَطْلُبُهُ فَيُهْلِكُهُ، ثُمَّ يَمْكُثُ النَّاسُ سَبْعَ سِنِينَ، لَيْسَ بَيْنَ اثْنَيْنِ عَدَاوَةٌ، ثُمَّ يُرْسِلُ اللَّهُ عَزَّ وَجَلَّ رِيحًا بَارِدَةً مِنْ قِبَلِ الشَّامِ، فَلَا يَبْقَى عَلَى وَجْهِ الْأَرْضِ أَحَدٌ فِي قَلْبِهِ مِثْقَالُ ذَرَّةٍ مِنْ خَيْرٍ أَوْ إِيمَانٍ إِلَّا قَبَضَتْهُ، حَتَّى لَوْ أَنَّ أَحَدَكُمْ دَخَلَ فِي كَبِدِ جَبَلٍ لَدَخَلَتْهُ عَلَيْهِ حَتَّى تَقْبِضَهُ". قَالَ: سَمِعْتُهَا مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَ: "فَيَبْقَى شِرَارُ النَّاسِ فِي خِفَّةِ الطَّيْرِ وَأَحْلَامِ السِّبَاعِ، لَا يَعْرِفُونَ مَعْرُوفًا وَلَا يُنْكِرُونَ مُنْكَرًا، فَيَتَمَثَّلُ لَهُمُ الشَّيْطَانُ فَيَقُولُ: أَلَا تَسْتَحْيُونَ؟ فَيَقُولُونَ: فَمَا تَأْمُرُنَا؟ فَيَأْمُرُهُمْ بِعِبَادَةِ الْأَوْثَانِ، وَهُمْ فِي ذَلِكَ دَارٌّ رِزْقُهُمْ حَسَنٌ عَيْشُهُمْ، ثُمَّ يُنْفَخُ فِي الصُّورِ فَلَا يَسْمَعُهُ أَحَدٌ إِلَّا أَصْغَى لِيتًا وَرَفَعَ لِيتًا، قَالَ: وَأَوَّلُ مَنْ يَسْمَعُهُ رَجُلٌ يَلُوطُ حَوْضَ إِبِلِهِ، قَالَ: فَيَصْعَقُ وَيَصْعَقُ النَّاسُ، ثُمَّ يُرْسِلُ اللَّهُ – أَوْ قَالَ: يُنْزِلُ اللَّهُ – مَطَرًا كَأَنَّهُ الطَّلُّ – أَوِ الظِّلُّ – نُعْمَانُ الشَّاكُّ – فَتَنْبُتُ مِنْهُ أَجْسَادُ النَّاسِ، ثُمَّ يُنْفَخُ فِيهِ أُخْرَى فَإِذَا هُمْ قِيَامٌ يَنْظُرُونَ، ثُمَّ يُقَالُ: يَا أَيُّهَا النَّاسُ، هَلُمَّ إِلَى رَبِّكُمْ {وَقِفُوهُمْ إِنَّهُمْ مَسْئُولُونَ} [الصّافات: ٢٤] ثُمَّ يُقَالُ: أَخْرِجُوا بَعْثَ النَّارِ، فَيُقَالُ: مِنْ كَمْ؟ فَيُقَالُ: مِنْ كُلِّ أَلْفٍ تِسْعَ مِائَةٍ وَتِسْعَةً وَتِسْعِينَ، قَالَ: فَذَاكَ يَوْمَ يَجْعَلُ الْوِلْدَانَ شِيبًا، وَذَلِكَ {يَوْمَ يُكْشَفُ عَنْ سَاقٍ} [القلم: ٤٢]". (م)', 'നുഅ്മാനുബ്നു സാലിം(റ): യഅ്ഖൂബുബ്നു ആസിമുബ്നു ഉർവതുബ്നു മസ്ഊദുസ്സഖഫി(റ) പറയുന്നത് ഞാൻ കേട്ടു: അബ്ദുല്ലാഹിബ്നു അംറ്(റ) പറയുന്നത് ഞാൻ കേട്ടു: അദ്ദേഹത്തിന്റെയടുക്കൽ ഒരാൾ വന്ന് ചോദിച്ചു: താങ്കൾ ഈ പറയുന്ന സംഭവമേതാണ്? താങ്കൾ പറയുന്നു: ഇന്ന സമയത്താണ് അന്ത്യനാൾ സംഭവിക്കുകയെന്ന്. അബ്ദുല്ലാഹ്(റ) പറഞ്ഞു: അല്ലാഹു എത്ര പരിശുദ്ധൻ - അല്ലെങ്കിൽ പറഞ്ഞു: അല്ലാഹു മാത്രമാണ് ആരാധ്യൻ. അല്ലെങ്കിൽ ഇതുപോലെ എന്തോ പറഞ്ഞു - ഇനി ഒരിക്കലും ആരോടും ഒന്നും പറയില്ലെന്ന് തീർച്ചയായും ഞാൻ തീരുമാനിച്ചു. കുറച്ച് കഴിഞ്ഞാൽ വലിയ സംഭവങ്ങൾ നിങ്ങൾ കാണുമെന്നാണ് ഞാൻ പറഞ്ഞത്. ബൈത്(കഅ്ബ) കത്തിക്കപ്പെടും, പിന്നെ മറ്റു പലതും സംഭവിക്കും. പിന്നെ പറഞ്ഞു: റസൂൽ(സ) പറയുന്നു: "എന്റെ സമുദായത്തിൽ ദജ്ജാൽ പുറപ്പെടും. നാൽപത് ദിവസമോ, നാൽപത് മാസമോ, നാൽപത് വർഷമോ - എനിക്കറിയില്ല - അവൻ താമസിക്കും. അപ്പോൾ അല്ലാഹു ഈസാ ബിൻമർയം(അ)മിനെ അയക്കും. അവർ ഉർവത് ബിൻമസ്ഊദ്(റ)വിനെപ്പോലെയാണ്. അങ്ങനെ ഈസാ(അ) ദജ്ജാലിനെ അന്വേഷിച്ച് പിടിക്കുകയും വധിക്കുകയും ചെയ്യും. ശേഷം ജനങ്ങൾ ഏഴ് വർഷം ജീവിക്കും. അവർക്കിടയിൽ ശത്രുത ഉണ്ടാവുകയില്ല. പിന്നെ ശാമിന്റെ ഭാഗത്ത് നിന്ന് ഒരു തണുത്ത കാറ്റ് അല്ലാഹു അയക്കും. അപ്പോൾ ഹൃദയത്തിൽ അൽപം നന്മയോ ഈമാനോ ഉള്ളവരെയെല്ലാം ആ കാറ്റ് പിടികൂടുക തന്നെ ചെയ്യും. നിങ്ങളിലൊരാൾ ഒരു മലയിലെ രഹസ്യ സങ്കേതത്തിലാണെങ്കിൽ പോലും ആ കാറ്റ് അവനെ പിടികൂടും." അദ്ദേഹം പറയുന്നു: അത് റസൂൽ(സ)യിൽ നിന്നും ഞാൻ കേട്ടതാണ്. റസൂൽ(സ) പറയുന്നു: "പിന്നെ ജനങ്ങളിലെ മോശപ്പെട്ടവർ മാത്രം അവശേഷിക്കും. അവർക്ക് പക്ഷികളുടെ ലാഘവവും മൃഗങ്ങളുടെ ബുദ്ധിയുമായിരിക്കും. അവർ നന്മ തിരിച്ചറിയുകയോ തിന്മയെ ഉപേക്ഷിക്കുകയോ ചെയ്യുകയില്ല. അപ്പോൾ അവർക്കു മുന്നിൽ പിശാച് പ്രത്യക്ഷപ്പെടും. അവൻ ചോദിക്കും: നിങ്ങൾ ലജ്ജിക്കുന്നില്ലേ? അപ്പോഴവർ ചോദിക്കും: അതിന് താങ്കൾക്കെന്താണ് ഞങ്ങളോട് കൽപിക്കാനുള്ളത്? അപ്പോൾ പിശാച് അവരോട് ബിംബങ്ങളെ ആരാധിക്കാൻ കൽപിക്കും. അവർ അതിൽ സുഖ ജീവിതവും സുഭിക്ഷ ഭക്ഷണവുമായി കഴിയും. പിന്നെ കാഹളത്തിൽ ഊതപ്പെടും. അത് കേട്ടവരെല്ലാം തലകറങ്ങി വീഴും. അവരിലാദ്യത്തവൻ തന്റെ ഒട്ടകത്തിന്റെ കുടിവെള്ളത്തിന്റെ തടാകം നന്നാക്കിക്കൊണ്ടിരിക്കുന്നവനായിരിക്കും. അദ്ദേഹം പറഞ്ഞു: അവൻ അട്ടഹസിച്ചുവീഴും, അപ്പോൾ ജനങ്ങളെല്ലാം അട്ടഹസിച്ചുവീഴും. പിന്നെ അല്ലാഹു ഒരു ചാറ്റൽ മഴ വർഷിപ്പിക്കും. അതിൽ എല്ലാ മനുഷ്യ ശരീരങ്ങളും മുളച്ചുവരും. പിന്നെ രണ്ടാമതും കാഹളത്തിൽ ഊതപ്പെടും. അപ്പോളവർ എഴുന്നേറ്റ് നോക്കിക്കൊണ്ടിരിക്കും. ശേഷം പറയപ്പെടും: ഓ ജനങ്ങളേ, നിങ്ങളുടെ നാഥന്റെ അടുത്തേക്ക് വരിക. പിന്നെ പറയപ്പെടും: ''നിങ്ങളവരെ നിർത്തുക, നിശ്ചയം അവർ ചോദിക്കപ്പെടുന്നവരാകുന്നു.'' (സ്വാഫാത്: 24) പിന്നെ പറയപ്പെടും: ഒരു സംഘത്തെ നരകത്തിലേക്ക് കൊണ്ട് വരിക. അപ്പോൾ ചോദിക്കപ്പെടും: എത്രയാണ് കൊണ്ട് വരേണ്ടത്? അപ്പോൾ പറയപ്പെടും: എല്ലാ ആയിരത്തിൽ നിന്നും തൊള്ളായിരത്തി തൊണ്ണൂറ്റി ഒമ്പത് പേരെ." റസൂൽ(സ) പറയുന്നു: "കുട്ടികൾ വൃദ്ധരാകുന്ന ദിവസമാണത്. ആ ദിവസത്തെക്കുറിച്ചാണ് ''കണങ്കാൽ വെളിവാക്കപ്പെടുന്ന ദിവസം'' (ഖലം: 42) എന്ന് പറഞ്ഞിട്ടുള്ളത്." (മു)', 'النُّعْمَانِ بْنِ سَالِمٍ', 'നുഅ്മാനുബ്നു സാലിം(റ)', null, null, array['م']::text[], array['മു']::text[], 'القلم: ٤٢', null, 766, 767, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 169, 'عَنْ حُمَيْدِ بْنِ هِلَالٍ، عَنْ رَهْطٍ، مِنْهُمْ أَبُو الدَّهْمَاءِ وَأَبُو قَتَادَةَ، قَالُوا: كُنَّا نَمُرُّ عَلَى هِشَامِ بْنِ عَامِرٍ، نَأْتِي عِمْرَانَ بْنَ حُصَيْنٍ رَضِيَ اللَّهُ عَنْهُمْ، فَقَالَ ذَاتَ يَوْمٍ: إِنَّكُمْ لَتُجَاوِزُونِي إِلَى رِجَالٍ مَا كَانُوا بِأَحْضَرَ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنِّي، وَلَا أَعْلَمَ بِحَدِيثِهِ مِنِّي، سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَا بَيْنَ خَلْقِ آدَمَ إِلَى قِيَامِ السَّاعَةِ خَلْقٌ أَكْبَرُ مِنَ الدَّجَّالِ". (م)', 'ഹുമൈദുബ്നു ഹിലാൽ(റ): അബുദ്ദഹ്മാഅ്(റ)വും അബൂഖതാദ(റ)വും ഉൾപ്പെടെയുള്ള ഒരു കൂട്ടം ആളുകൾ പറയുന്നു: ഞങ്ങൾ ഇംറാനുബ്നു ഹുസ്വൈൻ(റ)വിന്റെ അടുത്തേക്ക് പോകുമ്പോൾ ഹിശാമു ബ്നു ആമിർ(റ)വിന്റെ അരികിലൂടെ കടന്നുപോകാറുണ്ടായിരുന്നു. അങ്ങനെ ഒരു ദിവസം അദ്ദേഹം പറഞ്ഞു: റസൂൽ(സ)യുടെ തിരുസന്നിതിയിൽ എന്നെക്കാൾ കൂടുതലായി വരികയോ, റസൂൽ(സ)യുടെ ഹദീസിനെക്കുറിച്ച് എന്നെക്കാൾ കൂടുതലായി അറിയുകയോ ചെയ്യാത്ത ചില ആളുകളുടെ അടുത്തേക്കാണോ എന്റെ അടുത്ത് കൂടെ നിങ്ങൾ പോകുന്നത്? റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "ആദം(അ)മിന്റെ സൃഷ്ടിപ്പ് മുതൽ അന്ത്യനാൾ വരെ ദജ്ജാലിനേക്കാൾ വലിയ ഒരു സൃഷ്ടിയുമില്ല." (മു)', 'حُمَيْدِ بْنِ هِلَالٍ، عَنْ رَهْطٍ، مِنْهُمْ أَبُو الدَّهْمَاءِ وَأَبُو قَتَادَةَ، قَالُوا', 'ഹുമൈദുബ്നു ഹിലാൽ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 767, 767, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 170, 'عَنِ النَّوَّاسِ بْنِ سَمْعَانَ الْكِلَابِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: ذَكَرَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الدَّجَّالَ ذَاتَ غَدَاةٍ فَخَفَّضَ فِيهِ وَرَفَّعَ، حَتَّى ظَنَنَّاهُ فِي طَائِفَةِ النَّخْلِ، قَالَ: فَانْصَرَفْنَا مِنْ عِنْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ثُمَّ رَجَعْنَا إِلَيْهِ، فَعَرَفَ ذَلِكَ فِينَا، فَقَالَ: "مَا شَأْنُكُمْ". قَالَ: قُلْنَا: يَا رَسُولَ اللَّهِ، ذَكَرْتَ الدَّجَّالَ الْغَدَاةَ، فَخَفَّضْتَ فِيهِ وَرَفَّعْتَ، حَتَّى ظَنَنَّاهُ فِي طَائِفَةِ النَّخْلِ. قَالَ: "غَيْرُ الدَّجَّالِ أَخْوَفُ لِي عَلَيْكُمْ، إِنْ يَخْرُجْ وَأَنَا فِيكُمْ فَأَنَا حَجِيجُهُ دُونَكُمْ، وَإِنْ يَخْرُجْ وَلَسْتُ فِيكُمْ فَامْرُؤٌ حَجِيجُ نَفْسِهِ، وَاللَّهُ خَلِيفَتِي عَلَى كُلِّ مُسْلِمٍ، إِنَّهُ شَابٌّ قَطَطٌ عَيْنُهُ طَافِئَةٌ، شَبِيهٌ بِعَبْدِ الْعُزَّى بْنِ قَطَنٍ، فَمَنْ رَآهُ مِنْكُمْ فَلْيَقْرَأْ فَوَاتِحَ سُورَةِ أَصْحَابِ الْكَهْفِ". قَالَ: "يَخْرُجُ مَا بَيْنَ الشَّامِ وَالْعِرَاقِ، فَعَاثَ يَمِينًا وَشِمَالًا، يَا عِبَادَ اللَّهِ اثْبُتُوا". قَالَ: قُلْنَا: يَا رَسُولَ اللَّهِ، وَمَا لَبْثُهُ فِي الْأَرْضِ؟ قَالَ: "أَرْبَعِينَ يَوْمًا: يَوْمٌ كَسَنَةٍ، وَيَوْمٌ كَشَهْرٍ، وَيَوْمٌ كَجُمُعَةٍ، وَسَائِرُ أَيَّامِهِ كَأَيَّامِكُمْ". قَالَ: قُلْنَا: يَا رَسُولَ اللَّهِ، أَرَأَيْتَ الْيَوْمَ الَّذِي كَالسَّنَةِ، أَتَكْفِينَا فِيهِ صَلَاةُ يَوْمٍ؟ قَالَ: "لَا، وَلَكِنِ اقْدُرُوا لَهُ". قَالَ: قُلْنَا: يَا رَسُولَ اللَّهِ، فَمَا سُرْعَتُهُ فِي الْأَرْضِ؟ قَالَ: "كَالْغَيْثِ اسْتَدْبَرَتْهُ الرِّيحُ، فَيَأْتِي الْقَوْمَ فَيَدْعُوهُمْ فَيُكَذِّبُونَهُ وَيَرُدُّونَ عَلَيْهِ قَوْلَهُ، فَيَنْصَرِفُ عَنْهُمْ، فَتَتْبَعُهُ أَمْوَالُهُمْ وَيُصْبِحُونَ لَيْسَ بِأَيْدِيهِمْ شَيْءٌ، ثُمَّ يَأْتِي الْقَوْمَ فَيَدْعُوهُمْ فَيَسْتَجِيبُونَ لَهُ وَيُصَدِّقُونَهُ، فَيَأْمُرُ السَّمَاءَ أَنْ تُمْطِرَ، فَتُمْطِرُ، وَيَأْمُرُ الْأَرْضَ أَنْ تُنْبِتَ فَتُنْبِتُ، فَتَرُوحُ عَلَيْهِمْ سَارِحَتُهُمْ كَأَطْوَلِ مَا كَانَتْ ذُرًا، وَأَمَدِّهِ خَوَاصِرَ، وَأَدَرِّهِ ضُرُوعًا. قَالَ: ثُمَّ يَأْتِي الْخَرِبَةَ فَيَقُولُ لَهَا: أَخْرِجِي كُنُوزَكِ. فَيَنْصَرِفُ مِنْهَا، فَيَتْبَعُهُ كَيَعَاسِيبِ النَّحْلِ، ثُمَّ يَدْعُو رَجُلًا شَابًّا مُمْتَلِئًا شَبَابًا فَيَضْرِبُهُ بِالسَّيْفِ فَيَقْطَعُهُ جَزْلَتَيْنِ، ثُمَّ يَدْعُوهُ فَيُقْبِلُ يَتَهَلَّلُ وَجْهُهُ يَضْحَكُ، فَبَيْنَمَا هُوَ كَذَلِكَ إِذْ هَبَطَ عِيسَى بْنُ مَرْيَمَ عَلَيْهِ السَّلَامُ بِشَرْقِيِّ دِمَشْقَ، عِنْدَ الْمَنَارَةِ الْبَيْضَاءِ، بَيْنَ مَهْرُودَتَيْنِ، وَاضِعًا يَدَيْهِ عَلَى أَجْنِحَةِ مَلَكَيْنِ، إِذَا طَأْطَأَ رَأْسَهُ قَطَرَ، وَإِذَا رَفَعَهُ تَحَدَّرَ مِنْهُ جُمَّانٌ كَاللُّؤْلُؤِ. قَالَ: وَلَا يَجِدُ رِيحَ نَفَسِهِ – يَعْنِي – أَحَدٌ إِلَّا مَاتَ، وَرِيحُ نَفَسِهِ مُنْتَهَى بَصَرِهِ. قَالَ: فَيَطْلُبُهُ حَتَّى يُدْرِكَهُ بِبَابِ لُدٍّ فَيَقْتُلَهُ – وَفِي رِوَايَةٍ: ثُمَّ يَأْتِي عِيسَى بْنَ مَرْيَمَ قَوْمٌ قَدْ عَصَمَهُمُ اللَّهُ مِنْهُ، فَيَمْسَحُ عَنْ وُجُوهِهِمْ، وَيُحَدِّثُهُمْ بِدَرَجَاتِهِمْ فِي الْجَنَّةِ – قَالَ: فَيَلْبَثُ كَذَلِكَ مَا شَاءَ اللَّهُ، قَالَ: ثُمَّ يُوحِي اللَّهُ إِلَيْهِ: أَنْ حَرِّزْ عِبَادِي إِلَى الطُّورِ، فَإِنِّي قَدْ أَنْزَلْتُ عِبَادًا لِي لَا يَدَانِ لِأَحَدٍ بِقِتَالِهِمْ، قَالَ: وَيَبْعَثُ اللَّهُ يَأْجُوجَ وَمَأْجُوجَ، وَهُمْ كَمَا قَالَ اللَّهُ: {مِنْ كُلِّ حَدَبٍ يَنْسِلُونَ} [الأنبياء: ٩٦]. قَالَ: فَيَمُرُّ أَوَّلُهُمْ بِبُحَيْرَةِ الطَّبَرِيَّةِ فَيَشْرَبُ مَا فِيهَا، ثُمَّ يَمُرُّ بِهَا آخِرُهُمْ فَيَقُولُ: لَقَدْ كَانَ بِهَذِهِ مَرَّةً مَاءٌ، ثُمَّ يَسِيرُونَ حَتَّى يَنْتَهُوا إِلَى جَبَلِ بَيْتِ مَقْدِسٍ فَيَقُولُونَ: لَقَدْ قَتَلْنَا مَنْ فِي الْأَرْضِ، فَهَلُمَّ فَلْنَقْتُلْ مَنْ فِي السَّمَاءِ. فَيَرْمُونَ بِنُشَّابِهِمْ إِلَى السَّمَاءِ، فَيَرُدُّ اللَّهُ عَلَيْهِمْ نُشَّابَهُمْ مُحْمَرًّا دَمًا. وَيُحَاصَرُ عِيسَى بْنُ مَرْيَمَ وَأَصْحَابُهُ حَتَّى يَكُونَ رَأْسُ الثَّوْرِ يَوْمَئِذٍ خَيْرًا لِأَحَدِهِمْ مِنْ مِائَةِ دِينَارٍ لِأَحَدِكُمُ الْيَوْمَ، قَالَ: فَيَرْغَبُ عِيسَى بْنُ مَرْيَمَ إِلَى اللَّهِ وَأَصْحَابُهُ، قَالَ: فَيُرْسِلُ اللَّهُ إِلَيْهِمُ النَّغَفَ فِي رِقَابِهِمْ، فَيُصْبِحُونَ فَرْسَى مَوْتَى كَمَوْتِ نَفْسٍ وَاحِدَةٍ. قَالَ: وَيَهْبِطُ عِيسَى وَأَصْحَابُهُ، فَلَا يَجِدُ مَوْضِعَ شِبْرٍ إِلَّا وَقَدْ مَلَأَتْهُ زَهَمَتُهُمْ وَنَتْنُهُمْ وَدِمَاؤُهُمْ. قَالَ: فَيَرْغَبُ عِيسَى إِلَى اللَّهِ وَأَصْحَابُهُ، قَالَ: فَيُرْسِلُ اللَّهُ عَلَيْهِمْ طَيْرًا كَأَعْنَاقِ الْبُخْتِ، قَالَ: فَتَحْمِلُهُمْ فَتَطْرَحُهُمْ بِالْمَهْبِلِ – وَفِي رِوَايَةٍ: حَيْثُ شَاءَ اللَّهُ عَزَّ وَجَلَّ – وَيَسْتَوْقِدُ الْمُسْلِمُونَ مِنْ قِسِيِّهِمْ وَنُشَّابِهِمْ وَجِعَابِهِمْ سَبْعَ سِنِينَ. قَالَ: وَيُرْسِلُ اللَّهُ عَلَيْهِمْ مَطَرًا، لَا يُكِنُّ مِنْهُ بَيْتُ وَبَرٍ وَلَا مَدَرٍ، قَالَ: فَيَغْسِلُ الْأَرْضَ فَيَتْرُكُهَا كَالزَّلَفَةِ، قَالَ: ثُمَّ يُقَالُ لِلْأَرْضِ: أَخْرِجِي ثَمَرَتَكِ، وَرُدِّي بَرَكَتَكِ. فَيَوْمَئِذٍ تَأْكُلُ الْعِصَابَةُ مِنَ الرُّمَّانَةِ، وَيَسْتَظِلُّونَ بِقِحْفِهَا، وَيُبَارَكُ فِي الرِّسْلِ، حَتَّى إِنَّ الْفِئَامَ مِنَ النَّاسِ لَيَكْتَفُونَ بِاللِّقْحَةِ مِنَ الْإِبِلِ، وَإِنَّ الْقَبِيلَةَ لَيَكْتَفُونَ بِاللِّقْحَةِ مِنَ الْبَقَرِ، وَإِنَّ الْفَخِذَ لَيَكْتَفُونَ بِاللِّقْحَةِ مِنَ الْغَنَمِ. فَبَيْنَمَا هُمْ كَذَلِكَ إِذْ بَعَثَ اللَّهُ رِيحًا، فَقَبَضَتْ رُوحَ كُلِّ مُؤْمِنٍ – وَفِي رِوَايَةٍ: رِيحًا طَيِّبَةً، فَتَأْخُذُهُمْ تَحْتَ آبَاطِهِمْ، فَتَقْبِضُ رُوحَ كُلِّ مُؤْمِنٍ وَكُلِّ مُسْلِمٍ – وَيَبْقَى سَائِرُ النَّاسِ يَتَهَارَجُونَ كَمَا تَتَهَارَجُ الْحُمُرُ، فَعَلَيْهِمْ تَقُومُ السَّاعَةُ". حَسَنٌ صَحِيحٌ. (م,د,ت,جه)', 'നവാസുബ്നു സംആനുൽ കിലാബി(റ): ഒരു പ്രഭാതത്തിൽ റസൂൽ(സ) ദജ്ജാലിനെക്കുറിച്ച് പറഞ്ഞു. ഇടക്ക് ശബ്ദം കുറച്ചും ഇടക്ക് ശബ്ദമുയർത്തിയുമാണ് അവിടന്ന് സംസാരിച്ചത്. അങ്ങനെ ഞങ്ങൾ വിചാരിച്ചു, അവൻ ഈ ഈത്തപ്പനത്തോട്ടത്തിലുണ്ടെന്ന്. നിവേദകൻ പറയുന്നു: ഞങ്ങൾ തിരുസന്നിധിയിൽ നിന്ന് മടങ്ങിയ ശേഷം അവിടേക്ക് തന്നെ ചെന്നപ്പോൾ ഞങ്ങളുടെ മുഖത്തുള്ള ഭയം അവിടന്ന് മനസ്സിലാക്കി. റസൂൽ(സ) ചോദിച്ചു: "എന്താണ് നിങ്ങളുടെ പ്രശ്നം?" ഞങ്ങൾ പറഞ്ഞു: തിരുദൂതരേ, ഇന്ന് രാവിലെ അവിടന്ന് ദജ്ജാലിനെക്കുറിച്ച് ശബ്ദമുയർത്തിയും താഴ്തിയും പറഞ്ഞുവല്ലോ? എത്രത്തോളമെന്നാൽ അവൻ ഈ ഈത്തപ്പനത്തോട്ടത്തിലുണ്ടെന്ന് ഞങ്ങൾ വിചാരിച്ചു. റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളുടെ വിഷയത്തിൽ ദജ്ജാലല്ലാത്ത കാര്യമാണ് എന്നെ ഭയപ്പെടുത്തുന്നത്. ഞാൻ നിങ്ങളിലുണ്ടായിരിക്കെ അവൻ വന്നാൽ ഞാൻ അവനെ തെളിവ് കൊണ്ട് പരാജയപ്പെടുത്തും. ഞാൻ നിങ്ങളിലില്ലെങ്കിൽ നിങ്ങളോരോരുത്തരും അവനെ പരാജയപ്പെടുത്തണം. എല്ലാ മുസ്ലിംകളിലും അല്ലാഹു എന്റെ പ്രാതിനിധ്യം ഏറ്റെടുക്കും. അവൻ മുടി ജഡകുത്തിയ ഒറ്റക്കണ്ണനായ ഒരു യുവാവാണ്. അബ്ദുൽഉസ്സബ്നു ഖതനിനോട് സാമ്യമുള്ളവനാണവൻ. നിങ്ങളാരെങ്കിലും അവനെ കണ്ടാൽ കഹ്ഫ് സൂറത്തിലെ ആദ്യ ഭാഗങ്ങൾ ഓതുക." അവിടന്ന് പറഞ്ഞു: "ശാമിന്റെയും ഇറാഖിന്റെയും ഇടയിലൂടെ അവൻ പുറത്ത് വരും. ഭൂമിയിലൊന്നാകെ അവൻ കുഴപ്പം സൃഷ്ടിക്കും. ഓ അല്ലാഹുവിന്റെ അടിമകളേ, നിങ്ങൾ ദൃഢമായി നിൽക്കുക." ഞങ്ങൾ ചോദിച്ചു: തിരുദൂതരേ, അവൻ എത്ര കാലമായിരിക്കും ഭൂമിയിലുണ്ടാകുക? റസൂൽ(സ) പറഞ്ഞു: "നാൽപത് ദിവസം. അതിൽ ഒരു ദിവസം ഒരു വർഷത്തെപ്പോലെയും ഒരു ദിവസം ഒരു മാസത്തെപ്പോലെയും ഒരു ദിവസം ഒരു ആഴ്ചയെപ്പോലെയും ബാക്കിയുള്ള ദിവസങ്ങൾ നിങ്ങളുടെ സാധാരണ ദിവസങ്ങളെപ്പോലെയും ആയിരിക്കും." ഞങ്ങൾ ചോദിച്ചു: തിരുദൂതരേ, ഒരു വർഷം പോലെയുള്ള ആ ദിവസത്തിൽ ഒരു ദിവസത്തെ നിസ്കാരം മതിയാകുമോ? റസൂൽ(സ) പറഞ്ഞു: "ഇല്ല, അതിന് നിങ്ങൾ അതിന്റേതായ കണക്ക് കൂട്ടുക." നിവേദകൻ പറയുന്നു: ഞങ്ങൾ ചോദിച്ചു: തിരുദൂതരേ, ഭൂമിയിൽ അവന്റെ വേഗതയെങ്ങനെയാണ്? റസൂൽ(സ) പറഞ്ഞു: "കാറ്റിൽ ചലിക്കുന്ന മേഘത്തെപ്പോലെയാണ്. അങ്ങനെ അവൻ ഒരു സമൂഹത്തിന്റെ അടുത്ത് ചെന്ന് അവരെ ക്ഷണിക്കും. പക്ഷേ, അവർ അവനെ കളവാക്കുകയും അവന്റെ വാക്കുകളെ തട്ടിമാറ്റുകയും ചെയ്യും. അപ്പോൾ അവരുടെ സമ്പത്ത് മുഴുവൻ അവനെ പിന്തുടരുകയും അങ്ങനെ അവർ ഒന്നുമില്ലാത്തവരായി മാറുകയും ചെയ്യും. പിന്നെ അവൻ മറ്റൊരു സമൂഹത്തിൽ ചെല്ലും. അവൻ അവരെ ക്ഷണിക്കുകയും അവർ അവന് ഉത്തരം നൽകുകയും അവനെ വാസ്തവമാക്കുകയും ചെയ്യും. അപ്പോൾ അവൻ ആകാശത്തോട് മഴവർഷിപ്പിക്കാൻ കൽപിക്കുകയും അത് മഴ വർഷിപ്പിക്കുകയും ചെയ്യും. ഭൂമിയോട് അവൻ (സസ്യങ്ങളെ) മുളപ്പിക്കാൻ കൽപിക്കും, അപ്പോൾ അത് മുളപ്പിക്കും. അവരുടെ മൃഗങ്ങൾ അവരിലേക്ക് തിരിച്ച് വരുമ്പോൾ കൂടുതൽ ഉയരമുള്ളവയും കൊഴുത്തവയും പാലുള്ളവയും ആയിട്ടുണ്ടാകും." റസൂൽ(സ) പറയുന്നു: "ശേഷം അവൻ ആൾതാമസമില്ലാത്ത സ്ഥലത്ത് വന്ന് അതിനോട് പറയും: നിന്റെ നിധികളെ പുറത്തെടുക്കുക. എന്നിട്ടവിടെ നിന്ന് തിരിച്ച് പോകും. അപ്പോൾ തേനീച്ചക്കൂട്ടം പോലെ അവ അവനെ പിന്തുടരും. പിന്നെ ഒരു പൂർണ്ണ യുവാവിനെ വിളിച്ച് അവനെ വാള് കൊണ്ട് വെട്ടി രണ്ട് കഷ്ണങ്ങളാക്കി മാറ്റും. പിന്നെ അവൻ ആ യുവാവിനെ വിളിക്കും. അപ്പോൾ ശോഭിക്കുന്ന മുഖവുമായി ചിരിച്ചു കൊണ്ട് അവൻ നടന്ന് വരും. അങ്ങനെയിരിക്കെ ഈസബ്നു മർയം(അ), ചായം മുക്കിയ രണ്ട് വസ്ത്രങ്ങളണിഞ്ഞ് ഡമസ്കസിന്റെ കിഴക്ക് ഭാഗത്തെ വെള്ള മിനാരത്തിനടുത്ത് തന്റെ രണ്ട് കൈകളും രണ്ട് മലക്കുകളുടെ ചിറകുകളിൽ വെച്ച് ഇറങ്ങിവരും. അദ്ദേഹം തന്റെ തല താഴ്തിയാൽ വെള്ളമുറ്റും, തല ഉയർത്തിയാൽ വെള്ളിമുത്തുകൾ പോലുള്ള മണികൾ ഉതിർന്ന് വീഴും." റസൂൽ(സ) പറയുന്നു: "അദ്ദേഹത്തിന്റെ ശ്വാസത്തിന്റെ വാസന ഏറ്റവരെല്ലാം മരിക്കും. അതിന്റെ വാസന കണ്ണെത്തും ദൂരം വരെയാണ്." റസൂൽ(സ) പറയുന്നു: "അങ്ങനെ ഈസാ(അ) അവനെ അന്വേഷിക്കുകയും ലുദ്ദിലെ കവാടത്തിങ്കൽ വെച്ച് കണ്ടുമുട്ടുകയും അവനെ വധിക്കുകയും ചെയ്യും." - മറ്റൊരു നിവേദനം: "ദജ്ജാലിൽ നിന്നും അല്ലാഹു സംരക്ഷണം നൽകിയ ഒരു വിഭാഗം പിന്നീട് ഈസാ(അ)മിന്റെ അടുക്കൽ വരും. അപ്പോൾ ഈസാ(അ) അവരുടെ മുഖങ്ങളിൽ തടവുകയും സ്വർഗത്തിലെ അവരുടെ സ്ഥാനങ്ങളെക്കുറിച്ച് അവർക്ക് പറഞ്ഞുകൊടുക്കുകയും ചെയ്യും." - റസൂൽ(സ) പറയുന്നു: "അപ്രകാരം അല്ലാഹു ഉദ്ദേശിച്ചയത്ര കാലം ഈസാ(അ) കഴിയും. ശേഷം അല്ലാഹു ഇപ്രകാരം വഹ്യ് അറിയിക്കും: എന്റെ അടിമകളെ നീ ത്വൂർ പർവ്വതത്തിന്റെ ഭാഗത്തേക്ക് ഒരുമിച്ച് കൂട്ടുക. ഞാൻ എന്റെ ചില അടിമകളെ ഇറക്കിയിട്ടുണ്ട്, ഒരാൾക്കും അവരോട് പോരടിക്കാൻ സാധ്യമല്ല." റസൂൽ(സ) പറയുന്നു: "അങ്ങനെ അല്ലാഹു യഅ്ജൂജ് മഅ്ജൂജിനെ അയക്കും, അവർ അല്ലാഹു പറഞ്ഞത് പോലെയാണ്: ''എല്ലാ ഉയർന്ന സ്ഥലങ്ങളിൽ നിന്നും അവർ ദൃതിയിൽ പുറപ്പെട്ട് കൊണ്ടിരിക്കും'' (അമ്പിയാഅ്: 96)" റസൂൽ(സ) പറയുന്നു: "അവരിലെ ആദ്യ വിഭാഗം ത്വബ്‌രിയ്യ തടാകത്തിനടുത്തുകൂടെ നടന്ന് പോകുകയും അതിലുള്ള വെള്ളമെല്ലാം കുടിക്കുകയും ചെയ്യും. ശേഷം അവരിലെ അവസാന വിഭാഗം അതിനടുത്ത് കൂടെ നടന്ന് പോകുകയും ഇപ്രകാരം പറയുകയും ചെയ്യും: ഒരു കാലത്ത് ഇതിൽ വെള്ളമുണ്ടായിരുന്നു. അങ്ങനെ അവർ സഞ്ചരിച്ച് ബൈതുൽ മുഖദ്ദസിലെ പർവ്വതത്തിലെത്തിപ്പെടും. അവർ പറയും: ഭൂമിയിലുള്ളവരെ നാം വധിച്ചിരിക്കുന്നു. വരിക, നമുക്ക് ആകാശത്തിലുള്ളവരെക്കൂടി വധിക്കാം. അങ്ങനെ അവർ തങ്ങളുടെ അമ്പുകൾ കൊണ്ട് ആകാശത്തേക്ക് അമ്പെയ്യും. അല്ലാഹു അവയെ രക്തക്കറയോട് കൂടെ അവരിലേക്ക് തിരിച്ചയക്കുകയും ചെയ്യും. ഈസാ(അ)മും തന്റെ അനുചരരും അപ്രകാരം ഉപരോധിക്കപ്പെടും. അന്ന് ഒരു കാളയുടെ തല, നിങ്ങളുടെ നൂറ് ദീനാറിനേക്കാൾ ഉത്തമമായതാണെന്ന് അവർക്ക് തോന്നും." റസൂൽ(സ) പറയുന്നു: "അപ്പോൾ ഈസാ(അ)മും കൂട്ടരും അല്ലാഹുവിനോട് താഴ്മയോടെ ദുആ ചെയ്യും." റസൂൽ(സ) പറയുന്നു: "അങ്ങനെ അല്ലാഹു അവരുടെ (യഅ്ജൂജ് മഅ്ജൂജിന്റെ) പിരടിയിലേക്ക് ഒരു തരം പുഴുക്കളെ അയക്കുകയും അവർ ഒറ്റ ശരീരം പോലെ ഒറ്റയടിക്ക് ശവങ്ങളായി മാറുകയും ചെയ്യും." റസൂൽ(സ) പറയുന്നു: "അങ്ങനെ ഈസാ(അ)മും കൂട്ടരും ഇറങ്ങി വരും. ഭൂമിയിൽ യഅ്ജൂജ് മഅ്ജൂജിന്റെ രക്തവും നാറ്റവും ഇല്ലാത്ത ഒരു ചാൺ സ്ഥലം പോലും അവർ കാണുകയില്ല." റസൂൽ(സ) പറയുന്നു: "അപ്പോൾ ഈസാ(അ)മും കൂട്ടരും അല്ലാഹുവിനോട് താഴ്മയോടെ ദുആ ചെയ്യും." റസൂൽ(സ) പറയുന്നു: "അപ്പോൾ അല്ലാഹു ഒട്ടകങ്ങളുടെ കഴുത്ത് പോലോത്ത കഴുത്തുള്ള ചില പക്ഷികളെ അയക്കുകയും അവ അവരെ(യഅ്ജൂജ് മഅ്ജൂജിനെ) ചുമന്ന് വലിയ കുഴികളിൽ - മറ്റൊരു നിവേദനത്തിൽ: അല്ലാഹു ഉദ്ദേശിച്ചിടത്ത് - കൊണ്ടുപോയി ഇടുകയും ചെയ്യും. അവരുടെ (യഅ്ജൂജ് മഅ്ജൂജിന്റെ) അമ്പുകൾ കൊണ്ടും വില്ലുകൾ കൊണ്ടും ആവനാഴികൾ കൊണ്ടും മുസ്ലിംകൾ ഏഴ് വർഷത്തോളം തീ കത്തിക്കും." റസൂൽ(സ) പറയുന്നു: "ശേഷം അല്ലാഹു ഒരു മഴ വർഷിപ്പിക്കും. ഒരു ചെറിയ കുടിലോ വലിയ വീടോ അതിൽ നിന്ന് സംരക്ഷിക്കപ്പെടുകയില്ല." റസൂൽ(സ) പറയുന്നു: "അങ്ങനെ അല്ലാഹു ഭൂമിയെ കഴുകുകയും കണ്ണാടിപോലെയാക്കുകയും ചെയ്യും." റസൂൽ(സ) പറയുന്നു: "പിന്നെ ഭൂമിയോട് പറയപ്പെടും: നീ നിന്റെ ഫലങ്ങൾ പുറത്ത് കൊണ്ടുവരിക, നിന്റെ അനുഗ്രഹങ്ങൾ മടക്കിക്കൊണ്ട് വരിക. അക്കാലത്ത് ഒരു കൂട്ടമാളുകൾ കൂടി ഒരു ഉറുമാൻ പഴം കഴിക്കുകയും അതിന്റെ തോലിനടിയിൽ തണൽ കൊള്ളുകയും ചെയ്യും. അന്ന് പാലിലും അനുഗ്രഹം ചെയ്യപ്പെടും. അങ്ങനെ വലിയ ഒരു കൂട്ടം ജനതക്ക് ഒരു ഒട്ടകത്തിന്റെ പാൽ മതിയാകും. ഒരു ഗോത്രത്തിലെ ആളുകൾക്ക് ഒരു പശുവിന്റെ പാൽ മതിയാകും. ഒരു ചെറിയ കൂട്ടം ആളുകൾക്ക് ഒരു ആടിന്റെ പാൽ മതിയാകും. അവർ ഇങ്ങനെ കഴിയുന്നതിനിടയിൽ അല്ലാഹു ഒരു കാറ്റിനെ അയക്കും. എല്ലാ സത്യവിശ്വാസിയുടെയും ആത്മാവിനെ അത് പിടിക്കും. - മറ്റൊരു നിവേദനം: അല്ലാഹു ഒരു നല്ല കാറ്റിനെ അയക്കും. അത് അവരുടെ കക്ഷങ്ങളിൽ തട്ടുകയും, എല്ലാ സത്യവിശ്വാസികളുടെയും മുസ്ലിംകളുടെയും ആത്മാവുകളെ അത് പിടിക്കുകയും ചെയ്യും - ശേഷം കഴുതകളെപ്പോലെ (പരസ്യമായി) ലൈംഗിക വേഴ്ച നടത്തുന്ന മറ്റു ജനങ്ങൾ അവശേഷിക്കും. അവരുടെ മേലിലാണ് അന്ത്യനാൾ സംഭവിക്കുക." (മു,ദ,തു,ജ)', 'النَّوَّاسِ بْنِ سَمْعَانَ الْكِلَابِيِّ', 'നവാസുബ്നു സംആനുൽ കിലാബി(റ)', null, null, array['م','د','ت','جه']::text[], array['മു','ദ','തു','ജ']::text[], 'الأنبياء: ٩٦', null, 768, 770, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=13 and h.hadith_no=170), 1, 'وَفِي رِوَايَةٍ: ثُمَّ يَأْتِي عِيسَى بْنَ مَرْيَمَ قَوْمٌ قَدْ عَصَمَهُمُ اللَّهُ مِنْهُ، فَيَمْسَحُ عَنْ وُجُوهِهِمْ، وَيُحَدِّثُهُمْ بِدَرَجَاتِهِمْ فِي الْجَنَّةِ – قَالَ: فَيَلْبَثُ كَذَلِكَ مَا شَاءَ اللَّهُ، قَالَ: ثُمَّ يُوحِي اللَّهُ إِلَيْهِ: أَنْ حَرِّزْ عِبَادِي إِلَى الطُّورِ، فَإِنِّي قَدْ أَنْزَلْتُ عِبَادًا لِي لَا يَدَانِ لِأَحَدٍ بِقِتَالِهِمْ، قَالَ: وَيَبْعَثُ اللَّهُ يَأْجُوجَ وَمَأْجُوجَ، وَهُمْ كَمَا قَالَ اللَّهُ: {مِنْ كُلِّ حَدَبٍ يَنْسِلُونَ} [الأنبياء: ٩٦]. قَالَ: فَيَمُرُّ أَوَّلُهُمْ بِبُحَيْرَةِ الطَّبَرِيَّةِ فَيَشْرَبُ مَا فِيهَا، ثُمَّ يَمُرُّ بِهَا آخِرُهُمْ فَيَقُولُ: لَقَدْ كَانَ بِهَذِهِ مَرَّةً مَاءٌ، ثُمَّ يَسِيرُونَ حَتَّى يَنْتَهُوا إِلَى جَبَلِ بَيْتِ مَقْدِسٍ فَيَقُولُونَ: لَقَدْ قَتَلْنَا مَنْ فِي الْأَرْضِ، فَهَلُمَّ فَلْنَقْتُلْ مَنْ فِي السَّمَاءِ. فَيَرْمُونَ بِنُشَّابِهِمْ إِلَى السَّمَاءِ، فَيَرُدُّ اللَّهُ عَلَيْهِمْ نُشَّابَهُمْ مُحْمَرًّا دَمًا. وَيُحَاصَرُ عِيسَى بْنُ مَرْيَمَ وَأَصْحَابُهُ حَتَّى يَكُونَ رَأْسُ الثَّوْرِ يَوْمَئِذٍ خَيْرًا لِأَحَدِهِمْ مِنْ مِائَةِ دِينَارٍ لِأَحَدِكُمُ الْيَوْمَ، قَالَ: فَيَرْغَبُ عِيسَى بْنُ مَرْيَمَ إِلَى اللَّهِ وَأَصْحَابُهُ، قَالَ: فَيُرْسِلُ اللَّهُ إِلَيْهِمُ النَّغَفَ فِي رِقَابِهِمْ، فَيُصْبِحُونَ فَرْسَى مَوْتَى كَمَوْتِ نَفْسٍ وَاحِدَةٍ. قَالَ: وَيَهْبِطُ عِيسَى وَأَصْحَابُهُ، فَلَا يَجِدُ مَوْضِعَ شِبْرٍ إِلَّا وَقَدْ مَلَأَتْهُ زَهَمَتُهُمْ وَنَتْنُهُمْ وَدِمَاؤُهُمْ. قَالَ: فَيَرْغَبُ عِيسَى إِلَى اللَّهِ وَأَصْحَابُهُ، قَالَ: فَيُرْسِلُ اللَّهُ عَلَيْهِمْ طَيْرًا كَأَعْنَاقِ الْبُخْتِ، قَالَ: فَتَحْمِلُهُمْ فَتَطْرَحُهُمْ بِالْمَهْبِلِ –', 'മറ്റൊരു നിവേദനം: "ദജ്ജാലിൽ നിന്നും അല്ലാഹു സംരക്ഷണം നൽകിയ ഒരു വിഭാഗം പിന്നീട് ഈസാ(അ)മിന്റെ അടുക്കൽ വരും. അപ്പോൾ ഈസാ(അ) അവരുടെ മുഖങ്ങളിൽ തടവുകയും സ്വർഗത്തിലെ അവരുടെ സ്ഥാനങ്ങളെക്കുറിച്ച് അവർക്ക് പറഞ്ഞുകൊടുക്കുകയും ചെയ്യും." - റസൂൽ(സ) പറയുന്നു: "അപ്രകാരം അല്ലാഹു ഉദ്ദേശിച്ചയത്ര കാലം ഈസാ(അ) കഴിയും. ശേഷം അല്ലാഹു ഇപ്രകാരം വഹ്യ് അറിയിക്കും: എന്റെ അടിമകളെ നീ ത്വൂർ പർവ്വതത്തിന്റെ ഭാഗത്തേക്ക് ഒരുമിച്ച് കൂട്ടുക. ഞാൻ എന്റെ ചില അടിമകളെ ഇറക്കിയിട്ടുണ്ട്, ഒരാൾക്കും അവരോട് പോരടിക്കാൻ സാധ്യമല്ല." റസൂൽ(സ) പറയുന്നു: "അങ്ങനെ അല്ലാഹു യഅ്ജൂജ് മഅ്ജൂജിനെ അയക്കും, അവർ അല്ലാഹു പറഞ്ഞത് പോലെയാണ്: ''എല്ലാ ഉയർന്ന സ്ഥലങ്ങളിൽ നിന്നും അവർ ദൃതിയിൽ പുറപ്പെട്ട് കൊണ്ടിരിക്കും'' (അമ്പിയാഅ്: 96)" റസൂൽ(സ) പറയുന്നു: "അവരിലെ ആദ്യ വിഭാഗം ത്വബ്‌രിയ്യ തടാകത്തിനടുത്തുകൂടെ നടന്ന് പോകുകയും അതിലുള്ള വെള്ളമെല്ലാം കുടിക്കുകയും ചെയ്യും. ശേഷം അവരിലെ അവസാന വിഭാഗം അതിനടുത്ത് കൂടെ നടന്ന് പോകുകയും ഇപ്രകാരം പറയുകയും ചെയ്യും: ഒരു കാലത്ത് ഇതിൽ വെള്ളമുണ്ടായിരുന്നു. അങ്ങനെ അവർ സഞ്ചരിച്ച് ബൈതുൽ മുഖദ്ദസിലെ പർവ്വതത്തിലെത്തിപ്പെടും. അവർ പറയും: ഭൂമിയിലുള്ളവരെ നാം വധിച്ചിരിക്കുന്നു. വരിക, നമുക്ക് ആകാശത്തിലുള്ളവരെക്കൂടി വധിക്കാം. അങ്ങനെ അവർ തങ്ങളുടെ അമ്പുകൾ കൊണ്ട് ആകാശത്തേക്ക് അമ്പെയ്യും. അല്ലാഹു അവയെ രക്തക്കറയോട് കൂടെ അവരിലേക്ക് തിരിച്ചയക്കുകയും ചെയ്യും. ഈസാ(അ)മും തന്റെ അനുചരരും അപ്രകാരം ഉപരോധിക്കപ്പെടും. അന്ന് ഒരു കാളയുടെ തല, നിങ്ങളുടെ നൂറ് ദീനാറിനേക്കാൾ ഉത്തമമായതാണെന്ന് അവർക്ക് തോന്നും." റസൂൽ(സ) പറയുന്നു: "അപ്പോൾ ഈസാ(അ)മും കൂട്ടരും അല്ലാഹുവിനോട് താഴ്മയോടെ ദുആ ചെയ്യും." റസൂൽ(സ) പറയുന്നു: "അങ്ങനെ അല്ലാഹു അവരുടെ (യഅ്ജൂജ് മഅ്ജൂജിന്റെ) പിരടിയിലേക്ക് ഒരു തരം പുഴുക്കളെ അയക്കുകയും അവർ ഒറ്റ ശരീരം പോലെ ഒറ്റയടിക്ക് ശവങ്ങളായി മാറുകയും ചെയ്യും." റസൂൽ(സ) പറയുന്നു: "അങ്ങനെ ഈസാ(അ)മും കൂട്ടരും ഇറങ്ങി വരും. ഭൂമിയിൽ യഅ്ജൂജ് മഅ്ജൂജിന്റെ രക്തവും നാറ്റവും ഇല്ലാത്ത ഒരു ചാൺ സ്ഥലം പോലും അവർ കാണുകയില്ല." റസൂൽ(സ) പറയുന്നു: "അപ്പോൾ ഈസാ(അ)മും കൂട്ടരും അല്ലാഹുവിനോട് താഴ്മയോടെ ദുആ ചെയ്യും." റസൂൽ(സ) പറയുന്നു: "അപ്പോൾ അല്ലാഹു ഒട്ടകങ്ങളുടെ കഴുത്ത് പോലോത്ത കഴുത്തുള്ള ചില പക്ഷികളെ അയക്കുകയും അവ അവരെ(യഅ്ജൂജ് മഅ്ജൂജിനെ) ചുമന്ന് വലിയ കുഴികളിൽ -');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=13 and h.hadith_no=170), 2, 'وَفِي رِوَايَةٍ: حَيْثُ شَاءَ اللَّهُ عَزَّ وَجَلَّ – وَيَسْتَوْقِدُ الْمُسْلِمُونَ مِنْ قِسِيِّهِمْ وَنُشَّابِهِمْ وَجِعَابِهِمْ سَبْعَ سِنِينَ. قَالَ: وَيُرْسِلُ اللَّهُ عَلَيْهِمْ مَطَرًا، لَا يُكِنُّ مِنْهُ بَيْتُ وَبَرٍ وَلَا مَدَرٍ، قَالَ: فَيَغْسِلُ الْأَرْضَ فَيَتْرُكُهَا كَالزَّلَفَةِ، قَالَ: ثُمَّ يُقَالُ لِلْأَرْضِ: أَخْرِجِي ثَمَرَتَكِ، وَرُدِّي بَرَكَتَكِ. فَيَوْمَئِذٍ تَأْكُلُ الْعِصَابَةُ مِنَ الرُّمَّانَةِ، وَيَسْتَظِلُّونَ بِقِحْفِهَا، وَيُبَارَكُ فِي الرِّسْلِ، حَتَّى إِنَّ الْفِئَامَ مِنَ النَّاسِ لَيَكْتَفُونَ بِاللِّقْحَةِ مِنَ الْإِبِلِ، وَإِنَّ الْقَبِيلَةَ لَيَكْتَفُونَ بِاللِّقْحَةِ مِنَ الْبَقَرِ، وَإِنَّ الْفَخِذَ لَيَكْتَفُونَ بِاللِّقْحَةِ مِنَ الْغَنَمِ. فَبَيْنَمَا هُمْ كَذَلِكَ إِذْ بَعَثَ اللَّهُ رِيحًا، فَقَبَضَتْ رُوحَ كُلِّ مُؤْمِنٍ –', 'മറ്റൊരു നിവേദനത്തിൽ: അല്ലാഹു ഉദ്ദേശിച്ചിടത്ത് - കൊണ്ടുപോയി ഇടുകയും ചെയ്യും. അവരുടെ (യഅ്ജൂജ് മഅ്ജൂജിന്റെ) അമ്പുകൾ കൊണ്ടും വില്ലുകൾ കൊണ്ടും ആവനാഴികൾ കൊണ്ടും മുസ്ലിംകൾ ഏഴ് വർഷത്തോളം തീ കത്തിക്കും." റസൂൽ(സ) പറയുന്നു: "ശേഷം അല്ലാഹു ഒരു മഴ വർഷിപ്പിക്കും. ഒരു ചെറിയ കുടിലോ വലിയ വീടോ അതിൽ നിന്ന് സംരക്ഷിക്കപ്പെടുകയില്ല." റസൂൽ(സ) പറയുന്നു: "അങ്ങനെ അല്ലാഹു ഭൂമിയെ കഴുകുകയും കണ്ണാടിപോലെയാക്കുകയും ചെയ്യും." റസൂൽ(സ) പറയുന്നു: "പിന്നെ ഭൂമിയോട് പറയപ്പെടും: നീ നിന്റെ ഫലങ്ങൾ പുറത്ത് കൊണ്ടുവരിക, നിന്റെ അനുഗ്രഹങ്ങൾ മടക്കിക്കൊണ്ട് വരിക. അക്കാലത്ത് ഒരു കൂട്ടമാളുകൾ കൂടി ഒരു ഉറുമാൻ പഴം കഴിക്കുകയും അതിന്റെ തോലിനടിയിൽ തണൽ കൊള്ളുകയും ചെയ്യും. അന്ന് പാലിലും അനുഗ്രഹം ചെയ്യപ്പെടും. അങ്ങനെ വലിയ ഒരു കൂട്ടം ജനതക്ക് ഒരു ഒട്ടകത്തിന്റെ പാൽ മതിയാകും. ഒരു ഗോത്രത്തിലെ ആളുകൾക്ക് ഒരു പശുവിന്റെ പാൽ മതിയാകും. ഒരു ചെറിയ കൂട്ടം ആളുകൾക്ക് ഒരു ആടിന്റെ പാൽ മതിയാകും. അവർ ഇങ്ങനെ കഴിയുന്നതിനിടയിൽ അല്ലാഹു ഒരു കാറ്റിനെ അയക്കും. എല്ലാ സത്യവിശ്വാസിയുടെയും ആത്മാവിനെ അത് പിടിക്കും. -');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=13 and h.hadith_no=170), 3, 'وَفِي رِوَايَةٍ: رِيحًا طَيِّبَةً، فَتَأْخُذُهُمْ تَحْتَ آبَاطِهِمْ، فَتَقْبِضُ رُوحَ كُلِّ مُؤْمِنٍ وَكُلِّ مُسْلِمٍ – وَيَبْقَى سَائِرُ النَّاسِ يَتَهَارَجُونَ كَمَا تَتَهَارَجُ الْحُمُرُ، فَعَلَيْهِمْ تَقُومُ السَّاعَةُ". حَسَنٌ صَحِيحٌ. (م,د,ت,جه)', 'മറ്റൊരു നിവേദനം: അല്ലാഹു ഒരു നല്ല കാറ്റിനെ അയക്കും. അത് അവരുടെ കക്ഷങ്ങളിൽ തട്ടുകയും, എല്ലാ സത്യവിശ്വാസികളുടെയും മുസ്ലിംകളുടെയും ആത്മാവുകളെ അത് പിടിക്കുകയും ചെയ്യും - ശേഷം കഴുതകളെപ്പോലെ (പരസ്യമായി) ലൈംഗിക വേഴ്ച നടത്തുന്ന മറ്റു ജനങ്ങൾ അവശേഷിക്കും. അവരുടെ മേലിലാണ് അന്ത്യനാൾ സംഭവിക്കുക." (മു,ദ,തു,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 171, 'عَنْ أَبِي أُمَامَةَ الْبَاهِلِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: خَطَبَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَكَانَ أَكْثَرُ خُطْبَتِهِ حَدِيثًا حَدَّثَنَاهُ عَنِ الدَّجَّالِ، وَحَذَّرَنَاهُ، فَكَانَ مِنْ قَوْلِهِ أَنْ قَالَ: "إِنَّهُ لَمْ تَكُنْ فِتْنَةٌ فِي الْأَرْضِ، مُنْذُ ذَرَأَ اللَّهُ ذُرِّيَّةَ آدَمَ، أَعْظَمَ مِنْ فِتْنَةِ الدَّجَّالِ. وَإِنَّ اللَّهَ لَمْ يَبْعَثْ نَبِيًّا إِلَّا حَذَّرَ أُمَّتَهُ الدَّجَّالَ، وَأَنَا آخِرُ الْأَنْبِيَاءِ، وَأَنْتُمْ آخِرُ الْأُمَمِ، وَهُوَ خَارِجٌ فِيكُمْ لَا مَحَالَةَ. وَإِنْ يَخْرُجْ وَأَنَا بَيْنَ ظَهْرَانَيْكُمْ فَأَنَا حَجِيجٌ لِكُلِّ مُسْلِمٍ، وَإِنْ يَخْرُجْ مِنْ بَعْدِي فَكُلُّ امْرِئٍ حَجِيجُ نَفْسِهِ، وَاللَّهُ خَلِيفَتِي عَلَى كُلِّ مُسْلِمٍ. وَإِنَّهُ يَخْرُجُ مِنْ خَلَّةٍ بَيْنَ الشَّامِ وَالْعِرَاقِ، فَيَعِيثُ يَمِينًا وَيَعِيثُ شِمَالًا، يَا عِبَادَ اللَّهِ فَاثْبُتُوا، فَإِنِّي سَأَصِفُهُ لَكُمْ صِفَةً لَمْ يَصِفْهَا إِيَّاهُ نَبِيٌّ قَبْلِي. إِنَّهُ يَبْدَأُ فَيَقُولُ: أَنَا نَبِيٌّ. وَلَا نَبِيَّ بَعْدِي، ثُمَّ يُثَنِّي فَيَقُولُ: أَنَا رَبُّكُمْ. وَلَا تَرَوْنَ رَبَّكُمْ حَتَّى تَمُوتُوا. وَإِنَّهُ أَعْوَرُ، وَإِنَّ رَبَّكُمْ لَيْسَ بِأَعْوَرَ. وَإِنَّهُ مَكْتُوبٌ بَيْنَ عَيْنَيْهِ: كَافِرٌ، يَقْرَؤُهُ كُلُّ مُؤْمِنٍ، كَاتِبٍ أَوْ غَيْرِ كَاتِبٍ. وَإِنَّ مِنْ فِتْنَتِهِ أَنَّ مَعَهُ جَنَّةً وَنَارًا، فَنَارُهُ جَنَّةٌ وَجَنَّتُهُ نَارٌ، فَمَنِ ابْتُلِيَ بِنَارِهِ فَلْيَسْتَغِثْ بِاللَّهِ، وَلْيَقْرَأْ فَوَاتِحَ الْكَهْفِ، فَتَكُونَ عَلَيْهِ بَرْدًا وَسَلَامًا، كَمَا كَانَتِ النَّارُ عَلَى إِبْرَاهِيمَ. وَإِنَّ مِنْ فِتْنَتِهِ أَنْ يَقُولَ لِأَعْرَابِيٍّ: أَرَأَيْتَ إِنْ بَعَثْتُ لَكَ أَبَاكَ وَأُمَّكَ، أَتَشْهَدُ أَنِّي رَبُّكَ؟ فَيَقُولُ: نَعَمْ. فَيَتَمَثَّلُ لَهُ شَيْطَانَانِ فِي صُورَةِ أَبِيهِ وَأُمِّهِ، فَيَقُولَانِ: يَا بُنَيَّ، اتَّبِعْهُ، فَإِنَّهُ رَبُّكَ. وَإِنَّ مِنْ فِتْنَتِهِ أَنْ يُسَلَّطَ عَلَى نَفْسٍ وَاحِدَةٍ، فَيَقْتُلَهَا، وَيَنْشُرَهَا بِالْمِنْشَارِ، حَتَّى يُلْقَى شِقَّتَيْنِ. ثُمَّ يَقُولُ: انْظُرُوا إِلَى عَبْدِي هَذَا، فَإِنِّي أَبْعَثُهُ الْآنَ، ثُمَّ يَزْعُمُ أَنَّ لَهُ رَبًّا غَيْرِي. فَيَبْعَثُهُ اللَّهُ، وَيَقُولُ لَهُ الْخَبِيثُ: مَنْ رَبُّكَ؟ فَيَقُولُ: رَبِّيَ اللَّهُ، وَأَنْتَ عَدُوُّ اللَّهِ، أَنْتَ الدَّجَّالُ، وَاللَّهِ، مَا كُنْتُ بَعْدُ أَشَدَّ بَصِيرَةً بِكَ مِنِّي الْيَوْمَ".
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=13 and h.hadith_no=171), 1, 'وَفِي رِوَايَةٍ: عَنْ أَبِي سَعِيدٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "ذَلِكَ الرَّجُلُ أَرْفَعُ أُمَّتِي دَرَجَةً فِي الْجَنَّةِ". قَالَ أَبُو سَعِيدٍ: وَاللَّهِ، مَا كُنَّا نُرَى ذَلِكَ الرَّجُلَ إِلَّا عُمَرَ بْنَ الْخَطَّابِ، حَتَّى مَضَى لِسَبِيلِهِ.
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 172, 'عَنْ أَبِي الدَّرْدَاءِ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ حَفِظَ عَشْرَ آيَاتٍ مِنْ أَوَّلِ سُورَةِ الْكَهْفِ عُصِمَ مِنْ فِتْنَةِ الدَّجَّالِ". وَفِي رِوَايَةٍ: "مَنْ حَفِظَ مِنْ خَوَاتِيمِ سُورَةِ الْكَهْفِ". وَفِي رِوَايَةٍ: "مِنْ آخِرِ الْكَهْفِ". (م,د,ت,ن)', 'അബൂദ്ദർദാഅ്(റ): നബി(സ) പറഞ്ഞു: "സൂറത്തുൽ കഹ്ഫിന്റെ ആദ്യത്തെ പത്ത് ആയത്ത് ആരെങ്കിലും മനഃപാഠമാക്കിയാൽ ദജ്ജാലിന്റെ ഫിത്നയിൽ നിന്നവൻ രക്ഷപ്പെടും." മറ്റൊരു റിപ്പോർട്ടിൽ: "സൂറതുൽ കഹ്ഫിലെ അവസാന ഭാഗം മനപ്പാഠമാക്കിയാൽ." മറ്റൊരു റിപ്പോർട്ടിൽ: "കഹ്ഫിന്റെ അവസാന ഭാഗത്ത് നിന്നും." (മു,ദ,തു,ന)', 'أَبِي الدَّرْدَاءِ', 'അബൂദ്ദർദാഅ്(റ)', null, null, array['م','د','ت','ن']::text[], array['മു','ദ','തു','ന']::text[], null, null, 775, 775, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=13 and h.hadith_no=172), 1, 'وَفِي رِوَايَةٍ: "مَنْ حَفِظَ مِنْ خَوَاتِيمِ سُورَةِ الْكَهْفِ".', 'മറ്റൊരു നിവേദനിൽ: "സൂറതുൽ കഹ്ഫിലെ അവസാന ഭാഗം മനപ്പാഠമാക്കിയാൽ."');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=13 and h.hadith_no=172), 2, 'وَفِي رِوَايَةٍ: "مِنْ آخِرِ الْكَهْفِ". (م,د,ت,ن)', 'മറ്റൊരു നിവേദനിൽ: "കഹ്ഫിന്റെ അവസാന ഭാഗത്ത് നിന്നും." (മു,ദ,തു,ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 173, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "يَأْتِي الدَّجَّالُ الْمَدِينَةَ فَيَجِدُ الْمَلَائِكَةَ يَحْرُسُونَهَا، فَلَا يَدْخُلُهَا الطَّاعُونُ وَلَا الدَّجَّالُ إِنْ شَاءَ اللَّهُ". حَسَنٌ صَحِيحٌ. (خ,ت)', 'അനസ്(റ): റസൂൽ(സ) പറയുന്നു: "ദജ്ജാൽ മദീനയിൽ വരുമ്പോൾ മലക്കുകൾ അതിന് കാവൽ നിൽക്കുന്നതായി കാണും. അതിനാൽ മദീനയിൽ ദജ്ജാലോ പ്ലേഗോ പ്രവേശിക്കുകയില്ല, ഇൻശാഅല്ലാഹ്(അല്ലാഹു ഉദ്ധേശിച്ചാൽ)." (ബു,തു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['خ','ت']::text[], array['ബു','തു']::text[], null, null, 775, 775, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=42 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 174, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "الْإِيمَانُ يَمَانٍ، وَالْكُفْرُ مِنْ قِبَلِ الْمَشْرِقِ، وَالسَّكِينَةُ لِأَهْلِ الْغَنَمِ، وَالْفَخْرُ وَالرِّيَاءُ فِي الْفَدَّادِينَ أَهْلِ الْخَيْلِ وَأَهْلِ الْوَبَرِ. يَأْتِي الْمَسِيحُ: إِذَا جَاءَ دُبُرَ أُحُدٍ صَرَفَتِ الْمَلَائِكَةُ وَجْهَهُ قِبَلَ الشَّامِ، وَهُنَالِكَ يَهْلِكُ". حَسَنٌ صَحِيحٌ. (م,ت)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറയുന്നു: "ഈമാൻ യമനിയാകുന്നു, സത്യനിശേധം കിഴക്ക് ഭാഗത്ത് നിന്നുള്ളതാണ്, ശാന്തത ആടുകളുള്ളവർക്കാണ്, അഹന്തയും അഹംഭാവവും നല്ല വീടുകളും കുതിരകളുമുള്ള ഉച്ചത്തിൽ സംസാരിക്കുന്ന വിഭാഗത്തിലാണുണ്ടാവുക. ചുറ്റിസഞ്ചരിക്കുന്നവൻ(ദജ്ജാൽ) വരും, അവൻ ഉഹ്ദിന്റെ പിന്നിലൂടെ വന്നാൽ മലക്കുകൾ അവനെ ശാമിന്റെ ഭാഗത്തേക്ക് തിരിച്ചുവിടും. അവിടെ വെച്ചാണ് അവൻ നശിക്കുക." (മു,തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','ت']::text[], array['മു','തു']::text[], null, null, 775, 775, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=42 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 175, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَيْسَ مِنْ بَلَدٍ إِلَّا سَيَطَؤُهُ الدَّجَّالُ، إِلَّا مَكَّةَ وَالْمَدِينَةَ، وَلَيْسَ نَقْبٌ مِنْ أَنْقَابِهَا إِلَّا عَلَيْهِ الْمَلَائِكَةُ صَافِّينَ تَحْرُسُهَا، فَيَنْزِلُ بِالسَّبْخَةِ، فَتَرْجُفُ الْمَدِينَةُ ثَلَاثَ رَجَفَاتٍ، يَخْرُجُ إِلَيْهِ مِنْهَا كُلُّ كَافِرٍ وَمُنَافِقٍ". (م)', 'അനസുബ്നു മാലിക്(റ): റസൂൽ(സ) പറയുന്നു: "ദജ്ജാൽ കാലുകുത്താത്ത ഒരു നാടുമില്ല, മക്കയും മദീനയുമൊഴികെ. അവയുടെ ഓരോ കവാടത്തിലും അവയെ സംരക്ഷിക്കുന്ന മലക്കുകൾ വരിയായി നിൽക്കുന്നുണ്ടാകും. പുല്ല് മുളക്കാത്ത ഒരു സ്ഥലത്ത് അവനിറങ്ങും. അപ്പോൾ മദീന മൂന്നുപ്രാവശ്യം പ്രകമ്പനംകൊള്ളും. മദീനയിൽ നിന്ന് എല്ലാ സത്യനിഷേധികളും കപടവിശ്വാസികളും അവന്റെയടുത്തേക്ക് ചെല്ലും." (മു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 775, 775, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=42 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 176, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "يَتْبَعُ الدَّجَّالَ مِنْ يَهُودِ أَصْبَهَانَ سَبْعُونَ أَلْفًا، عَلَيْهِمُ الطَّيَالِسَةُ". (م)', 'അനസുബ്നു മാലിക്ക്(റ): റസൂൽ(സ) പറയുന്നു: "അസ്ബഹാനിലെ ജൂതരിൽ എഴുപതിനായിരം പേർ ദജ്ജാലിനെ പിന്തുടരും. അവർ മേൽവസ്ത്രം അണിഞ്ഞവരായിരിക്കും." (മു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്ക്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 776, 776, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=43 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 177, 'عَنْ أُمِّ شَرِيكٍ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّهَا سَمِعَتِ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَيَفِرَّنَّ النَّاسُ مِنَ الدَّجَّالِ فِي الْجِبَالِ". قَالَتْ أُمُّ شَرِيكٍ: يَا رَسُولَ اللَّهِ، فَأَيْنَ الْعَرَبُ يَوْمَئِذٍ؟ قَالَ: "هُمْ قَلِيلٌ". (م)', 'ഉമ്മുശരീക്(റ): അവർ റസൂൽ(സ) പറയുന്നത് കേട്ടു: "ദജ്ജാലിനെ പേടിച്ച് ജനങ്ങൾ മലകളിലേക്ക് ഓടുകതന്നെ ചെയ്യും." ഉമ്മുശരീക്(റ) ചോദിച്ചു: തിരുദൂതരേ അന്ന് അറബികൾ എവിടെയായിരിക്കും? റസൂൽ(സ) പറഞ്ഞു: "അവർ കുറവായിരിക്കും." (മു)', 'أُمِّ شَرِيكٍ', 'ഉമ്മുശരീക്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 776, 776, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=44 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 178, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا تَقُومُ السَّاعَةُ حَتَّى يَنْزِلَ عِيسَى بْنُ مَرْيَمَ حَكَمًا مُقْسِطًا، وَإِمَامًا عَدْلًا، فَيَكْسِرُ الصَّلِيبَ، وَيَقْتُلُ الْخِنْزِيرَ، وَيَضَعُ الْجِزْيَةَ، وَيَفِيضُ الْمَالُ حَتَّى لَا يَقْبَلَهُ أَحَدٌ". (ق,د,ت,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഈസബ്നു മർയം(അ) നീതിമാനായ ഭരണാധികാരിയും നേതാവുമായി നിങ്ങളിൽ ഇറങ്ങി കുരിശ് തകർക്കുകയും, പന്നിയെ കൊല്ലുകയും, ജിസ്യ ഒഴിവാക്കുകയും, ധനം അധികരിച്ച് അത് സ്വീകരിക്കാൻ ആളില്ലാതെ വരികയും ചെയ്യുന്നത് വരെ അന്ത്യനാൾ സംഭവിക്കുകയില്ല." (ബു,മു,ദ,തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], null, null, 776, 776, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=45 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 179, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَيْسَ بَيْنِي وَبَيْنَهُ نَبِيٌّ – يَعْنِي عِيسَى – وَإِنَّهُ نَازِلٌ، فَإِذَا رَأَيْتُمُوهُ فَاعْرِفُوهُ: رَجُلٌ مَرْبُوعٌ، إِلَى الْحُمْرَةِ وَالْبَيَاضِ، بَيْنَ مُمَصَّرَتَيْنِ، كَأَنَّ رَأْسَهُ يَقْطُرُ وَإِنْ لَمْ يُصِبْهُ بَلَلٌ، فَيُقَاتِلُ النَّاسَ عَلَى الْإِسْلَامِ، فَيَدُقُّ الصَّلِيبَ، وَيَقْتُلُ الْخِنْزِيرَ، وَيَضَعُ الْجِزْيَةَ، وَيُهْلِكُ اللَّهُ فِي زَمَانِهِ الْمِلَلَ كُلَّهَا إِلَّا الْإِسْلَامَ، وَيُهْلِكُ الْمَسِيحَ الدَّجَّالَ، فَيَمْكُثُ فِي الْأَرْضِ أَرْبَعِينَ سَنَةً ثُمَّ يُتَوَفَّى، فَيُصَلِّي عَلَيْهِ الْمُسْلِمُونَ". (د)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "എനിക്കും അദ്ദേഹത്തിനും - അതായത് ഈസാ(അ) - ഇടയിൽ ഒരു പ്രവാചകനുമില്ല. ഈസാ(അ) ഇറങ്ങിവരുന്നതാണ്. അവരെ കണ്ടാൽ നിങ്ങൾ മനസ്സിലാക്കുക: അദ്ദേഹം ഒരു ഒത്ത ഉയരമുള്ള ആളാണ്. ചുവപ്പും വെളുപ്പും കലർന്ന നിറമായിരിക്കും. ചായം മുക്കിയ രണ്ട് വസ്ത്രങ്ങൾ ധരിച്ചിരിക്കും. അദ്ദേഹത്തിന്റെ തലയിൽ നിന്ന് വെള്ളത്തുള്ളി ഉറ്റുന്നത് പോലെയുണ്ടാകും, അത് നനഞ്ഞിട്ടില്ലെങ്കിലും. ഇസ്ലാമിന്റെ പേരിൽ ജനങ്ങളോട് അദ്ദേഹം യുദ്ധംചെയ്യും. കുരിശ് തകർക്കും, പന്നിയെ കൊല്ലും, ജിസ്യ ഒഴിവാക്കും. അദ്ദേഹത്തിന്റെ കാലത്ത് ഇസ്ലാം ഒഴിച്ചുള്ള എല്ലാ പ്രസ്ഥാനങ്ങളെയും അല്ലാഹു നശിപ്പിക്കും. സഞ്ചാരിയായ ദജ്ജാലിനെ അദ്ദേഹം വധിക്കും. ഭൂമിയിൽ അദ്ദേഹം നാൽപത് വർഷം താമസിക്കും. പിന്നെ വഫാത്താകും. മുസ്ലിംകൾ അദ്ദേഹത്തിന് മേൽ നിസ്കരിക്കും." (ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 776, 776, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=45 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 180, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "وَاللَّهِ لَيَنْزِلَنَّ ابْنُ مَرْيَمَ حَكَمًا عَادِلًا، فَلَيَكْسِرَنَّ الصَّلِيبَ وَلَيَقْتُلَنَّ الْخِنْزِيرَ، وَلَيَضَعَنَّ الْجِزْيَةَ، وَلَتُتْرَكَنَّ الْقِلَاصُ فَلَا يُسْعَى عَلَيْهَا، وَلَتَذْهَبَنَّ الشَّحْنَاءُ وَالتَّبَاغُضُ وَالتَّحَاسُدُ، وَلَيَدْعُوَنَّ إِلَى الْمَالِ فَلَا يَقْبَلُهُ أَحَدٌ". (م)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഇബ്നുമർയം(അ) നീതിമാനായ ഭരണാധികാരിയായി ഇറങ്ങിവരും. അദ്ദേഹം കുരിശ് തകർക്കുകയും, പന്നിയെ കൊല്ലുകയും, ജിസ്യ ഒഴിവാക്കുകയും ചെയ്യും. അന്ന് ഒട്ടകങ്ങൾ ഒഴിവാക്കപ്പെടും, അവക്കു വേണ്ടി ആരും നടക്കുകയില്ല. വെറുപ്പും ദേഷ്യവും അസൂയയും ഇല്ലാതാകും. സമ്പത്തിന് വേണ്ടി വിളിച്ചാൽ അത് സ്വീകരിക്കാൻ ആരും ഉണ്ടാവുകയില്ല." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 777, 777, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=45 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 181, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "كَيْفَ أَنْتُمْ إِذَا نَزَلَ فِيكُمُ ابْنُ مَرْيَمَ، فَأَمَّكُمْ مِنْكُمْ". فَقُلْتُ لِابْنِ أَبِي ذِئْبٍ: إِنَّ الْأَوْزَاعِيَّ حَدَّثَنَا عَنِ الزُّهْرِيِّ، عَنْ نَافِعٍ، عَنْ أَبِي هُرَيْرَةَ: "وَإِمَامُكُمْ مِنْكُمْ". قَالَ ابْنُ أَبِي ذِئْبٍ: أَتَدْرِي مَا "أَمَّكُمْ مِنْكُمْ"؟ قُلْتُ: تُخْبِرُنِي، قَالَ: فَأَمَّكُمْ بِكِتَابِ رَبِّكُمْ تَبَارَكَ وَتَعَالَى وَسُنَّةِ نَبِيِّكُمْ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. (م)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) ചോദിച്ചു: "മർയമിന്റെ പുത്രൻ നിങ്ങളിലേക്ക് ഇറങ്ങുകയും നിങ്ങളിലുള്ളതുകൊണ്ട് നിങ്ങൾക്ക് നേതൃത്വം വഹിക്കുകയും ചെയ്താൽ എങ്ങനെയുണ്ടാകും." നിവേദകൻ പറയുന്നു: അപ്പോൾ ഇബ്നുഅബീ ദിഅ്ബ്(റ)വിനോട് ഞാൻ ചോദിച്ചു: ഔസാഇൗ(റ) സുഹ്‌രി(റ)വിൽ നിന്നും അദ്ദേഹം നാഫിഅ്(റ)വിൽ നിന്നും അദ്ദേഹം അബൂഹുറൈറ(റ)വിൽ നിന്നും ഇപ്രകാരം റിപ്പോർട്ട് ചെയ്യുന്നുണ്ടല്ലോ: "നിങ്ങളുടെ നേതാവ് നിങ്ങളിൽപ്പെട്ടയാളാവുകയും ചയ്താൽ (എങ്ങനെയുണ്ടാകും)" ഇബ്നുഅബീദിഅ്ബ്(റ) എന്നോട് ചോദിച്ചു: "നിങ്ങളിലുള്ളതുകൊണ്ട് നിങ്ങൾക്ക് നേതൃത്വം വഹിക്കുകയും ചെയ്താൽ" എന്നു പറഞ്ഞാൽ എന്താണെന്ന് നിനക്കറിയുമോ? ഞാൻ പറഞ്ഞു: താങ്കൾ എനിക്ക് പറഞ്ഞുതരിക. അദ്ദേഹം പറഞ്ഞു: നിങ്ങളുടെ നാഥന്റെ ഗ്രന്ഥം അനുസരിച്ചും പ്രവാചകന്റ ചര്യയനുസരിച്ചും ഈസാ(അ) നിങ്ങൾക്ക് നേതൃത്വം വഹിക്കുകയും ചെയ്താൽ എന്നാണതിനർത്ഥം. (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 777, 777, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=45 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 182, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَا تَزَالُ طَائِفَةٌ مِنْ أُمَّتِي يُقَاتِلُونَ عَلَى الْحَقِّ ظَاهِرِينَ إِلَى يَوْمِ الْقِيَامَةِ. قَالَ: فَيَنْزِلُ عِيسَى بْنُ مَرْيَمَ عَلَيْهِ السَّلَامُ، فَيَقُولُ أَمِيرُهُمْ: تَعَالَ صَلِّ لَنَا، فَيَقُولُ: لَا، إِنَّ بَعْضَكُمْ عَلَى بَعْضٍ أُمَرَاءُ، تَكْرِمَةَ اللَّهِ هَذِهِ الْأُمَّةَ". (م)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): നബി(സ) പറയുന്നത് ഞാൻ കേട്ടു: "എന്റെ സമുദായത്തിൽപെട്ട ഒരു വിഭാഗം അന്ത്യനാൾ വരെ സത്യത്തിനുവേണ്ടി പോരാടി വിജയിച്ചുകൊണ്ടേയിരിക്കും. നബി(സ) പറഞ്ഞു: ശേഷം ഈസബ്നു മർയം(അ) ഇറങ്ങിവരും. അപ്പോൾ (ഈസാ(അ)മിനോട്) അവരിലെ നേതാവ് പറയും: വരിക, ഞങ്ങൾക്ക് ഇമാമായി നിസ്കരിക്കുക. അപ്പോൾ ഈസാ(അ) പറയും: ഇല്ല, നിങ്ങളിൽ ചിലർ മറ്റുചിലരുടെ നേതാക്കന്മാരാണ്. ഈ ഉമ്മത്തിനുള്ള അല്ലാഹുവിന്റെ ആദരമാണത്." (മു)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 777, 777, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=45 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 183, 'عَنْ زَيْنَبَ بِنْتِ أَبِي سَلَمَةَ، عَنْ حَبِيبَةَ، عَنْ أُمِّ حَبِيبَةَ، عَنْ زَيْنَبَ بِنْتِ جَحْشٍ – رَضِيَ اللَّهُ عَنْهُنَّ – قَالَتْ: اسْتَيْقَظَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ نَوْمٍ مُحْمَرًّا وَجْهُهُ، وَهُوَ يَقُولُ: "لَا إِلَهَ إِلَّا اللَّهُ – يُرَدِّدُهَا ثَلَاثَ مَرَّاتٍ – وَيْلٌ لِلْعَرَبِ مِنْ شَرٍّ قَدِ اقْتَرَبَ، فُتِحَ الْيَوْمَ مِنْ رَدْمِ يَأْجُوجَ وَمَأْجُوجَ مِثْلُ هَذِهِ". وَعَقَدَ عَشْرًا. قَالَتْ زَيْنَبُ: قُلْتُ: يَا رَسُولَ اللَّهِ، أَفَنَهْلِكُ وَفِينَا الصَّالِحُونَ؟ قَالَ: "نَعَمْ، إِذَا كَثُرَ الْخُبْثُ". حَسَنٌ صَحِيحٌ. (ق,ت,جه)', 'സൈനബ് ബിൻത് അബീസലമ(റ) ഹബീബ(റ)യിൽ നിന്നും അവർ ഉമ്മുഹബീബ(റ)യിൽ നിന്നും അവർ സൈനബ് ബിൻതു ജഹ്ശ്(റ)യിൽ നിന്നും നിവേദനം: റസൂൽ(സ) ഉറക്കത്തിൽ നിന്ന് എഴുന്നേറ്റു. അവിടുത്തെ മുഖം ചുവന്നിരുന്നു. അവിടുന്ന് പറഞ്ഞു: "ലാഇലാഹ ഇല്ലല്ലാഹു" - അവിടന്നത് മൂന്ന് പ്രാവശ്യം പറഞ്ഞു - അടുത്തു വരാനിരിക്കുന്ന ഒരു തിന്മയുടെ കാര്യത്തിൽ അറബികൾക്ക് നാശം! യഅ്ജൂജ് മഅ്ജൂജിന്റെ കെട്ടിൽ നിന്ന് ഇന്ന് ഇത്രയളവ് തുറക്കപ്പെട്ടിരിക്കുന്നു." തിരുമേനി(സ) പത്തിന്റെ കെട്ട് (അതിന്റെ അളവ് സൂചിപ്പിക്കാൻ) കെട്ടി. സൈനബ്(റ) പറയുന്നു: ഞാൻ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, ഞങ്ങളിൽ നല്ലവരുണ്ടായിരിക്കെ ഞങ്ങൾ നശിക്കുമോ? അവിടുന്ന് പറഞ്ഞു: "അതെ, വേണ്ടാത്തരങ്ങൾ അധികരിച്ചാൽ." (ബു,മു,തു,ജ)', 'زَيْنَبَ بِنْتِ أَبِي سَلَمَةَ، عَنْ حَبِيبَةَ، عَنْ أُمِّ حَبِيبَةَ، عَنْ زَيْنَبَ بِنْتِ جَحْشٍ –', 'സൈനബ് ബിൻത് അബീസലമ(റ)', null, null, array['ق','ت','جه']::text[], array['ബു','മു','തു','ജ']::text[], null, null, 777, 778, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=46 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 184, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "تُفْتَحُ يَأْجُوجُ وَمَأْجُوجُ، فَيَخْرُجُونَ كَمَا قَالَ اللَّهُ تَعَالَى: {وَهُمْ مِنْ كُلِّ حَدَبٍ يَنْسِلُونَ} [الأنبياء: ٩٦]. فَيَعُمُّونَ الْأَرْضَ، وَيَنْحَازُ مِنْهُمُ الْمُسْلِمُونَ، حَتَّى تَصِيرَ بَقِيَّةُ الْمُسْلِمِينَ فِي مَدَائِنِهِمْ وَحُصُونِهِمْ، وَيَضُمُّونَ إِلَيْهِمْ مَوَاشِيَهُمْ، حَتَّى أَنَّهُمْ لَيَمُرُّونَ بِالنَّهَرِ فَيَشْرَبُونَهُ، حَتَّى مَا يَذَرُونَ فِيهِ شَيْئًا، فَيَمُرُّ آخِرُهُمْ عَلَى أَثَرِهِمْ، فَيَقُولُ قَائِلُهُمْ: لَقَدْ كَانَ بِهَذَا الْمَكَانِ مَرَّةً مَاءٌ. وَيَظْهَرُونَ عَلَى الْأَرْضِ، فَيَقُولُ قَائِلُهُمْ: هَؤُلَاءِ أَهْلُ الْأَرْضِ، قَدْ فَرَغْنَا مِنْهُمْ، وَلَنُنَازِلَنَّ أَهْلَ السَّمَاءِ. حَتَّى إِنَّ أَحَدَهُمْ لَيَهُزُّ حَرْبَتَهُ إِلَى السَّمَاءِ، فَتَرْجِعُ مُخَضَّبَةً بِالدَّمِ، فَيَقُولُونَ: قَدْ قَتَلْنَا أَهْلَ السَّمَاءِ. فَبَيْنَمَا هُمْ كَذَلِكَ إِذْ بَعَثَ اللَّهُ دَوَابَّ كَنَغَفِ الْجَرَادِ، فَتَأْخُذُ بِأَعْنَاقِهِمْ فَيَمُوتُونَ مَوْتَ الْجَرَادِ، يَرْكَبُ بَعْضُهُمْ بَعْضًا، فَيُصْبِحُ الْمُسْلِمُونَ لَا يَسْمَعُونَ لَهُمْ حِسًّا، فَيَقُولُونَ: مَنْ رَجُلٌ يَشْرِي نَفْسَهُ، وَيَنْظُرُ مَا فَعَلُوا؟ فَيَنْزِلُ مِنْهُمْ رَجُلٌ قَدْ وَطَّنَ نَفْسَهُ عَلَى أَنْ يَقْتُلُوهُ، فَيَجِدُهُمْ مَوْتَى، فَيُنَادِيهِمْ: أَلَا أَبْشِرُوا، فَقَدْ هَلَكَ عَدُوُّكُمْ. فَيَخْرُجُ النَّاسُ وَيَخْلُونَ سَبِيلَ مَوَاشِيهِمْ، فَمَا يَكُونُ لَهُمْ رَعْيٌ إِلَّا لُحُومُهُمْ، فَتَشْكَرُ عَلَيْهَا كَأَحْسَنِ مَا شَكِرَتْ مِنْ نَبَاتٍ أَصَابَتْهُ قَطُّ". (جه)', 'അബൂസഇൗദിൽ ഖുദ്‌രി(റ): റസൂൽ(സ) പറഞ്ഞു: "യഅ്ജൂജ് മഅ്ജൂജ് തുറക്കപ്പെടും. ''അവർ എല്ലാ കുന്നുകളിൽ നിന്നും ഇറങ്ങിവരുന്നവരാണ്.'' (അമ്പിയാഅ് 96) എന്ന് അല്ലാഹു പറഞ്ഞതുപോലെ അവർ പുറപ്പെടുകയും ഭൂമിയിൽ വ്യാപിക്കുകയും ചെയ്യും. മുസ്ലിംകൾ അവരിൽ നിന്ന് വിദൂരത്താകും. ബാക്കിയുള്ള മുസ്ലിംകൾ തങ്ങളുടെ പട്ടണങ്ങളിലും കോട്ടകളിലും എത്തിച്ചേരും. തങ്ങളുടെ മൃഗങ്ങളെയെല്ലാം അവർ കൊണ്ടുപോകും. അങ്ങനെ യഅ്ജൂജ് മഅ്ജൂജ് ഒരു നദിയുടെ അരികിലൂടെ നടന്നാൽ അതിലെ വെള്ളം മുഴുവൻ അവർ കുടിക്കും. അതിൽ ഒന്നും അവർ അവശേഷിപ്പിക്കുകയില്ല. ശേഷം അവരുടെ പിന്നിൽ അവസാനക്കാർ വരുമ്പോൾ പറയും: ഒരിക്കൽ ഇവിടെ വെള്ളമുണ്ടായിരുന്നല്ലോ. അവർ ഭൂമി മുഴുവൻ ജയിച്ചടക്കിയാൽ അവരിലൊരാൾ വിളിച്ചുപറയും. ഈ ഭൂനിവാസികളുടെ കാര്യം നാം പൂർത്തിയാക്കി. ഇനി ആകാശത്തിലുള്ളവരോടാവാം. അങ്ങനെ അവരിലൊരാൾ തന്റെ ചാട്ടുളി ആകാശത്തേക്കെറിയുമ്പോൾ രക്തം പുരണ്ടതായി തിരിച്ചുവരും. അപ്പോഴവർ പറയും: ആകാശത്തുള്ളവരെ നാം വധിച്ചിരിക്കുന്നു. അങ്ങനെയിരിക്കുമ്പോൾ ജറാദിനെ പോലെയുള്ള ഒരു തരം പുഴുക്കളെ അല്ലാഹു അയക്കും. അതവരുടെ പിരടികളിൽ പിടികൂടുകയും അവർ ജറാദിന്റെ മരണം പോലെ, ഒരാൾ മറ്റൊരാളുടെ മേലിൽ കിടന്നുകൊണ്ട് മരിക്കുകയും ചെയ്യും. അങ്ങനെ മുസ്ലിംകൾ ഉണരുമ്പോൾ അവർ ഒരു ശബ്ദവും കേൾക്കുകയില്ല. അവർ ചോദിക്കും: അവർ എന്താണ് ചെയ്യുന്നതെന്ന് പോയിനോക്കാൻ ആരാണ് ജീവൻ നൽകാൻ തയ്യാറുള്ളത്? അപ്പോൾ വധിക്കപ്പെടാൻ തയ്യാറുള്ള ഒരാൾ ഇറങ്ങിവരും. പക്ഷേ, അവരെല്ലാം മരിച്ചതായി അയാൾ കാണും. ഉടനെ അവൻ വിളിച്ചുപറയും: സന്തോഷിക്കുക, നിങ്ങളുടെ ശത്രുക്കൾ നശിച്ചിരിക്കുന്നു. അപ്പോൾ ജനങ്ങൾ പുറത്തുവരും. അവരുടെ മൃഗങ്ങളെ അവർ പുറത്തേക്കുവിടും. അവിടെ അവരുടെ ഇറച്ചിയല്ലാതെ ഒരു തീറ്റയുമുണ്ടാകില്ല. അങ്ങനെ ഏറ്റവും നല്ല സസ്യങ്ങൾ കൊണ്ട് അവ മുമ്പ് കൊഴുത്തതിനേക്കാൾ നന്നായി അവ കൊഴുത്ത് തടിക്കും." (ജ)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഇൗദിൽ ഖുദ്‌രി(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'الأنبياء: ٩٦', null, 778, 779, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=46 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 185, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ يَأْجُوجَ وَمَأْجُوجَ يَحْفِرُونَ كُلَّ يَوْمٍ، حَتَّى إِذَا كَادُوا يَرَوْنَ شُعَاعَ الشَّمْسِ قَالَ الَّذِي عَلَيْهِمْ: ارْجِعُوا، فَسَنَحْفِرُهُ غَدًا. فَيُعِيدُهُ اللَّهُ أَشَدَّ مَا كَانَ، حَتَّى إِذَا بَلَغَتْ مُدَّتُهُمْ وَأَرَادَ اللَّهُ أَنْ يَبْعَثَهُمْ عَلَى النَّاسِ حَفَرُوا، حَتَّى إِذَا كَادُوا يَرَوْنَ شُعَاعَ الشَّمْسِ قَالَ الَّذِي عَلَيْهِمُ: ارْجِعُوا، فَسَتَحْفِرُونَهُ غَدًا، إِنْ شَاءَ اللَّهُ تَعَالَى. وَاسْتَثْنَوْا، فَيَعُودُونَ إِلَيْهِ وَهُوَ كَهَيْئَتِهِ حِينَ تَرَكُوهُ، فَيَحْفِرُونَهُ وَيَخْرُجُونَ عَلَى النَّاسِ، فَيُنْشِفُونَ الْمَاءَ، وَيَتَحَصَّنُ النَّاسُ مِنْهُمْ فِي حُصُونِهِمْ، فَيَرْمُونَ بِسِهَامِهِمْ إِلَى السَّمَاءِ، فَتَرْجِعُ عَلَيْهَا الدَّمُ الَّذِي اجْفَظَّ، فَيَقُولُونَ: قَهَرْنَا أَهْلَ الْأَرْضِ وَعَلَوْنَا أَهْلَ السَّمَاءِ. فَيَبْعَثُ اللَّهُ نَغَفًا فِي أَقْفَائِهِمْ فَيَقْتُلُهُمْ بِهَا". قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "وَالَّذِي نَفْسِي بِيَدِهِ، إِنَّ دَوَابَّ الْأَرْضِ لَتَسْمَنُ وَتَشْكَرُ شَكْرًا مِنْ لُحُومِهِمْ". (ت,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "യഅ്ജൂജും മഅ്ജൂജും എല്ലാ ദിവസവും കുഴിക്കും. അങ്ങനെ സൂര്യന്റെ രശ്മികൾ കാണാനടുത്താൽ അവരുടെ നേതാവ് പറയും: നിങ്ങൾ മടങ്ങുക. നമുക്ക് നാളെ കുഴിക്കാം. അപ്പോൾ മുമ്പുണ്ടായിരുന്നതിനേക്കാൾ ശക്തമാക്കി അല്ലാഹു അതിനെ ആദ്യ രൂപത്തിലേക്ക് മടക്കും. അങ്ങനെ ജനങ്ങളിലേക്ക് അവരെ നിയോഗിക്കാൻ അല്ലാഹു ഉദ്ദേശിക്കുകയും അവരുടെ കാലം ആകുകയും ചെയ്താൽ അവർ കുഴിക്കും. അങ്ങനെ അവർ സൂര്യന്റെ രശ്മികൾ കാണാനാകുമ്പോൾ അവരുടെ നേതാവ് പറയും: നിങ്ങൾ മടങ്ങുക. അല്ലാഹു ഉദ്ദേശിക്കുന്ന പക്ഷം നാളെ നമുക്കത് കുഴിക്കാം. അവർ ''ഇൻഷാ അല്ലാഹ്'' എന്ന് പറഞ്ഞിട്ടുണ്ടാകും. അങ്ങനെ അവർ മടങ്ങും. പിന്നെ അവർ തിരിച്ചുവരുമ്പോൾ അവർ ഉപേക്ഷിച്ച അതേ രീതിയിൽ തന്നെയുണ്ടാകും. അപ്പോൾ അവർ വീണ്ടും കുഴിക്കുകയും ജനങ്ങളിലേക്ക് പുറപ്പെടുകയും ചെയ്യും. അവർ വെള്ളം ഊറ്റിക്കുടിക്കും. അപ്പോൾ ജനങ്ങൾ അവരെ ഭയന്ന് തങ്ങളുടെ കോട്ടകളിൽ അഭയം പ്രാപിക്കും. അപ്പോൾ അവർ ആകാശത്തേക്ക് അമ്പുകളെറിയും. രക്തത്തിൽ പുരണ്ട് അത് തിരിച്ചുവരും. അവർ പറയും: ഭൂമിയിലുള്ളവരെ നാം കീഴ്പ്പെടുത്തിയിരിക്കുന്നു. നാം ആകാശത്തുള്ളവരെ അതിജയിച്ചിരിക്കുന്നു. അപ്പോൾ അവരുടെ പിരടികളിൽ ഒരുതരം പുഴുവിനെ അല്ലാഹു നിയോഗിക്കുകയും അവരെ കൊല്ലുകയും ചെയ്യും." റസൂൽ(സ) പറഞ്ഞു: "എന്റെ ശരീരം ആരുടെ കയ്യിലാണോ അവൻ തന്നെ സത്യം, ഭൂമിയിലെ ജീവികൾ അവരുടെ ഇറച്ചി ഭക്ഷിച്ച് തടിച്ചുകൊഴുത്തവയാകും." (തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 779, 779, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=46 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 186, 'عَنِ النَّوَّاسِ بْنِ سَمْعَانَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "سَيُوقِدُ الْمُسْلِمُونَ مِنْ قِسِيِّ يَأْجُوجَ وَمَأْجُوجَ وَنُشَّابِهِمْ وَأَتْرِسَتِهِمْ سَبْعَ سِنِينَ". (جه)', 'നവ്വാസുബ്നു സംആൻ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഏഴ് വർഷത്തോളം യഅ്ജൂജ് മഅ്ജൂജിന്റെ വില്ലുകൾ കൊണ്ടും അമ്പുകൾ കൊണ്ടും, പരിചകൾ കൊണ്ടും മുസ്ലിംകൾ തീ കത്തിക്കും." (ജ)', 'النَّوَّاسِ بْنِ سَمْعَانَ', 'നവ്വാസുബ്നു സംആൻ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 779, 779, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=46 where b.volume_id=3 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 187, 'عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: لَمَّا كَانَ لَيْلَةَ أُسْرِيَ بِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَقِيَ إِبْرَاهِيمَ وَمُوسَى وَعِيسَى، فَتَذَاكَرُوا السَّاعَةَ، فَبَدَءُوا بِإِبْرَاهِيمَ فَسَأَلُوهُ عَنْهَا، فَلَمْ يَكُنْ عِنْدَهُ مِنْهَا عِلْمٌ. ثُمَّ سَأَلُوا مُوسَى، فَلَمْ يَكُنْ عِنْدَهُ مِنْهَا عِلْمٌ. فَرُدَّ الْحَدِيثُ إِلَى عِيسَى بْنِ مَرْيَمَ، فَقَالَ: قَدْ عُهِدَ إِلَيَّ فِيمَا دُونَ وَجْبَتِهَا، فَأَمَّا وَجْبَتُهَا فَلَا يَعْلَمُهَا إِلَّا اللَّهُ. فَذَكَرَ خُرُوجَ الدَّجَّالِ، قَالَ: فَأَنْزِلُ فَأَقْتُلُهُ، فَيَرْجِعُ النَّاسُ إِلَى بِلَادِهِمْ، فَيَسْتَقْبِلُهُمْ يَأْجُوجُ وَمَأْجُوجُ وَهُمْ مِنْ كُلِّ حَدَبٍ يَنْسِلُونَ، فَلَا يَمُرُّونَ بِمَاءٍ إِلَّا شَرِبُوهُ، وَلَا بِشَيْءٍ إِلَّا أَفْسَدُوهُ. فَيَجْأَرُونَ إِلَى اللَّهِ، فَأَدْعُو اللَّهَ أَنْ يُمِيتَهُمْ، فَتَنْتُنُ الْأَرْضُ مِنْ رِيحِهِمْ، فَيَجْأَرُونَ إِلَى اللَّهِ، فَأَدْعُو اللَّهَ، فَيُرْسِلُ السَّمَاءَ بِالْمَاءِ، فَيَحْمِلُهُمْ فَيُلْقِيهِمْ فِي الْبَحْرِ. ثُمَّ تُنْسَفُ الْجِبَالُ وَتُمَدُّ الْأَرْضُ مَدَّ الْأَدِيمِ، فَعُهِدَ إِلَيَّ: مَتَى كَانَ ذَلِكَ كَانَتِ السَّاعَةُ مِنَ النَّاسِ كَالْحَامِلِ الَّتِي لَا يَدْرِي أَهْلُهَا مَتَى تَفْجَؤُهُمْ بِوِلَادَتِهَا.
